pub fn extract_column_a(df: &DataFrame) -> Result<Vec<String>, PolarsError> {
    // Get the column "a" as a Series
    let series = df.column("a")?;

    // Convert the Series to a Vec<String>
    let mut result = Vec::with_capacity(series.len());

