```rust
use polars::prelude::*;

/// Compute the average (mean) of selected cells in a DataFrame.
///
/// - `df` is the input DataFrame.
/// - `row_idxs` (var1) is a slice of row indices to include.
/// - `col_idxs` (var0) is a slice of column indices to include.
///
/// Returns `Some(mean)` if at least one numeric, non-null value is found; otherwise `None`.
fn average_subset(df: &DataFrame, row_idxs: &[usize], col_idxs: &[usize]) -> Option<f64> {
    let mut sum = 0.0f64;
    let mut count = 0u64;

    let nrows = df.height();
    let ncols = df.width();

    for &ci in col_idxs {
        if ci >= ncols {
            // skip out-of-range column indexes
            continue;
        }

        // select column by index
        let series_ref = match df.select_at_idx(ci) {
            Some(s) => s,
            None => continue,
        };

        // try to cast to Float64 series; if casting fails (non-numeric), skip this column
        let s_float_res = series_ref.cast(&DataType::Float64);
        let s_float = match s_float_res {
            Ok(s) => s,
            Err(_) => continue,
        };

        // safe to get f64 ChunkedArray view
        let ca = match s_float.f64() {
            Ok(ca) => ca,
            Err(_) => continue,
        };

        for &ri in row_idxs {
            if ri >= nrows {
                // skip out-of-range rows
                continue;
            }
            if let Some(v) = ca.get(ri) {
                // get returns Option<f64>: None when null, Some(value) otherwise
                sum += v;
                count += 1;
            }
        }
    }

    if count == 0 {
        None
    } else {
        Some(sum / (count as f64))
    }
}

fn main() -> PolarsResult<()> {
    // Example DataFrame
    let s0 = Series::new("a", &[Some(1.0f64), None, Some(3.0), Some(4.0)]);
    let s1 = Series::new("b", &[Some(2i64), Some(5i64), None, Some(8i64)]);
    let s2 = Series::new("c", &["x", "y", "z", "w"]); // non-numeric column

    let df = DataFrame::new(vec![s0, s1, s2])?;

    // Example: var1 = rows [0, 2, 3], var0 = columns [0, 1]  (columns indices)
    let rows = [0usize, 2, 3];
    let cols = [0usize, 1];

    match average_subset(&df, &rows, &cols) {
        Some(mean) => println!("Mean of selected cells = {}", mean),
        None => println!("No numeric non-null values in the selected subset"),
    }

    Ok(())
}
