/// let cols = vec!["A", "B"];
/// let avg = compute_average(&df, rows, cols)?;
/// println!("Average: {}", avg);
/// ```
fn compute_average(
    df: &DataFrame,
    rows: Vec<usize>,
    cols: Vec<&str>,
) -> PolarsResult<f64> {
    // Filter rows by indices
    let row_filtered = df.slice(rows[0] as i64, rows.len());

    // Select specified columns
    let col_filtered = row_filtered.select(&cols)?;

    // Convert to numeric and compute mean
    let mut sum = 0.0;
    let mut count = 0;

    for col_name in cols {
        let series = col_filtered.column(col_name)?;
        let values = series.cast(&DataType::Float64)?;

        if let Ok(ca) = values.f64() {
            for val in ca.into_iter().flatten() {
                sum += val;
                count += 1;
            }
        }
    }

    Ok(if count > 0 { sum / count as f64 } else { 0.0 })
