use ndarray::{ArrayD, Axis};

/// Delete every `k`-th element along `axis` from `arr`.
///
/// - `k` must be >= 1. (If k == 1, all elements along that axis are removed and the result
///   will have zero length along that axis.)
/// - `axis` is zero-based and must be < arr.ndim().
///
/// Returns an owned ArrayD<T> on success or Err(String) for invalid inputs.
pub fn delete_every_kth_along_axis<T: Clone>(
    arr: &ArrayD<T>,
    k: usize,
    axis: usize,
) -> Result<ArrayD<T>, String> {
    if k == 0 {
        return Err("k must be >= 1".to_owned());
    }
    let ndim = arr.ndim();
    if axis >= ndim {
        return Err(format!("axis out of bounds: axis {} >= ndim {}", axis, ndim));
    }
    let axis_len = arr.shape()[axis];
    // Build indices to keep: keep index i if (i+1) % k != 0
    let mut keep: Vec<usize> = Vec::with_capacity(axis_len);
    for i in 0..axis_len {
        if (i + 1) % k != 0 {
            keep.push(i);
        }
    }
    // If nothing removed, we can return a clone
    if keep.len() == axis_len {
        return Ok(arr.clone());
    }
    // Use ndarray's select to pick the kept indices along the axis
    Ok(arr.select(Axis(axis), &keep))
}

