use ndarray::{Array, ArrayD, Axis, IxDyn};

/// Deletes elements from an n-dimensional array along a specified dimension,
/// removing every var0-th element.
///
/// # Arguments
/// * `arr0` - Input n-dimensional array
/// * `var1` - The axis/dimension along which to delete elements (0-indexed)
/// * `var0` - Delete every var0-th element (e.g., 2 means delete every 2nd element)
///
/// # Returns
/// A new array with elements removed along the specified dimension
///
/// # Panics
/// * If var1 >= number of dimensions
/// * If var0 is 0
///
/// # Example
/// ```ignore
/// let arr = array![[1, 2, 3, 4], [5, 6, 7, 8]];
/// let result = delete_elements(arr.view(), 1, 2);
/// // Removes every 2nd element along axis 1
/// ```
fn delete_elements(arr0: ndarray::ArrayViewD<i32>, var1: usize, var0: usize) -> ndarray::ArrayD<i32> {
    assert!(var0 > 0, "var0 must be greater than 0");
    assert!(var1 < arr0.ndim(), "var1 must be less than the number of dimensions");

    // Get the shape of the input array
    let mut new_shape = arr0.shape().to_vec();
    let axis_len = arr0.shape()[var1];

    // Calculate how many elements will remain
    let remaining_count = axis_len - (axis_len / var0);
    new_shape[var1] = remaining_count;

    // Create output array
    let mut result = Array::zeros(IxDyn(&new_shape));

    // Iterate through the array and copy elements, skipping every var0-th element
    let mut indices = vec![0; arr0.ndim()];
    let mut result_indices = vec![0; arr0.ndim()];

    fn iterate_and_copy(
        source: &ndarray::ArrayViewD<i32>,
        dest: &mut ndarray::ArrayD<i32>,
        dim: usize,
        src_idx: &mut Vec<usize>,
        dst_idx: &mut Vec<usize>,
        axis: usize,
        var0: usize,
    ) {
        if dim == source.ndim() {
            // Check if this element should be kept (not a multiple of var0)
            if (src_idx[axis] + 1) % var0 != 0 {
                dest[IxDyn(dst_idx)] = source[IxDyn(src_idx)];
                dst_idx[axis] += 1;
            }
            return;
        }

        if dim == axis {
            for i in 0..source.shape()[dim] {
                src_idx[dim] = i;
                if (i + 1) % var0 != 0 {
                    dst_idx[dim] = i - (i + 1) / var0;
                    iterate_and_copy(source, dest, dim + 1, src_idx, dst_idx, axis, var0);
                }
            }
        } else {
            for i in 0..source.shape()[dim] {
                src_idx[dim] = i;
                dst_idx[dim] = i;
                iterate_and_copy(source, dest, dim + 1, src_idx, dst_idx, axis, var0);
            }
        }
    }

    // Simpler approach: iterate along specified axis
    let mut out_pos = vec![0; arr0.ndim()];

    fn fill_array(
        src: &ndarray::ArrayViewD<i32>,
        dst: &mut ndarray::ArrayD<i32>,
        pos: &mut Vec<usize>,
        out_pos: &mut Vec<usize>,
        dim: usize,
        axis: usize,
        var0: usize,
    ) {
        if dim == src.ndim() {
            return;
        }

        if dim == axis {
            for i in 0..src.shape()[dim] {
                pos[dim] = i;
                if (i + 1) % var0 != 0 {
                    out_pos[dim] = i - (i + 1) / var0;
                    dst[IxDyn(out_pos)] = src[IxDyn(pos)];
                }
            }
        } else {
            for i in 0..src.shape()[dim] {
                pos[dim] = i;
                out_pos[dim] = i;
                fill_array(src, dst, pos, out_pos, dim + 1, axis, var0);
            }
        }
    }

    fill_array(&arr0, &mut result, &mut indices, &mut out_pos, 0, var1, var0);

    result
}

