use serde::Serialize;
use serde_json::{Map, Value};

/// Given two sequences of equal length and their desired keys (`key1`, `key2`),
/// produce a Vec of JSON objects where each object maps key1 -> seq1[i], key2 -> seq2[i].
///
/// Returns an Err if lengths differ or serialization fails.
pub fn zip_into_maps<A: Serialize, B: Serialize>(
    key1: &str,
    key2: &str,
    seq1: &[A],
    seq2: &[B],
) -> Result<Vec<Value>, String> {
    if seq1.len() != seq2.len() {
        return Err(format!(
            "Sequence length mismatch: {} vs {}",
            seq1.len(),
            seq2.len()
        ));
    }

    let mut out = Vec::with_capacity(seq1.len());
    for (a, b) in seq1.iter().zip(seq2.iter()) {
        let mut m = Map::new();
        let va = serde_json::to_value(a).map_err(|e| e.to_string())?;
        let vb = serde_json::to_value(b).map_err(|e| e.to_string())?;
        m.insert(key1.to_string(), va);
        m.insert(key2.to_string(), vb);
        out.push(Value::Object(m));
    }
    Ok(out)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
