# Rust Function for Creating an Associative Mapping

```rust
use std::collections::HashMap;

/// Creates a HashMap by using elements from var0 as keys and assigning var1 as the value for each.
/// 
/// # Arguments
/// * `var0` - A collection of items to use as keys
/// * `var1` - The value to assign to each key
/// 
/// # Returns
/// A HashMap where keys come from var0 and all values are var1
/// 
/// # Example
/// ```
/// let keys = vec!["a", "b", "c"];
/// let value = 42;
/// let result = create_mapping(keys, value);
/// assert_eq!(result.get("a"), Some(&42));
/// assert_eq!(result.get("b"), Some(&42));
/// ```
fn create_mapping<K, V>(var0: impl IntoIterator<Item = K>, var1: V) -> HashMap<K, V>
where
    K: std::hash::Hash + Eq,
    V: Clone,
{
    var0.into_iter()
        .map(|key| (key, var1.clone()))
        .collect()
}

fn main() {
    // Example 1: String keys with integer value
    let keys = vec!["apple", "banana", "cherry"];
    let value = 100;
    let result = create_mapping(keys, value);

    println!("Example 1 - String keys with integer value:");
    for (k, v) in &result {
        println!("  {} => {}", k, v);
    }

    // Example 2: Integer keys with string value
    let numbers = vec![1, 2, 3, 4, 5];
    let message = "hello".to_string();
    let result2 = create_mapping(numbers, message.clone());

    println!("\nExample 2 - Integer keys with string value:");
    for (k, v) in &result2 {
        println!("  {} => {}", k, v);
    }

    // Example 3: Using a range as keys
