use std::collections::HashMap;

fn reorder_rows_by_name_order(df: DataFrame, order: Vec<String>) -> Result<DataFrame, PolarsError> {
    // Create a HashMap to quickly look up the index of each name in the order list
    let order_map: HashMap<_, _> = order.iter().enumerate().map(|(idx, name)| (name.clone(), idx)).collect();

    // Create a new column that contains the order indexes
    let mut order_indices: Vec<u32> = Vec::with_capacity(df.height());

    for row in df.column("name")?.utf8()?.into_iter() {
        match row {
            Some(name) => {
                if let Some(&index) = order_map.get(&name.to_string()) {
                    order_indices.push(index as u32);
                } else {
                    // If the name is not found in the order list, we can push a placeholder value
                    order_indices.push u32::MAX);
                }
            },
            None => order_indices.push(u32::MAX), // Handle None values
        }
    }

    // Create a new Series for the ordering
    let order_series = Series::new("order_index", order_indices);

    // Sort the DataFrame by this new order index column
    let sorted_df = df.hstack(&[order_series])?.sort("order_index", false)?;

    // Drop the order index column before returning
    sorted_df.drop_in_place("order_index")?;

    Ok(sorted_df)
}

