use regex::Regex;

/// Determines if any text entry matches at least one of the provided regex patterns.
///
/// # Arguments
/// * `entries` - A slice of text entries to search through
/// * `patterns` - A slice of regex pattern strings to match against
///
/// # Returns
/// * `Ok(true)` if at least one entry matches any pattern
/// * `Ok(false)` if no entries match any pattern
/// * `Err(String)` if any regex pattern is invalid
///
/// # Example
/// ```
/// let entries = vec!["hello123", "world", "test456"];
/// let patterns = vec![r"\d+", r"^world$"];
/// assert_eq!(has_matching_entry(&entries, &patterns).unwrap(), true);
/// ```
fn has_matching_entry(entries: &[&str], patterns: &[&str]) -> Result<bool, String> {
    // Compile all regex patterns
    let mut compiled_patterns = Vec::new();
    for pattern in patterns {
        match Regex::new(pattern) {
            Ok(regex) => compiled_patterns.push(regex),
            Err(e) => return Err(format!("Invalid regex pattern '{}': {}", pattern, e)),
        }
    }

    // Check if any entry matches any pattern
    for entry in entries {
        for regex in &compiled_patterns {
            if regex.is_match(entry) {
                return Ok(true);
            }
        }
    }

    Ok(false)
}

fn main() {
