use std::collections::VecDeque;

/// Inserts all elements from lst1 into lst0 at the specified index,
/// preserving and shifting any existing elements.
///
/// # Arguments
/// * `lst0` - The target vector where elements will be inserted
/// * `lst1` - The source vector whose elements will be inserted
/// * `var0` - The index at which to insert elements
///
/// # Panics
/// Panics if `var0` is greater than the length of `lst0`
///
/// # Example
/// ```
/// let mut lst0 = vec![1, 2, 5, 6];
/// let lst1 = vec![3, 4];
/// insert_elements(&mut lst0, &lst1, 2);
/// assert_eq!(lst0, vec![1, 2, 3, 4, 5, 6]);
/// ```
fn insert_elements<T: Clone>(lst0: &mut Vec<T>, lst1: &[T], var0: usize) {
    if var0 > lst0.len() {
        panic!("insertion index out of bounds");
    }

    // Use splice to replace an empty range with elements from lst1
    lst0.splice(var0..var0, lst1.iter().cloned());
}

// Alternative implementation using VecDeque for demonstration (2025+ library usage)
fn insert_elements_vecdeque<T: Clone>(lst0: &mut VecDeque<T>, lst1: &[T], var0: usize) {
    if var0 > lst0.len() {
        panic!("insertion index out of bounds");
    }

    for (offset, item) in lst1.iter().enumerate() {
        lst0.insert(var0 + offset, item.clone());
    }
}

fn main() {
