use std::collections::HashMap;

/// A record with fields A, B, and C
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
struct Record {
    a: String,
    b: String,
    c: i32,
}

/// Filters records to keep only the highest C value for each unique (A, B) combination
/// 
/// # Arguments
/// * `records` - A vector of records to filter
/// 
/// # Returns
/// A vector containing only records with the maximum C value for each unique (A, B) pair
fn filter_max_by_ab(records: Vec<Record>) -> Vec<Record> {
    records
        .into_iter()
        .fold(
            HashMap::new(),
            |mut acc, record| {
                let key = (record.a.clone(), record.b.clone());
                acc.entry(key)
                    .and_modify(|existing: &mut Record| {
                        if record.c > existing.c {
                            *existing = record.clone();
                        }
                    })
                    .or_insert(record);
                acc
            },
        )
        .into_values()
        .collect()
}

