```rust
use polars::prelude::*;

/// Locates and returns the row index of the first entry in a tabular dataset
/// where the value in the specified column equals the target value.
///
/// # Arguments
/// * `df` - A Polars DataFrame containing the tabular dataset
/// * `column_name` - The name of the column to search in
/// * `target_value` - The value to match
///
/// # Returns
/// * `Result<Option<u32>, PolarsError>` - The row index if found, None if not found
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let df = df! {
///     "var0" => &[10, 20, 30, 40],
///     "var1" => &["a", "b", "c", "d"],
/// }?;
///
/// let index = find_row_index(&df, "var0", 20)?;
/// assert_eq!(index, Some(1));
/// # Ok::<(), PolarsError>(())
/// ```
fn find_row_index(
    df: &DataFrame,
    column_name: &str,
    target_value: i32,
) -> PolarsResult<Option<u32>> {
    // Get the column by name
    let column = df.column(column_name)?;

    // Cast to Int32 series for comparison
    let int_series = column.i32()?;

    // Find the first index where the value equals target_value
    let index = int_series
        .iter()
        .position(|value| value == Some(target_value))
        .map(|pos| pos as u32);

    Ok(index)
}

// Generic version that works with multiple data types
fn find_row_index_generic(
    df: &DataFrame,
    column_name: &str,
    target_value: &str,
) -> PolarsResult<Option<u32>> {
    let column = df.column(column_name)?;

    // Try to match based on the column's data type
    let index = match column.dtype() {
        DataType::String => {
            let str_series = column.str()?;
            str_series
                .iter()
                .position(|value| value == Some(target_value))
                .map(|pos| pos as u32)
        }
        DataType::Int32 => {
            if let Ok(num) = target_value.parse::<i32>() {
                let int_series = column.i32()?;
                int_series
                    .iter()
                    .position(|value| value == Some(num))
                    .map(|pos| pos as u32)
            } else {
                None
            }
        }
        _ => None,
    };

    Ok(index)
}

