use ndarray::{Array2, Axis};

/// Normalize each row of `input_data` in-place so that every row sums to exactly 1.0.
/// 
/// Behavior:
/// - For rows whose sum is non-zero, each element is divided by the row sum.
/// - For rows whose sum is zero, the row is replaced with a uniform distribution (1 / n_cols).
///
/// Panics:
/// - If `input_data` has zero columns (n_cols == 0) and contains a zero-sum row, the function will panic
///   when attempting to compute a uniform value (division by zero).
pub fn normalize_rows_inplace(input_data: &mut Array2<f64>) {
    let ncols = input_data.ncols();
    // Precompute 1.0 / ncols for zero-sum rows, but only if ncols > 0.
    let uniform_val = if ncols > 0 { 1.0 / ncols as f64 } else { f64::NAN };

    // Iterate over mutable rows
    for mut row in input_data.axis_iter_mut(Axis(0)) {
        let sum: f64 = row.sum();
        if sum == 0.0 {
            // Replace with uniform distribution when the row sums to zero
            if ncols == 0 {
                // Can't form a uniform distribution with zero columns; keep row as-is (empty)
                continue;
            }
            row.fill(uniform_val);
        } else {
            // Divide each element in the row by the sum (in-place)
            row.mapv_inplace(|x| x / sum);
        }
    }
}

fn main() {
    // Example usage
    let mut data = Array2::from_shape_vec(
        (4, 3),
        vec![
            1.0, 2.0, 3.0, // sums to 6 -> normalized -> [1/6, 2/6, 3/6]
            0.0, 0.0, 0.0, // sum 0 -> uniform -> [1/3, 1/3, 1/3]
            -1.0, 1.0, 0.0, // sums to 0 -> uniform -> [1/3, 1/3, 1/3]
            5.0, 5.0, 0.0, // sums to 10 -> normalized -> [0.5, 0.5, 0.0]
        ],
    ).expect("shape match");

    println!("Before:\n{:#?}", data);
    normalize_rows_inplace(&mut data);
    println!("After:\n{:#?}", data);
}
```

