# Rust Function to Reorder Items by Identifier Sequence

```rust
use std::collections::HashMap;

/// Reorders a collection of items based on a sequence of identifiers.
///
/// # Arguments
/// * `items` - A vector of items that have an identifier
/// * `id_sequence` - A vector of identifiers defining the desired order
/// * `get_id` - A closure that extracts the identifier from an item
///
/// # Returns
/// A new vector with items reordered according to `id_sequence`.
/// Items not in `id_sequence` are appended at the end in original order.
///
/// # Example
/// ```
/// let items = vec![
///     ("user_1", "Alice"),
///     ("user_3", "Charlie"),
///     ("user_2", "Bob"),
/// ];
///
/// let order = vec!["user_2", "user_1", "user_3"];
///
/// let result = reorder_by_sequence(items, order, |item| item.0);
/// assert_eq!(
///     result,
///     vec![
///         ("user_2", "Bob"),
///         ("user_1", "Alice"),
///         ("user_3", "Charlie"),
///     ]
/// );
/// ```
pub fn reorder_by_sequence<T, ID>(
    items: Vec<T>,
    id_sequence: Vec<ID>,
    get_id: impl Fn(&T) -> ID,
) -> Vec<T>
where
    ID: std::hash::Hash + Eq + Clone,
{
    // Create a map of id -> item for O(1) lookup
    let mut item_map: HashMap<ID, T> = items
        .into_iter()
        .map(|item| {
            let id = get_id(&item);
            (id, item)
        })
        .collect();

    let mut result = Vec::with_capacity(item_map.len());

    // Add items in the order specified by id_sequence
    for id in id_sequence {
        if let Some(item) = item_map.remove(&id) {
            result.push(item);
        }
    }

    // Append any remaining items (those not in id_sequence)
    for (_, item) in item_map {
        result.push(item);
    }

    result
}

// Example with a struct
#[derive(Debug, Clone, PartialEq)]
struct User {
    id: u32,
    name: String,
}

fn main() {
    // Example 1: Tuples
    let items = vec![
        ("user_1", "Alice"),
        ("user_3", "Charlie"),
        ("user_2", "Bob"),
    ];

    let order = vec!["user_2", "user_1", "user_3"];

    let result = reorder_by_sequence(items, order, |item| item.0);
    println!("Example 1 - Tuples:");
    for item in &result {
        println!("  {} - {}", item.0, item.1);
    }

    // Example 2: Structs
    let users = vec![
        User { id: 1, name: "Alice".to_string() },
        User { id: 3, name: "Charlie".to_string() },
        User { id: 2, name: "Bob".to_string() },
    ];

    let order = vec![3, 1, 2];

    let result = reorder_by_sequence(users, order, |user| user.id);
    println!("\nExample 2 - Structs:");
    for user in &result {
        println!("  {} - {}", user.id, user.name);
    }

    // Example 3: Partial sequence (items not in sequence appear at end)
    let items = vec![
        ("a", 1),
        ("b", 2),
        ("c", 3),
        ("d", 4),
    ];

    let order = vec!["c", "a"];

    let result = reorder_by_sequence(items, order, |item| item.0);
    println!("\nExample 3 - Partial sequence:");
    for item in &result {
        println!("  {} - {}", item.0, item.1);
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_reorder_complete_sequence() {
        let items = vec!["a", "c", "b"];
        let order = vec![2, 0, 1];
        let result = reorder_by_sequence(items, order, |_| items.len());
        assert_eq!(result.len(), 3);
    }

    #[test]
    fn test_reorder_with_missing_ids() {
        let items = vec![
            ("x", 10),
            ("y", 20),
            ("z", 30),
        ];
        let order = vec!["y", "x"];
        let result = reorder_by_sequence(items, order, |item| item.0);

        assert_eq!(result[0].0, "y");
        assert_eq!(result[1].0, "x");
        assert_eq!(result[2].0, "z"); // Remaining item at end
    }

    #[test]
    fn test_empty_items() {
        let items: Vec<i32> = vec![];
        let order = vec![1, 2, 3];
        let result = reorder_by_sequence(items, order, |x| x);
        assert!(result.is_empty());
    }
}
```

