use ndarray::{Array2, ArrayView2, Axis};

/// Calculate the sum of the outer products of each pair of corresponding lists.
///
/// # Arguments
///
/// * `seq1`: The first sequence of numeric lists.
/// * `seq2`: The second sequence of numeric lists.
///
/// # Returns
///
/// The sum of the outer products of each pair of corresponding lists.
///
/// # Panics
///
/// If the sequences are not of equal length, or if the lists within the sequences are not of equal length.
pub fn outer_product_sum(seq1: Vec<Vec<f64>>, seq2: Vec<Vec<f64>>) -> Array2<f64> {
    assert_eq!(seq1.len(), seq2.len(), "Sequences must be of equal length");

    if seq1.is_empty() {
        return Array2::zeros((0, 0));
    }

    assert_eq!(seq1[0].len(), seq2[0].len(), "Lists within sequences must be of equal length");

    let mut result = Array2::zeros((seq1[0].len(), seq1[0].len()));

    for (list1, list2) in seq1.into_iter().zip(seq2.into_iter()) {
        assert_eq!(list1.len(), seq1[0].len(), "Lists within sequences must be of equal length");
        assert_eq!(list2.len(), seq2[0].len(), "Lists within sequences must be of equal length");

        let array1 = ArrayView2::from_shape((list1.len(), 1), &list1).unwrap();
        let array2 = ArrayView2::from_shape((1, list2.len()), &list2).unwrap();

        result += &array1.dot(&array2);
    }

    result
}

