use ndarray::Array2;
use num_traits::Zero;
use std::ops::{AddAssign, Mul};

/// Sum of outer products:
/// Given sequences `a_seq` and `b_seq` of equal length,
/// where every `a` in `a_seq` has length M and every `b` in `b_seq` has length N,
/// returns an (M x N) matrix equal to sum_i (a_i outer b_i).
///
/// Returns Err(&str) if input sequences are empty or lengths mismatch.
///
/// Generic over numeric type T that supports Zero, Copy, Clone, Mul and AddAssign.
/// Example usage shown in `main`.
pub fn sum_outer_products<T>(
    a_seq: &[Vec<T>],
    b_seq: &[Vec<T>],
) -> Result<Array2<T>, &'static str>
where
    T: Zero + Copy + Clone + Mul<Output = T> + AddAssign,
{
    if a_seq.len() != b_seq.len() {
        return Err("The two sequences must have the same number of vectors.");
    }
    if a_seq.is_empty() {
        return Err("Input sequences must not be empty.");
    }

    let m = a_seq[0].len();
    let n = b_seq[0].len();

    if m == 0 || n == 0 {
        return Err("Vectors must have non-zero length.");
    }

    // Validate all a vectors have length m and all b vectors have length n
    if !a_seq.iter().all(|v| v.len() == m) {
        return Err("All vectors in the first sequence must have the same length.");
    }
    if !b_seq.iter().all(|v| v.len() == n) {
        return Err("All vectors in the second sequence must have the same length.");
    }

    // Initialize result matrix of zeros (m rows, n cols)
    let mut res = Array2::<T>::zeros((m, n));

    // Accumulate outer products
    for (a, b) in a_seq.iter().zip(b_seq.iter()) {
        for i in 0..m {
            let ai = a[i];
            for j in 0..n {
                // res[[i, j]] += ai * b[j];
                let prod = ai * b[j];
                // Using AddAssign
                let elem = &mut res[(i, j)];
                *elem += prod;
            }
        }
    }

    Ok(res)
}

fn main() {
    // Example with f64
    let a_seq = vec![
        vec![1.0_f64, 2.0, 3.0], // length m = 3
        vec![0.5_f64, -1.0, 2.0],
    ];
    let b_seq = vec![
        vec![1.0_f64, 0.0], // length n = 2
        vec![2.0_f64, -1.0],
    ];

    match sum_outer_products(&a_seq, &b_seq) {
        Ok(mat) => {
            println!("Result ({} x {}):", mat.nrows(), mat.ncols());
            for row in mat.rows() {
                println!("{:?}", row.to_vec());
            }
        }
        Err(e) => eprintln!("Error: {}", e),
    }
}
```

Notes:
- Complexity: O(K * M * N) where K is the number of vector pairs, M and N their lengths.
- If you plan to run large-scale computations, consider enabling BLAS-backed operations (ndarray + ndarray-linalg) or using a crate specialized for high-performance matrix ops.

