/// Calculate the sum of outer products for corresponding pairs of numeric lists.
///
/// Given two sequences of numeric lists of equal length, this function computes
/// the outer product of each pair of corresponding lists and sums them together.
///
/// # Arguments
///
/// * `seq1` - A slice of slices representing the first sequence of numeric lists
/// * `seq2` - A slice of slices representing the second sequence of numeric lists
///
/// # Returns
///
/// A 2D array (matrix) representing the sum of all outer products.
///
/// # Panics
///
/// Panics if the sequences have different lengths, or if any pair of corresponding
/// lists have incompatible dimensions for outer product computation.
///
/// # Example
///
/// ```
/// let seq1 = vec![vec![1.0, 2.0], vec![3.0, 4.0]];
/// let seq2 = vec![vec![5.0, 6.0], vec![7.0, 8.0]];
/// let result = sum_outer_products(&seq1, &seq2);
/// // result = [[1*5, 1*6], [2*5, 2*6]] + [[3*7, 3*8], [4*7, 4*8]]
/// //        = [[26, 30], [38, 44]]
/// ```
pub fn sum_outer_products<T>(seq1: &[Vec<T>], seq2: &[Vec<T>]) -> Array2<T>
where
    T: num_traits::Num + Copy + Add<Output = T>,
{
    assert_eq!(
        seq1.len(),
        seq2.len(),
        "Sequences must have the same length"
    );

    if seq1.is_empty() {
        return Array2::from_shape_vec((0, 0), vec![]).unwrap();
    }

    // Get dimensions from first pair
    let first_pair = (&seq1[0], &seq2[0]);
    let rows = first_pair.0.len();
    let cols = first_pair.1.len();

    // Initialize result matrix with zeros
    let mut result = Array2::<T>::zeros((rows, cols));

    // Compute and accumulate outer products
    for (list1, list2) in seq1.iter().zip(seq2.iter()) {
        assert_eq!(
            list1.len(),
            rows,
            "All lists in seq1 must have the same length"
        );
        assert_eq!(
            list2.len(),
            cols,
            "All lists in seq2 must have the same length"
        );

        // Compute outer product and add to result
        for (i, &val1) in list1.iter().enumerate() {
            for (j, &val2) in list2.iter().enumerate() {
                result[[i, j]] = result[[i, j]] + val1 * val2;
            }
        }
    }

    result
}

