# Rust Function for Sum of Outer Products

```rust
use nalgebra::{DMatrix, DVectorView};

/// Calculate the sum of outer products of corresponding vector pairs.
///
/// Given two sequences of numeric lists of equal length, this function
/// computes the outer product of each corresponding pair and sums all results.
///
/// # Arguments
/// * `sequences1` - First sequence of numeric lists
/// * `sequences2` - Second sequence of numeric lists
///
/// # Returns
/// A matrix representing the sum of all outer products
///
/// # Panics
/// Panics if sequences have different lengths or if corresponding vectors
/// have different dimensions.
///
/// # Example
/// ```
/// let seq1 = vec![vec![1.0, 2.0], vec![3.0, 4.0]];
/// let seq2 = vec![vec![5.0, 6.0], vec![7.0, 8.0]];
/// let result = sum_of_outer_products(&seq1, &seq2);
/// // Outer product of [1,2] and [5,6] + outer product of [3,4] and [7,8]
/// ```
fn sum_of_outer_products(
    sequences1: &[Vec<f64>],
    sequences2: &[Vec<f64>],
) -> DMatrix<f64> {
    assert_eq!(
        sequences1.len(),
        sequences2.len(),
        "Sequences must have equal length"
    );

    let n_vectors = sequences1.len();
    if n_vectors == 0 {
        return DMatrix::zeros(0, 0);
    }

    let vec_dim = sequences1[0].len();
    assert!(
        sequences1.iter().all(|v| v.len() == vec_dim),
        "All vectors in first sequence must have the same dimension"
    );
    assert!(
        sequences2.iter().all(|v| v.len() == vec_dim),
        "All vectors in second sequence must have the same dimension"
    );

    // Initialize result matrix with zeros
    let mut result = DMatrix::zeros(vec_dim, vec_dim);

    // Sum outer products
    for i in 0..n_vectors {
        let v1 = DVectorView::from_slice(&sequences1[i], vec_dim);
        let v2 = DVectorView::from_slice(&sequences2[i], vec_dim);

        // Compute outer product and add to result
        let outer = v1 * v2.transpose();
        result += outer;
    }

    result
}

fn main() {
    // Example usage
    let seq1 = vec![
        vec![1.0, 2.0],
        vec![3.0, 4.0],
    ];

    let seq2 = vec![
        vec![5.0, 6.0],
        vec![7.0, 8.0],
    ];

    let result = sum_of_outer_products(&seq1, &seq2);

    println!("Sum of outer products:");
    println!("{}", result);

    // Verify: outer([1,2], [5,6]) = [[5,6], [10,12]]
    //         outer([3,4], [7,8]) = [[21,24], [28,32]]
    //         sum = [[26,30], [38,44]]
}
