    if var2.len() != df0.height() {
        return Err(PolarsError::ComputeError(
            format!(
                "New column length {} doesn't match DataFrame height {}.",
                var2.len(),
                df0.height()
            )
            .into(),
        ));
    }

    // Create the new column as a Series
    let new_series = Series::new(var1, var2);

    // Split the DataFrame at the insertion point
    let (left, right) = if var0 == 0 {
        // Insert at beginning
        (DataFrame::default(), df0)
    } else if var0 == num_cols {
        // Insert at end
        (df0, DataFrame::default())
    } else {
        // Split in the middle
        let left_cols: Vec<&str> = df0.get_column_names()[..var0]
            .iter()
            .map(|s| s.as_str())
            .collect();
        let right_cols: Vec<&str> = df0.get_column_names()[var0..]
            .iter()
            .map(|s| s.as_str())
            .collect();

        let left = df0.select(left_cols)?;
        let right = df0.select(right_cols)?;
        (left, right)
    };

    // Build the new DataFrame by concatenating columns
    let mut result = left;
    result = result.hstack(&[new_series])?;
    result = result.hstack(&right.get_columns())?;

    Ok(result)
