use itertools::Itertools;
use std::collections::HashMap;

/// Partitions elements of a list into groups where elements share the same first 5 characters.
/// 
/// # Arguments
/// * `input` - A slice of string slices to partition
/// 
/// # Returns
/// A vector of vectors, where each inner vector contains elements with identical first 5 characters.
/// Elements with fewer than 5 characters are grouped together under their actual length prefix.
/// 
/// # Example
/// ```
/// let data = vec!["hello_world", "hello_there", "world_peace", "world_domination", "hi"];
/// let result = partition_by_first_five(&data);
/// assert_eq!(result.len(), 3);
/// ```
pub fn partition_by_first_five<'a>(input: &[&'a str]) -> Vec<Vec<&'a str>> {
    // Create a HashMap to group elements by their first 5 characters
    let mut groups: HashMap<String, Vec<&'a str>> = HashMap::new();

    for &item in input {
        // Get the first 5 characters (or fewer if the string is shorter)
        let key = if item.len() >= 5 {
            item[..5].to_string()
        } else {
            item.to_string()
        };

        groups.entry(key).or_default().push(item);
    }

    // Convert the HashMap into a vector of vectors
    groups.into_values().collect()
}

/// Alternative implementation using itertools for more functional style
pub fn partition_by_first_five_itertools<'a>(input: &[&'a str]) -> Vec<Vec<&'a str>> {
    input
        .iter()
        .copied()
        .into_group_map_by(|&item| {
            if item.len() >= 5 {
                item[..5].to_string()
            } else {
                item.to_string()
            }
        })
        .into_values()
        .collect()
}

