# Rust Function for Partitioning by First 5 Characters

```rust
use std::collections::HashMap;

/// Partitions a list of strings into groups where each group contains
/// strings with identical first 5 characters.
///
/// # Arguments
/// * `items` - A vector of strings to partition
///
/// # Returns
/// A vector of vectors, where each inner vector contains strings
/// grouped by their first 5 characters
///
/// # Example
/// ```
/// let input = vec![
///     "hello_world".to_string(),
///     "hello_there".to_string(),
///     "apple_pie".to_string(),
///     "hellooo".to_string(),
/// ];
/// let result = partition_by_prefix(&input);
/// // Groups: ["hello_world", "hello_there", "hellooo"] and ["apple_pie"]
/// ```
fn partition_by_prefix(items: &[String]) -> Vec<Vec<String>> {
    let mut groups: HashMap<String, Vec<String>> = HashMap::new();

    for item in items {
        // Get first 5 characters (or the whole string if shorter)
        let key = item.chars().take(5).collect::<String>();
        groups.entry(key).or_insert_with(Vec::new).push(item.clone());
    }

    // Convert HashMap to Vec and sort for consistent output
    let mut result: Vec<Vec<String>> = groups.into_values().collect();
    result.sort_by(|a, b| a[0].cmp(&b[0]));
    result
}

fn main() {
    // Example usage
    let input = vec![
        "hello_world".to_string(),
        "hello_there".to_string(),
        "apple_pie".to_string(),
        "hellooo".to_string(),
        "apply_now".to_string(),
    ];

    let partitions = partition_by_prefix(&input);

    println!("Partitioned groups:");
    for (i, group) in partitions.iter().enumerate() {
        println!("Group {}: {:?}", i + 1, group);
    }
}
