use std::collections::HashMap;

/// Converts categorical columns in a DataFrame to binary indicator columns.
///
/// # Arguments
/// * `df` - Input DataFrame containing categorical columns
/// * `categorical_cols` - Names of columns to convert (None to convert all)
///
/// # Returns
/// DataFrame with categorical columns replaced by binary indicator columns
///
/// # Example
/// ```
