/// let df = df!(
///     "A" => &[1, 2, 1],
///     "B" => &["x", "y", "x"]
/// );
/// let result = categorical_to_indicators(df, None);
/// ```
pub fn categorical_to_indicators(df: DataFrame, categorical_cols: Option<Vec<String>>) -> Result<DataFrame, PolarsError> {
    // Determine which columns to process
    let cols_to_process = match categorical_cols {
        Some(cols) => cols,
        None => df.get_column_names().to_vec(),
    };

    // Create a new DataFrame builder
    let mut new_df = df.clone();

    for col_name in cols_to_process {
        // Check if column exists
        if !new_df.column(&col_name).is_ok() {
            continue;
        }

        // Get the categorical series
        let series = new_df.column(&col_name)?.unwrap();

        // Convert to categorical if not already
        let cat_series = match series {
            Series::Categorical(cat) => cat,
            _ => {
                let cat_series = Series::new(&col_name, &series)
                    .categorize(None, None)?
                    .unwrap_categorical();
                new_df = new_df.with_column(Series::new(&col_name, &cat_series))?;
                cat_series
            }
        };

        // Get unique categories
        let categories = cat_series.get_categories().unwrap();

        // Create binary columns
        for (i, category) in categories.iter().enumerate() {
            let binary_col_name = format!("{}_{}", col_name, category);

            // Create binary mask
            let mask = cat_series.get_values()
                .iter()
                .map(|v| v == category)
                .collect::<Vec<_>>();

            let binary_series = Series::new(&binary_col_name, &mask)
                .into_object()
                .cast(&DataType::Int64)?;

            // Add to new DataFrame
            new_df = new_df.with_column(binary_series)?;
        }

        // Remove original categorical column
        new_df = new_df.drop(&col_name)?;
    }

    Ok(new_df)
}

