use polars::prelude::*;

/// One-hot encode discrete category labels in a DataFrame.
///
/// This function converts all columns containing discrete category labels in the data table `df0`
/// into multiple binary integer columns, one for each unique label.
///
/// # Arguments
///
/// * `df0` - The input DataFrame.
///
/// # Returns
///
/// A new DataFrame with one-hot encoded category labels.
fn one_hot_encode(df0: &DataFrame) -> DataFrame {
    let mut df = df0.clone();

    for s in df0.columns() {
        let series = df0.column(s).unwrap();
        if series.dtype() == DataType::Utf8 {
