            for category in categories {
                let mut mask = series.eq(category).unwrap();
                mask.rename(format!("{}_{}", s, category).as_str());
                df = df.with_column(mask).unwrap();
            }
            df = df.drop(s).unwrap();
        }
    }

    df
}

