```rust
use anyhow::Result;
use polars::prelude::*;

/// Convert all discrete/category columns in `df0` into multiple binary integer columns,
/// one column per unique label, and return a new DataFrame with the original categorical
/// columns replaced by their one-hot columns.
///
/// Categorical columns detected: Utf8 (string) and Categorical(dyn).
///
/// Example:
/// let df_encoded = one_hot_encode_all(&df)?;
pub fn one_hot_encode_all(df0: &DataFrame) -> Result<DataFrame> {
    // Collect names of columns to dummy-encode: Utf8 (strings) and Categorical
    let cat_cols: Vec<&str> = df0
        .get_columns()
        .iter()
        .filter_map(|s| {
            match s.dtype() {
                DataType::Utf8 => Some(s.name().as_str()),
                DataType::Categorical(_) => Some(s.name().as_str()),
                _ => None,
            }
        })
        .collect();

    // If there are no categorical columns, return a clone of the original
    if cat_cols.is_empty() {
        return Ok(df0.clone());
    }

    // Create dummy columns only for the categorical columns
    // DataFrame::to_dummies accepts an Option<&[&str]> (None => all columns),
    // here supply only categorical column names.
    let dummies = df0.to_dummies(Some(&cat_cols))?;

    // Drop original categorical columns from the base frame
    let mut base = df0.clone();
    base.drop_many(&cat_cols)?;

    // Horizontally stack dummy columns onto the base DataFrame
    // dummies.get_columns() yields Vec<Series>
    base.hstack_mut(dummies.get_columns())?;

    Ok(base)
}

#[cfg(test)]
mod tests {
