                .unique()?
                .str()?
                .into_iter()
                .filter_map(|v| v.map(|s| s.to_string()))
                .collect();

            // Create a binary column for each unique value
            for unique_val in &unique_values {
                let binary_col_name = format!("{}_{}", col_name, unique_val);
                let binary_values: Vec<i32> = series
                    .str()?
                    .into_iter()
                    .map(|v| {
                        match v {
                            Some(val) if val == unique_val => 1,
                            _ => 0
                        }
                    })
                    .collect();

                new_columns.push(Series::new(&binary_col_name, binary_values));
            }
        }
    }

    // Remove original categorical columns
    for col in &columns_to_remove {
        df = df.drop(col)?;
    }

    // Add new binary columns to the DataFrame
    for col in new_columns {
        df = df.with_column(col)?;
    }

    Ok(df)
}

