Here's a self-contained Rust function that performs one-hot encoding on categorical columns using **Polars**, a modern dataframe library:

```rust
use polars::prelude::*;

fn one_hot_encode_categories(df: DataFrame) -> PolarsResult<DataFrame> {
    /// Convert all categorical columns in a DataFrame into binary one-hot encoded columns
    /// 
    /// For each categorical column, creates n binary columns (where n is the number of unique categories)
    /// Each binary column represents one category with 1 if present, 0 otherwise.
    ///
    /// # Arguments
    /// * `df` - Input DataFrame
    ///
    /// # Returns
    /// * `PolarsResult<DataFrame>` - DataFrame with categorical columns replaced by binary columns

    let mut result_df = df.clone();

    // Identify categorical columns (String/Utf8 types)
    let categorical_cols: Vec<String> = result_df
        .get_columns()
        .iter()
        .filter_map(|col| {
            if matches!(col.dtype(), DataType::String | DataType::Categorical(_, _)) {
                col.name().to_string().into()
            } else {
                None
            }
        })
        .collect();

    // Process each categorical column
    for col_name in categorical_cols {
        // Get the column and cast to string if needed
        let col = result_df.column(&col_name)?;
        let str_col = col.cast(&DataType::String)?;

        // Get unique values
        let unique_vals = str_col
            .unique()?
            .sort(false)?
            .str()?
            .to_vec();

        // Create binary columns for each unique value
        let mut new_cols = Vec::new();
        for category in unique_vals {
            let category_str = category.unwrap_or("null");
            let binary_col = str_col
                .equal(category_str)?
                .cast(&DataType::Int32)?;
            let new_col_name = format!("{}_{}", col_name, category_str);
            new_cols.push((new_col_name, binary_col));
        }

        // Drop original categorical column
        result_df = result_df.drop(&col_name)?;

        // Add new binary columns
        for (new_name, binary_col) in new_cols {
            result_df = result_df.with_column(binary_col.alias(&new_name))?;
        }
    }

    Ok(result_df)
}

