Here's a self-contained function using **`ndarray`** (a modern library for n-dimensional array operations):

```rust
use ndarray::{Array, ArrayD, IxDyn, Axis};

/// Clones an input vector a specified number of times along a given axis.
/// 
/// # Arguments
/// * `vector` - A 1D array (vector) to be cloned
/// * `repeats` - Number of times to repeat the vector
/// * `axis` - The axis along which to repeat (0 or 1 for 2D result)
///
/// # Returns
/// A 2D array with the vector repeated along the specified axis
///
/// # Example
/// ```
/// use ndarray::array;
/// 
/// let v = array![1, 2, 3];
/// let result = repeat_vector(&v.view(), 4, 0);
/// // Result shape: (4, 3) - vector repeated 4 times along axis 0
/// ```
pub fn repeat_vector(
    vector: &ndarray::ArrayView1<i32>,
    repeats: usize,
    axis: usize,
) -> ndarray::Array2<i32> {
    let vec_len = vector.len();

    match axis {
        0 => {
            // Stack the vector vertically (repeats × vec_len)
            let mut result = Array::zeros((repeats, vec_len));
            for i in 0..repeats {
                result.row_mut(i).assign(vector);
            }
            result
        }
        1 => {
            // Stack the vector horizontally (vec_len × repeats)
            let mut result = Array::zeros((vec_len, repeats));
            for i in 0..repeats {
                result.column_mut(i).assign(vector);
            }
            result
        }
        _ => panic!("Axis must be 0 or 1 for 2D arrays"),
    }
}

// Generic version supporting different data types
pub fn repeat_vector_generic<T: Clone + Default>(
    vector: &[T],
    repeats: usize,
    axis: usize,
) -> Vec<Vec<T>> {
    match axis {
        0 => {
            // Repeat along axis 0: create 'repeats' copies of the vector
            vec![vector.to_vec(); repeats]
        }
        1 => {
            // Repeat along axis 1: transpose-like operation
            vector
                .iter()
                .map(|elem| vec![elem.clone(); repeats])
                .collect()
        }
        _ => panic!("Axis must be 0 or 1"),
    }
}

fn main() {
    use ndarray::array;

    // Example 1: Using ndarray with integers
    let v = array![1, 2, 3];
    let result = repeat_vector(&v.view(), 4, 0);
    println!("Repeat along axis 0 (4 times):");
    println!("{}", result);

    let result = repeat_vector(&v.view(), 3, 1);
    println!("\nRepeat along axis 1 (3 times):");
    println!("{}", result);

    // Example 2: Using generic version with floats
    let vec_float = vec![1.5, 2.5, 3.5];
    let result_generic = repeat_vector_generic(&vec_float, 3, 0);
    println!("\nGeneric version with floats (axis 0):");
    for row in &result_generic {
        println!("{:?}", row);
    }

    let result_generic = repeat_vector_generic(&vec_float, 2, 1);
    println!("\nGeneric version with floats (axis 1):");
    for row in &result_generic {
        println!("{:?}", row);
    }
}
```

