Here's an example implementation of a function that multiplies a vector by a matrix without using any external libraries. This function utilizes Rust's built-in `iter` and `map` functions to perform the multiplication.

```rust
/// Represents a 2D matrix.
#[derive(Debug)]
struct Matrix {
    rows: usize,
    cols: usize,
    data: Vec<f64>,
}

impl Matrix {
    /// Creates a new matrix with the given dimensions and data.
    fn new(rows: usize, cols: usize, data: Vec<f64>) -> Self {
        assert_eq!(rows * cols, data.len());
        Matrix { rows, cols, data }
    }

    /// Multiplies this matrix by a vector.
    fn multiply_by_vector(&self, vector: &Vec<f64>) -> Vec<f64> {
        assert_eq!(self.cols, vector.len());
        (0..self.rows)
            .map(|row| {
                (0..self.cols)
                    .map(|col| self.data[row * self.cols + col] * vector[col])
                    .sum::<f64>()
            })
            .collect()
    }
}

/// Represents a vector.
#[derive(Debug)]
struct Vector {
    data: Vec<f64>,
}

impl Vector {
    /// Creates a new vector with the given data.
    fn new(data: Vec<f64>) -> Self {
        Vector { data }
    }
}

