// lib2025: tiny self-contained "library" (2025+) for vector×matrix multiplication
// No external crates. Mapping-based implementation using iterators.

pub mod lib2025 {
    /// Multiply a row vector `var0` by a matrix `var1`.
    ///
    /// - `var0` is treated as a 1×N row vector (slice of length N).
    /// - `var1` is an N×M matrix represented as a slice of N rows, each of length M.
    ///
    /// Returns Err if dimensions are inconsistent; otherwise returns a Vec<f64> of length M.
    pub fn mul_row_vector_by_matrix(var0: &[f64], var1: &[Vec<f64>]) -> Result<Vec<f64>, &'static str> {
        // Check sizes: number of rows in matrix must equal length of vector
        let n = var0.len();
        if var1.len() != n {
            return Err("dimension mismatch: vector length must equal number of matrix rows");
        }

        // Handle empty matrix (no columns). If n==0 and matrix empty, return empty result.
        // If matrix has at least one row, determine column count from first row and check consistency.
        let m = if n == 0 {
            // If there are zero rows, we define the result as an empty vector (no columns).
            return Ok(Vec::new());
        } else {
            var1[0].len()
        };

        // Verify all rows have same number of columns
        if !var1.iter().all(|row| row.len() == m) {
            return Err("inconsistent row lengths in matrix");
        }

        // For each column j, compute sum_i var0[i] * var1[i][j]
        // Mapping-based approach: map over column indices, and for each column map over row/vector pairs.
        let result: Vec<f64> = (0..m)
            .map(|j| {
                var1
                    .iter()
                    .zip(var0.iter())
                    .map(|(row, &v)| row[j] * v)
                    .fold(0.0f64, |acc, val| acc + val)
            })
            .collect();

        Ok(result)
    }

