/// Recursively compare two serde_json::Value objects treating JSON objects
/// (maps) as equal regardless of property order.
///
/// - Arrays are order-sensitive (compared index-by-index).
/// - Objects (maps) are order-insensitive: same set of keys and equal values => equal.
pub fn values_equal(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Null, Value::Null) => true,
        (Value::Bool(x), Value::Bool(y)) => x == y,
        (Value::Number(x), Value::Number(y)) => x == y,
        (Value::String(x), Value::String(y)) => x == y,
        (Value::Array(x), Value::Array(y)) => {
            if x.len() != y.len() {
                return false;
            }
            x.iter().zip(y.iter()).all(|(xi, yi)| values_equal(xi, yi))
        }
        (Value::Object(x), Value::Object(y)) => {
            if x.len() != y.len() {
                return false;
            }
            x.iter().all(|(k, v)| match y.get(k) {
                Some(v2) => values_equal(v, v2),
                None => false,
            })
        }
        _ => false, // different variant types (e.g., String vs Object)
    }
}

