use std::collections::HashMap;

/// Compares two key-value data objects for equality, regardless of order.
/// 
/// Returns `true` if both maps contain the same key-value pairs,
/// `false` otherwise.
///
/// # Arguments
/// * `map1` - First HashMap to compare
/// * `map2` - Second HashMap to compare
///
/// # Example
/// ```
/// let mut map1 = HashMap::from([("name", "Alice"), ("age", "30")]);
/// let mut map2 = HashMap::from([("age", "30"), ("name", "Alice")]);
/// assert!(maps_are_equal(&map1, &map2));
/// ```
fn maps_are_equal<K, V>(map1: &HashMap<K, V>, map2: &HashMap<K, V>) -> bool
where
    K: Eq + std::hash::Hash,
    V: PartialEq,
{
    // Quick check: different sizes means not equal
    if map1.len() != map2.len() {
        return false;
    }

    // Check that all keys and values in map1 exist in map2 with same values
    map1.iter().all(|(key, value1)| {
        map2.get(key).map_or(false, |value2| value1 == value2)
    })
}

