use std::cmp::Reverse;
use std::collections::BinaryHeap;
use ordered_float::OrderedFloat;

/// Example element type: must have a `var0` field (f64).
#[derive(Debug)]
struct Item {
    var0: f64,
    // other fields...
}

/// Return the indices of the top `n` elements in `lst0` by descending `var0`.
/// Result is sorted from largest var0 to smallest among the top-n.
///
/// - `lst0`: slice of elements each with a `var0: f64` field.
/// - `n`: how many indices to return. If n > lst0.len(), returns all indices sorted.
///
/// Complexity: O(len(lst0) * log(min(n, len(lst0))))
fn top_n_indices_by_var0(lst0: &[Item], n: usize) -> Vec<usize> {
    if n == 0 {
        return Vec::new();
    }

    // Maintain a min-heap (of size up to n) containing the current top-n items.
    // We store Reverse((OrderedFloat(var0), index)) so BinaryHeap (a max-heap) gives us the smallest var0 at the top.
    let mut heap: BinaryHeap<Reverse<(OrderedFloat<f64>, usize)>> = BinaryHeap::with_capacity(n.min(lst0.len()));

    for (i, item) in lst0.iter().enumerate() {
        let key = OrderedFloat(item.var0);
        let entry = Reverse((key, i));
        if heap.len() < n {
            heap.push(entry);
        } else if let Some(top) = heap.peek() {
            // top is the smallest var0 among the currently stored top-n; if current item is larger, replace it
            if entry.0 .0 > top.0 .0 {
                heap.pop();
                heap.push(entry);
            }
        }
    }

    // Extract and sort by descending var0, then return indices.
    let mut top_vec: Vec<(OrderedFloat<f64>, usize)> = heap.into_iter().map(|Reverse(pair)| pair).collect();
    // Sort descending by var0
    top_vec.sort_unstable_by(|a, b| b.0.cmp(&a.0));

    top_vec.into_iter().map(|(_key, idx)| idx).collect()
}

fn main() {
    // Example usage
