use polars::prelude::*;
use std::collections::HashMap;

/// Groups a DataFrame by one "Event" column and counts occurrences of values in another "Event" column within each group.
///
/// # Arguments
/// * `df` - The input DataFrame containing the data
/// * `group_by_col` - Name of the column to group by
/// * `count_col` - Name of the column to count occurrences of within each group
///
/// # Returns
/// A new DataFrame with two columns: the group key and the count of each value in the count column
///
/// # Example
/// ```
/// use polars::prelude::*;
/// let df = df!(
///     "Event1" => &["A", "B", "A", "C", "B", "A"],
///     "Event2" => &["X", "Y", "X", "Z", "Y", "X"]
/// ).unwrap();
///
/// let result = group_and_count(&df, "Event1", "Event2").unwrap();
/// // Result will show counts of Event2 values within each Event1 group
/// ```
pub fn group_and_count(df: &DataFrame, group_by_col: &str, count_col: &str) -> Result<DataFrame, PolarsError> {
    // Verify columns exist
    if !df.column(group_by_col).is_ok() {
        return Err(PolarsError::ComputeError(
            "Group by column not found".to_string()
        ));
    }
    if !df.column(count_col).is_ok() {
        return Err(PolarsError::ComputeError(
            "Count column not found".to_string()
        ));
    }

    // Create a new DataFrame with the grouped data
    let grouped = df
        .lazy()
        .group_by([group_by_col])
        .agg([col(count_col).value_counts()])
        .collect()?;

    // Rename columns for clarity
    let mut result = grouped
        .rename(&[
            (format!("{}.value_counts", count_col), "count"),
            (format!("{}.value_counts", count_col), "value") // This is a bit hacky - see note below
        ])?;

    // The value_counts() operation creates a struct column with two fields.
    // We need to extract them into separate columns.
    let value_counts_col = result.column("value_counts")?;
    let value_counts_series = value_counts_col.downcast::<Struct>(true)?;

    // Extract the two fields from the struct column
    let value_series = value_counts_series.field("value")?;
    let count_series = value_counts_series.field("count")?;

    // Create new DataFrame with extracted columns
    let mut new_df = DataFrame::new(vec![
        Series::new(group_by_col, result.column(group_by_col)?),
        Series::new("value", value_series),
        Series::new("count", count_series)
    ])?;

    // Reorder columns to have group key first
    new_df = new_df.reorder_columns(&[group_by_col, "value", "count"])?;

    Ok(new_df)
}

