use num_traits::Float;
use itertools::Itertools;

/// Generate a grid of points representing the Cartesian product of two intervals.
///
/// # Arguments
///
/// * `var0`: The start of the first interval.
/// * `var1`: The end of the first interval.
/// * `var2`: The start of the second interval.
/// * `var3`: The end of the second interval.
/// * `num_points`: The number of points to generate in each interval.
///
/// # Returns
///
/// A vector of tuples, where each tuple represents a point in the grid.
fn generate_grid<T>(var0: T, var1: T, var2: T, var3: T, num_points: usize) -> Vec<(T, T)>
where
    T: Float + Copy,
{
    let interval1: Vec<T> = (0..num_points)
        .map(|i| var0 + (var1 - var0) * (i as T) / (num_points as T - 1.0))
        .collect();

    let interval2: Vec<T> = (0..num_points)
        .map(|i| var2 + (var3 - var2) * (i as T) / (num_points as T - 1.0))
        .collect();

    interval1
        .into_iter()
        .cartesian_product(interval2)
        .collect()
}

