mod grid_2025 {
    /// Create `n` evenly spaced samples in [start, end], inclusive.
    /// - If n == 0 -> empty Vec
    /// - If n == 1 -> vec![start]
    pub fn linspace(start: f64, end: f64, n: usize) -> Vec<f64> {
        match n {
            0 => Vec::new(),
            1 => vec![start],
            _ => {
                let step = (end - start) / ((n - 1) as f64);
                (0..n).map(|i| start + step * (i as f64)).collect()
            }
        }
    }

