    /// Returns a Vec<[f64; 2]> where each entry is [x, y].
    pub fn cartesian_product_2d(xs: &[f64], ys: &[f64]) -> Vec<[f64; 2]> {
        let mut out = Vec::with_capacity(xs.len().saturating_mul(ys.len()));
        for &x in xs {
            for &y in ys {
                out.push([x, y]);
            }
        }
        out
    }
}

