use ndarray::{Array2, s};

/// Generate a grid of points representing the Cartesian product of two intervals.
///
/// # Arguments
/// * `var0` - Start of first interval
/// * `var1` - End of first interval
/// * `var2` - Start of second interval
/// * `var3` - End of second interval
/// * `num_points_x` - Number of points in the first dimension
/// * `num_points_y` - Number of points in the second dimension
///
