pub fn cartesian_product_grid(
    var0: f64,
    var1: f64,
    var2: f64,
    var3: f64,
    num_points_x: usize,
    num_points_y: usize,
) -> Array2<f64> {
    // Generate linearly spaced points for each interval
    let x_points = linspace(var0, var1, num_points_x);
    let y_points = linspace(var2, var3, num_points_y);

    // Create Cartesian product grid
    let total_points = num_points_x * num_points_y;
    let mut grid = Array2::zeros((total_points, 2));

    let mut idx = 0;
    for &y in y_points.iter() {
        for &x in x_points.iter() {
            grid[[idx, 0]] = x;
            grid[[idx, 1]] = y;
            idx += 1;
        }
    }

    grid
