/// // mse is ((0.1)^2 + (-0.1)^2 + ( -0.2)^2) / 3 = (0.01 + 0.01 + 0.04)/3 = 0.02
/// assert!((mse - 0.02).abs() < 1e-12);
/// ```
pub fn avg_squared_diff<T: ToF64, U: ToF64>(lst0: &[T], lst1: &[U]) -> Option<f64> {
