/// )?;
///
/// let result = group_and_sum(&df, "A", vec!["B", "C"])?;
/// println!("{:?}", result);
/// ```
pub fn group_and_sum(df: &DataFrame, group_by_col: &str, sum_cols: Vec<&str>) -> Result<DataFrame, Box<dyn Error>> {
    // Ensure the group_by column exists
    if !df.column(group_by_col).is_ok() {
