```rust
use polars::prelude::*;

/// Group the rows in `var1` by the corresponding keys in `var0`.
/// For each group, produce a single row whose columns are the sums
/// of the corresponding columns across rows in that group.
///
/// - `var0`: keys for each row (length must equal number of rows in var1)
/// - `var1_rows`: slice of rows; each inner Vec<f64> must have the same length
///
/// Returns a DataFrame with columns:
///   - "var0" (group key)
///   - "c0", "c1", ... summed numeric columns per group
pub fn group_sum_by_key(var0: &[String], var1_rows: &[Vec<f64>]) -> PolarsResult<DataFrame> {
    // basic validation
    if var0.len() != var1_rows.len() {
        return Err(PolarsError::ShapeMisMatch(
            "length of var0 must equal number of rows in var1".into(),
        ));
    }
    let nrows = var1_rows.len();
    let ncols = match var1_rows.get(0) {
        Some(first_row) => first_row.len(),
        None => {
            // no rows -> empty dataframe with only var0 distinct keys (none)
            let df = DataFrame::new(vec![Series::new("var0", Vec::<&str>::new())])?;
            return Ok(df);
        }
    };

    // Ensure all rows have same length
    for (i, row) in var1_rows.iter().enumerate() {
        if row.len() != ncols {
            return Err(PolarsError::ShapeMisMatch(
                format!("row {} has length {}, expected {}", i, row.len(), ncols).into(),
            ));
        }
    }

    // Build the Series for the key column (var0)
    let key_refs: Vec<&str> = var0.iter().map(|s| s.as_str()).collect();
    let key_series = Series::new("var0", key_refs);

    // Build numeric columns as Series c0, c1, ...
    let mut cols: Vec<Series> = vec![key_series];
    for col_idx in 0..ncols {
        let mut col_vals = Vec::with_capacity(nrows);
        for row in var1_rows {
            col_vals.push(row[col_idx]);
        }
        cols.push(Series::new(&format!("c{}", col_idx), col_vals));
    }

    // Build DataFrame and group+sum
    let df = DataFrame::new(cols)?;
    let grouped = df.groupby(&["var0"])?.sum()?;
    Ok(grouped)
}

fn main() -> PolarsResult<()> {
    // Example usage
    let var0 = vec![
        "A".to_string(),
        "B".to_string(),
        "A".to_string(),
        "C".to_string(),
        "B".to_string(),
    ];
    let var1_rows = vec![
        vec![1.0, 10.0],
        vec![2.0, 20.0],
        vec![3.0, 30.0],
        vec![4.0, 40.0],
        vec![5.0, 50.0],
    ];

    let result = group_sum_by_key(&var0, &var1_rows)?;
