use num_bigint::BigInt;
use serde_json::Value;
use std::str::FromStr;

/// Returns true iff every element in `items` is:
///  - a two-item array/sequence, and
///  - the first item can be parsed as a BigInt (wide-range integer), and
///  - the second item can be parsed as an i64 (standard integer).
///
/// The function accepts JSON-like values:
///  - For the first component: accepts JSON number or JSON string that parses as an integer (arbitrary size).
///  - For the second component: accepts JSON number (fits in i64) or JSON string that parses as i64.
pub fn check_two_item_bigint_pairs(items: &[Value]) -> bool {
    fn parse_bigint_from_value(v: &Value) -> Option<BigInt> {
        match v {
            Value::String(s) => BigInt::from_str(s).ok(),
            Value::Number(n) => {
                // Use the numeric textual representation to preserve full precision if it's too large for i64/u64.
                // serde_json::Number implements Display producing the exact JSON numeric text.
                let s = n.to_string();
                BigInt::from_str(&s).ok()
            }
            _ => None,
        }
    }

    fn parse_i64_from_value(v: &Value) -> Option<i64> {
        match v {
            Value::Number(n) => {
                // Prefer as_i64(); if not available, try as_u64 and check range.
                if let Some(i) = n.as_i64() {
                    Some(i)
                } else if let Some(u) = n.as_u64() {
                    if u <= i64::MAX as u64 {
                        Some(u as i64)
                    } else {
                        None
                    }
                } else {
                    None
                }
            }
            Value::String(s) => s.parse::<i64>().ok(),
            _ => None,
        }
    }

    for item in items {
        // Each element must be an array of length 2
        let arr = match item {
            Value::Array(a) if a.len() == 2 => a,
            _ => return false,
        };

        // First must be parseable as BigInt
        if parse_bigint_from_value(&arr[0]).is_none() {
            return false;
        }

        // Second must be parseable as i64
        if parse_i64_from_value(&arr[1]).is_none() {
            return false;
        }
    }

    true
}

