use polars::prelude::*;
use std::error::Error;

/// Counts occurrences of each unique value in the first column of a tabular dataset.
///
/// # Arguments
/// * `data` - A string slice containing tabular data (CSV format with headers)
///
/// # Returns
/// * A `Result` containing a `DataFrame` with two columns:
///   - "value": The unique values from the first column
///   - "count": The number of occurrences for each value
///
/// # Errors
/// Returns an error if the data cannot be parsed or if the DataFrame is empty.
///
/// # Example
/// ```
/// let data = "name,age\nAlice,30\nBob,25\nAlice,35\nCharlie,30\nBob,28";
/// let result = count_first_column_occurrences(data).unwrap();
/// println!("{}", result);
/// // Output:
/// // shape: (3, 2)
/// // ┌─────────┬───────┐
/// // │ value   ┆ count │
/// // ╞═════════╪═══════╡
/// // │ Alice   ┆ 2     │
/// // │ Bob     ┆ 2     │
/// // │ Charlie ┆ 1     │
/// // └─────────┴───────┘
/// ```
pub fn count_first_column_occurrences(data: &str) -> Result<DataFrame, Box<dyn Error>> {
    // Parse the CSV data into a DataFrame
    let df = CsvReader::new(std::io::Cursor::new(data))
        .has_header(true)
        .finish()?;

    // Check if DataFrame is empty
    if df.is_empty() {
        return Err("DataFrame is empty".into());
    }

    // Get the first column name
    let first_col_name = df.get_column_names()[0].to_string();

    // Select the first column and count occurrences
    let result = df
        .lazy()
        .select([col(&first_col_name).alias("value")])
        .group_by([col("value")])
        .agg([col("value").count().alias("count")])
        .collect()?;

    Ok(result)
}

