/// Count occurrences of each unique value in the first column of a dataset
/// 
/// # Arguments
/// * `data` - A 2D vector where each inner vector represents a row
/// 
/// # Returns
/// A HashMap with unique values from the first column as keys and their counts as values
fn count_first_column_occurrences(data: Vec<Vec<String>>) -> Result<HashMap<String, u32>> {
    // Create a DataFrame from the data
    let first_column: Vec<String> = data.iter().map(|row| row[0].clone()).collect();

