    // Use value_counts to get counts
    let value_counts = df
        .clone()
        .lazy()
        .select([col("col1").value_counts(true, true)])
        .collect()?
        .unnest(["col1"])?;

    // Extract results into HashMap
    let mut result = HashMap::new();
    let values = value_counts.column("col1")?.str()?.into_iter();
    let counts = value_counts.column("counts")?.u32()?.into_iter();

    for (val, count) in values.zip(counts) {
        if let (Some(v), Some(c)) = (val, count) {
            result.insert(v.to_string(), c);
