/// let subset = extract_subset(&entries, 1, 2);
/// assert_eq!(subset, vec!["banana", "cherry"]);
/// ```
pub fn extract_subset<T, I>(entries: &[T], start: usize, end: usize) -> Vec<&T>
where
    T: Clone,
{
    // Bounds checking
    if start > end {
        panic!("Start index must be less than or equal to end index");
    }
    if start >= entries.len() || end >= entries.len() {
        panic!("Index out of bounds");
    }

    // Extract the subset
    entries[start..=end].to_vec()
}

