///     Ok(())
/// }
/// ```
pub fn calculate_missing_percentages(df0: &DataFrame) -> Result<DataFrame, Box<dyn Error>> {
    // Calculate the number of missing values for each column
    let missing_counts = df0.null_count()?;

    // Calculate the total number of rows (non-null rows)
    let total_rows = df0.height() as f64;

    // Create a new DataFrame with column names and missing percentages
    let mut result = DataFrame::default();

    for (col_name, null_count) in missing_counts {
