/// Calculates the percentage of missing entries for each column in a DataFrame
/// 
/// # Arguments
/// * `df0` - A Polars DataFrame to analyze
///
/// # Returns
/// * `Result<DataFrame>` - A DataFrame with column names and their missing percentages
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let df = df! {
///     "A" => &[Some(1), None, Some(3)],
///     "B" => &[Some(4.0), Some(5.0), None],
///     "C" => &[Some("x"), Some("y"), Some("z")],
/// }.unwrap();
///
/// let result = calculate_missing_percentage(&df).unwrap();
/// println!("{}", result);
/// ```
fn calculate_missing_percentage(df0: &DataFrame) -> PolarsResult<DataFrame> {
    let mut column_names = Vec::new();
    let mut missing_percentages = Vec::new();

    for column_name in df0.get_column_names() {
        column_names.push(column_name.to_string());

        let series = df0.column(column_name)?;
        let total_entries = series.len() as f64;
        let null_count = series.null_count() as f64;
        let missing_percentage = (null_count / total_entries) * 100.0;

        missing_percentages.push(missing_percentage);
    }

    // Create result DataFrame with column names and their missing percentages
    DataFrame::new(vec![
        Series::new("column".into(), column_names)?,
        Series::new("missing_percentage".into(), missing_percentages)?,
    ])
}

fn main() -> PolarsResult<()> {
    // Example usage
    let df = df! {
        "A" => &[Some(1), None, Some(3), None, Some(5)],
