    let value = match df0.column(var0).unwrap().dtype() {
        DataType::Utf8 => Series::new(var0, vec![var1.to_string()])?,
        DataType::Int64 => Series::new(var0, vec![var1.parse::<i64>()?])?,
        DataType::Float64 => Series::new(var0, vec![var1.parse::<f64>()?])?,
