    let mut summed_map: HashMap<String, i32> = HashMap::new();

    // Iterate over each key-value mapping in the list.
    for mapping in lst0 {
        // Iterate over each key-value pair in the mapping.
        for (key, value) in mapping {
            // If the key already exists in the summed map, add the value to its current sum.
            // Otherwise, insert the key with its value into the summed map.
            *summed_map.entry(key).or_insert(0) += value;
        }
    }

    // Convert the summed HashMap to a BTreeMap, which automatically sorts its entries.
    let mut sorted_map: BTreeMap<String, i32> = BTreeMap::new();
    for (key, value) in summed_map {
        sorted_map.insert(key, value);
    }

    // Sort the BTreeMap by value in descending order.
    let mut sorted_map_by_value: BTreeMap<i32, Vec<String>> = BTreeMap::new();
