///
/// Behavior:
/// - If `df0` is empty, returns an empty Vec.
/// - If some rows are shorter than the header, missing values become empty strings in the output.
pub fn remove_columns_by_name(df0: &[Vec<String>], lst0: &[&str]) -> Vec<Vec<String>> {
    if df0.is_empty() {
        return Vec::new();
    }

    // Build a set of names to drop for O(1) lookup
    let drop_set: HashSet<&str> = lst0.iter().cloned().collect();

    // Determine which column indices to keep based on the header row
    let header = &df0[0];
    let keep_indices: Vec<usize> = header
        .iter()
        .enumerate()
