        .collect();

    // Build the resulting table by selecting only kept indices for every row
    df0.iter()
        .map(|row| {
            keep_indices
                .iter()
                .map(|&i| row.get(i).cloned().unwrap_or_else(|| String::new()))
                .collect::<Vec<String>>()
        })
        .collect()
}

