/// assert_eq!(result, vec![
///     vec![1, 3],
///     vec![1, 4],
///     vec![2, 3],
///     vec![2, 4],
/// ]);
/// ```
pub fn cartesian_product<T: Clone>(lst0: &[Vec<T>]) -> Vec<Vec<T>> {
    if lst0.is_empty() {
        return vec![vec![]];
    }

    // Start with the first sublist's elements as individual sequences
    let mut result: Vec<Vec<T>> = lst0[0]
        .iter()
        .map(|item| vec![item.clone()])
        .collect();

