use polars::prelude::*;
use std::error::Error;

/// Updates values in `df0` based on corresponding values from `df1` for matching columns.
///
/// # Arguments
/// * `df0` - The DataFrame to be updated (modified in-place)
/// * `df1` - The DataFrame containing the new values
/// * `update_columns` - List of columns to update (if None, all matching columns are updated)
///
/// # Returns
/// Result<(), Box<dyn Error>> - Ok if successful, Err with error details if failed
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let df0 = df!(
///     "A" => &[1, 2, 3],
///     "B" => &[4.0, 5.0, 6.0],
///     "C" => &["x", "y", "z"]
/// ).unwrap();
///
/// let df1 = df!(
///     "A" => &[10, 20, 30],
///     "B" => &[40.0, 50.0, 60.0]
/// ).unwrap();
///
/// update_dataframe_values(&mut df0, &df1, None).unwrap();
/// ```
pub fn update_dataframe_values(
    df0: &mut DataFrame,
    df1: &DataFrame,
    update_columns: Option<&[&str]>,
) -> Result<(), Box<dyn Error>> {
    // Check if DataFrames have the same number of rows
    if df0.height() != df1.height() {
        return Err("DataFrames must have the same number of rows".into());
    }

    // Get common columns between df0 and df1
    let df0_columns = df0.get_column_names();
    let df1_columns = df1.get_column_names();

    let columns_to_update = match update_columns {
        Some(columns) => {
            // Filter columns that exist in both DataFrames
            columns
                .iter()
                .filter(|col| df0_columns.contains(*col) && df1_columns.contains(*col))
                .cloned()
                .collect::<Vec<_>>()
        }
        None => {
            // Find intersection of columns
            df0_columns
                .iter()
                .filter(|col| df1_columns.contains(*col))
                .cloned()
                .collect::<Vec<_>>()
        }
    };

    if columns_to_update.is_empty() {
        return Ok(()); // No columns to update
    }

    // Update each column
    for col_name in columns_to_update {
        let df0_series = df0.column(&col_name)?;
        let df1_series = df1.column(&col_name)?;

        // Check if types are compatible
        if df0_series.dtype() != df1_series.dtype() {
            return Err(format!(
                "Type mismatch for column '{}': {} vs {}",
                col_name,
                df0_series.dtype(),
                df1_series.dtype()
            )
            .into());
        }

        // Update the column in df0
        df0.set_column(col_name, df1_series)?;
    }

    Ok(())
}

