# Rust Function for Conditional Cell Updates Between DataFrames

```rust
use polars::prelude::*;

/// Updates specific cells in df0 based on values from corresponding cells in df1.
/// 
/// # Arguments
/// * `df0` - The primary dataframe whose cells will be updated
/// * `df1` - The source dataframe containing the new values
/// * `condition_col` - Column name to use as a condition for updating
/// * `condition_value` - The value that triggers an update
/// 
/// # Returns
/// A new dataframe with updated cells
fn update_cells_conditional(
    df0: &DataFrame,
    df1: &DataFrame,
    condition_col: &str,
    condition_value: i32,
) -> PolarsResult<DataFrame> {
    // Verify both dataframes have the same shape
    if df0.shape() != df1.shape() {
        return Err(PolarsError::ComputeError(
            "DataFrames must have the same shape".into(),
        ));
    }

    // Get the condition column from df1
    let condition_series = df1.column(condition_col)?;
    let mask = condition_series
        .equal(condition_value)?;

    // Clone df0 to modify
    let mut result = df0.clone();

    // Update each column in result based on the mask
    for col_name in result.get_column_names() {
        let original = result.column(col_name)?;
        let update_source = df1.column(col_name)?;

        // Use where to conditionally update: if mask is true, use df1 value, else keep df0 value
        let updated = update_source.zip_with(&mask, original)?;
        result = result.with_column(updated.alias(col_name))?;
    }

    Ok(result)
}

