use polars::prelude::*;

fn rename_row_label(
    mut df: DataFrame,
    row_index: usize,
    new_label: String,
) -> Result<DataFrame, PolarsError> {
    // Get the current index name or use default
    let index_name = df.get_column_names()[0].to_string();

    // Convert DataFrame to a mutable series for the index column
    let mut index_col = df
        .select([&index_name])?
        .to_series()
        .clone();

    // Check if row index is valid
    if row_index >= index_col.len() {
        return Err(PolarsError::ComputeError(
            format!("Row index {} out of bounds", row_index).into(),
        ));
    }

    // Cast to string series and rename the value at row_index
    let str_series = index_col.cast(&DataType::String)?;
    let mut values: Vec<String> = str_series
        .str()?
        .into_iter()
        .map(|opt| opt.map(|s| s.to_string()))
        .collect::<Vec<_>>()
        .into_iter()
        .map(|opt| opt.unwrap_or_default())
        .collect();

    values[row_index] = new_label;

