    LessThan,
    LessThanOrEqual,
    GreaterThan,
    GreaterThanOrEqual,
    Equal,
    Approximate,
    Unknown(String),
}

#[derive(Debug, Clone, PartialEq)]
pub struct Extraction {
    // The original matched substring (trimmed)
    pub text: String,
    // Comparator type (if recognized)
    pub comparator: Comparator,
    // One or more numeric values parsed from the match (percent_flag is parallel)
    pub values: Vec<f64>,
    // Whether each value had a trailing percent sign (true if it was "5%")
    pub percent: Vec<bool>,
    // Byte indices into the original text
    pub start: usize,
    pub end: usize,
