pub fn extract_numerical_comparisons(var0: &str) -> Vec<Extraction> {
    static RE_BETWEEN: Lazy<Regex> = Lazy::new(|| {
        // between X and Y  (allow "to" and hyphen too)
        Regex::new(r"(?i)\bbetween\s+([+-]?\d+(?:\.\d+)?%?)\s+(?:and|to|-)\s+([+-]?\d+(?:\.\d+)?%?)\b").unwrap()
    });

    static RE_COMPARISON_WORDS: Lazy<Regex> = Lazy::new(|| {
        // phrases like "less than", "greater than or equal to", "about", etc.
        // capture comparator phrase and a number
        Regex::new(r"(?i)\b(no more than|no less than|less than or equal to|less than|at most|at least|greater than or equal to|greater than|more than|equal to|equal|approximately|approx(?:\.)?|around|about)\s+([+-]?\d+(?:\.\d+)?%?)\b").unwrap()
    });

    static RE_COMPARISON_SYMBOLS: Lazy<Regex> = Lazy::new(|| {
        // symbols like <=, >=, <, >, = optionally followed by number
        Regex::new(r"(?P<op><=|>=|<|>|=)\s*([+-]?\d+(?:\.\d+)?%?)").unwrap()
    });

    static RE_RANGE_DASH: Lazy<Regex> = Lazy::new(|| {
        // numeric dash numeric: "5-10", "5 - 10", "5–10"
        Regex::new(r"\b([+-]?\d+(?:\.\d+)?%?)\s*[-–—]\s*([+-]?\d+(?:\.\d+)?%?)\b").unwrap()
    });

    // Helper to parse "12%" -> (12.0, true)
    fn parse_number_token(tok: &str) -> Option<(f64, bool)> {
        let tok = tok.trim();
        if tok.ends_with('%') {
            let num = &tok[..tok.len()-1];
            if let Ok(v) = num.parse::<f64>() { Some((v, true)) } else { None }
        } else {
            if let Ok(v) = tok.parse::<f64>() { Some((v, false)) } else { None }
