    let mut used_ranges: Vec<(usize, usize)> = Vec::new();
    let mut result: Vec<Extraction> = Vec::new();

    // Helper: check overlap
    fn overlaps_any(start: usize, end: usize, used: &[(usize, usize)]) -> bool {
        used.iter().any(|&(s,e)| !(end <= s || start >= e))
    }

    // Pattern order: between -> dash ranges -> word comparisons -> symbol comparisons
