#[derive(Debug, Clone)]
pub struct NumberWithComparison {
    pub number: String,
    pub comparison: String,
    pub full_match: String,
}

/// Extracts numerical values with comparison terms or range expressions from text
/// 
/// # Arguments
/// * `var0` - Input text to parse
/// 
/// # Returns
/// A vector of NumberWithComparison structs containing extracted values
/// 
/// # Examples
/// ```
