/// let results = extract_numbers_with_comparisons(input);
/// // Results will include:
/// // - "greater than 5"
/// // - "less than 10"
/// // - "between 2 and 8"
/// ```
pub fn extract_numbers_with_comparisons(var0: &str) -> Vec<NumberWithComparison> {
    // Regex pattern to match comparison terms with numbers
    // Matches: (comparison_term) (number) or (number) (comparison_term)
    let pattern = Regex::new(
        r"(?i)\b(less\s+than|greater\s+than|more\s+than|at\s+least|at\s+most|between|approximately|around|roughly|exactly|up\s+to|over|under|above|below|exceeds?|within)?\s*(-?\d+\.?\d*)\s*(and\s+(-?\d+\.?\d*))?\b"
    ).unwrap();

    let mut results = Vec::new();

    for caps in pattern.captures_iter(var0) {
        let full_match = caps.get(0).map(|m| m.as_str()).unwrap_or("");
        let comparison = caps.get(1).map(|m| m.as_str()).unwrap_or("").trim().to_lowercase();
        let first_number = caps.get(2).map(|m| m.as_str()).unwrap_or("");
        let second_number = caps.get(4).map(|m| m.as_str()).unwrap_or("");

        // Build the number string (handle ranges)
        let number = if !second_number.is_empty() {
            format!("{} and {}", first_number, second_number)
        } else {
            first_number.to_string()
        };

        // Build comparison string
        let final_comparison = if comparison.is_empty() && second_number.is_empty() {
            "value".to_string()
        } else if !second_number.is_empty() {
            "between".to_string()
        } else {
            comparison.clone()
        };

        results.push(NumberWithComparison {
            number,
            comparison: final_comparison,
            full_match: full_match.to_string(),
        });
    }

    results
}

