    fn key_from_value(v: &Value) -> String {
        match v {
            Value::String(s) => s.clone(),
            Value::Number(n) => n.to_string(),
            Value::Bool(b) => b.to_string(),
            Value::Null => "null".to_string(),
            other => other.to_string(), // fallback (arrays/objects)
        }
    }

    // helper: try to extract a f64 from Value
    fn value_to_f64(v: &Value) -> Option<f64> {
        match v {
            Value::Number(n) => n.as_f64(),
            Value::String(s) => s.parse::<f64>().ok(),
            Value::Bool(b) => Some(if *b { 1.0 } else { 0.0 }),
            _ => None,
        }
    }

    // First pass: accumulate sum and count per group
    let mut acc: HashMap<String, (f64, usize)> = HashMap::new();
    for row in df0.iter() {
        let key = row.get(var0).map(key_from_value).unwrap_or_else(|| "null".to_string());
        if let Some(v) = row.get(var1) {
            if let Some(x) = value_to_f64(v) {
                let entry = acc.entry(key).or_insert((0.0_f64, 0_usize));
                entry.0 += x;
                entry.1 += 1;
            } else {
                // skip non-numeric var1 values
            }
        } else {
            // missing var1, skip
        }
    }

    // Compute mean per group
    let mut stats: HashMap<String, (f64, f64)> = HashMap::new(); // key -> (mean, sum)
    for (k, (sum, count)) in acc.into_iter() {
        let mean = if count > 0 { sum / (count as f64) } else { f64::NAN };
        stats.insert(k, (mean, sum));
    }

    // Second pass: write new columns to each row
    let mean_col = format!("{}_mean", var1);
    let sum_col = format!("{}_sum", var1);

    for row in df0.iter_mut() {
        let key = row.get(var0).map(key_from_value).unwrap_or_else(|| "null".to_string());
        if let Some((mean, sum)) = stats.get(&key) {
            row.insert(mean_col.clone(), Value::Number(serde_json::Number::from_f64(*mean).unwrap_or_else(|| serde_json::Number::from_f64(f64::NAN).unwrap())));
            row.insert(sum_col.clone(), Value::Number(serde_json::Number::from_f64(*sum).unwrap_or_else(|| serde_json::Number::from_f64(f64::NAN).unwrap())));
        } else {
            // group not present in stats (no numeric var1 in that group) -> inject nulls
            row.insert(mean_col.clone(), Value::Null);
            row.insert(sum_col.clone(), Value::Null);
        }
    }

    Ok(())
}

