```rust
use polars::prelude::*;

/// Adds group mean and sum columns to a DataFrame based on grouping variable
/// 
/// # Arguments
/// * `df0` - Input DataFrame with columns "var0" (grouping) and "var1" (numeric values)
/// 
/// # Returns
/// * Result containing the updated DataFrame with new columns "var0_mean" and "var0_sum"
/// 
/// # Example
/// ```
/// use polars::prelude::*;
/// 
/// let df = df!(
///     "var0" => &["A", "A", "B", "B"],
///     "var1" => &[10, 20, 30, 40],
/// ).unwrap();
/// 
/// let result = add_group_statistics(df).unwrap();
/// println!("{}", result);
/// ```
fn add_group_statistics(mut df0: DataFrame) -> PolarsResult<DataFrame> {
    // Calculate mean for each group in var0
    let mean_col = df0
        .clone()
        .lazy()
        .group_by([col("var0")])
        .agg([col("var1").mean().alias("var0_mean")])
        .collect()?;

    // Calculate sum for each group in var0
    let sum_col = df0
        .clone()
        .lazy()
        .group_by([col("var0")])
        .agg([col("var1").sum().alias("var0_sum")])
        .collect()?;

    // Join mean values back to original dataframe
    df0 = df0
        .lazy()
        .join(
            mean_col.lazy(),
            [col("var0")],
            [col("var0")],
            JoinArgs::new(JoinType::Left),
        )
        .collect()?;

    // Join sum values back to original dataframe
    df0 = df0
        .lazy()
        .join(
            sum_col.lazy(),
            [col("var0")],
            [col("var0")],
            JoinArgs::new(JoinType::Left),
        )
        .collect()?;

    Ok(df0)
}

