use polars::prelude::*;

/// For each row in `df0`, returns the name of the column containing the highest numeric value.
/// Non-numeric columns are ignored. If a row has no numeric (non-null) values, the returned name is an empty string.
/// Ties: the first (leftmost) column with the max value is chosen.
pub fn max_column_per_row(df0: &DataFrame) -> PolarsResult<Series> {
    // Collect numeric columns cast to float64 so we can compare uniformly.
    let mut numeric_cols: Vec<(String, ChunkedArray<Float64Type>)> = Vec::new();

    for s in df0.get_columns() {
        match s.dtype() {
            DataType::Float32
            | DataType::Float64
            | DataType::Int8
            | DataType::Int16
            | DataType::Int32
            | DataType::Int64
            | DataType::UInt8
            | DataType::UInt16
            | DataType::UInt32
            | DataType::UInt64 => {
                let casted = s.cast(&DataType::Float64)?;
                let ca = casted.f64()?.clone();
                numeric_cols.push((s.name().to_string(), ca));
            }
            _ => {
                // skip non-numeric columns
            }
        }
    }

    let height = df0.height();

    // If there are no numeric columns, return a series of empty strings
    if numeric_cols.is_empty() {
        let empty_names = vec![""; height];
        return Ok(Series::new("max_col", empty_names));
    }

    // For each row, find the numeric column with the max value
    let mut winners: Vec<String> = Vec::with_capacity(height);

    for row_idx in 0..height {
        let mut best_idx: Option<usize> = None;
        let mut best_val: f64 = f64::NEG_INFINITY;

        for (col_idx, (_name, col)) in numeric_cols.iter().enumerate() {
            match col.get(row_idx) {
                Some(v) if !v.is_nan() => {
                    if best_idx.is_none() || v > best_val {
                        best_val = v;
                        best_idx = Some(col_idx);
                    }
                }
                _ => {
                    // null or NaN: skip
                }
            }
        }

        if let Some(idx) = best_idx {
            winners.push(numeric_cols[idx].0.clone());
        } else {
            // no numeric non-null value in this row
            winners.push(String::new());
        }
    }

    Ok(Series::new("max_col", winners))
}

