/// println!("{:?}", result); // Should show: ["B", "A", "B"]
/// ```
pub fn get_highest_value_column(df: &DataFrame) -> Result<Series, Box<dyn Error>> {
    // Get column names
    let column_names: Vec<&str> = df.get_column_names().iter().map(|s| s.as_str()).collect();

    // Convert all columns to f64 for comparison
    let numeric_cols: Vec<Series> = column_names.iter()
        .map(|name| df.column(name).unwrap().cast(&DataType::Float64).unwrap())
        .collect();

    // Stack all columns horizontally
    let stacked = DataFrame::new(numeric_cols)?;

    // Find the index of the maximum value in each row
    let max_indices = stacked
        .to_ndarray::<Float64Type>()?
        .rows()
        .into_iter()
        .map(|row| {
            row.iter()
                .enumerate()
                .max_by(|(_, a), (_, b)| a.partial_cmp(b).unwrap())
                .map(|(idx, _)| idx)
                .unwrap_or(0)
        })
        .collect::<Vec<usize>>();

    // Map indices back to column names
    let result: Vec<&str> = max_indices.iter()
        .map(|&idx| column_names[idx])
        .collect();

    Ok(Series::new("highest_column", result))
}

