                        let fields = struct_series.fields();

                        // Find index of maximum value
                        let max_idx = fields.iter()
                            .enumerate()
                            .max_by(|(_, a), (_, b)| {
                                let a_val = a.f64().unwrap().get(0).unwrap_or(f64::NEG_INFINITY);
                                let b_val = b.f64().unwrap().get(0).unwrap_or(f64::NEG_INFINITY);
                                a_val.partial_cmp(&b_val).unwrap()
                            })
                            .map(|(idx, _)| idx)
                            .unwrap_or(0);

