# Rust Version Sorting Function

```rust
use std::cmp::Ordering;

/// Sorts a list of version identifiers in ascending order.
/// 
/// Each version is composed of numeric segments separated by dots (e.g., "1.2.3").
/// Versions are compared segment by segment numerically, not lexicographically.
/// 
/// # Arguments
/// * `versions` - A mutable slice of version strings
/// 
/// # Example
/// ```
/// let mut versions = vec!["1.9.0", "1.10.0", "1.2.0", "2.0.0"];
/// sort_versions(&mut versions);
/// assert_eq!(versions, vec!["1.2.0", "1.9.0", "1.10.0", "2.0.0"]);
/// ```
fn sort_versions(versions: &mut [&str]) {
    versions.sort_by(|a, b| {
        let a_parts: Vec<u64> = a
            .split('.')
            .filter_map(|s| s.parse::<u64>().ok())
            .collect();

        let b_parts: Vec<u64> = b
            .split('.')
            .filter_map(|s| s.parse::<u64>().ok())
            .collect();

        // Compare segment by segment
        for i in 0..a_parts.len().max(b_parts.len()) {
            let a_segment = a_parts.get(i).copied().unwrap_or(0);
            let b_segment = b_parts.get(i).copied().unwrap_or(0);

            match a_segment.cmp(&b_segment) {
                Ordering::Equal => continue,
                other => return other,
            }
        }

        Ordering::Equal
    });
}

fn main() {
    // Example usage
    let mut versions = vec!["1.9.0", "1.10.0", "1.2.0", "2.0.0", "1.10.1", "1.10.0.1"];
    println!("Before sorting: {:?}", versions);

