/// Remove columns from `mat0` whose indices appear in `columns_to_delete`.
///
/// - `mat0` is a slice of rows; each row is a Vec<T>.
/// - Rows must have equal length (checked at runtime).
/// - Out-of-range indices in `columns_to_delete` are ignored.
/// - Duplicate indices in `columns_to_delete` are handled gracefully.
///
/// Returns `Err(&'static str)` if input rows have mismatched lengths,
/// otherwise returns the new matrix with columns removed.
///
/// Example:
/// let mat = vec![vec![1,2,3], vec![4,5,6]];
/// let res = remove_columns(&mat, &[0, 2]).unwrap();
/// // res == vec![vec![2], vec![5]]
pub fn remove_columns<T: Clone>(
    mat0: &[Vec<T>],
    columns_to_delete: &[usize],
) -> Result<Vec<Vec<T>>, &'static str> {
    // Empty input: nothing to do
    if mat0.is_empty() {
        return Ok(Vec::new());
    }

    // Determine number of columns and validate all rows have the same length
    let ncols = mat0[0].len();
    for (i, row) in mat0.iter().enumerate().skip(1) {
        if row.len() != ncols {
            return Err("inconsistent row lengths in matrix");
        }
    }

    // Build a mask of columns to keep; default true (keep)
    let mut keep = vec![true; ncols];
    for &col in columns_to_delete {
        if col < ncols {
            keep[col] = false;
        }
        // out-of-range columns are ignored
    }

    // Prepare output: each row filtered by the keep mask
    let mut out = Vec::with_capacity(mat0.len());
    for row in mat0 {
        let mut new_row = Vec::with_capacity(ncols); // upper bound
        for (j, item) in row.iter().enumerate() {
            if keep[j] {
                new_row.push(item.clone());
            }
        }
        out.push(new_row);
    }

    Ok(out)
}

