use ndarray::{Array2, Axis};

/// Removes columns from a 2D matrix based on indices to delete.
///
/// # Arguments
/// * `mat0` - Input 2D matrix
/// * `columns_to_delete` - Slice of column indices to remove
///
/// # Returns
/// A new matrix with the specified columns removed
///
/// # Panics
/// Panics if any column index in `columns_to_delete` is out of bounds
///
/// # Example
/// ```
/// use ndarray::arr2;
/// 
/// let mat = arr2(&[[1, 2, 3, 4],
///                  [5, 6, 7, 8]]);
/// let result = remove_columns(&mat, &[1, 3]);
/// // Result: [[1, 3],
/// //          [5, 7]]
/// ```
pub fn remove_columns(mat0: &Array2<i32>, columns_to_delete: &[usize]) -> Array2<i32> {
    // Handle edge case: empty matrix
    if mat0.is_empty() {
        return mat0.clone();
    }

    let num_cols = mat0.ncols();

    // Validate indices
    for &col in columns_to_delete {
        assert!(
            col < num_cols,
            "Column index {} is out of bounds for matrix with {} columns",
            col,
            num_cols
        );
    }

    // Create a sorted, deduplicated list of columns to keep
    let mut columns_to_keep: Vec<usize> = (0..num_cols)
        .filter(|i| !columns_to_delete.contains(i))
        .collect();

    // If no columns to delete, return clone
    if columns_to_keep.len() == num_cols {
        return mat0.clone();
    }

    // If all columns deleted, return empty matrix with same rows
    if columns_to_keep.is_empty() {
        return Array2::zeros((mat0.nrows(), 0));
    }

    // Select the columns we want to keep
    mat0.select(Axis(1), &columns_to_keep)
}

