/// Append elements from lst1 to each sublist in lst0 at positions 0 through 3.
/// 
/// # Arguments
/// * `lst0` - A 2D array where each row is a sublist
/// * `lst1` - A 1D array containing elements to append
///
/// # Returns
/// A new 2D array with appended elements
///
/// # Panics
/// Panics if lst0 has fewer than 4 columns or lst1 has fewer than 4 elements
fn append_sublist_elements(lst0: &Array2<f64>, lst1: &[f64]) -> Array2<f64> {
    assert!(lst0.ncols() >= 4, "lst0 must have at least 4 columns");
    assert!(lst1.len() >= 4, "lst1 must have at least 4 elements");

    let nrows = lst0.nrows();
    let ncols = lst0.ncols();

    // Create new array with 4 additional columns
    let mut result = Array2::zeros((nrows, ncols + 4));

    // Copy original data
    result.slice_mut(s![.., ..ncols]).assign(lst0);

    // Append elements from lst1 at positions 0-3
    for i in 0..4 {
        result.slice_mut(s![.., ncols + i]).fill(lst1[i]);
    }

    result
