use polars::prelude::*;

/// Transforms all string entries in a specified column of a DataFrame to uppercase.
///
/// # Arguments
/// * `df` - A Polars DataFrame containing the data table
/// * `column_name` - The name of the column to transform
///
/// # Returns
/// A new DataFrame with the specified column's string values converted to uppercase
///
/// # Examples
/// ```
/// use polars::prelude::*;
///
/// let df = df!(
///     "name" => &["alice", "bob", "charlie"],
///     "age" => &[25, 30, 35]
/// );
///
/// let uppercase_df = transform_column_to_uppercase(df, "name");
/// ```
pub fn transform_column_to_uppercase(df: DataFrame, column_name: &str) -> Result<DataFrame> {
    // Check if column exists
    if !df.column(column_name).is_ok() {
        return Err(DataFrameError::ColumnNotFound(column_name.to_string()));
    }

    // Get the column data
    let col = df.column(column_name)?;

    // Convert to String type if it's not already
    let str_col = match col.dtype() {
        DataType::Utf8 => col,
        _ => {
            // Try to convert to string if possible
            let cast_col = col.cast(&DataType::Utf8)?;
            if cast_col.dtype() == DataType::Utf8 {
                cast_col
            } else {
                return Err(DataFrameError::InvalidOperation(
                    format!("Column '{}' cannot be converted to string", column_name)
                ));
            }
        }
    };

    // Apply uppercase transformation
    let uppercase_col = str_col.apply(|s| {
        if let Ok(s) = s {
            Ok(s.to_uppercase())
        } else {
            Ok(s)
        }
    })?;

    // Create new DataFrame with the transformed column
    let mut new_df = df.clone();
    new_df = new_df.with_column(uppercase_col)?;

    Ok(new_df)
}
