fn compute_dataframe_difference(
    df0: &DataFrame,
    df1: &DataFrame,
) -> Result<DataFrame, PolarsError> {
    // Validate that dimensions match
    if df0.shape() != df1.shape() {
        return Err(PolarsError::ComputeError(
            "DataFrames must have identical dimensions".into(),
