    let mut idx: Vec<usize> = (0..n).collect();
    idx.sort_by_key(|&i| timestamps_ms[i]);

    // Build sorted timestamps and sorted values (Option<f64>)
    let mut sorted_ts: Vec<i64> = Vec::with_capacity(n);
    let mut sorted_vals: Vec<Option<f64>> = Vec::with_capacity(n);
    for &i in &idx {
        sorted_ts.push(timestamps_ms[i]);
        sorted_vals.push(vals_f64[i]);
    }

    // Build prefix sums and prefix counts (ignoring nulls)
    let mut prefix_sum: Vec<f64> = Vec::with_capacity(n + 1);
    let mut prefix_cnt: Vec<usize> = Vec::with_capacity(n + 1);
    prefix_sum.push(0.0);
    prefix_cnt.push(0);
    for opt_v in &sorted_vals {
        match opt_v {
            Some(v) => {
                prefix_sum.push(prefix_sum.last().unwrap() + *v);
                prefix_cnt.push(prefix_cnt.last().unwrap() + 1);
            }
            None => {
                prefix_sum.push(*prefix_sum.last().unwrap());
