use polars::prelude::*;

/// Changes the row index of a DataFrame to a two-level hierarchical index
/// using values from the specified columns.
///
/// # Arguments
/// * `df` - The input DataFrame
/// * `col1` - Name of the first column for the hierarchical index
/// * `col2` - Name of the second column for the hierarchical index
///
/// # Returns
/// * `Result<DataFrame, PolarsError>` - DataFrame with hierarchical index set
///
/// # Example
/// ```
/// let df = df! {
///     "str0" => &["A", "A", "B", "B"],
///     "str1" => &["X", "Y", "X", "Y"],
///     "value" => &[1, 2, 3, 4],
/// }?;
///
/// let result = create_hierarchical_index(df, "str0", "str1")?;
/// ```
fn create_hierarchical_index(
    df: DataFrame,
    col1: &str,
    col2: &str,
) -> PolarsResult<DataFrame> {
    // Set the first column as index
    let df_indexed = df.clone().set_sorted(col1).set_sorted(col2);

    // Create a new DataFrame with hierarchical structure by keeping
    // the two columns and using them as multi-level index
    let result = df_indexed
        .select([col1, col2])?
        .with_row_index("index", Some(0))?;

    // Alternative approach: Use pivot or restructuring
    // In Polars, we can represent hierarchical indices by keeping
    // the columns and sorting by them
    let df_result = df
        .sort([col1, col2], vec![false, false])?
        .select(
            df.get_columns()
                .iter()
                .map(|s| s.name())
                .collect::<Vec<_>>()
                .as_slice(),
        )?;

    Ok(df_result)
}

