use polars::prelude::*;
use std::collections::HashMap;

/// Filters rows of a 2D table based on multiple conditions.
///
/// # Arguments
/// * `data` - A 2D table (Vec<Vec<String>>) where each inner vector represents a row.
/// * `conditions` - A map of column names to filter functions.
///   Each function takes a column value and returns a boolean.
///
/// # Returns
/// A new 2D table with only the rows that satisfy all conditions.
pub fn filter_table(
    data: Vec<Vec<String>>,
    conditions: HashMap<String, Box<dyn Fn(&String) -> bool>>,
) -> Vec<Vec<String>> {
    // Extract column names from the first row (assuming first row is headers)
    let headers = data.first().unwrap().clone();
    let mut filtered_data = Vec::new();

    // Skip the header row and process data rows
    for row in data.iter().skip(1) {
        let mut satisfies_all = true;

        for (col_name, condition) in &conditions {
            // Find the column index
            if let Some(col_idx) = headers.iter().position(|h| h == col_name) {
                let value = &row[col_idx];
                if !condition(value) {
                    satisfies_all = false;
                    break;
                }
            }
        }

        if satisfies_all {
            filtered_data.push(row.clone());
        }
    }

    // Prepend headers if needed (or return without them)
    if !filtered_data.is_empty() {
        filtered_data.insert(0, headers);
    }

    filtered_data
}

