/// Filter a 2D table according to multiple specified conditions.
///
/// # Arguments
///
/// * `data` - The input 2D table.
/// * `conditions` - A vector of conditions. Each condition is a tuple containing the column name, the operator, and the value.
///
/// # Returns
///
/// The filtered 2D table.
fn filter_table(data: &DataFrame, conditions: Vec<(&str, &str, &str)>) -> DataFrame {
    let mut filtered_data = data.clone();

    for (column, operator, value) in conditions {
        match operator {
            "==" => {
