            }
            ">=" => {
                filtered_data = filtered_data.filter(&format!("{} >= {}", column, value).parse().unwrap());
            }
            "<=" => {
                filtered_data = filtered_data.filter(&format!("{} <= {}", column, value).parse().unwrap());
            }
            _ => panic!("Invalid operator"),
        }
    }

