```rust
// Self-contained Rust example: filter rows of a 2D table by multiple conditions.
// No external crates required.

#[derive(Debug, Clone)]
enum Column {
    Name(String),   // column name (will be looked up in headers)
    Index(usize),   // zero-based column index
}

#[derive(Debug, Clone, Copy)]
enum Op {
    Eq,
    Ne,
    Lt,
    Lte,
    Gt,
    Gte,
    Contains,   // substring containment (case-sensitive)
    Between,    // numeric between: rhs ..= rhs2 (inclusive)
}

#[derive(Debug, Clone)]
struct Condition {
    column: Column,
    op: Op,
    rhs: String,
    rhs2: Option<String>, // used for Between
}

/// Filter a table (headers + rows) by multiple conditions.
///
/// - headers: slice of column names (one per column).
/// - rows: slice of rows; each row is Vec<String> with same length as headers.
/// - conditions: list of conditions to apply.
/// - require_all: if true, a row must satisfy ALL conditions (AND); if false, ANY (OR).
///
/// Returns a Vec of rows that pass the filter (rows are cloned).
fn filter_table(
    headers: &[String],
    rows: &[Vec<String>],
    conditions: &[Condition],
    require_all: bool,
) -> Vec<Vec<String>> {
    // helper: resolve Column -> Option<usize>
    fn col_index(headers: &[String], col: &Column) -> Option<usize> {
        match col {
            Column::Index(i) => {
                if *i < headers.len() { Some(*i) } else { None }
            }
            Column::Name(name) => headers.iter().position(|h| h == name),
        }
    }

    // helper: try parse to f64
    fn to_f64(s: &str) -> Option<f64> {
        // trim to be forgiving
        s.trim().parse::<f64>().ok()
    }

    // evaluate a single condition against a single cell string
    fn eval_cell(cell: &str, cond: &Condition) -> bool {
        match cond.op {
            Op::Eq => cell == cond.rhs,
            Op::Ne => cell != cond.rhs,
            Op::Contains => cell.contains(&cond.rhs),
            Op::Lt | Op::Lte | Op::Gt | Op::Gte => {
                // numeric comparison preferred
                if let (Some(a), Some(b)) = (to_f64(cell), to_f64(&cond.rhs)) {
                    match cond.op {
                        Op::Lt => a < b,
                        Op::Lte => a <= b,
                        Op::Gt => a > b,
                        Op::Gte => a >= b,
                        _ => false,
                    }
                } else {
                    // fall back to lexicographic comparison if not numeric
                    match cond.op {
                        Op::Lt => cell < cond.rhs.as_str(),
                        Op::Lte => cell <= cond.rhs.as_str(),
                        Op::Gt => cell > cond.rhs.as_str(),
                        Op::Gte => cell >= cond.rhs.as_str(),
                        _ => false,
                    }
                }
            }
            Op::Between => {
                // Need rhs and rhs2 numeric
                if let (Some(lo_s), Some(hi_s)) = (cond.rhs.parse::<f64>().ok(), cond.rhs2.as_ref().and_then(|s| s.parse::<f64>().ok())) {
                    if let Some(v) = to_f64(cell) {
                        (lo_s <= v) && (v <= hi_s)
                    } else {
                        false
                    }
                } else {
                    false
                }
            }
        }
    }

    let mut out = Vec::new();

    'rows: for row in rows.iter() {
        // basic sanity: skip rows with insufficient columns
        if row.len() < headers.len() {
            continue;
        }

        // evaluate conditions
        if conditions.is_empty() {
            // no conditions => keep all rows
            out.push(row.clone());
            continue;
        }

        if require_all {
            // AND: all conditions must be true
            for cond in conditions {
                if let Some(idx) = col_index(headers, &cond.column) {
                    let cell = &row[idx];
                    if !eval_cell(cell, cond) {
                        continue 'rows; // fails an AND condition => reject row
                    }
                } else {
                    // missing column: treat as failure for AND
                    continue 'rows;
                }
            }
            // all conditions passed
            out.push(row.clone());
        } else {
            // OR: at least one condition true
            let mut any = false;
            for cond in conditions {
                if let Some(idx) = col_index(headers, &cond.column) {
                    let cell = &row[idx];
                    if eval_cell(cell, cond) {
                        any = true;
                        break;
                    }
                } else {
                    // missing column: skip this condition (doesn't set any = true)
                }
            }
            if any {
                out.push(row.clone());
            }
        }
    }

    out
}

// Example usage
fn main() {
    let headers = vec!["id".into(), "name".into(), "age".into(), "score".into()];

    let rows = vec![
        vec!["1".into(), "Alice Smith".into(), "30".into(), "88.5".into()],
        vec!["2".into(), "Bob Jones".into(), "25".into(), "92".into()],
        vec!["3".into(), "Carol Smith".into(), "40".into(), "79".into()],
        vec!["4".into(), "Dan".into(), "22".into(), "95".into()],
    ];

    // Example: find rows where age >= 30 AND name contains "Smith"
    let conditions = vec![
        Condition {
            column: Column::Name("age".into()),
            op: Op::Gte,
            rhs: "30".into(),
            rhs2: None,
        },
        Condition {
            column: Column::Name("name".into()),
            op: Op::Contains,
            rhs: "Smith".into(),
            rhs2: None,
        },
    ];

    let filtered = filter_table(&headers, &rows, &conditions, true); // require_all = true (AND)
    println!("Filtered (age >= 30 AND name contains \"Smith\"):");
    for r in filtered {
        println!("{:?}", r);
    }

    // Example: find rows where score is between 90 and 100 OR age < 23
    let conditions2 = vec![
        Condition {
            column: Column::Name("score".into()),
            op: Op::Between,
            rhs: "90".into(),
            rhs2: Some("100".into()),
        },
        Condition {
            column: Column::Name("age".into()),
            op: Op::Lt,
            rhs: "23".into(),
            rhs2: None,
        },
    ];

    let filtered2 = filter_table(&headers, &rows, &conditions2, false); // require_all = false (OR)
    println!("\nFiltered (score between 90 and 100) OR (age < 23):");
    for r in filtered2 {
        println!("{:?}", r);
    }
}
```

