        // Create filter mask based on condition type
        let column_mask = if condition.starts_with('>') || condition.starts_with('<') 
            || condition.starts_with("==") || condition.starts_with("!=") {
            // Numeric comparison
            let value: f64 = condition[2..].trim().parse()
                .map_err(|_| PolarsError::ComputeError("Invalid numeric value".into()))?;

            let numeric_series = series.cast(&DataType::Float64)?;
            let numeric_ca = numeric_series.f64()?;

            match &condition[..2] {
                ">=" => numeric_ca.gt_eq(value),
                "<=" => numeric_ca.lt_eq(value),
                "==" => numeric_ca.equal(value),
                "!=" => numeric_ca.not_equal(value),
                _ => unreachable!(),
            }
        } else if condition.starts_with('>') {
            let value: f64 = condition[1..].trim().parse()
                .map_err(|_| PolarsError::ComputeError("Invalid numeric value".into()))?;
            let numeric_series = series.cast(&DataType::Float64)?;
            numeric_series.f64()?.gt(value)
        } else if condition.starts_with('<') {
            let value: f64 = condition[1..].trim().parse()
                .map_err(|_| PolarsError::ComputeError("Invalid numeric value".into()))?;
            let numeric_series = series.cast(&DataType::Float64)?;
            numeric_series.f64()?.lt(value)
        } else if condition.starts_with("contains:") {
            let value = &condition[9..];
            series.str()?.contains(value, false)
        } else if condition.starts_with("starts:") {
            let value = &condition[7..];
            series.str()?.starts_with(value)
        } else if condition.starts_with("ends:") {
            let value = &condition[5..];
            series.str()?.ends_with(value)
        } else if condition.starts_with("==") {
            let value = &condition[2..];
            series.str()?.equal(value)
        } else if condition.starts_with("!=") {
            let value = &condition[2..];
            series.str()?.not_equal(value)
        } else {
            return Err(PolarsError::ComputeError(
                format!("Unknown condition format: {}", condition).into()
            ));
        };

        // Combine with existing mask using AND logic
        mask = match mask {
            None => Some(column_mask),
            Some(existing) => Some(existing & column_mask),
        };
    }

    // Apply the combined mask
    match mask {
        Some(m) => df.filter(&m),
        None => Ok(df), // No conditions means return all rows
    }
}

/// Helper function to convert Vec<Vec<String>> to Polars DataFrame
fn convert_to_dataframe(data: Vec<Vec<String>>) -> Result<DataFrame, PolarsError> {
    if data.is_empty() {
        return Err(PolarsError::ComputeError("Empty data".into()));
    }

    let headers = &data[0];
    let num_cols = headers.len();

    // Initialize column vectors
    let mut columns: Vec<Series> = Vec::with_capacity(num_cols);

    for col_idx in 0..num_cols {
        let mut col_data: Vec<String> = Vec::with_capacity(data.len() - 1);

        for row in data.iter().skip(1) {
            if row.len() != num_cols {
                return Err(PolarsError::ComputeError(
                    "Inconsistent row lengths".into()
                ));
            }
            col_data.push(row[col_idx].clone());
        }

