        let series = if col_data.iter().all(|v| v.parse::<f64>().is_ok()) {
            let numeric: Vec<f64> = col_data.iter()
                .map(|v| v.parse().unwrap())
                .collect();
            Series::new(headers[col_idx].as_str(), &numeric)
        } else {
            Series::new(headers[col_idx].as_str(), &col_data)
        };

        columns.push(series);
    }

    DataFrame::new(columns)
