///     ("city", "eq", "NYC"),
///     ("salary", "gt", "50000"),
/// ];
/// let result = filter_table_data(df, conditions)?;
/// ```
pub fn filter_table_data(
    data: DataFrame,
    conditions: Vec<(&str, &str, &str)>,
) -> PolarsResult<DataFrame> {
    let mut result = data;

    for (column_name, operator, value) in conditions {
        let col = col(column_name);

        let mask = match operator {
            "eq" => {
                // Try parsing as number first, then treat as string
                if let Ok(num_val) = value.parse::<i64>() {
                    col.eq(num_val)
                } else {
                    col.eq(value)
                }
            }
            "ne" => {
                if let Ok(num_val) = value.parse::<i64>() {
                    col.neq(num_val)
                } else {
                    col.neq(value)
                }
            }
            "gt" => {
                let num_val = value.parse::<f64>()
                    .map_err(|_| PolarsError::ComputeError("Invalid number format".into()))?;
                col.gt(num_val)
            }
            "gte" => {
                let num_val = value.parse::<f64>()
                    .map_err(|_| PolarsError::ComputeError("Invalid number format".into()))?;
                col.gt_eq(num_val)
            }
            "lt" => {
                let num_val = value.parse::<f64>()
                    .map_err(|_| PolarsError::ComputeError("Invalid number format".into()))?;
                col.lt(num_val)
            }
            "lte" => {
                let num_val = value.parse::<f64>()
                    .map_err(|_| PolarsError::ComputeError("Invalid number format".into()))?;
                col.lt_eq(num_val)
            }
            "contains" => col.str().unwrap().contains(value, false),
            _ => return Err(PolarsError::ComputeError(
                format!("Unknown operator: {}", operator).into()
            )),
        };

        result = result.filter(&mask)?;
    }

    Ok(result)
}

