/// ```
pub fn filter_by_matching_rows(
    table_a: &DataFrame,
    table_b: &DataFrame,
    join_columns: &[&str],
) -> Result<DataFrame, Box<dyn Error>> {
    // Validate that join columns exist in both tables
    for col in join_columns {
        if !table_a.get_column_names().contains(col) {
            return Err(format!("Column '{}' not found in table A", col).into());
        }
        if !table_b.get_column_names().contains(col) {
            return Err(format!("Column '{}' not found in table B", col).into());
        }
    }

    // Perform a semi-join (keeps only rows from left table that have matches in right table)
    let result = table_a.join(
        table_b,
        join_columns,
        join_columns,
        JoinArgs::new(JoinType::Semi),
    )?;

    Ok(result)
}

