        if !table_a.get_column_names().contains(col) {
            return Err(format!("Column '{}' not found in table A", col).into());
        }
        if !table_b.get_column_names().contains(col) {
            return Err(format!("Column '{}' not found in table B", col).into());
        }
    }

    // Get unique combinations from table B for the join columns
    let unique_b = table_b.unique(Some(join_columns), UniqueKeepStrategy::First)?;

    // Perform inner join to find matching rows
    let matched = table_a.join(
        &unique_b,
        join_columns,
        join_columns,
        JoinArgs::new(JoinType::Inner),
    )?;

    // Remove duplicate rows that might have been created by the inner join
    let result = matched.unique(None, UniqueKeepStrategy::First)?;

    Ok(result)
