/// let result = calculate_column_means(df).unwrap();
/// // Result: "value" column with means [2.5, 3.5, 4.5], "other" with [7.0, 8.0, 9.0]
/// ```
fn calculate_column_means(df: DataFrame) -> PolarsResult<DataFrame> {
    // Get all column names
    let column_names = df.get_column_names();

    // Group column indices by their names
    let mut name_to_indices: std::collections::HashMap<String, Vec<usize>> = 
        std::collections::HashMap::new();

    for (idx, name) in column_names.iter().enumerate() {
        name_to_indices
            .entry(name.to_string())
            .or_insert_with(Vec::new)
            .push(idx);
    }

    // Calculate mean for each group of same-named columns
    let mut result_columns: Vec<Series> = Vec::new();

    for (name, indices) in name_to_indices.iter() {
        if indices.len() == 1 {
            // Only one column with this name, keep as is
            result_columns.push(df.get_column(&column_names[indices[0]])?.clone());
        } else {
            // Multiple columns with same name, calculate mean
            let mut series_list: Vec<Series> = Vec::new();

            for &idx in indices {
                series_list.push(df.get_column(&column_names[idx])?.clone());
            }

            // Convert all series to float and calculate mean
            let float_series: Vec<Series> = series_list
                .iter()
                .map(|s| s.cast(&DataType::Float64).unwrap())
                .collect();

            // Stack series horizontally and calculate mean across columns
            let stacked = concat_list(&float_series)?;
            let mean_values = stacked
                .list()?
                .into_iter()
                .map(|list_opt| {
                    list_opt.and_then(|list| {
                        let values: Vec<f64> = list
                            .iter()
                            .filter_map(|v| v.try_extract::<f64>().ok())
                            .collect();
                        if values.is_empty() {
                            None
                        } else {
                            Some(values.iter().sum::<f64>() / values.len() as f64)
                        }
                    })
                })
                .collect::<Vec<_>>();

            let mean_series = Series::new(name.as_str(), mean_values);
            result_columns.push(mean_series);
        }
    }

    // Create new DataFrame from result columns
    DataFrame::new(result_columns)
}

// Alternative simpler implementation using grouping approach
fn calculate_column_means_v2(df: DataFrame) -> PolarsResult<DataFrame> {
    let column_names = df.get_column_names();
    let mut processed_names = std::collections::HashSet::new();
    let mut result_columns: Vec<Series> = Vec::new();

    for col_name in column_names {
        if processed_names.contains(col_name) {
            continue;
        }
        processed_names.insert(col_name.to_string());

        // Find all columns with this name
        let matching_cols: Vec<Series> = df
            .get_columns()
            .iter()
            .filter(|s| s.name() == col_name)
            .cloned()
            .collect();

        if matching_cols.len() == 1 {
            result_columns.push(matching_cols[0].clone());
        } else {
            // Calculate mean across multiple columns with same name
            let mean_series = matching_cols
                .iter()
                .fold(
                    Series::new(col_name, vec![0.0; df.height()]),
                    |acc, series| {
                        let casted = series.cast(&DataType::Float64).unwrap();
                        (acc + &casted).unwrap()
                    },
                ) / matching_cols.len() as f64;

            result_columns.push(mean_series);
        }
    }

    DataFrame::new(result_columns)
}
