    ///
    /// - If `times == 0` the result is an empty Vec.
    /// - Elements are cloned, so `T` must implement `Clone`.
    /// - Panics if the resulting capacity would overflow usize.
    pub fn duplicate_each<T: Clone>(lst: &[T], times: usize) -> Vec<T> {
