Below is a self-contained Rust function that implements a Pandas-like "reset_index": it takes a polars DataFrame and converts an existing row-index (if provided as one or more Series) into new columns prepended to the table; if no index Series are provided it inserts a numeric row-index column. The example uses the polars crate (modern releases in the 2025+ timeframe — change the version as needed).

Cargo.toml (example):
- polars crate (pick a recent 2025+ release in your project):
  polars = { version = "0.35", features = ["lazy", "temporal", "strings"] }

Code:

```rust
use polars::prelude::*;

/// Reset the row index of `df` and convert existing index values into new columns.
///
/// - If `index_levels` is `Some(vec![Series, ...])`, each Series is treated as an index level:
///   they are validated to have the same length as `df` and then prepended as columns.
///   If a series has no name, it will be renamed to "index_0", "index_1", ...
/// - If `index_levels` is `None`, a numeric integer index column named "index" is prepended
///   with values 0..(n_rows-1).
///
/// Returns a new DataFrame with the index columns inserted at the front.
///
/// Note: if an inserted index column name collides with an existing column name in `df`,
/// polars will allow duplicate names; callers can rename or resolve collisions after the call.
pub fn reset_index(mut df: DataFrame, index_levels: Option<Vec<Series>>) -> PolarsResult<DataFrame> {
    let n_rows = df.height();

    match index_levels {
        Some(levels) => {
            for (i, mut s) in levels.into_iter().enumerate() {
                if s.len() != n_rows {
                    return Err(PolarsError::ShapeMisMatch(
                        format!(
                            "index level {} has length {} but dataframe has {} rows",
                            i,
                            s.len(),
                            n_rows
                        )
                        .into(),
                    ));
                }
                // Ensure the Series has a name; if not, assign a default name.
                if s.name().is_empty() {
                    let default = format!("index_{}", i);
                    s.rename(&default);
                }
                // Prepend index level as a column (insert at position i).
                df.insert_at_idx(i, s)?;
            }
        }
        None => {
            // Create a numeric index column 0..n_rows-1 and prepend it.
            let idx_vals: Vec<i64> = (0..n_rows as i64).collect();
            let idx_series = Series::new("index", idx_vals);
            df.insert_at_idx(0, idx_series)?;
        }
    }

    Ok(df)
}

#[cfg(test)]
mod tests {
    use super::*;
    use polars::df;

    #[test]
    fn test_reset_index_with_auto_index() {
        let mut df = df![
            "a" => &[10, 20, 30],
            "b" => &["x", "y", "z"]
        ].unwrap();

        let out = reset_index(df, None).unwrap();
        assert_eq!(out.get_column_names(), &["index", "a", "b"]);
        // check index values
        let idx = out.column("index").unwrap().i64().unwrap();
        assert_eq!(idx.get(0), Some(0));
        assert_eq!(idx.get(2), Some(2));
    }

    #[test]
    fn test_reset_index_with_levels() {
        let df = df![
            "val" => &[1, 2, 3]
        ].unwrap();

        let idx0 = Series::new("date", &["2025-01-01", "2025-01-02", "2025-01-03"]);
        let idx1 = Series::new("", &[100i64, 200, 300]); // unnamed level -> will become index_1

        let out = reset_index(df.clone(), Some(vec![idx0.clone(), idx1.clone()])).unwrap();
        assert_eq!(out.get_column_names(), &["date", "index_1", "val"]);
        // values preserved
        assert_eq!(out.column("date").unwrap().utf8().unwrap().get(1), Some("2025-01-02"));
        assert_eq!(out.column("index_1").unwrap().i64().unwrap().get(2), Some(300));
    }
}
```

