use polars::prelude::*;
use std::error::Error;

/// Resets the row index of a DataFrame and converts existing index values into new columns.
///
/// This function takes a DataFrame with an existing index column, resets it to a sequential
/// integer index starting from 0, and moves the original index values into a new column.
///
/// # Arguments
/// * `df` - Input DataFrame with an index column
/// * `index_col` - Name of the column containing the current index values
/// * `new_index_col` - Name for the new sequential index column (optional, defaults to "index")
/// * `old_index_col` - Name for the column that will store the original index values (optional, defaults to "old_index")
///
/// # Returns
/// * `Result<DataFrame>` - DataFrame with reset index and original index values as a new column
///
/// # Example
/// ```rust
/// use polars::prelude::*;
///
/// let df = df!(
///     "id" => &[1, 2, 3],
///     "value" => &[10, 20, 30]
/// ).unwrap();
///
/// let result = reset_index(&df, "id", Some("new_idx"), Some("original_id")).unwrap();
/// println!("{:?}", result);
/// ```
pub fn reset_index(
    df: &DataFrame,
    index_col: &str,
    new_index_col: Option<&str>,
    old_index_col: Option<&str>,
) -> Result<DataFrame, Box<dyn Error>> {
    // Set default column names
    let new_idx_name = new_index_col.unwrap_or("index");
    let old_idx_name = old_index_col.unwrap_or("old_index");

    // Validate that the index column exists
    if !df.get_column_names().contains(&index_col) {
        return Err(format!("Column '{}' not found in DataFrame", index_col).into());
    }

    // Extract the original index values
    let original_index = df.column(index_col)?.clone();

    // Remove the original index column from the DataFrame
    let mut df_without_index = df.drop(index_col)?;

    // Create a new sequential index starting from 0
    let n_rows = df_without_index.height();
    let new_index = (0u32..n_rows as u32).collect::<Vec<_>>();
    let new_index_series = Series::new(new_idx_name, new_index);

    // Rename the original index column
    let original_index_renamed = original_index.rename(old_idx_name);

    // Add the new sequential index as the first column
    let mut result_df = DataFrame::new(vec![new_index_series])?;

    // Add the renamed original index column
    result_df.hstack_mut(&[original_index_renamed])?;

    // Add the remaining columns from the original DataFrame
    result_df.hstack_mut(&df_without_index)?;

    Ok(result_df)
}

// Alternative implementation using with_column and more modern Polars API
pub fn reset_index_v2(
    df: &DataFrame,
    index_col: &str,
    new_index_col: Option<&str>,
    old_index_col: Option<&str>,
) -> Result<DataFrame, Box<dyn Error>> {
    let new_idx_name = new_index_col.unwrap_or("index");
    let old_idx_name = old_index_col.unwrap_or("old_index");

    // Validate that the index column exists
    if !df.get_column_names().contains(&index_col) {
        return Err(format!("Column '{}' not found in DataFrame", index_col).into());
    }

    // Create a new sequential index
    let n_rows = df.height();
    let new_index = (0u32..n_rows as u32).collect::<Vec<_>>();
    let new_index_series = Series::new(new_idx_name, new_index);

    // Rename the original index column
    let original_index = df.column(index_col)?.clone().rename(old_idx_name);

    // Remove the original index column and add new columns
    let mut result = df.drop(index_col)?;
    result.insert_column(0, new_index_series)?;
    result.insert_column(1, original_index)?;

    Ok(result)
}

