use polars::prelude::*;

/// Reset the row index of a DataFrame and convert the existing index values into a new column.
/// 
/// # Arguments
/// * `df` - The input DataFrame
/// * `index_name` - The name for the new column created from the index
/// 
/// # Returns
/// A new DataFrame with reset index and the old index as a column
/// 
/// # Example
/// ```
/// let df = df! {
///     "name" => ["Alice", "Bob", "Charlie"],
///     "age" => [25, 30, 35],
/// }?;
/// 
/// let result = reset_index(df, "original_index")?;
/// println!("{}", result);
/// ```
fn reset_index(df: DataFrame, index_name: &str) -> PolarsResult<DataFrame> {
    // Create a new index column with sequential values (0, 1, 2, ...)
    let n_rows = df.height();
    let new_index = Series::new(
        index_name,
        (0..n_rows as i32).collect::<Vec<_>>(),
    );

    // Insert the new index column at the beginning
    let mut df_with_index = df.clone();
    df_with_index.insert_at_idx(0, new_index)?;

    Ok(df_with_index)
}

// Alternative version using with_row_index() - Polars 0.20.31+
fn reset_index_modern(df: DataFrame, index_name: &str) -> PolarsResult<DataFrame> {
    // Using the built-in with_row_index() method available in newer Polars
    df.with_row_index(index_name, Some(0))
}

