use polars::prelude::*;
use serde_json::Value;
use std::collections::HashMap;

/// Converts a Polars DataFrame into a list of dictionaries, each containing:
/// - The row index (as a string)
/// - Column-value pairs (as JSON-compatible values)
///
/// # Example
/// ```
/// use polars::prelude::*;
/// let df = df!(
///     "a" => &[1, 2, 3],
///     "b" => &["x", "y", "z"]
/// ).unwrap();
/// let result = dataframe_to_dicts(&df);
/// ```
pub fn dataframe_to_dicts(df: &DataFrame) -> Result<Vec<HashMap<String, Value>>, PolarsError> {
    let mut result = Vec::with_capacity(df.height());

    for row_idx in 0..df.height() {
        let mut row_dict = HashMap::new();

        // Add row index
        row_dict.insert("index".to_string(), Value::String(row_idx.to_string()));

        // Process each column
        for col_name in df.get_column_names() {
            let col = df.column(col_name).unwrap();
            let value = match col {
                // Handle numeric types
                DataType::Int64 => {
                    let series = col.downcast::<Int64Type>()?;
                    Value::from(series.get(row_idx).unwrap())
                }
                DataType::Float64 => {
                    let series = col.downcast::<Float64Type>()?;
                    Value::from(series.get(row_idx).unwrap())
                }
                // Handle string types
                DataType::Utf8 => {
                    let series = col.downcast::<Utf8Type>()?;
                    Value::String(series.get(row_idx).unwrap().to_string())
                }
                // Handle boolean types
                DataType::Boolean => {
                    let series = col.downcast::<BooleanType>()?;
                    Value::Bool(series.get(row_idx).unwrap())
                }
                // Handle datetime types
                DataType::Datetime(_) => {
                    let series = col.downcast::<DatetimeType>()?;
                    Value::String(series.get(row_idx).unwrap().to_string())
                }
                // Handle other types (fallback to string representation)
                _ => {
                    let series = col.downcast::<StringType>()?;
                    Value::String(series.get(row_idx).unwrap().to_string())
                }
            };

            row_dict.insert(col_name.to_string(), value);
        }

        result.push(row_dict);
    }

    Ok(result)
}
