/// Generates pairs of adjacent elements where the second element equals the target value.
///
/// # Arguments
/// * `list` - A slice of comparable elements
/// * `target` - The target value to match against the second element of each pair
///
/// # Returns
/// A vector of tuples containing adjacent pairs where the second element equals the target
///
/// # Example
/// ```
/// let numbers = vec![1, 2, 2, 3, 2, 4];
/// let result = find_adjacent_pairs(&numbers, &2);
/// assert_eq!(result, vec![(1, 2), (3, 2)]);
/// ```
fn find_adjacent_pairs<T: Clone + PartialEq>(list: &[T], target: &T) -> Vec<(T, T)> {
    list.windows(2)
        .filter(|window| window[1] == *target)
        .map(|window| (window[0].clone(), window[1].clone()))
        .collect()
}

fn main() {
    // Example 1: Integer list
    let numbers = vec![1, 2, 2, 3, 2, 4, 2];
    let result = find_adjacent_pairs(&numbers, &2);
    println!("Input: {:?}", numbers);
    println!("Target: 2");
    println!("Result: {:?}\n", result);
    // Output: [(1, 2), (3, 2), (4, 2)]

    // Example 2: String list
    let words = vec!["apple", "banana", "apple", "cherry", "apple"];
    let result = find_adjacent_pairs(&words, &"apple");
    println!("Input: {:?}", words);
    println!("Target: \"apple\"");
    println!("Result: {:?}\n", result);
    // Output: [("banana", "apple"), ("cherry", "apple")]

    // Example 3: Character list
    let chars = vec!['a', 'b', 'b', 'c', 'b', 'd'];
