    pub struct DataFrame {
        // rows: outer Vec = rows; inner Vec = columns per row
        data: Vec<Vec<Value>>,
        // column names (length == ncols)
        columns: Vec<String>,
        // optional row/index names (length == nrows)
        index: Option<Vec<String>>,
    }

    impl DataFrame {
        // Construct from parts; checks sizes for consistency.
        pub fn from_parts(
            columns: Vec<String>,
            index: Option<Vec<String>>,
            data: Vec<Vec<Value>>,
        ) -> Result<Self, String> {
            let nrows = data.len();
            let ncols = if nrows > 0 { data[0].len() } else { columns.len() };
            // verify each row length
            for (r, row) in data.iter().enumerate() {
                if row.len() != ncols {
                    return Err(format!(
                        "row {} length {} does not match expected {}",
                        r,
                        row.len(),
                        ncols
                    ));
                }
            }
            if columns.len() != ncols {
                return Err(format!(
                    "columns length {} does not match number of columns {}",
                    columns.len(),
                    ncols
                ));
            }
            if let Some(ix) = &index {
                if ix.len() != nrows {
                    return Err(format!(
                        "index length {} does not match number of rows {}",
                        ix.len(),
                        nrows
                    ));
                }
            }
            Ok(Self { data, columns, index })
        }

