        (0..nrows).map(|i| format!("row_{}", i)).collect()
    };

    // New index (row names) are original column names
    let new_index: Option<Vec<String>> = Some(df0.column_names().iter().cloned().collect());

    // Build and return; unwrap is safe because sizes match by construction
    DataFrame::from_parts(new_columns, new_index, new_data)
