```rust
use std::collections::HashMap;

/// Combines multiple key-value mappings into a single mapping where each key's 
/// value is the sum of that key's values across all input mappings.
/// 
/// # Arguments
/// * `mappings` - A list of HashMaps with String keys and numeric values
/// 
/// # Returns
/// A HashMap where each key maps to the sum of its values across all input mappings
/// 
/// # Example
/// ```
/// let mut map1 = HashMap::from([("a".to_string(), 10), ("b".to_string(), 20)]);
/// let mut map2 = HashMap::from([("a".to_string(), 5), ("c".to_string(), 15)]);
/// let result = combine_mappings(vec![map1, map2]);
/// assert_eq!(result.get("a"), Some(&15));
/// assert_eq!(result.get("b"), Some(&20));
/// assert_eq!(result.get("c"), Some(&15));
/// ```
fn combine_mappings(mappings: Vec<HashMap<String, i32>>) -> HashMap<String, i32> {
    mappings
        .into_iter()
        .flat_map(|map| map.into_iter())
        .fold(HashMap::new(), |mut acc, (key, value)| {
            acc.entry(key)
                .and_modify(|v| *v += value)
                .or_insert(value);
            acc
        })
}

// Self-contained test
