        ("cherry".to_string(), 15),
    ]);

    let map3 = HashMap::from([
        ("banana".to_string(), 8),
        ("apple".to_string(), 7),
    ]);

    let result = combine_mappings(vec![map1, map2, map3]);

    println!("Combined mappings:");
    let mut sorted_keys: Vec<_> = result.keys().collect();
    sorted_keys.sort();

    for key in sorted_keys {
        println!("  {}: {}", key, result[key]);
    }

    assert_eq!(result.get("apple"), Some(&22));
    assert_eq!(result.get("banana"), Some(&28));
    assert_eq!(result.get("cherry"), Some(&15));

    println!("\nAll assertions passed!");
}
