pub fn conditional_update(
    df: DataFrame,
    col_condition: &str,
    col_update: &str,
    condition_val: f64,
    new_val: f64,
) -> Result<DataFrame, PolarsError> {
    // Create a boolean mask where condition is met
    let mask = df.column(col_condition)?
        .f64()?
        .unwrap_or_else(|| {
            panic!("Column '{}' must contain f64 values", col_condition)
        })
        .gt(&condition_val);

    // Create a new column with the updated values
