        .f64()?
        .unwrap_or_else(|| {
            panic!("Column '{}' must contain f64 values", col_update)
        })
        .map_with(|s| {
            if s {
                Ok(Some(new_val))
            } else {
                Ok(None)
            }
        }, &mask)?;

