use fast_table_2025::{Table, Value};

/// Update `table` in-place: set each entry in `col_update` to `new_val` whenever the
/// corresponding entry in `col_condition` is greater than `condition_val`.
///
/// Returns the number of rows updated, or an Err(String) if columns are missing or types are incompatible.
///
/// Comparison rules:
/// - Int and Float compare numerically (Int is coerced to Float for mixed comparisons).
/// - Str compares lexicographically.
/// - Any other mismatched types or Null comparison -> considered not greater (no update).
pub fn update_where_greater(
    table: &mut Table,
    col_update: &str,
    col_condition: &str,
    condition_val: &Value,
    new_val: &Value,
) -> Result<usize, String> {
    let idx_update = table
        .col_index(col_update)
        .ok_or_else(|| format!("update column '{}' not found", col_update))?;
    let idx_cond = table
        .col_index(col_condition)
        .ok_or_else(|| format!("condition column '{}' not found", col_condition))?;

    let mut updated = 0usize;

    for row in table.rows.iter_mut() {
        // defensive check for row length
        if idx_update >= row.len() || idx_cond >= row.len() {
            return Err("row length does not match column count".to_string());
        }
        let cond_val = &row[idx_cond];
        match cond_val.greater_than(condition_val) {
            Some(true) => {
                row[idx_update] = new_val.clone();
                updated += 1;
            }
            // Some(false) (not greater) or None (not comparable) => do nothing
            _ => {}
        }
    }

    Ok(updated)
}

