use rocksdb::{DB, DBWithTTL, Options, ReadOptions};
use std::error::Error;

/// Fetches all key-value entries from a RocksDB database where keys fall between two boundary keys (inclusive).
///
/// # Arguments
/// * `db_path` - Path to the RocksDB database directory
/// * `start_key` - The lower boundary key (inclusive)
/// * `end_key` - The upper boundary key (exclusive)
///
/// # Returns
/// A `Result` containing a vector of `(key, value)` tuples if successful, or an error otherwise.
///
/// # Example
/// ```rust
/// use rocksdb::DB;
///
/// #[tokio::main]
/// async fn main() -> Result<(), Box<dyn Error>> {
///     let db_path = "test_db";
///     let start_key = b"apple";
///     let end_key = b"banana";
///
///     let entries = fetch_range_entries(db_path, start_key, end_key)?;
///     for (k, v) in entries {
///         println!("{}: {}", String::from_utf8_lossy(k), String::from_utf8_lossy(v));
///     }
///     Ok(())
/// }
/// ```
pub fn fetch_range_entries<DBType: rocksdb::DB>(
    db_path: &str,
    start_key: &[u8],
    end_key: &[u8],
) -> Result<Vec<(Vec<u8>, Vec<u8>)>, Box<dyn Error>> {
    // Open the database
    let mut options = Options::default();
    options.create_if_missing(true);
    let db = DB::open(&options, db_path)?;

    // Create read options
    let read_options = ReadOptions::default();

    // Iterate through the range
    let mut entries = Vec::new();
    let mut iter = db.raw_iterator(read_options);

    // Seek to the start key
    iter.seek(start_key);

    // Iterate until we pass the end key
    while iter.valid() && iter.key() <= end_key {
        let key = iter.key().to_vec();
        let value = iter.value().to_vec();
        entries.push((key, value));
        iter.next();
    }

    Ok(entries)
}
```

