```rust
use regex::Regex;

/// Counts the number of times a specified word occurs as a whole word in the given text.
///
/// # Arguments
/// * `text` - The text to search within
/// * `word` - The word to count (case-sensitive)
///
/// # Returns
/// The number of whole word occurrences
///
/// # Example
/// ```
/// let count = count_word_occurrences("Hello world, hello there! Hello again.", "Hello");
/// assert_eq!(count, 2); // Only matches exact case
/// ```
fn count_word_occurrences(text: &str, word: &str) -> usize {
    // Escape special regex characters in the word
    let escaped_word = regex::escape(word);

    // Create a pattern with word boundaries (\b)
    // \b matches at word boundaries (between word and non-word characters)
    let pattern = format!(r"\b{}\b", escaped_word);

    // Compile the regex pattern
    match Regex::new(&pattern) {
        Ok(re) => {
            // Count all non-overlapping matches
            re.find_iter(text).count()
        }
        Err(e) => {
            eprintln!("Regex error: {}", e);
            0
        }
    }
}

/// Case-insensitive variant
fn count_word_occurrences_case_insensitive(text: &str, word: &str) -> usize {
    let escaped_word = regex::escape(word);
    let pattern = format!(r"(?i)\b{}\b", escaped_word);

    match Regex::new(&pattern) {
        Ok(re) => re.find_iter(text).count(),
        Err(e) => {
            eprintln!("Regex error: {}", e);
            0
        }
    }
}

fn main() {
    // Example 1: Case-sensitive counting
    let text1 = "The quick brown fox jumps over the lazy dog. The fox is quick.";
    let count1 = count_word_occurrences(text1, "The");
    println!("Case-sensitive 'The': {}", count1); // Output: 2

    // Example 2: Word with special characters
    let text2 = "I don't like don't, but I like don't-care attitude.";
    let count2 = count_word_occurrences(text2, "don't");
    println!("Word 'don't': {}", count2); // Output: 2

    // Example 3: Case-insensitive counting
    let text3 = "Hello world, hello there! HELLO again.";
    let count3 = count_word_occurrences_case_insensitive(text3, "hello");
    println!("Case-insensitive 'hello': {}", count3); // Output: 3

    // Example 4: Avoiding partial matches
    let text4 = "The cat catalog contains a catalog of cats.";
    let count4 = count_word_occurrences(text4, "cat");
    println!("Word 'cat' (not in 'catalog'): {}", count4); // Output: 1

