use std::error::Error;

/// Computes the mean of each column in a DataFrame, grouped by `var0` and `var1`.
///
/// # Arguments
/// * `df0` - The input DataFrame containing the data.
///
/// # Returns
/// A `Result` containing a grouped DataFrame with mean values for each column.
///
/// # Example
/// ```rust
/// use polars::prelude::*;
///
/// fn main() -> Result<(), Box<dyn Error>> {
///     // Example DataFrame
///     let df0 = df!(
///         "var0" => &[1, 1, 2, 2],
///         "var1" => &["A", "B", "A", "B"],
///         "col1" => &[10.0, 20.0, 30.0, 40.0],
///         "col2" => &[100.0, 200.0, 300.0, 400.0],
///     )?;
///
///     let result = compute_grouped_means(&df0, "var0", "var1")?;
///     println!("{:?}", result);
///     Ok(())
/// }
/// ```
pub fn compute_grouped_means(df0: &DataFrame, group_by_col1: &str, group_by_col2: &str) -> Result<DataFrame, Box<dyn Error>> {
    // Group by the specified columns
    let grouped = df0
        .lazy()
        .group_by([group_by_col1, group_by_col2])?
        .agg([
            // Compute mean for each numeric column
            for col in df0.get_column_names()?
                .into_iter()
                .filter(|col_name| ![group_by_col1, group_by_col2].contains(&col_name.as_str()))
                .collect::<Vec<_>>()
            {
                col_name => agg_col_mean(&col_name)
            }
        ])?
        .collect()?;

    Ok(grouped)
}

/// Helper function to create a mean aggregation for a column.
fn agg_col_mean(col_name: &str) -> (String, AggExpr) {
    (col_name.clone(), AggExpr::mean(col_name))
}
```

