/// by converting each to its digit sequence and concatenating them in order.
///
/// # Arguments
/// * `numbers` - A slice of integers to concatenate
///
/// # Returns
/// * `Result<i64, std::num::ParseIntError>` - The concatenated integer or parse error
///
/// # Examples
/// ```
/// let result = concatenate_integers(&[1, 2, 3]).unwrap();
/// assert_eq!(result, 123);
///
/// let result = concatenate_integers(&[10, 20, 30]).unwrap();
/// assert_eq!(result, 102030);
/// ```
fn concatenate_integers(numbers: &[i32]) -> Result<i64, std::num::ParseIntError> {
    let mut result = String::new();

    for &num in numbers {
        write!(&mut result, "{}", num).unwrap();
    }

    result.parse::<i64>()
}

fn main() {
    // Test case 1: Simple consecutive numbers
    match concatenate_integers(&[1, 2, 3]) {
        Ok(n) => println!("concatenate_integers(&[1, 2, 3]) = {}", n),
        Err(e) => println!("Error: {}", e),
    }

    // Test case 2: Numbers with different magnitudes
    match concatenate_integers(&[10, 20, 30]) {
        Ok(n) => println!("concatenate_integers(&[10, 20, 30]) = {}", n),
        Err(e) => println!("Error: {}", e),
    }

    // Test case 3: Single element
    match concatenate_integers(&[42]) {
        Ok(n) => println!("concatenate_integers(&[42]) = {}", n),
        Err(e) => println!("Error: {}", e),
    }

