    match concatenate_integers(&[]) {
        Ok(n) => println!("concatenate_integers(&[]) = {}", n),
        Err(e) => println!("Error: {}", e),
    }

    // Test case 5: Negative numbers
    match concatenate_integers(&[1, -2, 3]) {
        Ok(n) => println!("concatenate_integers(&[1, -2, 3]) = {}", n),
        Err(e) => println!("Error: {}", e),
    }
}
```

