pub fn cartesian_product<T: Clone>(lst0: &[Vec<T>]) -> Vec<Vec<T>> {
    if lst0.is_empty() {
        return vec![vec![]];
    }

    // Start with the first sequence
    let mut result: Vec<Vec<T>> = lst0[0]
        .iter()
        .map(|item| vec![item.clone()])
        .collect();

