/// Generates a new sequence by alternately taking elements from the first sequence
/// and from the second sequence in reverse order.
///
/// # Arguments
/// * `lst0` - The first input sequence (will be consumed)
/// * `lst1` - The second input sequence (will be consumed)
///
/// # Returns
/// A new Vec containing the interleaved elements
///
/// # Example
/// ```
/// let result = interleave_reverse(vec![1, 2, 3], vec![4, 5, 6]);
/// assert_eq!(result, vec![1, 6, 2, 5, 3, 4]);
/// ```
fn interleave_reverse<T>(lst0: Vec<T>, lst1: Vec<T>) -> Vec<T> {
    let mut result = Vec::with_capacity(lst0.len() + lst1.len());
    let mut iter0 = lst0.into_iter();
    let mut iter1 = lst1.into_iter().rev();

    loop {
        match (iter0.next(), iter1.next()) {
            (Some(item0), Some(item1)) => {
                result.push(item0);
                result.push(item1);
            }
            (Some(item0), None) => {
                result.push(item0);
                // Continue with remaining items from lst0
                result.extend(iter0);
                break;
            }
            (None, Some(item1)) => {
                result.push(item1);
                // Continue with remaining items from lst1 (already reversed)
                result.extend(iter1);
                break;
            }
            (None, None) => break,
        }
    }

    result
}

