fn interleave_reverse_iter<T>(lst0: Vec<T>, lst1: Vec<T>) -> Vec<T> {
    let mut iter0 = lst0.into_iter();
    let mut iter1 = lst1.into_iter().rev();

    std::iter::from_fn(move || {
        iter0.next().or_else(|| iter1.next())
    })
    .collect()
}

