use itertools::Itertools;

fn alternate_with_reverse(lst0: Vec<i32>, lst1: Vec<i32>) -> Vec<i32> {
    let reversed_lst1 = lst1.into_iter().rev();

    lst0.into_iter()
        .zip_longest(reversed_lst1)
        .flat_map(|pair| {
            use itertools::EitherOrBoth::*;
            match pair {
                Both(a, b) => vec![a, b],
                Left(a) => vec![a],
                Right(b) => vec![b],
            }
        })
        .collect()
}

fn main() {
    let lst0 = vec![1, 2, 3];
    let lst1 = vec![10, 20, 30];

    let result = alternate_with_reverse(lst0, lst1);
    println!("{:?}", result); // Output: [1, 30, 2, 20, 3, 10]
}
```

