/// Sorts a Polars DataFrame according to specified columns.
///
/// # Arguments
/// * `data0` - The input DataFrame to be sorted
/// * `cols0` - A list of column names to sort by (first column is primary sort key)
///
/// # Returns
/// A new sorted DataFrame
///
/// # Examples
/// ```
/// use polars::prelude::*;
///
/// let df = df!(
///     "A" => &[3, 1, 2],
///     "B" => &["z", "a", "y"],
///     "C" => &[10.5, 20.1, 5.3]
/// ).unwrap();
///
/// let sorted = sort_dataframe(&df, &["B", "A"]).unwrap();
/// ```
pub fn sort_dataframe(data0: &DataFrame, cols0: &[&str]) -> Result<DataFrame, PolarsError> {
    // Validate input columns exist
    let schema = data0.schema();
    let missing_cols: Vec<&str> = cols0
        .iter()
        .filter(|col| !schema.contains(*col))
        .collect();

    if !missing_cols.is_empty() {
        return Err(PolarsError::ComputeError(
            "ColumnNotFound".to_string(),
            format!("Columns not found: {:?}", missing_cols),
        ));
    }

    // Create sort expression
    let mut sort_expr = Vec::with_capacity(cols0.len());

    for col in cols0 {
        // Handle both string and numeric columns appropriately
        let col_type = schema.get(*col).unwrap().data_type();
        let expr = match col_type {
            DataType::Utf8 => col.to_string().into(),
            DataType::Int64 | DataType::Float64 | DataType::Float32 | DataType::Int32 |
            DataType::Int16 | DataType::Int8 | DataType::UInt64 | DataType::UInt32 |
            DataType::UInt16 | DataType::UInt16 => col.to_string().into(),
            _ => return Err(PolarsError::ComputeError(
                "UnsupportedType".to_string(),
                format!("Unsupported column type for sorting: {}", col),
            )),
        };

        sort_expr.push(expr);
    }

    // Perform the sort
    let sorted_df = data0.clone().lazy().sort(&sort_expr, DefaultSortOptions::default())?.collect()?;

    Ok(sorted_df)
}

