    // Create a new BTreeMap with the sorted key-value pairs
    let mut result: BTreeMap<String, Vec<i32>> = BTreeMap::new();
    for (key, value) in sorted_map {
        for (k, v) in value {
            result.insert(k, v);
        }
    }

    result
