use std::collections::HashMap;

/// Sum columns with identical headers in a numeric table.
///
/// Input:
/// - `headers`: slice of header names (may contain duplicates).
/// - `rows`: slice of rows; each row is a Vec<Option<f64>>. A None means missing cell.
///
/// Returns:
/// - (unique_headers, aggregated_rows) where each header appears only once and each
///   cell is the row-wise sum of all original columns that shared that header.
///   If all contributing cells for a given row/header were None, the result is None.
///
/// Keeps the order of first appearance of each header.
///
/// Example:
/// headers = ["A","B","A"]
/// rows = [ [Some(1.0), Some(2.0), Some(3.0)], [Some(4.0), None, Some(1.0)] ]
/// returns:
/// unique_headers = ["A","B"]
/// aggregated_rows = [ [Some(4.0), Some(2.0)], [Some(5.0), None] ]
pub fn sum_duplicate_headers(
    headers: &[String],
    rows: &[Vec<Option<f64>>],
) -> (Vec<String>, Vec<Vec<Option<f64>>>) {
    // Map header -> list of column indices that have that header
    let mut index_map: HashMap<&str, Vec<usize>> = HashMap::new();
    let mut unique_headers: Vec<String> = Vec::new();

    for (i, h) in headers.iter().enumerate() {
        let h_str: &str = h.as_str();
        if !index_map.contains_key(h_str) {
            unique_headers.push(h.clone());
            index_map.insert(h_str, vec![i]);
        } else {
            if let Some(vec) = index_map.get_mut(h_str) {
                vec.push(i);
            }
        }
    }

    // Prepare aggregated rows: for each input row, compute sums for each unique header
    let mut aggregated_rows: Vec<Vec<Option<f64>>> = Vec::with_capacity(rows.len());

    for row in rows.iter() {
        let mut new_row: Vec<Option<f64>> = Vec::with_capacity(unique_headers.len());

        for header in unique_headers.iter() {
            let indices = index_map.get(header.as_str()).expect("header should exist");
            let mut sum = 0.0_f64;
            let mut any = false;

            for &col_idx in indices.iter() {
                if let Some(cell) = row.get(col_idx) {
                    if let Some(v) = cell {
                        sum += *v;
                        any = true;
                    }
                }
                // if column index is out-of-range for this row, treat as None
            }

            if any {
                new_row.push(Some(sum));
            } else {
                new_row.push(None);
            }
        }

        aggregated_rows.push(new_row);
    }

    (unique_headers, aggregated_rows)
}

