pub fn sum_duplicate_columns(df: DataFrame) -> PolarsResult<DataFrame> {
    // Get column names and their indices
    let column_names: Vec<&str> = df.get_column_names();

    // Group column indices by their names
    let mut column_groups: HashMap<&str, Vec<usize>> = HashMap::new();
    for (idx, name) in column_names.iter().enumerate() {
        column_groups.entry(name).or_default().push(idx);
    }

    // Build new columns by summing duplicates
    let mut new_columns: Vec<Series> = Vec::with_capacity(column_groups.len());

    for (name, indices) in column_groups {
        if indices.len() == 1 {
            // Single column - just clone it
            new_columns.push(df.column(name)?.clone());
