/// ].unwrap();
///
/// let result = sum_duplicate_columns(df).unwrap();
/// // Result will have columns "A" (summed) and "B"
/// ```
fn sum_duplicate_columns(df: DataFrame) -> PolarsResult<DataFrame> {
    // Get all column names
    let column_names = df.get_column_names();

    // Collect unique column names while tracking which indices to sum
    let mut unique_columns: Vec<String> = Vec::new();
    let mut column_groups: Vec<Vec<usize>> = Vec::new();

    for (idx, col_name) in column_names.iter().enumerate() {
        if let Some(pos) = unique_columns.iter().position(|x| x == col_name) {
            // Add to existing group
            column_groups[pos].push(idx);
        } else {
            // Create new group
            unique_columns.push(col_name.to_string());
            column_groups.push(vec![idx]);
        }
    }

    // Build new dataframe with summed columns
    let mut new_columns: Vec<Series> = Vec::new();

    for (unique_name, indices) in unique_columns.iter().zip(column_groups.iter()) {
        let series_to_sum: Vec<Series> = indices
            .iter()
            .map(|&idx| df.select_at_idx(idx).unwrap().clone())
            .collect();

        // Sum all series with the same name
        let summed = if series_to_sum.len() == 1 {
            series_to_sum[0].clone()
        } else {
            // Use the first series as base and add others
            let mut result = series_to_sum[0].clone();
            for series in &series_to_sum[1..] {
                result = (&result + series)?;
            }
            result
        };

        // Rename to the unique column name
        new_columns.push(summed.rename(unique_name));
    }

    // Create new dataframe from columns
    DataFrame::new(new_columns)
}

