    let mut ordered_map: IndexMap<usize, Value> = IndexMap::new();

    // First pass: separate elements into two groups
    let mut keep_front: Vec<(usize, Value)> = Vec::new();
    let mut move_back: Vec<(usize, Value)> = Vec::new();

    for (index, item) in lst0.iter().enumerate() {
