            move_back.push((index, item.clone()));
        }
    }

    // Rebuild the vector with original order preserved within groups
    let mut result = Vec::with_capacity(lst0.len());
    result.extend(keep_front.into_iter().map(|(_, v)| v));
    result.extend(move_back.into_iter().map(|(_, v)| v));

    result
