    /// Stable-partition `slice` in-place according to `pred`.
    /// Elements satisfying `pred` will appear first, preserving order,
    /// followed by elements not satisfying `pred`, also preserving order.
    pub fn stable_partition_by<T, F>(slice: &mut Vec<T>, mut pred: F)
    where
        F: FnMut(&T) -> bool,
    {
        // Fast path: if empty or single element, nothing to do.
        if slice.len() <= 1 {
            return;
        }

        let mut left: Vec<T> = Vec::with_capacity(slice.len());
        let mut right: Vec<T> = Vec::with_capacity(slice.len());

        // Drain by moving out of the original vector
        for item in slice.drain(..) {
            if pred(&item) {
                left.push(item);
            } else {
                right.push(item);
            }
        }

        // Reconstruct original vector: left then right.
        slice.extend(left);
        slice.extend(right);
    }

