/// assert_eq!(data[2].get("type").unwrap(), "b");
/// ```
pub fn reorder_by_key_value(
    lst0: &mut Vec<IndexMap<String, String>>,
    var0: &str,
    var1: &str,
) {
    // Partition the vector in-place while preserving relative order
    // Elements matching the condition stay in front, others go to the back
    let mut write_pos = 0;

    // First pass: move matching elements to the front
    for read_pos in 0..lst0.len() {
        if lst0[read_pos].get(var0).map_or(false, |v| v == var1) {
            if read_pos != write_pos {
                lst0.swap(read_pos, write_pos);
            }
            write_pos += 1;
        }
    }

    // Note: The elements that don't match are now at positions write_pos..len()
    // Their relative order is preserved because we only swapped matching elements forward
}

