/// Transforms a nested sequence of two-element sequences into a HashMap.
/// 
/// Takes a slice of tuples/pairs where each inner sequence contains exactly two elements.
/// The first element becomes the key and the second becomes the value.
/// 
/// # Arguments
/// * `sequences` - A slice of tuples containing (key, value) pairs
/// 
/// # Returns
/// A HashMap where keys are the first elements and values are the second elements
/// 
/// # Example
/// ```
/// let input = vec![(1, "a"), (2, "b"), (3, "c")];
/// let result = transform_to_mapping(input.as_slice());
/// assert_eq!(result.get(&1), Some(&"a"));
/// assert_eq!(result.get(&2), Some(&"b"));
/// ```
fn transform_to_mapping<K, V>(sequences: &[(K, V)]) -> HashMap<K, V>
where
    K: Eq + std::hash::Hash + Clone,
    V: Clone,
{
    sequences
        .iter()
        .map(|(key, value)| (key.clone(), value.clone()))
        .collect()
}

