/// ```
fn iterate_and_apply<F>(df0: &Array2<f64>, var0: usize, func: F)
where
    F: Fn(f64) -> f64,
{
    match var0 {
        0 => {
            // Iterate along rows (axis 0)
            for row in df0.rows() {
                for &element in row.iter() {
                    let result = func(element);
                    println!("Processing element: {} -> {}", element, result);
                }
            }
