        1 => {
            // Iterate along columns (axis 1)
            for col in df0.columns() {
                for &element in col.iter() {
                    let result = func(element);
                    println!("Processing element: {} -> {}", element, result);
                }
            }
        }
        _ => panic!("Invalid axis. Use 0 for rows or 1 for columns."),
    }
}

/// Alternative version that collects and returns results
fn iterate_and_collect<F>(df0: &Array2<f64>, var0: usize, func: F) -> Vec<f64>
where
    F: Fn(f64) -> f64,
{
    let mut results = Vec::new();

    match var0 {
        0 => {
            for row in df0.rows() {
                for &element in row.iter() {
                    results.push(func(element));
                }
            }
        }
        1 => {
            for col in df0.columns() {
                for &element in col.iter() {
                    results.push(func(element));
                }
            }
        }
        _ => panic!("Invalid axis. Use 0 for rows or 1 for columns."),
    }

    results
}

