pub fn sum_second_elements(data: Vec<Vec<Vec<f64>>>) -> Vec<f64> {
    data.iter()
        .map(|sublist| {
            sublist
                .iter()
                .map(|inner_list| {
                    // Get the second element (index 1) and sum them
                    inner_list[1]
                })
                .sum()
        })
        .collect()
}

/// Alternative implementation using ndarray for better performance with large datasets
pub fn sum_second_elements_ndarray(data: Vec<Vec<Vec<f64>>>) -> Vec<f64> {
    // Convert to 3D array if possible, otherwise process iteratively
    if data.is_empty() {
        return Vec::new();
    }

    let n_outer = data.len();
    let n_mid = data[0].len();
    let n_inner = data[0][0].len();

    // Check if all dimensions are consistent for array conversion
    let is_regular = data.iter().all(|sublist| {
        sublist.len() == n_mid && sublist.iter().all(|inner| inner.len() == n_inner)
    });

    if is_regular && n_inner >= 2 {
        // Convert to 3D array and extract second elements
        let flat: Vec<f64> = data.into_iter().flatten().flatten().collect();
        let array = Array2::from_shape_vec((n_outer * n_mid, n_inner), flat)
            .expect("Failed to create array");

        // Extract column 1 (second elements) and reshape
        let second_elements = array.column(1).to_vec();

        // Sum in groups of n_mid
        second_elements
            .chunks(n_mid)
            .map(|chunk| chunk.iter().sum())
            .collect()
    } else {
        // Fall back to iterative approach for irregular data
        sum_second_elements(data)
    }
}

