```rust
use std::str::FromStr;

/// Given a slice of (label, value_str) pairs, return the pair with the smallest valid numeric value.
/// A "valid" numeric value is one that successfully parses to f64 and is finite (not NaN or ±inf).
///
/// Returns `None` if no valid numeric value is found.
///
/// Example:
/// let items = vec![
///     ("a".to_string(), "3.5".to_string()),
///     ("b".to_string(), "invalid".to_string()),
///     ("c".to_string(), "-1.2".to_string()),
/// ];
/// assert_eq!(min_valid_pair(&items), Some(("c".to_string(), -1.2)));
pub fn min_valid_pair(pairs: &[(String, String)]) -> Option<(String, f64)> {
    let mut best: Option<(String, f64)> = None;

    for (label, s_val) in pairs {
        // try to parse the numeric value
        if let Ok(v) = f64::from_str(s_val) {
            // ignore NaN and infinite values
            if !v.is_finite() {
                continue;
            }

            match &best {
                None => best = Some((label.clone(), v)),
                Some((_, best_v)) => {
                    if v < *best_v {
                        best = Some((label.clone(), v));
                    }
                }
            }
        }
    }

    best
}

