/// Compare two sequences position-by-position.
///
/// Strict version: returns Err if lengths differ.
pub fn elementwise_equal_strict<T: PartialEq>(a: &[T], b: &[T]) -> Result<Vec<bool>, String> {
    if a.len() != b.len() {
        return Err(format!("length mismatch: {} vs {}", a.len(), b.len()));
    }
    Ok(a.iter().zip(b.iter()).map(|(x, y)| x == y).collect())
}

/// Zip-up-to-min version: returns comparisons for positions 0..min(len(a), len(b)).
pub fn elementwise_equal_zip<T: PartialEq, A: IntoIterator<Item = T>, B: IntoIterator<Item = T>>(
    a: A,
    b: B,
) -> Vec<bool> {
    a.into_iter().zip(b).map(|(x, y)| x == y).collect()
}

fn main() {
    // Example 1: strict (same-length)
    let a = [1, 2, 3];
    let b = [1, 0, 3];
    match elementwise_equal_strict(&a, &b) {
        Ok(vec) => println!("strict equal positions: {:?}", vec), // prints [true, false, true]
