/// Sorts the text elements in ascending order by default, but sorts those at the specified positions in descending order.
///
/// # Arguments
///
/// * `text_elements`: A vector of text elements to be sorted.
/// * `positions`: An optional vector of integer positions. If provided, elements at these positions will be sorted in descending order.
///
/// # Returns
///
/// A vector of sorted text elements.
fn custom_sort(text_elements: Vec<String>, positions: Option<Vec<usize>>) -> Vec<String> {
    let mut sorted_elements: Vec<String> = text_elements;
    sorted_elements.sort_unstable();

    if let Some(positions) = positions {
        let mut result: Vec<String> = Vec::new();
        let mut index = 0;
        for &pos in positions.iter() {
            // Add elements before the current position in ascending order
            while index < pos {
                result.push(sorted_elements[index].clone());
                index += 1;
            }
            // Add the element at the current position in descending order
            if let Some(element) = sorted_elements.get(pos) {
                result.push(element.clone());
            }
            index += 1;
        }
        // Add any remaining elements in ascending order
        while index < sorted_elements.len() {
            result.push(sorted_elements[index].clone());
            index += 1;
        }
        result
    } else {
        sorted_elements
    }
}

