mod sortkit2025 {
    use std::collections::BTreeSet;

    /// Sort items normally ascending, but sort items at the given positions descending.
    ///
    /// - `items` is any slice of types that implement AsRef<str>.
    /// - `positions` is an optional slice of 0-based indices. If `None`, all items are
    ///   sorted ascending and returned.
    ///
    /// Behavior details:
    /// - Indices out of range are ignored.
    /// - Duplicate indices are treated once.
    /// - Relative slot positions are preserved: the elements selected by `positions`
    ///   are extracted, sorted descending, then put back only into those slots. Similarly
    ///   the remaining slots are filled with the ascending-sorted remaining elements.
    ///
    /// Examples:
    /// ```
    /// use sortkit2025::mixed_sort_texts;
    ///
    /// let v = vec!["c","a","b","d"].iter().map(|s| s.to_string()).collect::<Vec<_>>();
    /// // Positions 0 and 3 will be sorted descending among themselves and placed back at 0 and 3.
    /// let res = mixed_sort_texts(&v, Some(&[0, 3]));
    /// assert_eq!(res, vec!["d", "a", "b", "c"]);
    ///
    /// // If positions is None, sort all ascending:
    /// let res2 = mixed_sort_texts(&v, None);
    /// assert_eq!(res2, vec!["a", "b", "c", "d"]);
    /// ```
    pub fn mixed_sort_texts<T: AsRef<str>>(items: &[T], positions: Option<&[usize]>) -> Vec<String> {
        let len = items.len();

        // If no positions given, just return a fully ascending sorted vector.
        if positions.is_none() {
            let mut all: Vec<String> = items.iter().map(|s| s.as_ref().to_string()).collect();
            all.sort(); // ascending
            return all;
        }

        // Build a set of valid, unique indices.
        let pos_slice = positions.unwrap();
        let mut idx_set = BTreeSet::<usize>::new();
        for &i in pos_slice.iter() {
            if i < len {
                idx_set.insert(i);
            }
        }

        // If there are no valid indices, fallback to full ascending sort.
        if idx_set.is_empty() {
            let mut all: Vec<String> = items.iter().map(|s| s.as_ref().to_string()).collect();
            all.sort();
            return all;
        }

        // Collect elements at selected positions (to be sorted descending)
        let mut desc_elems: Vec<String> = idx_set
            .iter()
            .map(|&i| items[i].as_ref().to_string())
            .collect();
        desc_elems.sort(); // ascending first
        desc_elems.reverse(); // now descending

        // Collect remaining elements (to be sorted ascending)
        let mut asc_elems: Vec<String> = items
            .iter()
            .enumerate()
            .filter_map(|(i, v)| if idx_set.contains(&i) { None } else { Some(v.as_ref().to_string()) })
            .collect();
        asc_elems.sort();

        // Reconstruct result: fill positions in order, using iterators for each pool.
        let mut desc_it = desc_elems.into_iter();
        let mut asc_it = asc_elems.into_iter();
        let mut result = Vec::with_capacity(len);

        for i in 0..len {
            if idx_set.contains(&i) {
                // safe: we ensured desc_it has exactly |idx_set| elements
                result.push(desc_it.next().unwrap());
            } else {
                result.push(asc_it.next().unwrap());
            }
        }

        result
    }

    // Re-export for convenience when using the module as a crate.
    pub use mixed_sort_texts;
}

