use std::cmp::Reverse;
use std::collections::BinaryHeap;

/// Return the indices of the `var0` largest elements in `lst0`,
/// sorted from highest value to lowest. Ties are broken by smaller index first.
/// 
/// - lst0: slice of values (T must implement Ord + Clone)
/// - var0: number of top elements to return (if >= lst0.len(), returns indices of all elements)
pub fn top_k_indices<T: Ord + Clone>(lst0: &[T], var0: usize) -> Vec<usize> {
    let n = lst0.len();
    if var0 == 0 || n == 0 {
        return Vec::new();
    }
    let k = std::cmp::min(var0, n);

    // Min-heap of the current top-k, stored as Reverse((value, index))
    // so heap.peek() is the smallest (value, index) among current top-k.
    let mut heap: BinaryHeap<Reverse<(T, usize)>> = BinaryHeap::with_capacity(k + 1);

    for (i, v) in lst0.iter().cloned().enumerate() {
        let entry = Reverse((v, i));
        if heap.len() < k {
            heap.push(entry);
        } else if entry.0 > heap.peek().unwrap().0 {
            // current entry is strictly greater (by value, then index) than the smallest in heap
            heap.pop();
            heap.push(entry);
        }
    }

    // Extract and sort by value descending, then index ascending
    let mut vec: Vec<(T, usize)> = heap.into_iter().map(|r| r.0).collect();
    vec.sort_by(|a, b| b.0.cmp(&a.0).then(a.1.cmp(&b.1)));

    vec.into_iter().map(|(_, idx)| idx).collect()
}

