use std::collections::HashSet;
use std::error::Error;
use std::fs::File;
use std::io::{BufReader, BufWriter};

pub fn remove_duplicate_identifiers_csv(
    input_path: &str,
    output_path: &str,
    id_col: &str,
) -> Result<(), Box<dyn Error>> {
    // Open reader and writer with buffering
    let rdr_file = File::open(input_path)?;
    let mut rdr = csv::Reader::from_reader(BufReader::new(rdr_file));

    let wtr_file = File::create(output_path)?;
    let mut wtr = csv::Writer::from_writer(BufWriter::new(wtr_file));

    // Read headers and locate id column index
    let headers = rdr.headers()?.clone(); // csv::StringRecord
    let id_index = headers
        .iter()
        .position(|h| h == id_col)
        .ok_or_else(|| format!("Identifier column '{}' not found in headers", id_col))?;

    // Write headers to output
    wtr.write_record(&headers)?;

    // Track seen identifiers
    let mut seen: HashSet<String> = HashSet::new();

    // Iterate records streaming; keep first occurrence of each id
    for result in rdr.records() {
        let record = result?;
        // get returns Option<&str>, fallback to empty string if missing
        let id_val = record.get(id_index).unwrap_or("").to_string();

        // Insert returns true only if it was not present before
        if seen.insert(id_val) {
            wtr.write_record(&record)?;
        }
    }

    // Ensure all data is written
    wtr.flush()?;
    Ok(())
}
```

