/// Inserts a new sublist into a list of sublists, maintaining sorted order
/// by the second element of each sublist.
///
/// # Arguments
/// * `lists` - A mutable vector of vectors containing integers
/// * `new_sublist` - The sublist to insert
///
/// # Example
/// ```
/// let mut data = vec![
///     vec![1, 10],
///     vec![2, 20],
///     vec![3, 30],
/// ];
/// insert_sorted_sublist(&mut data, vec![4, 15]);
/// assert_eq!(data, vec![
///     vec![1, 10],
///     vec![4, 15],
///     vec![2, 20],
///     vec![3, 30],
/// ]);
/// ```
fn insert_sorted_sublist(lists: &mut Vec<Vec<i32>>, new_sublist: Vec<i32>) {
    // Find the correct position to insert based on the second element
    let position = lists.iter().position(|sublist| {
        sublist.get(1).unwrap_or(&i32::MAX) > new_sublist.get(1).unwrap_or(&i32::MAX)
    }).unwrap_or(lists.len());

    lists.insert(position, new_sublist);
}

fn main() {
