    let mut new_df = df.clone();

    // Get the penultimate column
    let penultimate_col = new_df.column(penultimate_col_name).unwrap();

    // Convert to Series for processing
    let mut series = penultimate_col.to_series();

    // Process each value to remove currency symbol and convert to f64
    let processed_series = series
        .into_iter()
        .map(|opt_val| {
            opt_val.map(|val| {
                // Convert to string slice
                let s: &str = val.downcast_ref::<&str>().unwrap();

                // Remove currency symbol from start
                let mut chars = s.chars();
                let mut cleaned = String::new();

                // Skip the currency symbol if it matches
                if let Some(first_char) = chars.next() {
                    if first_char == currency_symbol.chars().next().unwrap() {
                        // Skip the symbol and any whitespace
                        while let Some(c) = chars.next() {
                            if !c.is_whitespace() {
                                cleaned.push(c);
                                break;
                            }
                        }
                    } else {
                        // If first character doesn't match, prepend it
                        cleaned.push(first_char);
                    }
                }

                // Append the rest of the characters
                for c in chars {
                    cleaned.push(c);
                }

                // Try to parse as f64
