                    PolarsError::ComputeError(format!(
                        "Failed to parse '{}' as f64 after removing currency symbol",
                        cleaned
                    ))
                })
            })
        })
        .collect::<Series>()?;

    // Replace the penultimate column with the processed series
    new_df = new_df.with_column(
        Column::new(penultimate_col_name, processed_series)
    );

    Ok(new_df)
}

