/// - If your data uses a decimal comma (e.g. "1.234,56"), pre-normalize to a dot decimal before calling.
pub fn extract_penultimate_currency_column(table: &[Vec<String>]) -> Result<Vec<f64>, String> {
    fn parse_currency_str(s: &str) -> Result<f64, String> {
        let mut t = s.trim().to_string();
        if t.is_empty() {
            return Err("empty string".into());
        }

        // Remove common thousands separators: comma, ASCII space, NBSP, apostrophe
        t = t.replace(',', "")
             .replace(' ', "")
             .replace('\u{00A0}', "")
             .replace('\'', "");

        // Handle parentheses as negative numbers: "(1,234.56)" -> -1234.56
        let negative = if t.starts_with('(') && t.ends_with(')') {
            t = t[1..t.len()-1].to_string();
            true
        } else {
            false
        };

        // Strip leading non-numeric characters (e.g. currency symbols, leading letters)
        while let Some(ch) = t.chars().next() {
            if ch.is_ascii_digit() || ch == '+' || ch == '-' || ch == '.' { break; }
            t.remove(0);
        }

        // Strip trailing non-numeric characters (e.g. currency codes like "USD")
        while let Some(ch) = t.chars().last() {
            if ch.is_ascii_digit() || ch == '.' || ch == 'e' || ch == 'E' || ch == '+' || ch == '-' { break; }
            t.pop();
        }

        if t.is_empty() {
            return Err("no numeric content after stripping".into());
        }

        // Normalize unicode minus sign to ASCII minus
        let t = t.replace('−', "-");

        // Finally parse
        match t.parse::<f64>() {
            Ok(v) => Ok(if negative { -v } else { v }),
            Err(e) => Err(format!("parse error '{}': {}", t, e)),
        }
    }

    let mut out = Vec::with_capacity(table.len());
    for (i, row) in table.iter().enumerate() {
        if row.len() < 2 {
            return Err(format!("row {}: fewer than 2 columns", i));
