use polars::prelude::*;
use std::error::Error;

/// Unpivots columns from a DataFrame, creating rows with original column names and values.
///
/// # Arguments
/// * `df0` - The input DataFrame containing the data to unpivot
/// * `lst0` - A list of column names to unpivot
///
/// # Returns
/// A Result containing the unpivoted DataFrame or an error
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let df = df!(
///     "A" => &[1, 2, 3],
///     "B" => &[4, 5, 6],
///     "C" => &[7, 8, 9]
/// ).unwrap();
///
/// let unpivoted = unpivot_columns(&df, &["A", "B"]).unwrap();
/// println!("{:?}", unpivoted);
/// ```
pub fn unpivot_columns(df0: &DataFrame, lst0: &[&str]) -> Result<DataFrame, Box<dyn Error>> {
    // Create a new DataFrame with only the columns we want to unpivot
    let df_filtered = df0.clone().lazy().select(lst0.iter().map(|&col| col.to_string()))?
        .collect()?;

    // Create a new DataFrame with the remaining columns (excluding those to unpivot)
    let df_remaining = df0.clone().lazy().select(
        df0.get_column_names()?
            .into_iter()
            .filter(|col| !lst0.contains(&col.as_str()))
            .map(|col| col.to_string())
    )?
    .collect()?;

    // Create a list of all rows from the filtered DataFrame
    let rows = df_filtered.lazy().collect()?.into_iter().collect::<Vec<_>>();

    // Create a new DataFrame with the unpivoted structure
    let mut unpivoted_rows = Vec::new();

    for row in rows {
        let mut new_row = HashMap::new();
        let mut id = 0;

        // Add the remaining columns (non-unpivoted) to each new row
        for col in df_remaining.get_column_names()? {
            new_row.insert(col.to_string(), row.get(col).unwrap());
        }

        // Add the unpivoted columns
        for (i, col) in lst0.iter().enumerate() {
            new_row.insert("var0".to_string(), col.to_string());
            new_row.insert("var1".to_string(), row.get(col).unwrap());
            new_row.insert("id".to_string(), id);
            unpivoted_rows.push(new_row.clone());
            id += 1;
        }
    }

    // Convert to DataFrame
    let schema = Schema::new(vec![
        Field::new("var0", DataType::Utf8, false),
        Field::new("var1", DataType::Object, false),
        Field::new("id", DataType::Int64, false),
    ]);

    // Add the remaining columns to the schema
    for col in df_remaining.get_column_names()? {
        let dtype = df_remaining.column(col)?.dtype().clone();
        schema.add_field(Field::new(col.to_string(), dtype, false));
    }

    let mut df = DataFrame::new(schema)?;

    // Add the unpivoted data
    for row in unpivoted_rows {
        let mut new_row = Vec::new();
        for col in df.get_column_names()? {
            new_row.push(row.get(col).unwrap());
        }
        df.append_row(new_row)?;
    }

    Ok(df)
}

