use std::hash::Hash;

/// Assign integer labels to each unique element in `items`.
///
/// Labels start at 0 and reflect the order in which elements first appear.
/// Returns (labels_per_item, uniques_in_label_order).
///
/// Example:
/// let items = ["a", "b", "a", "c"];
/// let (labels, uniques) = assign_labels(&items);
/// // labels == [0, 1, 0, 2]
/// // uniques == ["a", "b", "c"]
pub fn assign_labels<T>(items: &[T]) -> (Vec<usize>, Vec<T>)
where
    T: Eq + Hash + Clone,
{
    let mut map: HashMap<T, usize> = HashMap::with_capacity(items.len());
