/// ```
/// let input = vec!["apple", "banana", "apple", "cherry", "banana"];
/// let labels = label_unique_elements(&input);
/// assert_eq!(labels, vec![0, 1, 0, 2, 1]);
/// ```
fn label_unique_elements<T: Eq + std::hash::Hash + Clone>(items: &[T]) -> Vec<usize> {
    let mut label_map: HashMap<T, usize> = HashMap::new();
    let mut next_label = 0;
    let mut result = Vec::with_capacity(items.len());

    for item in items {
        let label = label_map.entry(item.clone()).or_insert_with(|| {
            let current_label = next_label;
            next_label += 1;
            current_label
        });
        result.push(*label);
    }

    result
}

