use polars::prelude::*;

/// Split the "str0" column at the first space into new columns "str1" and "str2".
/// - If a value in "str0" contains a space, str1 gets the substring before the first space,
///   str2 gets the substring after the first space.
/// - If a value has no space, str1 gets the whole value and str2 is null.
/// - Nulls in str0 produce nulls in both outputs.
///
/// Returns a new DataFrame with the two new columns appended.
fn split_str0_at_first_space(df: &DataFrame) -> PolarsResult<DataFrame> {
    // Get the "str0" column as an Utf8Chunked
    let s = df.column("str0")?.utf8()?;

    // Prepare vectors to build new columns (Option<String> to preserve nulls)
    let mut left: Vec<Option<String>> = Vec::with_capacity(s.len());
    let mut right: Vec<Option<String>> = Vec::with_capacity(s.len());

    for opt in s.into_iter() {
        match opt {
            Some(text) => {
                if let Some(pos) = text.find(' ') {
                    left.push(Some(text[..pos].to_string()));
                    // skip the space at pos
                    right.push(Some(text[pos + 1..].to_string()));
                } else {
                    // no space: entire string goes to left, right is null
                    left.push(Some(text.to_string()));
                    right.push(None);
                }
            }
            None => {
                left.push(None);
                right.push(None);
            }
        }
    }

    // Create Series for new columns
    let left_series = Series::new("str1", left);
    let right_series = Series::new("str2", right);

    // Clone input DataFrame, append the new columns, return
    let mut out = df.clone();
    out.with_column(left_series)?;
    out.with_column(right_series)?;
    Ok(out)
}

