use ndarray::{Array2, ArrayView2, Axis};

/// Computes the mean of corresponding entries across multiple 2D numeric tables.
///
/// # Arguments
/// * `tables` - A list of 2D numeric arrays (Array2<f64> or Array2<i64>)
///
/// # Returns
/// A new Array2 containing the mean of each corresponding entry across all input tables.
///
/// # Panics
/// Panics if the input tables have different dimensions.
///
/// # Examples
/// ```
/// use ndarray::array;
///
/// let tables = vec![
///     array![[1.0, 2.0], [3.0, 4.0]],
///     array![[5.0, 6.0], [7.0, 8.0]],
/// ];
/// let mean = mean_tables(&tables);
/// assert_eq!(mean, array![[3.0, 4.0], [5.0, 5.0]]);
/// ```
pub fn mean_tables<T>(tables: &[Array2<T>]) -> Array2<f64>
where
    T: Into<f64> + Copy,
{
    // Check for empty input
    if tables.is_empty() {
        return Array2::zeros((0, 0));
    }

    // Get the shape of the first table as reference
    let shape = tables[0].shape();

    // Verify all tables have the same shape
    for table in tables.iter().skip(1) {
        assert_eq!(table.shape(), shape,
            "All tables must have the same dimensions");
    }

    // Initialize result array with zeros
    let mut result = Array2::zeros(shape);

    // Sum all values for each position
    for table in tables {
        for ((i, j), &val) in table.indexed_iter() {
            result[[i, j]] += val.into();
        }
    }

    // Divide by number of tables to get mean
    result.mapv(|x| x / tables.len() as f64)
}
