/// Compute the mean of corresponding entries across multiple 2D numeric tables.
///
/// # Arguments
///
/// * `tables` - A slice of 2D arrays (f64) that must all have the same dimensions.
///
/// # Returns
///
/// * `Ok(Array2<f64>)` - A new 2D array where each entry is the mean of the corresponding
///   entries across all input tables.
/// * `Err(String)` - An error message if the tables have inconsistent dimensions or if
///   the input is empty.
///
/// # Example
///
/// ```
/// use ndarray::array;
///
/// let table1 = array![[1.0, 2.0], [3.0, 4.0]];
/// let table2 = array![[5.0, 6.0], [7.0, 8.0]];
/// let tables = vec![table1, table2];
///
/// let result = mean_of_tables(&tables).unwrap();
/// assert_eq!(result, array![[3.0, 4.0], [5.0, 6.0]]);
/// ```
pub fn mean_of_tables(tables: &[Array2<f64>]) -> Result<Array2<f64>, String> {
    if tables.is_empty() {
        return Err("Input list is empty".to_string());
    }

    // Check that all tables have the same dimensions
    let reference_shape = tables[0].shape().to_vec();
    for (i, table) in tables.iter().enumerate().skip(1) {
        if table.shape() != reference_shape.as_slice() {
            return Err(format!(
                "Table {} has shape {:?}, but expected {:?}",
                i,
                table.shape(),
                reference_shape
            ));
        }
    }

    // Stack all tables along a new axis (axis 0 becomes the table index)
    let stacked = stack(Axis(0), tables).map_err(|e| format!("Stacking error: {}", e))?;

    // Compute mean along axis 0 (across all tables)
    let mean = stacked.mean_axis(Axis(0)).unwrap();

    Ok(mean)
}

