Here's a self-contained Rust function that combines a list of integers into a single integer using positional powers of 10:

```rust
/// Combines a list of integers into a single integer by summing each element
/// multiplied by the power of ten corresponding to its position.
/// 
/// # Arguments
/// * `digits` - A slice of integers to combine
/// 
/// # Returns
/// The combined integer result
/// 
/// # Example
/// ```
/// assert_eq!(combine_digits(&[1, 2, 3]), 123);
/// assert_eq!(combine_digits(&[5, 0, 7]), 507);
/// assert_eq!(combine_digits(&[9]), 9);
/// ```
fn combine_digits(digits: &[i32]) -> i64 {
    digits
        .iter()
        .enumerate()
        .map(|(pos, &digit)| {
            let exponent = (digits.len() - 1 - pos) as u32;
            (digit as i64) * 10_i64.pow(exponent)
        })
        .sum()
}

fn main() {
    println!("Test 1: {:?} -> {}", vec![1, 2, 3], combine_digits(&[1, 2, 3]));
    println!("Test 2: {:?} -> {}", vec![5, 0, 7], combine_digits(&[5, 0, 7]));
    println!("Test 3: {:?} -> {}", vec![9], combine_digits(&[9]));
    println!("Test 4: {:?} -> {}", vec![1, 0, 0, 5], combine_digits(&[1, 0, 0, 5]));
}
```

