use std::collections::HashMap;
use std::hash::Hash;

/// Create an associative mapping from two sequences:
/// elements from `keys_iter` become keys and corresponding elements from
/// `vals_iter` become values.
///
/// Returns Err if the two sequences have different lengths.
///
/// Example:
/// let m = zip_to_map(vec![1,2,3], vec!["a","b","c"])?;
pub fn zip_to_map<K, V, KI, VI>(
    keys_iter: KI,
    vals_iter: VI,
) -> Result<HashMap<K, V>, String>
where
    KI: IntoIterator<Item = K>,
    VI: IntoIterator<Item = V>,
    K: Eq + Hash,
{
    let mut keys = keys_iter.into_iter();
    let mut vals = vals_iter.into_iter();
    let mut map: HashMap<K, V> = HashMap::new();

    loop {
        match (keys.next(), vals.next()) {
            (Some(k), Some(v)) => {
                map.insert(k, v);
            }
            (None, None) => break,
            (Some(_), None) => return Err("keys and values have different lengths: more keys than values".into()),
            (None, Some(_)) => return Err("keys and values have different lengths: more values than keys".into()),
        }
    }

    Ok(map)
}

fn main() -> Result<(), String> {
    // Example 1: vectors of same length
    let keys = vec!["apple", "banana", "cherry"];
    let vals = vec![1, 2, 3];
    let m = zip_to_map(keys, vals)?;
    assert_eq!(m.get("banana"), Some(&2));
    println!("Map: {:?}", m);

    // Example 2: length mismatch -> Err
    let k2 = vec![1, 2];
    let v2 = vec!["x", "y", "z"];
    match zip_to_map(k2, v2) {
        Ok(_) => println!("unexpected success"),
        Err(e) => println!("expected error: {}", e),
    }

    // Note: if keys contain duplicates, later values overwrite earlier ones (HashMap::insert behavior).
    Ok(())
}
```

Notes:
- The function is generic over any IntoIterator for keys and values.
- Keys must implement Eq + Hash to be used in HashMap.
- If you want to preserve insertion order for duplicate keys, you can use the indexmap crate (IndexMap) in place of HashMap.
- If you prefer a variant that truncates to the shorter sequence instead of returning an error on length mismatch, that can be provided as well. Which behavior do you prefer?

