fn create_mapping_itertools<K: Eq + std::hash::Hash, V>(
    var0: impl IntoIterator<Item = K>,
    var1: impl IntoIterator<Item = V>,
) -> HashMap<K, V> {
    var0.into_iter()
        .zip(var1)
        .collect::<HashMap<_, _>>()
