use std::collections::HashMap;
use std::hash::Hash;

/// Group rows by the key (var0) and sum all other numeric columns (element-wise).
///
/// - `rows` is a slice of pairs (key, values), where `values` contains the numeric columns
///   (columns 1..N) for that row.
/// - All `values` vectors must have the same length.
/// - Returns a Vec of (key, summed_values). Order is unspecified (depends on HashMap iteration).
///
/// Example:
/// let rows = vec![
///     ("A".to_string(), vec![1.0, 2.0]),
///     ("B".to_string(), vec![3.0, 4.0]),
///     ("A".to_string(), vec![5.0, 6.0]),
/// ];
/// let out = aggregate_by_var0(&rows);
/// // out contains ("A", vec![6.0, 8.0]) and ("B", vec![3.0, 4.0]) (order unspecified)
pub fn aggregate_by_var0<K>(rows: &[(K, Vec<f64>)]) -> Vec<(K, Vec<f64>)>
where
    K: Eq + Hash + Clone,
{
    if rows.is_empty() {
        return Vec::new();
    }

    // Ensure consistent row widths (panic on mismatch)
    let width = rows[0].1.len();
    for (_, vals) in rows.iter() {
        assert!(
            vals.len() == width,
            "All value vectors must have the same length"
        );
    }

    let mut map: HashMap<K, Vec<f64>> = HashMap::new();

    for (key, vals) in rows.iter() {
        let entry = map.entry(key.clone()).or_insert_with(|| vec![0.0; width]);
        for i in 0..width {
            entry[i] += vals[i];
        }
    }

    // Convert to Vec and return. If desired, caller can sort the Vec by key.
    map.into_iter().collect()
}

