        ("A".to_string(), vec![5.0, 6.0]),
        ("C".to_string(), vec![0.5, 1.5]),
        ("B".to_string(), vec![1.0, 1.0]),
    ];

    let aggregated = aggregate_by_var0(&rows);

    // Print results
    for (k, sums) in aggregated {
        println!("{} -> {:?}", k, sums);
    }
}
