use polars::prelude::*;

/// Groups rows by a column and sums all other numeric columns
/// 
/// # Arguments
/// * `df` - Input DataFrame with data to group and aggregate
/// * `group_col` - Name of the column to group by
///
/// # Returns
/// * `Result<DataFrame, PolarsError>` - Aggregated DataFrame with summed values
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let mut data = std::collections::HashMap::new();
/// data.insert("var0", Series::new("var0", &["A", "A", "B", "B"]));
/// data.insert("var1", Series::new("var1", &[1, 2, 3, 4]));
/// data.insert("var2", Series::new("var2", &[10, 20, 30, 40]));
///
/// let df = DataFrame::new(data.values().cloned().collect()).unwrap();
/// let result = group_and_sum(df, "var0").unwrap();
/// println!("{}", result);
/// ```
fn group_and_sum(df: DataFrame, group_col: &str) -> Result<DataFrame, PolarsError> {
    df.lazy()
        .groupby([group_col])?
        .agg(
            df.get_columns()
                .iter()
                .filter(|col| col.name() != group_col)
                .map(|col| col.sum())
                .collect::<Vec<_>>()
        )
        .collect()
}

fn main() -> Result<(), PolarsError> {
    // Example usage
    let df = DataFrame::new(vec![
        Series::new("var0", &["A", "A", "B", "B", "C"]),
        Series::new("var1", &[1, 2, 3, 4, 5]),
        Series::new("var2", &[10, 20, 30, 40, 50]),
        Series::new("var3", &[100, 200, 300, 400, 500]),
    ])?;

