use std::collections::HashMap;

/// Fill missing entries (None) in the specified categorical columns with the column mode.
/// - `df`: slice of rows (each row: column name -> Option<String>)
/// - `categorical_columns`: list of column names to treat as categorical
///
/// Behavior:
/// - For each column, compute the most frequent non-null string value (mode).
/// - Replace None entries (or missing keys) in that column with the mode.
/// - If a column has no non-null values, it is left unchanged.
fn fill_missing_categories_with_mode(
    df: &mut [HashMap<String, Option<String>>],
    categorical_columns: &[&str],
) {
    for &col in categorical_columns {
        // Count occurrences of each non-null value
        let mut counts: HashMap<String, usize> = HashMap::new();
        for row in df.iter() {
            if let Some(Some(val)) = row.get(col) {
                counts
                    .entry(val.clone())
                    .and_modify(|c| *c += 1)
                    .or_insert(1);
            }
        }

        // If there are no non-null values for this column, skip it
        if counts.is_empty() {
            continue;
        }

        // Find mode (most frequent value). If tie, arbitrary one (first max found) is used.
        let mode = counts
            .into_iter()
            .max_by_key(|(_, count)| *count)
            .map(|(val, _)| val)
            .unwrap();

        // Fill missing values (None) or missing keys with the mode
        for row in df.iter_mut() {
            match row.get_mut(col) {
                Some(opt) => {
                    if opt.is_none() {
                        *opt = Some(mode.clone());
                    }
                }
                None => {
                    // Column absent in this row -> insert with mode
                    row.insert(col.to_string(), Some(mode.clone()));
                }
            }
        }
    }
}

