/// ).unwrap();
/// 
/// let result = impute_categorical_mode(df).unwrap();
/// println!("{:?}", result);
/// ```
pub fn impute_categorical_mode(df0: DataFrame) -> Result<DataFrame> {
    let mut df = df0.clone();

    // Collect column names that are categorical (String or Categorical type)
    let categorical_cols: Vec<&str> = df
        .get_column_names()
        .iter()
        .filter(|&&name| {
            let col = df.column(name).unwrap();
            matches!(col.dtype(), DataType::String | DataType::Categorical(None))
        })
        .copied()
        .collect();

    // For each categorical column, find the mode and impute missing values
    for col_name in categorical_cols {
        let col = df.column(col_name)?.clone();

        // Get the mode (most frequent non-null value)
        let mode_value = match col.dtype() {
            DataType::String => {
                let str_col = col.str()?;
                let mut freq_map: HashMap<&str, usize> = HashMap::new();

                // Count frequencies of non-null values
                for opt_val in str_col.into_iter() {
                    if let Some(val) = opt_val {
                        *freq_map.entry(val).or_insert(0) += 1;
                    }
                }

                // Find the most frequent value
                freq_map.into_iter()
                    .max_by_key(|&(_, count)| count)
                    .map(|(val, _)| val.to_string())
            },
            DataType::Categorical(_) => {
                let cat_col = col.categorical()?;
                let rev_map = cat_col.get_rev_map();
                let physical = cat_col.physical();

                let mut freq_map: HashMap<u32, usize> = HashMap::new();

                // Count frequencies of non-null values using physical indices
                for opt_val in physical.into_no_null_iter() {
                    *freq_map.entry(opt_val).or_insert(0) += 1;
                }

                // Find the most frequent value and convert back to string
                freq_map.into_iter()
                    .max_by_key(|&(_, count)| count)
                    .and_then(|(idx, _)| rev_map.get(idx))
                    .map(|s| s.to_string())
            },
            _ => unreachable!(), // We already filtered for String and Categorical
        };

        // If we found a mode value, impute the missing entries
        if let Some(mode) = mode_value {
            let mask = col.is_null();
            let replacement = Series::new(col_name, &[mode.as_str()])
                .cast(&col.dtype())?;

            // Create the imputed column
            let imputed = col.zip_with(&mask, &replacement)?;
            df.replace(col_name)?;
            df.with_column(imputed)?;
        }
    }

    Ok(df)
}

