/// "Whole-word" means non-alphanumeric (or start/end) on both sides.
/// Case-sensitive: only exact "cat" (lowercase) matches.
/// Returns the original string unchanged if fewer than two matches are found.
pub fn replace_second_cat(input: &str) -> String {
    let mut count = 0usize;

    // Iterate over character boundaries (byte indices) so we can safely slice.
    for (byte_idx, _ch) in input.char_indices() {
        if !input[byte_idx..].starts_with("cat") {
            continue;
        }

        // Check left boundary: previous char (if any) must NOT be alphanumeric.
        let left_is_alnum = input[..byte_idx]
            .chars()
            .rev()
            .next()
            .map_or(false, |c| c.is_alphanumeric());

        // Check right boundary: next char after "cat" (if any) must NOT be alphanumeric.
        let after_idx = byte_idx + 3; // "cat" is ASCII, 3 bytes
        let right_is_alnum = input[after_idx..]
            .chars()
            .next()
            .map_or(false, |c| c.is_alphanumeric());

        if !left_is_alnum && !right_is_alnum {
            count += 1;
            if count == 2 {
