/// Input: df as slice of rows (Vec<Vec<f64>>). All rows must have same length.
/// Output: new Vec<Vec<f64>> with columns removed.
fn remove_cols_max_gt_zero(df: &[Vec<f64>]) -> Vec<Vec<f64>> {
    if df.is_empty() {
        return Vec::new();
    }

    let ncols = df[0].len();
    // Ensure rectangular table
    for (i, row) in df.iter().enumerate() {
        if row.len() != ncols {
