/// ```
pub fn group_and_pivot<F>(
    df0: &DataFrame,
    var0: &str,
    agg_function: F,
) -> Result<DataFrame, Box<dyn Error>>
where
    F: Fn(GroupBy<'_, PolarsDataType>) -> Result<DataFrame, PolarsError>,
{
