    let grouped = df0.group_by([var0])?;

    // Step 2: Apply the aggregation function
    let aggregated = agg_function(grouped)?;

    // Step 3: Identify the aggregation column (assumes it's the last column)
    let agg_col_name = aggregated
        .get_column_names()
        .last()
        .ok_or("No columns in aggregated DataFrame")?
        .to_string();

    // Step 4: Create a unique identifier for pivoting (if needed)
    // For simplicity, we'll create a row index to pivot on
    let mut pivoted = aggregated
        .lazy()
        .with_column(
            // Create a row number column for pivoting
            lit(1).alias("_pivot_key")
        )
        .collect()?;

    // Step 5: Pivot the data to create a two-dimensional table
    // This converts the one-dimensional aggregation into a wide format
    let result = pivoted
        .pivot(
            // Values to fill in the pivot table
            [&agg_col_name],
            // Index column (the group-by column)
            [var0],
            // Column to create new columns from (using the pivot key)
            ["_pivot_key"],
            // Aggregation function for pivot (first value since each cell has one value)
            PivotAgg::First,
        )
        .collect::<Result<DataFrame, _>>()?;

    // Step 6: Clean up - remove the pivot key column if it exists
    let result = result.drop("_pivot_key").unwrap_or(result);

    Ok(result)
}

