use std::collections::HashMap;
use std::hash::Hash;

/// Convert an iterator of (K, V) groups into a HashMap<K, (K, V)>,
/// using each group's first element as the key and the whole group as the value.
/// If the same key appears multiple times, later groups overwrite earlier ones.
///
/// K must be cloneable because the key is stored both as the map key and as
/// the first element of the stored tuple.
pub fn groups_to_hashmap<I, K, V>(iter: I) -> HashMap<K, (K, V)>
where
    I: IntoIterator<Item = (K, V)>,
    K: Eq + Hash + Clone,
{
    let mut map = HashMap::new();
    for (k, v) in iter {
        // store the original pair as the value, clone key for the map key
        let pair = (k.clone(), v);
        map.insert(k, pair);
    }
    map
}

