pub fn count_by_group(df: &DataFrame, key_columns: &[&str]) -> Result<DataFrame> {
    // Validate that all key columns exist in the DataFrame
    for col in key_columns {
        if !df.get_column_names().contains(col) {
            return Err(PolarsError::ComputeError(
                format!("Column '{}' not found in DataFrame", col).into(),
            ));
        }
    }

    // Group by the specified columns and count
    let result = df
        .group_by(key_columns)?
        .agg([col("*").count().alias("count")])
        .sort(key_columns, SortMultipleOptions::default())?;

    Ok(result)
}

/// Alternative implementation using a HashMap for manual counting
/// (useful if you need more control or want to avoid Polars' group_by overhead for small datasets)
pub fn count_by_group_manual(df: &DataFrame, key_columns: &[&str]) -> Result<DataFrame> {
    // Extract column data as vectors of strings for comparison
    let columns: Vec<Vec<String>> = key_columns
        .iter()
        .map(|col| {
            df.column(col)
                .map_err(|e| PolarsError::ComputeError(format!("{}", e).into()))
                .and_then(|s| {
                    s.str()
                        .map_err(|e| PolarsError::ComputeError(format!("{}", e).into()))
                        .map(|ca| ca.into_iter().map(|v| v.unwrap_or("").to_string()).collect())
                })
        })
        .collect::<Result<Vec<_>>>()?;

    // Count occurrences of each combination
    let mut counts: HashMap<Vec<String>, usize> = HashMap::new();

    let row_count = df.height();
    for i in 0..row_count {
        let key: Vec<String> = columns.iter().map(|col| col[i].clone()).collect();
        *counts.entry(key).or_insert(0) += 1;
    }

    // Build result DataFrame
    let mut result_columns: Vec<Series> = Vec::new();

    for (col_idx, col_name) in key_columns.iter().enumerate() {
        let values: Vec<String> = counts.keys().map(|k| k[col_idx].clone()).collect();
        result_columns.push(Series::new(col_name, &values));
    }

    let count_values: Vec<u32> = counts.values().map(|&c| c as u32).collect();
    result_columns.push(Series::new("count", &count_values));

    DataFrame::new(result_columns)
