/// let df = df! {
///     "category" => ["A", "B", "A", "B", "A"],
///     "region" => ["North", "North", "South", "South", "North"],
/// }.unwrap();
///
/// let result = count_groups(&df, &["category", "region"]).unwrap();
/// println!("{}", result);
/// ```
fn count_groups(df: &DataFrame, key_columns: &[&str]) -> PolarsResult<DataFrame> {
    // Validate that all key columns exist in the DataFrame
    for col in key_columns {
        if !df.get_column_names().contains(col) {
            return Err(PolarsError::ColumnNotFound((*col).into()));
        }
    }

    // Group by the specified columns and count rows in each group
    df.clone()
        .lazy()
        .groupby(key_columns)
        .agg([len().alias("count")])
        .collect()
}

