/// Computes mean values for specified rows and columns from a 2D DataFrame.
///
/// # Arguments
/// * `df` - A Polars DataFrame containing the data.
/// * `row_indices` - A list of row indices to include (0-based).
/// * `col_indices` - A list of column indices to include (0-based).
///
/// # Returns
/// A tuple of two `Series`:
/// - First element: Mean values for the specified rows (across all columns).
/// - Second element: Mean values for the specified columns (across all rows).
///
/// # Example
/// ```rust
/// use polars::prelude::*;
///
/// let df = df!(
///     "A" => &[1.0, 2.0, 3.0, 4.0],
///     "B" => &[5.0, 6.0, 7.0, 8.0],
///     "C" => &[9.0, 10.0, 11.0, 12.0]
/// ).unwrap();
///
/// let (row_means, col_means) = compute_specific_means(&df, &[0, 2], &[0, 1]).unwrap();
/// ```
pub fn compute_specific_means(
    df: &DataFrame,
    row_indices: &[usize],
    col_indices: &[usize],
) -> Result<(Series, Series), PolarsError> {
    // Validate indices
    if row_indices.is_empty() || col_indices.is_empty() {
        return Err(PolarsError::ComputeError(
            "Row and column indices lists cannot be empty".into(),
        ));
    }

    let row_count = df.height();
    let col_count = df.width();

    if row_indices.iter().any(|&i| i >= row_count) {
        return Err(PolarsError::ComputeError(
            "Invalid row index provided".into(),
        ));
    }

    if col_indices.iter().any(|&i| i >= col_count) {
        return Err(PolarsError::ComputeError(
            "Invalid column index provided".into(),
        ));
    }

    // Create a new DataFrame with only the specified rows and columns
    let mut selected_df = df.clone();
    selected_df = selected_df.select(&col_indices.iter().map(|&i| i.to_string()).collect::<Vec<_>>())?;
    selected_df = selected_df.slice(usize::try_from(row_indices[0])?, usize::try_from(row_indices.last().unwrap())? + 1)?;

    // Compute row means (across all selected columns)
    let row_means = selected_df
        .select(&selected_df.get_column_names())?
        .mean(None)?;

    // Compute column means (across all selected rows)
    let col_means = selected_df
        .select(&selected_df.get_column_names())?
        .mean(Some("row"))?;

    Ok((row_means, col_means))
}

