/// * If any index in `row_indices` or `col_indices` is out of bounds
/// * If either index list is empty
pub fn compute_means(
    data: &Array2<f64>,
    row_indices: &[usize],
    col_indices: &[usize],
) -> (Vec<f64>, Vec<f64>) {
