    assert!(!row_indices.is_empty(), "row_indices must not be empty");
    assert!(!col_indices.is_empty(), "col_indices must not be empty");

    let max_row = data.nrows();
    let max_col = data.ncols();

    for &idx in row_indices {
        assert!(idx < max_row, "Row index {} out of bounds (max: {})", idx, max_row - 1);
    }
    for &idx in col_indices {
        assert!(idx < max_col, "Column index {} out of bounds (max: {})", idx, max_col - 1);
    }

