use polars::prelude::*;

/// Computes mean values for specified rows and columns from a DataFrame
/// 
/// # Arguments
/// * `df` - The input DataFrame
/// * `row_indices` - Vector of row indices to include in computation
/// * `col_indices` - Vector of column indices to include in computation
/// 
/// # Returns
/// A Result containing a Series with mean values for each selected column
pub fn compute_mean_by_indices(
    df: &DataFrame,
    row_indices: Vec<usize>,
    col_indices: Vec<usize>,
) -> PolarsResult<Vec<f64>> {
    // Get column names based on indices
    let col_names: Vec<&str> = col_indices
        .iter()
        .filter_map(|&idx| df.get_column_names().get(idx).copied())
        .collect();

    if col_names.is_empty() {
        return Err(PolarsError::ComputeError("No valid columns selected".into()));
    }

    // Select columns
    let selected_df = df.select(col_names)?;

    // Filter rows by indices
    let row_mask = (0..selected_df.height())
        .map(|i| row_indices.contains(&i))
        .collect::<Vec<_>>();

    let filtered_df = selected_df.filter(&BooleanChunked::from_slice("", &row_mask))?;

    // Compute means for each column
    let mut means = Vec::new();
    for col in filtered_df.get_columns() {
        let mean_val = col.mean();
        means.push(mean_val.unwrap_or(f64::NAN));
    }

    Ok(means)
}

