pub fn sort_lists_with_mapping<T, K>(lists: Vec<Vec<T>>, order_mapping: &IndexMap<T, usize>)
where
    T: Ord + Clone + std::hash::Hash + Eq,
{
    lists.into_iter()
        .map(|inner_list| {
            inner_list.into_iter()
                .map(|item| (item.clone(), order_mapping.get(&item).copied().unwrap_or(usize::MAX)))
                .collect::<Vec<_>>()
                .into_iter()
                .collect::<Vec<_>>()
                .into_iter()
                .collect()
        })
        .collect()
}

