        .map(|inner_list| {
            let mut sorted: Vec<_> = inner_list
                .into_iter()
                .map(|item| (item.clone(), order_mapping.get(&item).copied().unwrap_or(usize::MAX)))
                .collect();

            // Sort by the order mapping value
            sorted.sort_by_key(|(_, order)| *order);

            // Extract the original values in new order
            sorted.into_iter().map(|(item, _)| item).collect()
        })
        .collect()
}
