The implementation is generic over element type T (T: Eq + Hash + Clone). You can drop the inline module into your project or replace it with a real crate if you prefer.

```rust
use std::hash::Hash;

/// Small in-file "library" (replaceable by an external crate if you like).
pub mod order_sort_2025 {
    use std::collections::HashMap;
    use std::hash::Hash;

    /// Sort each inner list in `lists` according to `mapping`.
    ///
    /// `mapping` is any IntoIterator<Item = (T, usize)> where the usize is the rank
    /// (lower ranks come first). Elements not present in the mapping are placed
    /// after mapped elements and retain their original relative order.
    ///
    /// Example: mapping = [('a',0), ('b',1), ('c',2)]
    /// Inner list ['b','x','a'] -> ['a','b','x'] (x not in mapping, stays after, preserving relative order)
    pub fn sort_lists_by_mapping<T>(
        lists: &mut [Vec<T>],
        mapping: impl IntoIterator<Item = (T, usize)>,
    )
    where
        T: Eq + Hash + Clone,
    {
        let map: HashMap<T, usize> = mapping.into_iter().collect();

        for list in lists.iter_mut() {
            // Keep original indices so we can keep relative order for unmapped items
            let mut enumerated: Vec<(usize, T)> =
                list.iter().cloned().enumerate().collect();

            // Sort by a composite key:
            // - First component: 0 for items in mapping, 1 for items not in mapping (mapped items first)
            // - Second component: rank from the mapping (for mapped items)
            // - Third component: original index (stable tie-breaker so we preserve original relative order)
            enumerated.sort_by_key(|(orig_idx, item)| {
                match map.get(item) {
                    Some(&rank) => (0usize, rank, *orig_idx),
                    None => (1usize, usize::MAX, *orig_idx),
                }
            });

            // Write back the sorted items into the original list
            for (i, (_, item)) in enumerated.into_iter().enumerate() {
                list[i] = item;
            }
        }
    }
}

fn main() {
    // Example usage
    let mut lists = vec![
        vec!['b', 'a', 'c', 'd', 'z'],
        vec!['x', 'y', 'b', 'a'],
    ];

    // Define desired order (lower number = earlier)
    let mapping = vec![('a', 0), ('b', 1), ('c', 2), ('d', 3)];

    order_sort_2025::sort_lists_by_mapping(&mut lists, mapping);

    assert_eq!(lists[0], vec!['a', 'b', 'c', 'd', 'z']);
    assert_eq!(lists[1], vec!['a', 'b', 'x', 'y']);

    println!("Sorted lists: {:#?}", lists);
}
```

