/// assert!(!all_same_length(&vec1, &[&vec4]));
/// ```
fn all_same_length<T: Len>(first: &T, rest: &[&T]) -> bool {
    let first_len = first.len();
    rest.iter().all(|seq| seq.len() == first_len)
}

