use indexmap::IndexMap;

/// Sort the keys of a mapping according to their associated values,
/// and return a list of triples containing each key, its value, and
/// the index where that value appeared in the original mapping.
///
/// # Arguments
/// * `map` - An IndexMap where keys and values implement necessary traits
///
/// # Returns
/// A Vec of (key, value, original_index) triples sorted by value
///
/// # Type Requirements
/// * K: Clone + Ord - Keys must be cloneable and orderable
/// * V: Clone + Ord - Values must be cloneable and orderable
pub fn sort_keys_by_value<K, V>(map: &IndexMap<K, V>) -> Vec<(K, V, usize)>
where
    K: Clone + Ord,
    V: Clone + Ord,
{
    // Collect all entries with their original indices
    let mut entries: Vec<(K, V, usize)> = map
        .iter()
        .enumerate()
        .map(|(index, (key, value))| (key.clone(), value.clone(), index))
        .collect();

    // Sort by value (ascending), then by key for deterministic ordering
    entries.sort_by(|a, b| {
        a.1.cmp(&b.1)  // Compare values first
            .then(a.0.cmp(&b.0))  // Then compare keys for stability
    });

    entries
}

