/// assert_eq!(result.height(), 4); // 2,2,4,4 are duplicates
/// ```
pub fn find_duplicates(df: &DataFrame, column_name: &str) -> Result<DataFrame, PolarsError> {
    // Get the unique values and their counts
    let counts = df
        .lazy()
        .select([col(column_name).unique().with_name("unique_value")])
        .collect()?
        .lazy()
        .group_by([col("unique_value")])
        .agg([count().alias("count")])
        .collect()?;

    // Filter for values that appear more than once
    let duplicates = counts
        .lazy()
        .filter(col("count") > 1)
        .collect()?;

    // Get the unique values that are duplicates
    let duplicate_values = duplicates
        .column("unique_value")?
        .utf8()?
        .into_iter()
        .map(|s| s.unwrap_or_default())
        .collect::<Vec<_>>();

    // Filter the original dataframe to keep only rows with duplicate values
    let mask = df
        .column(column_name)?
        .utf8()?
        .into_iter()
        .map(|s| duplicate_values.contains(&s.unwrap_or_default()))
        .collect::<Vec<_>>();

    let mask_series = Series::new(column_name, mask);
    Ok(df.filter(&mask_series)?)
}
