```rust
/// Extracts a substring from the input text starting at a specified position
/// and spanning a given number of characters.
///
/// # Arguments
/// * `text` - The input string to extract from
/// * `start` - The starting position (0-indexed)
/// * `length` - The number of characters to extract
///
/// # Returns
/// * `Some(String)` - The extracted substring if valid
/// * `None` - If the position is out of bounds or invalid
///
/// # Examples
/// ```
/// assert_eq!(substring("Hello, World!", 0, 5), Some("Hello".to_string()));
/// assert_eq!(substring("Hello, World!", 7, 5), Some("World".to_string()));
/// assert_eq!(substring("Hello, World!", 100, 5), None);
/// ```
fn substring(text: &str, start: usize, length: usize) -> Option<String> {
    let chars: Vec<char> = text.chars().collect();

    // Check if start position is within bounds
    if start >= chars.len() {
        return None;
    }

    // Calculate the end position
    let end = (start + length).min(chars.len());

    // Extract the substring and return as String
    let result: String = chars[start..end].iter().collect();

    Some(result)
}

fn main() {
    // Example usage
    println!("{:?}", substring("Hello, World!", 0, 5));      // Some("Hello")
    println!("{:?}", substring("Hello, World!", 7, 5));      // Some("World")
    println!("{:?}", substring("Hello, World!", 100, 5));    // None
    println!("{:?}", substring("🦀 Rust", 0, 3));            // Some("🦀 R")
}
```

