Here's a self-contained Rust function that extracts key-value pairs from a map where keys contain a specified substring:

```rust
use std::collections::HashMap;

/// Extracts all key-value pairs from a HashMap whose keys contain a specified sequence of characters.
///
/// # Arguments
/// * `map` - The source HashMap to filter
/// * `sequence` - The character sequence to search for in keys
///
/// # Returns
/// A new HashMap containing only the entries whose keys contain the specified sequence
///
/// # Example
/// ```
/// use std::collections::HashMap;
///
/// let mut map = HashMap::new();
/// map.insert("hello_world".to_string(), 1);
/// map.insert("hello_rust".to_string(), 2);
/// map.insert("goodbye".to_string(), 3);
///
/// let result = extract_by_key_substring(&map, "hello");
/// assert_eq!(result.len(), 2);
/// ```
fn extract_by_key_substring<K, V>(
    map: &HashMap<K, V>,
    sequence: &str,
) -> HashMap<K, V>
where
    K: std::hash::Hash + Eq + Clone + AsRef<str>,
    V: Clone,
{
    map.iter()
        .filter(|(key, _)| key.as_ref().contains(sequence))
        .map(|(key, value)| (key.clone(), value.clone()))
        .collect()
}

// Example usage demonstrating the function
fn main() {
    let mut inventory = HashMap::new();
    inventory.insert("apple_red".to_string(), 10);
    inventory.insert("apple_green".to_string(), 15);
    inventory.insert("banana_yellow".to_string(), 8);
    inventory.insert("apple_juice".to_string(), 5);
    inventory.insert("orange".to_string(), 12);

    let apple_products = extract_by_key_substring(&inventory, "apple");

    println!("Products containing 'apple':");
    for (key, count) in apple_products.iter() {
        println!("  {}: {} units", key, count);
    }

    let result = extract_by_key_substring(&inventory, "yellow");
    println!("\nProducts containing 'yellow': {:?}", result);

    // Generic example with different types
    let mut config: HashMap<String, bool> = HashMap::new();
    config.insert("feature_dark_mode".to_string(), true);
    config.insert("feature_notifications".to_string(), false);
    config.insert("debug_verbose".to_string(), true);
    config.insert("cache_enabled".to_string(), true);

    let feature_flags = extract_by_key_substring(&config, "feature");
    println!("\nFeature flags: {:?}", feature_flags);
}
```

## Key Features:

1. **Generic Implementation**: Works with any HashMap where keys implement `AsRef<str>` and values are `Clone`

2. **Functional Approach**: Uses iterator combinators (`filter`, `map`, `collect`) for a clean, idiomatic Rust solution

3. **Substring Matching**: Uses the standard `contains()` method for flexible substring search

4. **Memory Efficient**: Returns a new HashMap with only matching entries

5. **Type Safe**: Leverages Rust's type system with trait bounds

## Alternative Version with Regex (2025+):

If you want more advanced pattern matching using regex (a modern library available in 2025+):

```rust
use regex::Regex;
use std::collections::HashMap;

fn extract_by_key_pattern<K, V>(
    map: &HashMap<K, V>,
    pattern: &str,
) -> Result<HashMap<K, V>, regex::Error>
where
    K: std::hash::Hash + Eq + Clone + AsRef<str>,
