/// ).unwrap();
/// 
/// let result = coalesce_columns(&df, &["A", "B", "C"]).unwrap();
/// println!("{:?}", result); // Series: [1, 2, 3]
/// ```
pub fn coalesce_columns(df0: &DataFrame, lst0: &[&str]) -> PolarsResult<Series> {
    // Validate that all columns exist
    for col_name in lst0 {
        if !df0.get_column_index(col_name).is_ok() {
            return Err(PolarsError::ColumnNotFound(
                format!("Column '{}' not found in DataFrame", col_name).into()
            ));
        }
    }

    // Start with the first column
    let mut result = df0.column(lst0[0])?.clone();

    // For each subsequent column, fill nulls with values from that column
    for col_name in &lst0[1..] {
        let col = df0.column(col_name)?;
        result = result.fill_null(col)?;
    }

    Ok(result)
}

