            col("_keep_mask")
                .list()
                .eval(
                    when(col("").sum().gt(lit(0)))
                        .then(lit(true))
                        .otherwise(lit(false)),
                    true
                )
                .alias("_keep")
        ])
        .select([
            col("*").exclude(["_keep_mask", "_keep"]),
            col("_keep")
        ])
        .collect()?
        .column("_keep")?
        .bool()?
        .clone();

    // Filter the DataFrame using the mask
    df.filter(&mask)
}

