/// * `df` - A reference to the DataFrame to process
///
/// # Returns
/// * `Result<DataFrame>` - A new DataFrame with consecutive duplicates removed
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let df = df! {
///     "A" => [1, 1, 2, 2, 2, 3],
///     "B" => ["a", "a", "b", "b", "b", "c"],
/// }.unwrap();
///
/// let result = remove_consecutive_duplicates(&df).unwrap();
/// // Result: 3 rows with values (1,"a"), (2,"b"), (3,"c")
/// ```
fn remove_consecutive_duplicates(df: &DataFrame) -> PolarsResult<DataFrame> {
    if df.is_empty() {
        return Ok(df.clone());
    }

    let height = df.height();

    // Create a boolean mask where True indicates we should keep the row
    let mut keep_mask = vec![true; height];

    // Compare each row with the previous one
    for i in 1..height {
        let current_row = df.slice(i as i64, 1);
        let previous_row = df.slice((i - 1) as i64, 1);

        // Check if rows are equal by comparing their string representations
        // or by comparing each column
        let mut rows_equal = true;

        for col_name in df.get_column_names() {
            let current_col = current_row.column(col_name)?;
            let prev_col = previous_row.column(col_name)?;

            if !current_col.series_equal(prev_col) {
                rows_equal = false;
                break;
            }
        }

        // Mark for removal if identical to previous row
        if rows_equal {
            keep_mask[i] = false;
        }
    }

    // Convert mask to Series and filter
    let mask_series = Series::new("mask", keep_mask);
    df.filter(&mask_series.cast(&DataType::Boolean)?)
}

fn main() -> PolarsResult<()> {
