use polars::prelude::*;

/// Divides specified columns in a DataFrame by values from a reference column.
///
/// # Arguments
/// * `df0` - The input DataFrame
/// * `columns_list0` - Vec of column names to divide
/// * `column_name0` - The column to divide by (divisor)
///
/// # Returns
/// * `Result<DataFrame>` - DataFrame with divided columns, or error if operation fails
///
/// # Example
/// ```ignore
/// let df = df!("a" => &[10, 20, 30], "b" => &[2, 4, 5], "divisor" => &[2, 4, 5])?;
/// let result = divide_columns_by_reference(df, vec!["a", "b"], "divisor")?;
/// ```
fn divide_columns_by_reference(
    df0: DataFrame,
    columns_list0: Vec<&str>,
    column_name0: &str,
) -> PolarsResult<DataFrame> {
    let divisor_col = df0.column(column_name0)?;

    let mut result_df = df0.clone();

    for col_name in columns_list0 {
        let col = result_df.column(col_name)?;

        // Perform element-wise division
        let divided = col.divide(divisor_col)?;

        // Replace the original column with the divided result
        result_df = result_df.with_columns(vec![divided.with_name(col_name)])?;
    }

    Ok(result_df)
}

