use itertools::Itertools;
use hashbrown::HashMap;
use std::cmp::Ordering;

/// Counts the occurrences of each tuple in a given sequence, with support for filtering, ordering, and limiting the results.
///
/// # Arguments
///
/// * `tuples`: An iterator of tuples.
/// * `filter_predicate`: A predicate to filter the tuples (optional).
/// * `order_by`: A function to order the results (optional).
/// * `limit`: The maximum number of results to return (optional).
///
/// # Returns
///
/// A vector of tuples containing the original tuple and its count, ordered and limited according to the provided parameters.
pub fn count_tuples(
    tuples: impl Iterator<Item = (i32, i32)>,
    filter_predicate: Option<fn(&(i32, i32)) -> bool>,
    order_by: Option<fn(&((i32, i32), usize)) -> usize>,
    limit: Option<usize>,
) -> Vec<((i32, i32), usize)> {
    // Create a HashMap to count the occurrences of each tuple
    let mut counts: HashMap<(i32, i32), usize> = HashMap::new();

    // Iterate over the tuples and count their occurrences
    for tuple in tuples {
        // Apply the filter predicate if provided
        if filter_predicate.is_none() || filter_predicate.unwrap()(&tuple) {
            *counts.entry(tuple).or_insert(0) += 1;
        }
    }

    // Convert the HashMap to a vector of tuples
    let mut result: Vec<((i32, i32), usize)> = counts.into_iter().collect();

    // Order the results if a function is provided
    if let Some(order_by) = order_by {
        result.sort_by(|a, b| {
            let a_order = order_by(&a);
            let b_order = order_by(&b);
            if a_order < b_order {
                Ordering::Less
            } else if a_order > b_order {
                Ordering::Greater
            } else {
                Ordering::Equal
            }
        });
    }

    // Limit the results if a limit is provided
    if let Some(limit) = limit {
        result.truncate(limit);
    }

    result
}

