    pub enum Order {
        /// sort by count descending (highest first)
        CountDesc,
        /// sort by count ascending (lowest first)
        CountAsc,
        /// sort by key ascending (requires T: Ord)
        KeyAsc,
        /// sort by key descending (requires T: Ord)
