    ///     .filter(|k| some_pred(k))
    ///     .min_count(2)
    ///     .order(Order::CountDesc)
    ///     .limit(10)
    ///     .run();
    pub struct CountBuilder<I, T>
    where
        I: IntoIterator<Item = T>,
    {
        iter: I,
        filter: Option<Box<dyn Fn(&T) -> bool + Send + Sync>>,
        min_count: Option<usize>,
        order: Order,
        limit: Option<usize>,
