            self.order = order;
            self
        }

        /// Limit results to top `n` items after ordering.
        pub fn limit(mut self, n: usize) -> Self {
            self.limit = Some(n);
            self
        }

        /// Execute counting and return Vec<(T, usize)> according to specified options.
        pub fn run(self) -> Vec<(T, usize)> {
            // Count
            let mut counts: HashMap<T, usize> = HashMap::new();
            let filter = self.filter;

            for item in self.iter {
                if let Some(ref f) = filter {
                    if !f(&item) {
                        continue;
                    }
                }
                *counts.entry(item).or_insert(0) += 1;
            }

            // Convert to vec
            let mut vec: Vec<(T, usize)> = counts.into_iter().collect();

            // Apply min_count if present
            if let Some(min) = self.min_count {
                vec.retain(|(_, c)| *c >= min);
            }

            // Sort according to order
            match self.order {
                Order::CountDesc => vec.sort_by_key(|&(_k, c)| Reverse(c)),
                Order::CountAsc => vec.sort_by_key(|&(_k, c)| c),
                Order::KeyAsc => vec.sort_by(|a, b| a.0.cmp(&b.0)),
                Order::KeyDesc => vec.sort_by(|a, b| b.0.cmp(&a.0)),
            }

            // Apply limit
            if let Some(n) = self.limit {
                vec.truncate(n);
            }

            vec
        }
    }
}

