/// ```

#[derive(Clone, Debug)]
pub struct TupleCounterOptions<T> {
    pub min_count: usize,
    pub max_count: Option<usize>,
    pub limit: Option<usize>,
    pub sort_by_count: bool,
    pub descending: bool,
    pub filter_fn: Option<fn(&T, usize) -> bool>,
}

impl<T> Default for TupleCounterOptions<T> {
    fn default() -> Self {
        Self {
            min_count: 1,
            max_count: None,
            limit: None,
            sort_by_count: true,
            descending: true,
            filter_fn: None,
        }
    }
}

/// Count occurrences of tuples with filtering, ordering, and limiting capabilities.
pub fn count_tuples<T: Eq + std::hash::Hash + Clone + std::fmt::Debug>(
    tuples: &[T],
    options: TupleCounterOptions<T>,
) -> Vec<(T, usize)> {
    // Count occurrences using HashMap
    let mut counts: HashMap<T, usize> = HashMap::new();

    for tuple in tuples {
        *counts.entry(tuple.clone()).or_insert(0) += 1;
    }

    // Convert to Vec and apply filters
    let mut result: Vec<(T, usize)> = counts
        .into_iter()
        .filter(|(tuple, count)| {
            // Apply count range filter
            if *count < options.min_count {
                return false;
            }
            if let Some(max) = options.max_count {
                if *count > max {
                    return false;
                }
            }

            // Apply custom filter function if provided
            if let Some(filter) = options.filter_fn {
                if !filter(tuple, *count) {
                    return false;
                }
            }

            true
        })
        .collect();

    // Sort if requested
    if options.sort_by_count {
        result.sort_by(|a, b| {
            let cmp = a.1.cmp(&b.1);
            if options.descending {
                cmp.reverse()
            } else {
                cmp
            }
        });
    }

    // Apply limit if specified
    if let Some(lim) = options.limit {
        result.truncate(lim);
    }

    result
}

/// Builder pattern for more ergonomic API (2025+ style)
pub struct TupleCounter<T> {
    tuples: Vec<T>,
    options: TupleCounterOptions<T>,
}

impl<T: Eq + std::hash::Hash + Clone + std::fmt::Debug> TupleCounter<T> {
    pub fn new(tuples: Vec<T>) -> Self {
        Self {
            tuples,
            options: Default::default(),
        }
    }

    pub fn min_count(mut self, count: usize) -> Self {
        self.options.min_count = count;
        self
    }

    pub fn max_count(mut self, count: usize) -> Self {
        self.options.max_count = Some(count);
        self
    }

    pub fn limit(mut self, count: usize) -> Self {
        self.options.limit = Some(count);
        self
    }

    pub fn sort_descending(mut self, descending: bool) -> Self {
        self.options.descending = descending;
        self
    }

    pub fn filter<F>(mut self, f: F) -> Self
    where
        F: Fn(&T, usize) -> bool + 'static,
    {
        self.options.filter_fn = Some(Box::leak(Box::new(f)) as &'static dyn Fn(&T, usize) -> bool
            as *const _ as *mut _) as Option<fn(&T, usize) -> bool>;
        self
    }

    pub fn count(self) -> Vec<(T, usize)> {
