///     "value" => &[1, 2, 3, 4]
/// );
/// let result = expand_to_indicators(df, "var0");
/// ```
pub fn expand_to_indicators(df0: DataFrame, var0: &str) -> Result<DataFrame, PolarsError> {
    // Get the column to process
    let col = df0.column(var0).ok_or_else(|| {
        PolarsError::ComputeError("Column not found".into())
    })?;

    // Get all distinct values
    let distinct_values: Vec<String> = col
        .utf8()?
        .unique(true)?
        .into_iter()
        .map(|s| s.to_string())
        .collect();

    // Create a new DataFrame with binary columns
    let mut new_df = DataFrame::default();

    // Add the original columns (excluding var0)
    for col_name in df0.get_column_names() {
        if col_name != var0 {
            new_df = new_df.with_column(df0.column(col_name).unwrap());
        }
