            .lazy()
            .filter(col.eq(&value))
            .select([col.clone()])
            .collect()?
            .column(var0)
            .unwrap()
            .bool()?
            .into_primitive();

        new_df = new_df.with_column(Series::new(&indicator_name, indicator_col));
