use polars::prelude::*;

fn one_hot_encode(df: &DataFrame, column_name: &str) -> Result<DataFrame, PolarsError> {
    let s = df.column(column_name)?;
    let unique_values = s.unique()?;
    let mut new_df = DataFrame::new_no_defaults(vec![]);

    for value in unique_values {
        let mut new_series = Series::new(column_name, vec![0; df.height()]);
        for (index, row) in df.rows().enumerate() {
            if s.get(index).unwrap().eq(value) {
                new_series.set(index, 1);
            }
        }
        new_df = new_df.hstack(&[new_series])?;
