    let mut in_b: Vec<(i32, usize)> = Vec::new();
    let mut not_in_b: Vec<i32> = Vec::new();
    for &x in &a {
        if let Some(&index) = index_map.get(&x) {
            in_b.push((x, index));
        } else {
            not_in_b.push(x);
        }
    }

    // Sort the elements that appear in B based on their index in B
    in_b.sort_by_key(|(_, index)| *index);

    // Combine the two vectors, with elements not in B at the beginning
    let mut result: Vec<i32> = Vec::new();
    result.extend(not_in_b);
    result.extend(in_b.into_iter().map(|(x, _)| x));

    result
}

