# Rust Function: Sort List A by Order in List B

```rust
use std::collections::HashMap;

/// Sorts list A according to the order defined by list B.
/// Items in A that do not appear in B are placed at the beginning.
/// 
/// # Arguments
/// * `a` - The list to be sorted
/// * `b` - The reference list (already sorted) that defines the order
/// 
/// # Returns
/// A new vector with A sorted according to B's order
/// 
/// # Example
/// ```
/// let a = vec![3, 1, 4, 1, 5, 9, 2, 6];
/// let b = vec![9, 3, 2, 1];
/// let result = sort_by_reference(&a, &b);
/// assert_eq!(result, vec![4, 5, 6, 9, 3, 2, 1]);
/// ```
pub fn sort_by_reference<T: Ord + Clone + std::hash::Hash>(
    a: &[T],
    b: &[T],
) -> Vec<T> {
    // Create a HashMap for O(1) lookups of B's positions
    let b_order: HashMap<&T, usize> = b
        .iter()
        .enumerate()
        .map(|(idx, item)| (item, idx))
        .collect();

    // Partition and sort A
    let mut not_in_b: Vec<T> = Vec::new();
    let mut in_b: Vec<T> = Vec::new();

    for item in a {
        if b_order.contains_key(item) {
            in_b.push(item.clone());
        } else {
            not_in_b.push(item.clone());
        }
    }

    // Sort items that are in B according to B's order
    in_b.sort_by_key(|item| b_order[item]);

    // Combine: items not in B first, then items in B (in order of B)
    not_in_b.extend(in_b);
    not_in_b
}

