use polars::prelude::*;

/// Splits a column of tuples into separate columns.
///
/// # Arguments
///
/// * `df` - The DataFrame containing the column to split.
/// * `column_name` - The name of the column to split.
///
/// # Returns
///
/// A new DataFrame with the column split into two separate columns.
fn split_tuple_column(mut df: DataFrame, column_name: &str) -> DataFrame {
    // Split the column into two separate columns
    let s = df.column(column_name).unwrap();
    let s0 = s.struct_().unwrap().field_0().unwrap().alias(format!("{}_0", column_name));
    let s1 = s.struct_().unwrap().field_1().unwrap().alias(format!("{}_1", column_name));

    // Drop the original column
    df = df.drop(column_name).unwrap();

    // Add the new columns to the DataFrame
    df = df.with_column(s0).unwrap();
    df = df.with_column(s1).unwrap();

    df
}

fn main() {
    // Create a sample DataFrame
    let s = Series::new("var0", &[("a", 1), ("b", 2), ("c", 3)]);
    let mut df = DataFrame::new(vec![s]).unwrap();

    // Split the column of tuples
    df = split_tuple_column(df, "var0");

    // Print the resulting DataFrame
    println!("{:?}", df);
}
