use polars::prelude::*;

/// Split the column "var0" (each row is a 2-element tuple stored as a List or Struct)
/// into two columns "var0_0" and "var0_1".
///
/// This function modifies df0 in place (replaces it with a new DataFrame that has
/// the two new columns appended). Returns an Err if "var0" does not exist or is
/// not a 2-element List/Struct.
pub fn split_var0(df0: &mut DataFrame) -> PolarsResult<()> {
    // Ensure the column exists
    let s = df0.column("var0")?;
    match s.dtype() {
        // If var0 is a List type (each row is a list/array), use arr.get(0)/arr.get(1)
        DataType::List(_) => {
            // Build a lazy plan adding the two extracted elements as new columns,
            // then collect back into a DataFrame and replace df0.
            let new_df = df0
                .clone()
                .lazy()
                .with_columns(vec![
                    // get element 0
                    col("var0").arr().get(lit(0i64)).alias("var0_0"),
                    // get element 1
                    col("var0").arr().get(lit(1i64)).alias("var0_1"),
                ])
                .collect()?;
            *df0 = new_df;
            Ok(())
        }

        // If var0 is a Struct type (each row is a struct/tuple with named fields),
        // extract the two child fields. We require exactly two fields.
        DataType::Struct(fields) => {
            if fields.len() != 2 {
                return Err(PolarsError::ComputeError(
                    "Expected struct with exactly 2 fields in 'var0'".into(),
                ));
            }
            // get the two field names
            let fn0 = fields[0].name.clone();
            let fn1 = fields[1].name.clone();

            let new_df = df0
                .clone()
                .lazy()
                .with_columns(vec![
                    col("var0").struct_().field(&fn0).alias("var0_0"),
                    col("var0").struct_().field(&fn1).alias("var0_1"),
                ])
                .collect()?;
            *df0 = new_df;
            Ok(())
        }

        _ => Err(PolarsError::ComputeError(
            "Column 'var0' must be a List or Struct of length 2".into(),
        )),
    }
