use polars::prelude::*;

/// Splits a column containing two-element tuples into two separate columns.
///
/// # Arguments
/// * `df` - Input DataFrame containing the tuple column
/// * `tuple_col_name` - Name of the column containing tuples (default "var0")
/// * `col1_name` - Name for the first element column (default "var0_0")
/// * `col2_name` - Name for the second element column (default "var0_1")
///
/// # Returns
/// * `Result<DataFrame>` - DataFrame with the tuple column replaced by two separate columns
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// // Create sample data with tuple column
/// let df = df!(
///     "var0" => &[(1, "a"), (2, "b"), (3, "c")]
/// ).unwrap();
///
/// let result = split_tuple_column(&df, "var0", "first", "second").unwrap();
/// println!("{:?}", result);
/// ```
pub fn split_tuple_column(
    df: &DataFrame,
    tuple_col_name: &str,
    col1_name: &str,
    col2_name: &str,
) -> PolarsResult<DataFrame> {
    // Extract the tuple column
    let tuple_series = df.column(tuple_col_name)?;

    // Convert to a list of tuples and split
    let tuples: Vec<(i64, String)> = tuple_series
        .iter()
        .map(|opt_val| {
            match opt_val {
                AnyValue::List(series) => {
                    // Handle list/tuple representation
                    let first = series.get(0).unwrap().try_extract::<i64>().unwrap_or(0);
                    let second = series.get(1).unwrap().to_string();
                    (first, second)
                }
                _ => panic!("Expected tuple/list column"),
            }
        })
        .collect();

    // Create new columns from the split tuples
    let col1: Vec<i64> = tuples.iter().map(|(a, _)| *a).collect();
    let col2: Vec<&str> = tuples.iter().map(|(_, b)| b.as_str()).collect();

    // Build the result DataFrame
    let mut result_df = df.clone();

    // Remove the original tuple column
    result_df.drop_in_place(tuple_col_name)?;

    // Add the two new columns
    result_df.with_column(Series::new(col1_name, col1))?;
    result_df.with_column(Series::new(col2_name, col2))?;

    Ok(result_df)
}

// Alternative implementation using Polars expressions (more idiomatic)
pub fn split_tuple_column_expr(
    df: &DataFrame,
    tuple_col_name: &str,
    col1_name: &str,
    col2_name: &str,
) -> PolarsResult<DataFrame> {
