/// Create three new sequences from `input`:
/// - For 1-based odd positions (indices 0,2,4,...):
///     produce value - 1, value - 0, and value - (-1) respectively.
/// - For 1-based even positions (indices 1,3,5,...):
///     put 0 in all three sequences.
/// Return the three sequences as an array: [seq_minus1, seq_0, seq_plus1].
pub fn three_sequences(input: &[i32]) -> [Vec<i32>; 3] {
    let n = input.len();
    let mut seq_minus1 = Vec::with_capacity(n);
    let mut seq_0 = Vec::with_capacity(n);
    let mut seq_plus1 = Vec::with_capacity(n);

    for (idx, &val) in input.iter().enumerate() {
        if idx % 2 == 0 {
            // idx 0,2,4,... correspond to 1-based positions 1,3,5,... (odd positions)
            seq_minus1.push(val - 1);
            seq_0.push(val);
            seq_plus1.push(val + 1); // subtracting -1 is adding 1
        } else {
            // even positions become zero
            seq_minus1.push(0);
            seq_0.push(0);
            seq_plus1.push(0);
        }
    }

    [seq_minus1, seq_0, seq_plus1]
}

fn main() {
