pub fn sort_by_reference_order(
    lst0: Vec<HashMap<String, Value>>,
    lst1: Vec<Value>,
    var0: &str,
) -> Vec<HashMap<String, Value>> {
    // Create a lookup map from lst1 values to their positions
    let order_map: HashMap<&Value, usize> = lst1
        .iter()
        .enumerate()
        .map(|(index, value)| (value, index))
        .collect();

    // Separate items that are in lst1 from those that aren't
    let mut matched: Vec<(usize, HashMap<String, Value>)> = Vec::new();
    let mut unmatched: Vec<HashMap<String, Value>> = Vec::new();

    for item in lst0 {
        if let Some(key_value) = item.get(var0) {
            if let Some(&position) = order_map.get(key_value) {
                matched.push((position, item));
            } else {
                unmatched.push(item);
            }
        } else {
            unmatched.push(item);
        }
    }

    // Sort matched items by their position in lst1
    matched.sort_by_key(|(position, _)| *position);

    // Combine: matched items first (in order), then unmatched items
    let mut result: Vec<HashMap<String, Value>> = matched
        .into_iter()
        .map(|(_, item)| item)
        .collect();

    result.extend(unmatched);

    result
