    pub trait MergeFrom<Src> {
        /// Merge all items from `src` into `self`, updating existing entries
        /// when keys collide according to the collection's insert semantics.
        fn merge_from(&mut self, src: Src);
    }

    // Blanket implementation: if a target implements Extend<Item> and the source
    // is IntoIterator<Item = Item>, then the target can merge from the source.
    impl<Target, SrcIter, Item> MergeFrom<SrcIter> for Target
    where
        SrcIter: IntoIterator<Item = Item>,
        Target: Extend<Item>,
    {
        fn merge_from(&mut self, src: SrcIter) {
            self.extend(src);
        }
    }
