/// for matching keys.
///
/// Generic parameters:
/// - Target: the target collection type (must implement mergekit::MergeFrom<Src>)
/// - Src: something convertible to an iterator of items accepted by Target (e.g., IntoIterator<Item = (K, V)>)
pub fn add_all_into<Target, Src>(target: &mut Target, source: Src)
where
