/// ```
pub fn merge_into<K, V>(target: &mut IndexMap<K, V>, source: &IndexMap<K, V>)
where
    K: std::hash::Hash + Eq + Clone,
    V: Clone,
{
    for (key, value) in source.iter() {
        target.insert(key.clone(), value.clone());
    }
}

// Alternative version that consumes the source (more efficient for large collections)
pub fn merge_into_consuming<K, V>(target: &mut IndexMap<K, V>, source: IndexMap<K, V>)
where
    K: std::hash::Hash + Eq,
{
    target.extend(source);
}

