Here's a self-contained function using Rust's standard library that merges key-value pairs from one collection into another:

```rust
use std::collections::HashMap;

/// Adds all key-value pairs from `source` into `destination`,
/// updating any existing keys with values from `source`.
///
/// # Arguments
/// * `destination` - The HashMap to be updated
/// * `source` - The HashMap whose entries will be added to destination
///
/// # Example
/// ```
/// use std::collections::HashMap;
///
/// let mut dest = HashMap::from([("a", 1), ("b", 2)]);
/// let src = HashMap::from([("b", 20), ("c", 30)]);
///
/// merge_maps(&mut dest, src);
///
/// assert_eq!(dest.get("a"), Some(&1));
/// assert_eq!(dest.get("b"), Some(&20)); // Updated
/// assert_eq!(dest.get("c"), Some(&30)); // New entry
/// ```
fn merge_maps<K: Eq + std::hash::Hash, V>(
    destination: &mut HashMap<K, V>,
    source: HashMap<K, V>,
) {
    for (key, value) in source.into_iter() {
        destination.insert(key, value);
    }
}

fn main() {
    let mut destination = HashMap::from([
        ("name", "Alice"),
        ("age", "30"),
    ]);

    let source = HashMap::from([
        ("age", "31"),
        ("city", "NYC"),
    ]);

    merge_maps(&mut destination, source);

    println!("{:?}", destination);
    // Output: {"name": "Alice", "age": "31", "city": "NYC"}
}
```

