        let mut row = Vec::with_capacity(num_cols);
        for c in 0..num_cols {
            let cell = columns
                .get(c)
                .and_then(|col| col.get(r))
                .map(|v| v.to_string())
                .unwrap_or_else(|| "".to_string());
            row.push(cell);
        }
        table.push(row);
    }

    table
