/// Converts multiple lists contained in one list into a two-dimensional table,
/// using values from a second list as column headers.
///
/// # Arguments
/// * `data` - A vector of vectors containing the data rows
/// * `headers` - A vector of strings to use as column headers
///
/// # Returns
/// * `Result<Array2<Option<String>>, String>` - A 2D array where rows are from `data`
///   and columns are mapped according to `headers`, or an error if headers are empty
///
/// # Example
/// ```
/// use ndarray::Array2;
///
/// let data = vec![
///     vec!["Alice".to_string(), "30".to_string(), "Engineer".to_string()],
///     vec!["Bob".to_string(), "25".to_string(), "Designer".to_string()],
/// ];
/// let headers = vec!["Name".to_string(), "Age".to_string(), "Role".to_string()];
///
/// let table = lists_to_table(data, headers).unwrap();
/// assert_eq!(table[[0, 0]], Some("Alice".to_string()));
/// assert_eq!(table[[1, 1]], Some("25".to_string()));
/// ```
pub fn lists_to_table(
    data: Vec<Vec<String>>,
    headers: Vec<String>,
) -> Result<Array2<Option<String>>, String> {
    if headers.is_empty() {
        return Err("Headers list cannot be empty".to_string());
    }

    let num_rows = data.len();
    let num_cols = headers.len();

    // Create a mapping from header name to column index
    let header_map: HashMap<&str, usize> = headers
        .iter()
        .enumerate()
        .map(|(i, h)| (h.as_str(), i))
        .collect();

    // Initialize 2D array with None values
    let mut table = Array2::from_elem((num_rows, num_cols), None::<String>);

    // Fill the table row by row
    for (row_idx, row_data) in data.iter().enumerate() {
        // Each row in data is expected to be a list of [header, value] pairs
        // or a flat list where position maps to header position
        for (col_idx, value) in row_data.iter().enumerate() {
            if col_idx < num_cols {
                table[[row_idx, col_idx]] = Some(value.clone());
            }
        }
    }

    Ok(table)
}

/// Alternative version that handles explicit header-value pairs in each row
pub fn lists_to_table_with_pairs(
    data: Vec<Vec<(String, String)>>,
    headers: Vec<String>,
) -> Result<Array2<Option<String>>, String> {
    if headers.is_empty() {
        return Err("Headers list cannot be empty".to_string());
    }

    let num_rows = data.len();
    let num_cols = headers.len();

    // Create a mapping from header name to column index
    let header_map: HashMap<&str, usize> = headers
        .iter()
        .enumerate()
        .map(|(i, h)| (h.as_str(), i))
        .collect();

    // Initialize 2D array with None values
    let mut table = Array2::from_elem((num_rows, num_cols), None::<String>);

    // Fill the table using header-value pairs
    for (row_idx, row_pairs) in data.iter().enumerate() {
        for (header, value) in row_pairs {
            if let Some(&col_idx) = header_map.get(header.as_str()) {
                table[[row_idx, col_idx]] = Some(value.clone());
            }
        }
    }

    Ok(table)
}

