use polars::prelude::*;

/// Converts multiple lists into a 2D table with custom column headers.
///
/// # Arguments
/// * `data` - A vector of vectors where each inner vector represents a row
/// * `headers` - A vector of column header names
///
/// # Returns
/// * `Result<DataFrame, PolarsError>` - A Polars DataFrame or error
///
/// # Example
/// ```
/// let data = vec![
///     vec![1, 2, 3],
///     vec![4, 5, 6],
///     vec![7, 8, 9],
/// ];
/// let headers = vec!["A", "B", "C"];
/// let df = lists_to_table(data, headers)?;
/// println!("{}", df);
/// ```
fn lists_to_table(
    data: Vec<Vec<i32>>,
    headers: Vec<&str>,
) -> PolarsResult<DataFrame> {
    if data.is_empty() {
        return Ok(DataFrame::default());
    }

    // Validate that all rows have the same length as headers
    let expected_cols = headers.len();
    if !data.iter().all(|row| row.len() == expected_cols) {
        return Err(PolarsError::ComputeError(
            "All rows must have the same length as headers".into(),
        ));
    }

    // Transpose data: convert row-oriented to column-oriented
    let mut columns: Vec<Series> = vec![];

    for (col_idx, header) in headers.iter().enumerate() {
        let col_data: Vec<i32> = data.iter().map(|row| row[col_idx]).collect();
        let series = Series::new((*header).into(), col_data);
        columns.push(series);
    }

    DataFrame::new(columns)
}

// Alternative generic version that works with different types
fn lists_to_table_generic<T: 'static + IntoSeries>(
    data: Vec<Vec<T>>,
    headers: Vec<&str>,
) -> PolarsResult<DataFrame>
where
    T: Clone,
{
    if data.is_empty() {
        return Ok(DataFrame::default());
    }

    let expected_cols = headers.len();
    if !data.iter().all(|row| row.len() == expected_cols) {
        return Err(PolarsError::ComputeError(
            "All rows must have the same length as headers".into(),
        ));
    }

    let mut columns: Vec<Series> = vec![];

    for (col_idx, header) in headers.iter().enumerate() {
        let col_data: Vec<T> = data.iter().map(|row| row[col_idx].clone()).collect();
        let series = col_data.into_series(*header);
        columns.push(series);
    }

    DataFrame::new(columns)
}

