///     ("apple", "ab"),
///     ("apple", "xyz"),
///     ("apple", "world"),
///     ("banana", "hello"),
/// ]);
/// ```
fn sort_by_first_then_length<T: Ord>(items: &mut Vec<(T, &str)>) {
    items.sort_by(|a, b| {
        // First, compare by the first element
        match a.0.cmp(&b.0) {
            std::cmp::Ordering::Equal => {
                // If first elements are equal, compare by length of second element
                a.1.len().cmp(&b.1.len())
            }
            other => other,
        }
    });
}

