    items: &mut Vec<(T, S)>,
) {
    items.sort_by(|a, b| {
        match a.0.cmp(&b.0) {
            std::cmp::Ordering::Equal => {
                a.1.as_ref().len().cmp(&b.1.as_ref().len())
            }
            other => other,
        }
    });
}

