/// Simple cell type for demonstration.
#[derive(Debug, Clone)]
pub enum Cell {
    Int(i64),
    Float(f64),
    Text(String),
    Null,
}

impl PartialEq for Cell {
    fn eq(&self, other: &Self) -> bool {
        match (self, other) {
            (Cell::Int(a), Cell::Int(b)) => a == b,
            (Cell::Float(a), Cell::Float(b)) => a == b,
            (Cell::Int(a), Cell::Float(b)) => (*a as f64) == *b,
            (Cell::Float(a), Cell::Int(b)) => *a == (*b as f64),
            (Cell::Text(a), Cell::Text(b)) => a == b,
            (Cell::Null, Cell::Null) => true,
            _ => false,
        }
    }
}
impl Eq for Cell {}

impl PartialOrd for Cell {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for Cell {
    fn cmp(&self, other: &Self) -> Ordering {
        match (self, other) {
            (Cell::Int(a), Cell::Int(b)) => a.cmp(b),
            (Cell::Float(a), Cell::Float(b)) => a.partial_cmp(b).unwrap_or(Ordering::Equal),
            (Cell::Int(a), Cell::Float(b)) => (*a as f64).partial_cmp(b).unwrap_or(Ordering::Equal),
            (Cell::Float(a), Cell::Int(b)) => a.partial_cmp(&(*b as f64)).unwrap_or(Ordering::Equal),
            (Cell::Text(a), Cell::Text(b)) => a.cmp(b),
            (Cell::Null, Cell::Null) => Ordering::Equal,
            // If types differ (e.g. Text vs Int), fall back to string comparison for deterministic ordering
            _ => format!("{:?}", self).cmp(&format!("{:?}", other)),
        }
    }
}

/// Very small tabular data object
#[derive(Debug, Clone)]
pub struct DataFrame {
    pub columns: Vec<String>,
    pub rows: Vec<Vec<Cell>>,
}

/// Return a new DataFrame sorted by `var0` then `var1` (both ascending).
pub fn sort_df_by_two_columns(mut df: DataFrame, var0: &str, var1: &str) -> Result<DataFrame, String> {
    let i0 = df
        .columns
        .iter()
        .position(|c| c == var0)
        .ok_or_else(|| format!("column '{}' not found", var0))?;
    let i1 = df
        .columns
        .iter()
        .position(|c| c == var1)
        .ok_or_else(|| format!("column '{}' not found", var1))?;

    // Ensure every row has enough columns
    for (ridx, row) in df.rows.iter().enumerate() {
        if row.len() <= i0 || row.len() <= i1 {
            return Err(format!("row {} too short for requested columns", ridx));
        }
    }

    df.rows.sort_by(|a, b| {
        let by0 = a[i0].cmp(&b[i0]);
        if by0 == Ordering::Equal {
            a[i1].cmp(&b[i1])
        } else {
            by0
        }
    });

    Ok(df)
}

