use std::collections::HashMap;

/// Reorders elements of a collection by their frequency of occurrence.
/// Elements with higher frequency appear first. Elements with the same
/// frequency maintain their relative order of first appearance.
///
/// # Arguments
/// * `items` - A slice of comparable and hashable items
///
/// # Returns
/// A Vec with elements reordered by frequency (descending)
///
/// # Example
/// ```
/// let nums = vec![1, 1, 1, 2, 2, 3];
/// let result = reorder_by_frequency(nums);
/// assert_eq!(result, vec![1, 1, 1, 2, 2, 3]);
/// ```
fn reorder_by_frequency<T: Eq + std::hash::Hash + Clone + Ord>(
    items: &[T],
) -> Vec<T> {
    // Count frequency of each element
    let mut frequency: HashMap<T, usize> = HashMap::new();
    let mut first_appearance: HashMap<T, usize> = HashMap::new();

    for (index, item) in items.iter().enumerate() {
        *frequency.entry(item.clone()).or_insert(0) += 1;
        first_appearance.entry(item.clone()).or_insert(index);
    }

    // Create a vector of (element, frequency, first_appearance_index)
    let mut freq_items: Vec<(T, usize, usize)> = frequency
        .into_iter()
        .map(|(item, freq)| (item.clone(), freq, first_appearance[&item]))
        .collect();

    // Sort by: frequency (descending), then by first appearance (ascending)
    freq_items.sort_by(|a, b| {
        b.1.cmp(&a.1) // Compare frequencies in descending order
            .then_with(|| a.2.cmp(&b.2)) // Then by first appearance order
    });

    // Reconstruct the result with all elements in their original order
    // but grouped by frequency
    let mut result = Vec::new();
    for (item, freq, _) in freq_items {
        for _ in 0..freq {
            result.push(item.clone());
        }
    }

    result
}

