fn filter_by_statistical_distance(lst0: &[f64], var0: f64) -> Vec<f64> {
    if lst0.is_empty() {
        return Vec::new();
    }

    // Calculate mean
    let mean = lst0.iter().sum::<f64>() / lst0.len() as f64;

