```rust
use polars::prelude::*;
use std::collections::HashMap;

/// Applies a series of filter conditions to a Polars DataFrame.
///
/// # Arguments
/// * `df0` - The input DataFrame to filter.
/// * `var0` - A map of column names to filter conditions.
///   Each condition can be:
///   - A boolean value (for exact equality)
///   - A comparison operator (e.g., ">", "<", ">=") followed by a value
///   - A regex pattern (prefixed with "~")
///
/// # Returns
/// A filtered DataFrame.
///
/// # Example
/// ```
/// use polars::prelude::*;
/// let df = df!(
///     "A" => &[1, 2, 3, 4],
///     "B" => &["a", "b", "c", "d"],
///     "C" => &[true, false, true, false]
/// ).unwrap();
///
/// let filters = HashMap::from([
///     ("A".to_string(), ">= 2".to_string()),
///     ("B".to_string(), "~^[ab]$".to_string()),
///     ("C".to_string(), "true".to_string())
/// ]);
///
/// let result = apply_filters(df, filters).unwrap();
/// ```
pub fn apply_filters(df0: DataFrame, var0: HashMap<String, String>) -> Result<DataFrame, PolarsError> {
    let mut exprs = Vec::new();

    for (col, condition) in var0 {
        let col_expr = col.parse::<Expr>()?;
        match condition.as_str() {
            // Exact boolean match
            "true" => exprs.push(col_expr.eq(lit(true))),
            "false" => exprs.push(col_expr.eq(lit(false))),
            // Regex match (prefix with ~)
            cond if cond.starts_with("~") => {
                let pattern = cond[1..].to_string();
                exprs.push(col_expr.str().like(&pattern));
            }
            // Numeric comparisons
            cond if cond.contains(">") => {
                let (op, val) = cond.split_once(">").unwrap();
                let val = op.trim().parse::<f64>()?;
                exprs.push(col_expr.gt(lit(val)));
            }
            cond if cond.contains(">=") => {
                let (op, val) = cond.split_once(">=").unwrap();
                let val = op.trim().parse::<f64>()?;
                exprs.push(col_expr.ge(lit(val)));
            }
            cond if cond.contains("<") => {
                let (op, val) = cond.split_once("<").unwrap();
                let val = op.trim().parse::<f64>()?;
                exprs.push(col_expr.lt(lit(val)));
            }
            cond if cond.contains("<=") => {
                let (op, val) = cond.split_once("<=").unwrap();
                let val = op.trim().parse::<f64>()?;
                exprs.push(col_expr.le(lit(val)));
            }
            // String equality
            cond => {
                exprs.push(col_expr.eq(lit(cond)));
            }
        }
    }

    // Combine all conditions with AND
    let combined_expr = if exprs.is_empty() {
        lit(true)
    } else {
        exprs.into_iter().reduce(|a, b| a & b).unwrap()
    };

    df0.lazy().filter(&combined_expr).collect()
}
```

### Key Features:
1. **Flexible Filtering**: Supports boolean values, numeric comparisons, regex patterns, and string equality.
2. **Lazy Evaluation**: Uses Polars' lazy API for efficient filtering.
3. **Type Safety**: Proper error handling with `Result`.
4. **Modern Rust**: Uses Rust 2021 edition features.

