use polars::prelude::*;
use std::collections::HashMap;

/// Apply a series of filter conditions to a DataFrame
///
/// # Arguments
/// * `df0` - The input DataFrame to filter
/// * `var0` - A HashMap where keys are column names and values are filter conditions
///           Supported conditions: "eq:value", "gt:value", "lt:value", "gte:value", "lte:value", "ne:value"
///
/// # Returns
/// * `Result<DataFrame>` - The filtered DataFrame or an error
pub fn apply_filters(
    df0: &DataFrame,
    var0: &HashMap<String, String>,
) -> PolarsResult<DataFrame> {
    let mut filtered_df = df0.clone();

    for (column, condition) in var0 {
        // Parse the condition (format: "operator:value")
        let parts: Vec<&str> = condition.splitn(2, ':').collect();
        if parts.len() != 2 {
            return Err(PolarsError::ComputeError(
                format!("Invalid condition format for column '{}': '{}'. Expected format: 'operator:value'", column, condition).into(),
            ));
        }

        let operator = parts[0];
        let value_str = parts[1];

        // Try to parse value as numeric first, then fall back to string
        let mask = if let Ok(numeric_value) = value_str.parse::<f64>() {
            // Numeric comparison
            let series = filtered_df.column(column)?;
            match operator {
                "eq" => series.equal(numeric_value)?,
                "ne" => series.not_equal(numeric_value)?,
                "gt" => series.gt(numeric_value)?,
                "lt" => series.lt(numeric_value)?,
                "gte" => series.gt_eq(numeric_value)?,
                "lte" => series.lt_eq(numeric_value)?,
                _ => return Err(PolarsError::ComputeError(
                    format!("Unsupported operator '{}' for column '{}'", operator, column).into(),
                )),
            }
        } else {
            // String comparison
            let series = filtered_df.column(column)?;
            let str_series = series.str()?;
            match operator {
                "eq" => str_series.equal(value_str)?,
                "ne" => str_series.not_equal(value_str)?,
                "contains" => str_series.contains(value_str)?,
                "starts_with" => str_series.starts_with(value_str)?,
                "ends_with" => str_series.ends_with(value_str)?,
                _ => return Err(PolarsError::ComputeError(
                    format!("Unsupported string operator '{}' for column '{}'", operator, column).into(),
                )),
            }
        };

        filtered_df = filtered_df.filter(&mask)?;
    }

    Ok(filtered_df)
}

