use std::collections::HashMap;

/// Group columns by label and compute the row-wise sum for each group.
///
/// Inputs:
/// - `labels`: vector of length `n_cols` with the label for each column (labels may repeat).
/// - `table`: rows x cols matrix represented as `Vec<Vec<f64>>`.
///
/// Returns:
/// - Ok((unique_labels_in_first_seen_order, grouped_table_rows_x_groups))
/// - Err if input dimensions are inconsistent.
///
/// Example:
/// labels = ["a", "b", "a"]
/// table = [ [1.0, 2.0, 3.0],   // row 0
///           [4.0, 5.0, 6.0] ]  // row 1
/// Unique labels in order: ["a", "b"]
/// Resulting grouped table: [ [1+3, 2] => [4.0, 2.0],
///                            [4+6, 5] => [10.0,5.0] ]
fn group_columns_by_label_sum(
    labels: &[String],
    table: &[Vec<f64>],
) -> Result<(Vec<String>, Vec<Vec<f64>>), String> {
    let n_cols = labels.len();

    // Quick checks
    for (r, row) in table.iter().enumerate() {
        if row.len() != n_cols {
            return Err(format!(
                "Row {} has length {}, but expected {} (labels length)",
                r,
                row.len(),
                n_cols
            ));
        }
    }

    // Build mapping from label -> output index, preserving first-seen order.
    let mut label_to_index: HashMap<&str, usize> = HashMap::new();
    let mut unique_labels: Vec<String> = Vec::new();
    for label in labels {
        let key: &str = label.as_str();
        if !label_to_index.contains_key(key) {
            let idx = unique_labels.len();
            unique_labels.push(label.clone());
            label_to_index.insert(key, idx);
        }
    }

    let n_groups = unique_labels.len();
    let n_rows = table.len();

    // Prepare output table initialized to zeros: rows x groups
    let mut out = vec![vec![0.0_f64; n_groups]; n_rows];

    // Aggregate: for each cell add into its group's column
    for r in 0..n_rows {
        let row = &table[r];
        for c in 0..n_cols {
            let label = labels[c].as_str();
            let g = label_to_index[label];
            out[r][g] += row[c];
        }
    }

    Ok((unique_labels, out))
}

fn main() {
