use std::cmp::Reverse;
use std::collections::BinaryHeap;

/// Return the indices of the `n` highest values in `values`.
/// Indices are sorted by value descending; ties broken by smaller index.
/// Requires T: Ord + Copy.
///
/// Example:
/// let v = [10, 30, 20, 40];
/// assert_eq!(top_n_indices(&v, 2), vec![3, 1]); // indices of 40 and 30
pub fn top_n_indices<T: Ord + Copy>(values: &[T], n: usize) -> Vec<usize> {
    let len = values.len();
    if n == 0 || len == 0 {
        return Vec::new();
    }
    let k = n.min(len);

    // Min-heap (by value) of size up to k storing (value, index).
    let mut heap: BinaryHeap<(Reverse<T>, usize)> = BinaryHeap::with_capacity(k);
    for i in 0..k {
        heap.push((Reverse(values[i]), i));
    }
    for i in k..len {
        // If current value is greater than the smallest in the heap, replace.
        if values[i] > heap.peek().unwrap().0 .0 {
            heap.pop();
            heap.push((Reverse(values[i]), i));
        }
    }

    // Extract indices and sort them by value descending, then index ascending.
    let mut indices: Vec<usize> = heap.into_iter().map(|(_, idx)| idx).collect();
    indices.sort_by_key(|&i| (Reverse(values[i]), i));
    indices
}

