use std::ops::{Add, Mul};

/// Sum of products of every unique subset of `values` of size `k`.
/// Returns the k-th elementary symmetric sum of the inputs.
///
/// Generic over numeric types that implement Copy, Add, Mul and From<u8>.
///
/// Examples:
/// let vals = [1i64, 2, 3, 4];
/// assert_eq!(sum_products_of_subsets(&vals, 2), 35); // 1*2+1*3+1*4+2*3+2*4+3*4 = 35
pub fn sum_products_of_subsets<T>(values: &[T], k: usize) -> T
where
    T: Copy + Add<Output = T> + Mul<Output = T> + From<u8>,
{
    if k == 0 {
        return T::from(1u8);
    }
    let n = values.len();
    if k > n {
        return T::from(0u8);
    }

    let mut dp = vec![T::from(0u8); k + 1];
    dp[0] = T::from(1u8);

    for &x in values {
        // iterate backward so we don't reuse updated dp[j-1] in this iteration
        for j in (1..=k).rev() {
            dp[j] = dp[j] + dp[j - 1] * x;
        }
    }

    dp[k]
}

