        panic!("k cannot be larger than the number of elements");
    }
    if k == 0 {
        return 0;
    }

    let mut total = 0;
    let mut indices = (0..k).collect::<Vec<_>>();

    loop {
        // Calculate product for current combination
        let product: i64 = indices.iter().map(|&i| values[i]).product();
        total += product;

        // Generate next combination
        let mut i = k;
        while i > 0 {
