Rust code:

```rust
use std::collections::HashMap;
use indexmap::IndexMap;

/// A simple row-based table representation: vector of rows, each row is a HashMap column_name -> value.
type Row = HashMap<String, String>;
type Table = Vec<Row>;

/// Replace categories in `col_name` with integer indices (as decimal strings) in-place.
/// Returns an IndexMap mapping each seen category -> assigned index (0..k-1) in order of first appearance.
///
/// Complexity: O(n) time, O(k) extra memory for the mapping (k = # unique categories).
fn factorize_column(table: &mut Table, col_name: &str) -> IndexMap<String, usize> {
    let mut mapping: IndexMap<String, usize> = IndexMap::new();
    let mut next_index: usize = 0;

    for row in table.iter_mut() {
        // If the column is missing, treat as an empty string (change as desired)
        let cat = row.get(col_name).map(|s| s.clone()).unwrap_or_default();

        // Get or insert index for this category
        let idx = if let Some(&existing) = mapping.get(&cat) {
            existing
        } else {
            let i = next_index;
            mapping.insert(cat.clone(), i);
            next_index += 1;
            i
        };

        // Replace the original category with the index (stored as decimal string)
        row.insert(col_name.to_string(), idx.to_string());
    }

    mapping
}

// Example usage
fn main() {
    // Build a simple table df0 with a column "col0"
    let mut df0: Table = vec![
        hashmap! { "col0".into() => "apple".into(), "other".into() => "x".into() },
        hashmap! { "col0".into() => "banana".into(), "other".into() => "y".into() },
        hashmap! { "col0".into() => "apple".into(), "other".into() => "z".into() },
        hashmap! { "col0".into() => "orange".into(), "other".into() => "w".into() },
    ];

    // Factorize
    let mapping = factorize_column(&mut df0, "col0");

    // Print results
    println!("Mapping (category -> index):");
    for (cat, idx) in mapping.iter() {
        println!("  {} -> {}", cat, idx);
    }

    println!("Table after factorization:");
    for row in &df0 {
        println!("{:?}", row);
    }
}

// A tiny helper macro to create HashMaps inline for the example.
// You can remove it in production and build rows however you like.
#[macro_export]
macro_rules! hashmap {
    ($( $key:expr => $val:expr ),* $(,)?) => {{
         let mut m = std::collections::HashMap::new();
         $( m.insert($key.to_string(), $val.to_string()); )*
         m
    }}
}
```

Notes and variations
- If you want the resulting column to be numeric-typed rather than strings, adapt your table representation to support typed columns (e.g., enum Column { Str(Vec<String>), Int(Vec<usize>), ... }) and store the indices as integers.
- If you want mapping ordered by sorted category values rather than first-seen order, sort the unique keys and assign indices accordingly.
- For very large tables, consider using a columnar representation (Vec of columns) to avoid HashMap cloning overhead and to enable zero-copy operations. In that case you can keep a separate Vec<String> for the category column and transform it into Vec<usize> in-place (or produce a new Vec<usize>) using the same IndexMap approach.
- indexmap preserves insertion order which makes the mapping deterministic based on first appearance; if ordering doesn't matter, std::collections::HashMap is slightly more lightweight.

