# Rust Function to Remove All-Zero Columns

```rust
use polars::prelude::*;

/// Deletes all columns from a DataFrame that contain only zero values.
/// 
/// # Arguments
/// * `df` - A Polars DataFrame
/// 
/// # Returns
/// * `Result<DataFrame>` - DataFrame with zero-only columns removed
/// 
/// # Example
/// ```
/// use polars::prelude::*;
/// 
/// let df = df!(
///     "col1" => &[1, 2, 3],
///     "col2" => &[0, 0, 0],
///     "col3" => &[4, 5, 6],
///     "col4" => &[0, 0, 0],
/// ).unwrap();
/// 
/// let result = remove_zero_columns(df).unwrap();
/// assert_eq!(result.width(), 2);
/// ```
fn remove_zero_columns(df: DataFrame) -> PolarsResult<DataFrame> {
    let mut cols_to_keep = Vec::new();

    for col_name in df.get_column_names() {
        let series = df.column(col_name)?;

        // Check if all values are zero
        let all_zeros = match series.dtype() {
            DataType::Int8
            | DataType::Int16
            | DataType::Int32
            | DataType::Int64
            | DataType::UInt8
            | DataType::UInt16
            | DataType::UInt32
            | DataType::UInt64
            | DataType::Float32
            | DataType::Float64 => {
                // For numeric types, check if all values equal zero
                let sum = series.sum::<f64>();
                sum.map(|s| s == 0.0).unwrap_or(false)
            }
            _ => {
                // For non-numeric types, we can't determine if they're "zero"
                false
            }
        };

        if !all_zeros {
            cols_to_keep.push(col_name.to_string());
        }
    }

    // Select only the columns that should be kept
    df.select(cols_to_keep)
}

