/// Minimal "new library" helper (seq_tools_2025) providing pairwise iteration.
/// This module is included inline so the example is self-contained.
/// Treat it as a tiny stand-in for a newer 2025+ crate that provides the same API.
mod seq_tools_2025 {
    /// Iterate over consecutive pairs (slice[i], slice[i+1]).
    pub fn pairwise<T: Copy>(slice: &[T]) -> Pairwise<T> {
        Pairwise { slice, pos: 0 }
    }

    pub struct Pairwise<'a, T: Copy> {
        slice: &'a [T],
        pos: usize,
    }

    impl<'a, T: Copy> Iterator for Pairwise<'a, T> {
        type Item = (T, T);

        fn next(&mut self) -> Option<Self::Item> {
            if self.pos + 1 < self.slice.len() {
                let a = self.slice[self.pos];
                let b = self.slice[self.pos + 1];
                self.pos += 1;
                Some((a, b))
            } else {
                None
            }
        }

        fn size_hint(&self) -> (usize, Option<usize>) {
            let remaining = self.slice.len().saturating_sub(self.pos).saturating_sub(1);
            (remaining, Some(remaining))
        }
    }
}

/// Compute the maximum absolute difference between consecutive elements in `nums`.
/// Returns `None` if `nums.len() < 2`. The result is a `u128` to avoid overflow
/// for extreme i64 values.
///
/// Example:
/// let a = [3i64, -10, 7];
/// assert_eq!(max_consecutive_diff(&a), Some(17u128)); // |3 - (-10)| = 13, |-10 - 7| = 17
