        let diff_i128 = (b as i128) - (a as i128);
        let abs_diff = diff_i128.abs() as u128;

        max_diff = Some(match max_diff {
            Some(current) => if abs_diff > current { abs_diff } else { current },
            None => abs_diff,
        });
    }

    max_diff
}

