use polars::prelude::*;
use std::error::Error;

/// Calculates the Pearson correlation coefficient between two numeric columns in a DataFrame.
///
/// # Arguments
/// * `df0` - A reference to the DataFrame containing the columns to correlate
/// * `var0` - Name of the first column (must be numeric)
/// * `var1` - Name of the second column (must be numeric)
///
/// # Returns
/// A `Result` containing the correlation coefficient (between -1.0 and 1.0) or an error
///
/// # Examples
/// ```
/// use polars::prelude::*;
/// let df = df![
///     "var0" => &[1.0, 2.0, 3.0, 4.0],
///     "var1" => &[2.0, 4.0, 6.0, 8.0]
/// ].unwrap();
/// let corr = calculate_pearson_correlation(&df, "var0", "var1").unwrap();
/// assert!((corr - 1.0).abs() < 1e-6);
/// ```
pub fn calculate_pearson_correlation(
    df0: &DataFrame,
    var0: &str,
    var1: &str,
) -> Result<f64, Box<dyn Error>> {
    // Check if columns exist
    if !df0.column(var0).is_ok() || !df0.column(var1).is_ok() {
        return Err(format!("Column {} or {} not found", var0, var1).into());
    }

    // Get the columns as Series
    let series0 = df0.column(var0)?.f64()?;
    let series1 = df0.column(var1)?.f64()?;

    // Check for empty or NaN-only columns
    if series0.null_count() == series0.len() || series1.null_count() == series1.len() {
        return Err("One or both columns contain only null values".into());
    }

    // Calculate means
    let mean0 = series0.mean().ok_or("Failed to calculate mean")?;
    let mean1 = series1.mean().ok_or("Failed to calculate mean")?;

    // Calculate covariance and standard deviations
    let cov = series0
        .iter()
        .zip(series1.iter())
        .filter_map(|(a, b)| {
            let a = a.ok()?;
            let b = b.ok()?;
            Some((a - mean0) * (b - mean1))
        })
        .sum::<f64>();

    let stddev0 = series0
        .iter()
        .filter_map(|a| {
            let a = a.ok()?;
            Some((a - mean0).powi(2))
        })
        .sum::<f64>()
        .sqrt();

    let stddev1 = series1
        .iter()
        .filter_map(|b| {
            let b = b.ok()?;
            Some((b - mean1).powi(2))
        })
        .sum::<f64>()
        .sqrt();

    // Handle division by zero cases
    if stddev0 == 0.0 || stddev1 == 0.0 {
        return Err("Cannot calculate correlation: one or both columns have zero standard deviation".into());
    }

    // Calculate Pearson correlation coefficient
    let correlation = cov / (stddev0 * stddev1);

    Ok(correlation.clamp(-1.0, 1.0)) // Ensure result is within valid range
}

