pub fn correlation_coefficient_manual(df0: &DataFrame) -> Result<f64, PolarsError> {
    let var0 = df0.column("var0")?.f64()?;
    let var1 = df0.column("var1")?.f64()?;

    // Filter out any null values and collect into vectors
    let pairs: Vec<(f64, f64)> = var0
        .into_iter()
        .zip(var1.into_iter())
        .filter_map(|(a, b)| match (a, b) {
            (Some(x), Some(y)) => Some((x, y)),
            _ => None,
        })
        .collect();

    let n = pairs.len() as f64;
    if n < 2.0 {
        return Err(PolarsError::ComputeError(
            "Need at least 2 data points for correlation".into(),
        ));
    }

    // Calculate sums
    let sum_x: f64 = pairs.iter().map(|(x, _)| x).sum();
    let sum_y: f64 = pairs.iter().map(|(_, y)| y).sum();
    let sum_xy: f64 = pairs.iter().map(|(x, y)| x * y).sum();
    let sum_x2: f64 = pairs.iter().map(|(x, _)| x * x).sum();
    let sum_y2: f64 = pairs.iter().map(|(_, y)| y * y).sum();

    // Calculate Pearson correlation coefficient
    let numerator = n * sum_xy - sum_x * sum_y;
    let denominator = ((n * sum_x2 - sum_x * sum_x) * (n * sum_y2 - sum_y * sum_y)).sqrt();

    if denominator == 0.0 {
        return Err(PolarsError::ComputeError(
            "Denominator is zero - no variance in data".into(),
        ));
    }

    Ok(numerator / denominator)
}

