fn calculate_correlation(df: &DataFrame, col1: &str, col2: &str) -> PolarsResult<f64> {
    // Extract the two columns as Series
    let series1 = df.column(col1)?;
    let series2 = df.column(col2)?;

    // Convert to f64 for correlation calculation
    let values1: Vec<f64> = series1
        .cast(&DataType::Float64)?
        .f64()?
        .into_iter()
        .filter_map(|x| x)
        .collect();

    let values2: Vec<f64> = series2
        .cast(&DataType::Float64)?
        .f64()?
        .into_iter()
        .filter_map(|x| x)
        .collect();

    // Calculate means
    let mean1 = values1.iter().sum::<f64>() / values1.len() as f64;
    let mean2 = values2.iter().sum::<f64>() / values2.len() as f64;

    // Calculate correlation coefficient (Pearson)
    let mut numerator = 0.0;
    let mut sum_sq1 = 0.0;
    let mut sum_sq2 = 0.0;

