/// let result = convert_to_date(df).unwrap();
/// assert_eq!(result.column("var0").dtype(), &DataType::Date);
/// ```
pub fn convert_to_date(df0: &DataFrame) -> Result<DataFrame, Box<dyn Error>> {
    // Check if the column exists
    if !df0.column("var0").is_some() {
        return Err("Column 'var0' not found in DataFrame".into());
    }

    // Get the original column
    let var0_series = df0.column("var0").unwrap().clone();

    // Convert to string slice for parsing
    let string_series = match var0_series.dtype() {
        DataType::Utf8 => var0_series.utf8().unwrap(),
