///
/// # Examples
/// ```
/// use ndarray::array;
///
/// let data = array![
///     [1.0, 2.0, f64::NAN],
///     [4.0, f64::NAN, 6.0],
///     [7.0, 8.0, 9.0]
/// ];
///
/// let result = replace_missing_with_column_avg(data);
/// assert_eq!(result[[0, 2]], 7.5); // (2+6+9)/3 = 5.666..., but wait no - let's check:
/// // Actually the column averages are:
/// // col0: (1+4+7)/3 = 4.0
/// // col1: (2+8)/2 = 5.0 (since one NAN)
/// // col2: (6+9)/2 = 7.5
/// // So result[[0,2]] should be 7.5
/// ```
pub fn replace_missing_with_column_avg<T>(data: Array2<T>) -> Array2<f64>
where
    T: Data + Copy + Into<f64>,
{
    // Convert to f64 array for easier NAN handling
    let mut array: Array2<f64> = data.mapv(|x| x.into());

    // Calculate column averages, ignoring NANs
    let (rows, cols) = array.dim();
    let mut column_sums = vec![0.0; cols];
    let mut column_counts = vec![0; cols];

    for row in array.axis_iter(Axis(0)) {
        for (col, &val) in row.iter().enumerate() {
            if !val.is_nan() {
                column_sums[col] += val;
                column_counts[col] += 1;
            }
        }
    }

    // Calculate actual averages
    let mut column_avgs = vec![0.0; cols];
    for (col, &count) in column_counts.iter().enumerate() {
        if count > 0 {
            column_avgs[col] = column_sums[col] / count as f64;
        } else {
            // If entire column is NAN, we'll leave it as NAN
            column_avgs[col] = f64::NAN;
        }
    }

    // Replace NANs with column averages
    for row in array.axis_iter_mut(Axis(0)) {
        for (col, val) in row.iter_mut().enumerate() {
            if val.is_nan() {
                *val = column_avgs[col];
            }
        }
    }

    array
}

