/// Replace missing entries in a rectangular 2D numeric dataset with the column mean.
///
/// The dataset is represented as Vec<Vec<Option<f64>>> (rows of optional values).
/// Rows must all have identical lengths (a proper matrix).
///
/// - impute_column_means_inplace(&mut data)
///     Mutates `data` in place: every None becomes Some(column_mean).
///
/// - impute_column_means(&data) -> Result<Vec<Vec<f64>>, String>
///     Returns a new matrix of f64 with missing values replaced by the column means.
///
/// If an entire column is missing, the code uses 0.0 as the column mean (changeable).
///
/// Example usage is shown in main().
fn impute_column_means_inplace(data: &mut [Vec<Option<f64>>]) -> Result<(), String> {
    if data.is_empty() {
        return Ok(());
    }
    let ncols = data[0].len();
    // Validate rectangular shape
    for (i, row) in data.iter().enumerate() {
        if row.len() != ncols {
            return Err(format!(
                "inconsistent row lengths: row 0 has length {}, row {} has length {}",
                ncols,
                i,
                row.len()
            ));
        }
    }

    // Compute sums and counts per column
    let mut sums = vec![0.0f64; ncols];
    let mut counts = vec![0usize; ncols];
    for row in data.iter() {
        for (j, cell) in row.iter().enumerate() {
            if let Some(v) = cell {
                sums[j] += *v;
                counts[j] += 1;
            }
        }
    }

    // Compute means (use 0.0 when count == 0)
    let mut means = vec![0.0f64; ncols];
    for j in 0..ncols {
        if counts[j] > 0 {
            means[j] = sums[j] / (counts[j] as f64);
        } else {
            means[j] = 0.0; // choose default for all-missing column; change if desired
        }
    }

    // Fill missing entries
    for row in data.iter_mut() {
        for (j, cell) in row.iter_mut().enumerate() {
            if cell.is_none() {
                *cell = Some(means[j]);
            }
        }
    }

    Ok(())
}

fn impute_column_means(data: &[Vec<Option<f64>>]) -> Result<Vec<Vec<f64>>, String> {
