/// let result = fill_missing_with_column_mean(&data);
/// // Column 0 mean: (1+4+7)/3 = 4.0
/// // Column 1 mean: (2+8)/2 = 5.0
/// // Column 2 mean: (6+9)/2 = 7.5
/// // Result: [[1.0, 2.0, 7.5], [4.0, 5.0, 6.0], [7.0, 8.0, 9.0]]
/// ```
pub fn fill_missing_with_column_mean(data: &[Vec<Option<f64>>]) -> Vec<Vec<f64>> {
    if data.is_empty() || data[0].is_empty() {
        return Vec::new();
    }

    let ncols = data[0].len();

    // Convert to Polars DataFrame
    let mut columns = Vec::with_capacity(ncols);

    for col_idx in 0..ncols {
        let col_data: Vec<Option<f64>> = data.iter()
            .map(|row| row[col_idx])
            .collect();
        columns.push(Series::new(&format!("col_{}", col_idx), col_data));
    }

    let mut df = DataFrame::new(columns).expect("Failed to create DataFrame");

    // Fill null values with column means
    let filled = df.fill_null(FillNullStrategy::Mean).expect("Failed to fill null values");

    // Convert back to Vec<Vec<f64>>
    let mut result = Vec::with_capacity(data.len());

    for row_idx in 0..data.len() {
        let mut row = Vec::with_capacity(ncols);
        for col_idx in 0..ncols {
            let value = filled.column(&format!("col_{}", col_idx))
                .unwrap()
                .f64()
                .unwrap()
                .get(row_idx)
                .unwrap();
            row.push(value);
        }
        result.push(row);
    }

    result
}

