```rust
use polars::prelude::*;

/// Replaces missing (null) entries in a DataFrame with the average value 
/// of their corresponding column.
///
/// # Arguments
/// * `df` - A DataFrame with numeric columns containing potential null values
///
/// # Returns
/// * `Result<DataFrame>` - DataFrame with missing values imputed by column mean
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let df = df! {
///     "A" => &[1.0, 2.0, f64::NAN, 4.0],
///     "B" => &[10.0, f64::NAN, 30.0, 40.0],
/// }.unwrap();
///
/// let result = impute_with_column_mean(df).unwrap();
/// println!("{}", result);
/// ```
fn impute_with_column_mean(df: DataFrame) -> PolarsResult<DataFrame> {
    let mut result = df.clone();

    for column_name in result.get_column_names() {
        let column = result.column(column_name)?;

        // Calculate the mean of the column
        let mean = match column.dtype() {
            DataType::Float32 => {
                let values = column.f32()?;
                let sum: f32 = values.into_iter().filter_map(|v| v).sum();
                let count = values.into_iter().filter(|v| v.is_some()).count();
                if count > 0 { (sum / count as f32) as f64 } else { 0.0 }
            }
            DataType::Float64 => {
                let values = column.f64()?;
                let sum: f64 = values.into_iter().filter_map(|v| v).sum();
                let count = values.into_iter().filter(|v| v.is_some()).count();
                if count > 0 { sum / count as f64 } else { 0.0 }
            }
            DataType::Int32 => {
                let values = column.i32()?;
                let sum: i32 = values.into_iter().filter_map(|v| v).sum();
                let count = values.into_iter().filter(|v| v.is_some()).count();
                if count > 0 { (sum as f64) / (count as f64) } else { 0.0 }
            }
            DataType::Int64 => {
                let values = column.i64()?;
                let sum: i64 = values.into_iter().filter_map(|v| v).sum();
                let count = values.into_iter().filter(|v| v.is_some()).count();
                if count > 0 { (sum as f64) / (count as f64) } else { 0.0 }
            }
            _ => continue, // Skip non-numeric columns
        };

        // Fill nulls with the mean
        let filled = column.fill_null(FillNullStrategy::Mean)?;
        result.replace(column_name, filled)?;
    }

    Ok(result)
}

fn main() -> PolarsResult<()> {
    // Create a sample DataFrame with missing values
    let df = df! {
        "score_a" => &[Some(85.5), None, Some(92.0), Some(78.5)],
        "score_b" => &[Some(90.0), Some(88.5), None, Some(95.0)],
        "score_c" => &[None, Some(76.0), Some(82.0), Some(79.5)],
    }?;

    println!("Original DataFrame:");
    println!("{}", df);
    println!("\n");

    let result = impute_with_column_mean(df)?;

    println!("After imputation with column means:");
    println!("{}", result);

    Ok(())
}
