Code:

```rust
use std::collections::HashMap;
use std::hash::Hash;

/// A small, self-contained helper module (named like a 2025 helper).
pub mod orderer_2025 {
    use super::{Hash, HashMap};

    /// Reorder items in `lst0` according to the order of keys in `lst1`.
    ///
    /// - lst0: input items (owned Vec so we can reorder/move them).
    /// - lst1: slice of keys that defines desired ordering.
    /// - key: function to extract a key from each item of lst0.
    ///
    /// Behavior:
    /// - All items whose extracted key appears in `lst1` are grouped and emitted
    ///   in the same order as keys in `lst1`. For a given key, the relative
    ///   order of items from the original `lst0` is preserved (stable).
    /// - Items whose key is not present in `lst1` are appended at the end,
    ///   preserving their original relative order.
    ///
    /// Complexity: O(n + m) time and O(m) extra space (m = lst1.len()).
    pub fn reorder_by_order<T, K, F>(lst0: Vec<T>, lst1: &[K], key: F) -> Vec<T>
    where
        K: Eq + Hash + Clone,
        F: Fn(&T) -> K,
    {
        // Map each key in lst1 to its index (order position)
        let mut pos: HashMap<K, usize> = HashMap::with_capacity(lst1.len());
        for (i, k) in lst1.iter().enumerate() {
            // last occurrence in lst1 wins if duplicates exist
            pos.insert(k.clone(), i);
        }

        // Prepare buckets for each position in lst1, plus an "unmatched" bucket
        let mut buckets: Vec<Vec<T>> = vec![Vec::new(); lst1.len()];
        let mut unmatched: Vec<T> = Vec::new();

        for item in lst0 {
            let k = key(&item);
            if let Some(&idx) = pos.get(&k) {
                buckets[idx].push(item);
            } else {
                unmatched.push(item);
            }
        }

        // Flatten buckets in order, then append unmatched
        let mut result: Vec<T> = Vec::new();
        // Reserve approximate space to avoid reallocs (optional)
        let total = buckets.iter().map(|b| b.len()).sum::<usize>() + unmatched.len();
        result.reserve(total);

        for b in buckets {
            result.extend(b);
        }
        result.extend(unmatched);

        result
    }
}

