/// Reorder a sequence of tuples based on a desired ordering sequence.
/// 
/// # Arguments
/// * `lst0` - A slice of tuples to be reordered
/// * `lst1` - A slice defining the desired ordering (elements that should appear first)
/// 
/// # Returns
/// A new Vec containing the tuples from lst0 reordered according to lst1.
/// Elements not present in lst1 are appended at the end in their original relative order.
/// 
/// # Type Parameters
/// * `T` - The tuple type, must implement Clone, Hash, and Eq
/// 
/// # Example
/// ```
/// let lst0 = vec![(3, "c"), (1, "a"), (2, "b"), (4, "d")];
/// let lst1 = vec![(1, "a"), (2, "b"), (3, "c")];
/// let result = reorder_by(&lst0, &lst1);
/// assert_eq!(result, vec![(1, "a"), (2, "b"), (3, "c"), (4, "d")]);
/// ```
pub fn reorder_by<T: Clone + Hash + Eq>(lst0: &[T], lst1: &[T]) -> Vec<T> {
    // Create an IndexSet from lst1 to preserve order and enable O(1) lookups
    let order_set: IndexSet<T> = lst1.iter().cloned().collect();

    // Partition lst0 into elements that are in lst1 and those that aren't
    let mut ordered: Vec<T> = Vec::with_capacity(lst0.len());
    let mut remaining: Vec<T> = Vec::new();

    for item in lst0 {
        if order_set.contains(item) {
            ordered.push(item.clone());
        } else {
            remaining.push(item.clone());
        }
    }

    // Sort the ordered elements according to their position in lst1
    ordered.sort_by_key(|item| order_set.get_index_of(item).unwrap());

    // Append remaining elements at the end
    ordered.extend(remaining);

    ordered
}

