/// - `feature_names0`: slice of feature names (index i corresponds to feature i).
///
/// Returns a Vec<String> where every element is a single IF ... THEN ... rule.
///
/// Example rule output:
/// "IF (petal_length <= 2.45) AND (sepal_width > 3.1) THEN predict = setosa (samples=23)"
pub fn extract_decision_rules(tree0: &DecisionTree, feature_names0: &[&str]) -> Vec<String> {
    // Helper to get a feature name or a fallback string for unknown indices.
    let get_feat = |i: usize| {
        feature_names0.get(i).map(|s| s.to_string()).unwrap_or_else(|| format!("feature_{}", i))
    };

    // Recursive traversal. Assumes nodes are stored in tree0.nodes and children are indices.
    fn recurse(
        nodes: &[Node],
        node_idx: usize,
        path: &mut Vec<String>,
        get_feat: &dyn Fn(usize) -> String,
        out: &mut Vec<String>,
    ) {
        let node = &nodes[node_idx];

        if node.is_leaf {
            // Build prediction string: prefer a scalar 'value', else use class distribution if present.
            let pred_str = match (&node.value, &node.class_distribution) {
                (Some(v), _) => format!("predict = {}", v),
                (None, Some(dist)) if !dist.is_empty() => {
                    // argmax class
                    let (best_i, best_p) = dist
                        .iter()
                        .enumerate()
                        .max_by(|a, b| a.1.partial_cmp(b.1).unwrap_or(std::cmp::Ordering::Equal))
                        .map(|(i, p)| (i, *p))
                        .unwrap_or((0, 0.0));
                    format!("predict = class_{} (p={:.3})", best_i, best_p)
                }
                _ => "predict = <leaf>".to_string(),
            };

            // Add sample info if available.
            let sample_info = match node.samples {
                Some(s) => format!(" (samples={})", s),
                None => String::new(),
            };

            let conds = if path.is_empty() {
                "True".to_string()
            } else {
                path.join(" AND ")
            };
            out.push(format!("IF {} THEN {}{}", conds, pred_str, sample_info));
            return;
        }

        // Non-leaf: assume feature_index, threshold, left_child, right_child exist.
        let feat_idx = node.feature_index.unwrap_or(usize::MAX);
        let feat_name = if feat_idx != usize::MAX { get_feat(feat_idx) } else { "<unknown_feature>".to_string() };
        let thresh = node.threshold.unwrap_or(0.0);

        // Left branch: feature <= threshold (conventional)
        if let Some(left_idx) = node.left_child {
            path.push(format!("({} <= {})", feat_name, format_threshold(thresh)));
            recurse(nodes, left_idx, path, get_feat, out);
            path.pop();
        }

