    // the caller can adapt the function accordingly.
    let mut rules = Vec::new();
    if tree0.nodes.is_empty() {
        return rules;
    }
    let mut path = Vec::new();
    recurse(&tree0.nodes, 0, &mut path, &get_feat, &mut rules);
    rules
