/// Extract decision rules from a trained decision tree
///
/// # Arguments
/// * `tree0` - The root node of the trained decision tree
/// * `feature_names0` - List of feature names corresponding to feature indices
///
/// # Returns
/// A vector of DecisionRule structs, each containing:
/// - conditions: List of human-readable conditions
/// - prediction: The predicted value for this path
/// - rule_string: A complete human-readable rule string
pub fn extract_decision_rules(
    tree0: &TreeNode,
    feature_names0: &[String],
) -> Vec<DecisionRule> {
    let mut rules = Vec::new();
    let mut current_conditions: Vec<String> = Vec::new();

    traverse_tree(tree0, feature_names0, &mut current_conditions, &mut rules);

    rules
}

/// Recursively traverse the tree to extract all decision paths
fn traverse_tree(
    node: &TreeNode,
    feature_names: &[String],
    current_conditions: &mut Vec<String>,
    rules: &mut Vec<DecisionRule>,
) {
    match node {
        TreeNode::Leaf { value, sample_count: _ } => {
            // Create the rule string from current conditions
            let rule_string = if current_conditions.is_empty() {
                format!("PREDICT: {:.4}", value)
            } else {
                format!(
                    "IF {} THEN PREDICT: {:.4}",
                    current_conditions.join(" AND "),
                    value
                )
            };

            rules.push(DecisionRule {
                conditions: current_conditions.clone(),
                prediction: *value,
                rule_string,
            });
        }
        TreeNode::Split {
            feature_index,
            threshold,
            left,
            right,
            sample_count: _,
        } => {
            // Get feature name, with fallback for out-of-range indices
            let feature_name = feature_names
                .get(*feature_index)
                .cloned()
                .unwrap_or_else(|| format!("feature_{}", feature_index));

            // Traverse left branch (feature <= threshold)
            let left_condition = format!("{} <= {:.4}", feature_name, threshold);
            current_conditions.push(left_condition);
            traverse_tree(left, feature_names, current_conditions, rules);
            current_conditions.pop();

            // Traverse right branch (feature > threshold)
            let right_condition = format!("{} > {:.4}", feature_name, threshold);
            current_conditions.push(right_condition);
            traverse_tree(right, feature_names, current_conditions, rules);
            current_conditions.pop();
        }
    }
}

