/// # Arguments
/// * `lst0` - A mutable reference to a vector of HashMap-like items
/// * `var0` - The key to check in each mapping
/// * `var1` - The expected value for the specified key
///
/// # Type Parameters
/// * `K` - The key type (must be hashable and comparable)
/// * `V` - The value type (must be comparable)
/// * `S` - The state type for the hash builder
pub fn reorder_by_key_value<K, V, S>(
    lst0: &mut Vec<std::collections::HashMap<K, V, S>>,
    var0: &K,
    var1: &V,
) where
    K: std::hash::Hash + Eq,
    V: PartialEq,
    S: std::hash::BuildHasher,
{
    // Use partition to separate matching and non-matching elements
    // Elements where key value equals var1 stay at the front
    // Elements where key value doesn't equal var1 go to the end
    let split_index = lst0.iter().position(|item| {
        item.get(var0).map_or(true, |val| val != var1)
    });

    if let Some(idx) = split_index {
        // Rotate the list so non-matching elements move to the end
        lst0.rotate_left(idx);
    }
}

// Alternative implementation using stable partition (preserves relative order)
pub fn reorder_by_key_value_stable<K, V, S>(
    lst0: &mut Vec<std::collections::HashMap<K, V, S>>,
    var0: &K,
    var1: &V,
) where
    K: std::hash::Hash + Eq,
    V: PartialEq,
    S: std::hash::BuildHasher,
{
    // Use stable partition to maintain relative order within each group
    let split_point = lst0.iter().position(|item| {
        item.get(var0).map_or(true, |val| val != var1)
    });

    if let Some(idx) = split_point {
        // Collect non-matching elements and remove them
        let non_matching: Vec<_> = lst0.drain(idx..).collect();
        // Append them to the end
        lst0.extend(non_matching);
    }
