/// Splits and expands a column in a DataFrame, then reorders columns based on a specification.
///
/// # Arguments
/// * `df` - Input DataFrame containing the data
/// * `split_column` - Name of the column to split (default: "str0")
/// * `delimiter` - Delimiter to use for splitting (default: ",")
/// * `order_spec` - Column order specification (e.g., "new_col1,str0,new_col2")
///
/// # Returns
/// Result<DataFrame, PolarsError> - Expanded and reordered DataFrame
pub fn split_and_reorder(
    df: DataFrame,
    split_column: &str,
    delimiter: &str,
    order_spec: &str,
) -> Result<DataFrame, PolarsError> {
    // Split the specified column
    let split_expr = df.column(split_column)?
        .str()?
        .split(delimiter, -1)?; // -1 means split on every occurrence

    // Create new columns from the split
    let mut new_columns = Vec::new();
    let split_series = split_expr.into_series();

    for (i, col_name) in order_spec.split(',').enumerate() {
        let new_col_name = format!("{}_{}", split_column, i);

        // Create a new column with the i-th split value
        let new_col = split_series
            .apply(|s| s.get(i).unwrap_or(""), &[Utf8Type::default()])
            .rename(&new_col_name)?;

        new_columns.push(new_col);
    }

    // Reorder all columns according to the specification
    let mut columns = df.columns().to_vec();
    let mut new_order = Vec::new();

    // First add the new split columns in order
    for col_name in order_spec.split(',') {
        if let Some(col) = columns.iter().find(|c| c.name() == col_name) {
            new_order.push(col.clone());
        }
