    // Then add the remaining original columns
    for col in columns {
        if !order_spec.split(',').any(|s| s == col.name()) {
            new_order.push(col);
        }
    }

    // Create new DataFrame with reordered columns
    let reordered_df = DataFrame::new(new_order)?;

    Ok(reordered_df)
}

