/// Split and expand the entries in the column named `str0` using delimiter `var1`,
/// then rearrange all columns to match the order specified by `str1`.
///
/// - `table`: input table (tabularx2025::Table)
/// - `str0`: column name to split & expand (explode)
/// - `var1`: delimiter character used to split the cell (e.g. ',')
/// - `str1`: slice of column names indicating the desired final column order (must contain exactly the same columns)
///
/// Returns a new Table with exploded rows and columns reordered.
///
/// Behavior:
/// - For each input row, the cell at `str0` is split on `var1`. Leading/trailing whitespace around each token is trimmed.
/// - If the cell is empty, a single row with an empty string is produced.
/// - Other columns are duplicated for each exploded value.
/// - Final columns are reordered to exactly match `str1`; an error is returned if `str1` doesn't match the set of columns.
fn split_expand_and_reorder(
    table: &tabularx2025::Table,
    str0: &str,
    var1: char,
    str1: &[&str],
) -> Result<tabularx2025::Table, String> {
    // 1) validate that str0 exists
    let idx = table
        .col_index(str0)
        .ok_or_else(|| format!("Column '{}' not found in table", str0))?;

    // 2) explode rows
    let mut expanded_rows: Vec<Vec<String>> = Vec::new();
    for row in &table.rows {
        let cell = &row[idx];
        // split, trim each token
        let tokens: Vec<String> = if cell.is_empty() {
            vec![String::new()]
        } else {
            cell.split(var1)
                .map(|s| s.trim().to_string())
                .collect()
        };

        // produce one output row per token
        for tok in tokens {
            let mut new_row = row.clone();
            new_row[idx] = tok;
            expanded_rows.push(new_row);
        }
    }

    // Build intermediate table with same columns
    let intermediate = tabularx2025::Table {
        columns: table.columns.clone(),
        rows: expanded_rows,
    };

    // 3) reorder columns to match str1 exactly
    intermediate.reorder_columns(str1)
}

