/// Concatenates new columns onto a base table while preserving column order
///
/// # Arguments
/// * `base_df` - The base DataFrame containing existing columns
/// * `new_columns` - A map of new columns to add (column name -> Series)
/// * `priority_order` - A vector specifying the desired column order
///
/// # Returns
/// A new DataFrame with columns in the specified priority order, with other columns
/// maintaining their original relative positions after the priority columns
pub fn concatenate_with_order(
    base_df: &DataFrame,
    new_columns: HashMap<String, Series>,
    priority_order: Vec<String>,
) -> Result<DataFrame, PolarsError> {
    // Create a new DataFrame with all existing columns
    let mut result_df = base_df.clone();

    // Add new columns to the result
    for (name, series) in new_columns {
        result_df = result_df.with_column(series)?;
    }

    // Get all column names from the result
    let all_columns: Vec<String> = result_df
        .columns()
        .iter()
        .map(|col| col.name().to_string())
        .collect();

    // Build the new column order:
    // 1. Priority columns (in specified order)
    // 2. All other columns (in their original relative order)
    let mut new_order = Vec::with_capacity(all_columns.len());
    let mut remaining_columns = all_columns.clone();

    // Add priority columns first
