            new_order.push(col_name);
            remaining_columns.retain(|x| x != &col_name);
        }
    }

    // Add remaining columns in their original order
    new_order.extend(remaining_columns);

    // Reorder the DataFrame
    let reordered_df = result_df.reorder_columns(&new_order)?;

    Ok(reordered_df)
