```rust
use polars::prelude::*;

/// Merge `base` with `new_cols` (new columns to add or use to overwrite existing columns),
/// then reorder columns so that `priority` columns appear in exactly that sequence
/// (as a contiguous block at the front), while all other columns retain their original
/// relative order (base columns keep their base relative order; newly appended columns
/// keep the order they had in `new_cols`).
///
/// Returns a new DataFrame or a Polars error.
///
/// Example usage:
/// let base = DataFrame::new(vec![
///     Series::new("id", &[1, 2]),
///     Series::new("a", &[10, 20]),
///     Series::new("b", &[100, 200]),
/// ])?;
/// let new_cols = DataFrame::new(vec![
///     Series::new("b", &[111, 222]), // will overwrite base.b
///     Series::new("c", &[7, 8]),     // new column appended
/// ])?;
/// let priority = vec!["c", "id"]; // want "c" then "id" first
/// let out = merge_with_priority(&base, &new_cols, &priority)?;
/// // `out` will have columns: ["c", "id", "a", "b"]
///
pub fn merge_with_priority(
    base: &DataFrame,
    new_cols: &DataFrame,
    priority: &[&str],
) -> PolarsResult<DataFrame> {
    // Start with a clone of base so we preserve base column positions.
    let mut merged = base.clone();

    // Apply new_cols: overwrite existing columns (preserving position) or append new ones.
    for s in new_cols.get_columns() {
        let name = s.name();
        if merged.get_column_names().iter().any(|n| n == name) {
            // replace will overwrite values but keep the column in its current position
            merged.replace(name, s.clone())?;
        } else {
            // append new column at the end (preserve new_cols' order)
            merged.with_column(s.clone())?;
        }
    }

    // Build final order:
    // 1) Priority columns (in the exact order), but only those present in merged.
    // 2) All remaining columns in the order they appear in the merged DataFrame now.
    let merged_names = merged.get_column_names();
    let mut in_priority = std::collections::HashSet::new();
    let mut final_order: Vec<String> = Vec::with_capacity(merged_names.len());

    // Add priority columns first (only those present in merged)
    for &p in priority {
        if merged_names.iter().any(|n| n == p) {
            final_order.push(p.to_string());
            in_priority.insert(p.to_string());
        }
    }

    // Then add the other columns in their current relative order
    for col in merged_names.iter() {
        if !in_priority.contains(col) {
            final_order.push(col.clone());
        }
    }

    // Reassemble DataFrame in final_order
    let cols: Vec<Series> = final_order
        .iter()
        .map(|name| merged.column(name).unwrap().clone())
        .collect();

    DataFrame::new(cols)
}

