/// # Ok::<(), PolarsError>(())
/// ```
pub fn merge_with_column_order(
    base_df: &DataFrame,
    new_df: &DataFrame,
    priority_columns: &[&str],
) -> Result<DataFrame, PolarsError> {
    // Step 1: Merge the DataFrames horizontally
    let mut merged_df = base_df.hstack(new_df.get_columns())?;

    // Step 2: Get all column names from the merged DataFrame
    let all_columns: Vec<&str> = merged_df.get_column_names()
        .iter()
        .map(|s| s.as_str())
        .collect();

    // Step 3: Create a set of priority columns for quick lookup
    let priority_set: std::collections::HashSet<&str> = 
        priority_columns.iter().cloned().collect();

    // Step 4: Build the new column order
    let mut new_order: Vec<&str> = Vec::with_capacity(all_columns.len());
    let mut seen_priority: std::collections::HashSet<&str> = std::collections::HashSet::new();

    // First, add priority columns in the specified order
    for col in priority_columns {
        if all_columns.contains(col) && seen_priority.insert(col) {
            new_order.push(col);
        }
    }

    // Then, add remaining columns in their original relative order
    for col in &all_columns {
        if !priority_set.contains(col) {
            new_order.push(col);
        }
    }

    // Step 5: Reorder the columns
    let reordered_df = merged_df.select(new_order)?;

    Ok(reordered_df)
}

