# Rust Function for Ordered Column Concatenation

```rust
use polars::prelude::*;

/// Concatenates new columns onto a base table while preserving a specified column order.
///
/// # Arguments
/// * `base_df` - The base DataFrame to which columns will be added
/// * `new_columns` - A DataFrame containing new columns to concatenate
/// * `priority_order` - A list of column names defining the desired priority order
///
/// # Returns
/// A DataFrame with columns ordered according to priority_order, followed by remaining columns
/// in their original relative positions
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let base = df! {
///     "A" => &[1, 2, 3],
///     "B" => &[4, 5, 6],
/// }?;
///
/// let new = df! {
///     "C" => &[7, 8, 9],
/// }?;
///
/// let priority = vec!["C", "A", "B"];
/// let result = reorder_columns_on_concat(&base, &new, &priority)?;
/// // Result columns: C, A, B
/// ```
fn reorder_columns_on_concat(
    base_df: &DataFrame,
    new_columns: &DataFrame,
    priority_order: &[&str],
) -> PolarsResult<DataFrame> {
    // Merge the dataframes horizontally
    let merged = base_df.hstack(new_columns.get_columns())?;

    // Get all column names from merged dataframe
    let all_columns: Vec<&str> = merged.get_column_names();

    // Build the final column order
    let mut final_order = Vec::new();
    let mut used_columns = std::collections::HashSet::new();

    // First, add columns in priority order (if they exist)
    for col_name in priority_order {
        if all_columns.contains(col_name) {
            final_order.push(*col_name);
            used_columns.insert(*col_name);
        }
    }

    // Then, add remaining columns in their original order
    for col_name in all_columns {
        if !used_columns.contains(col_name) {
            final_order.push(col_name);
        }
    }

    // Select columns in the final order
    merged.select(final_order)
}

// ============================================================================
// Example usage and tests
// ============================================================================

fn main() -> PolarsResult<()> {
    // Create a base table
    let base_df = DataFrame::new(vec![
        Series::new("ID".into(), &[1, 2, 3, 4]),
        Series::new("Name".into(), &["Alice", "Bob", "Charlie", "Diana"]),
        Series::new("Salary".into(), &[50000, 60000, 75000, 80000]),
