    println!("{}", base_df);
    println!();

    // Create new columns to add
    let new_columns_df = DataFrame::new(vec![
        Series::new("Department".into(), &["IT", "HR", "Finance", "IT"]),
        Series::new("Bonus".into(), &[5000, 3000, 8000, 6000]),
    ])?;

    println!("New Columns:");
    println!("{}", new_columns_df);
    println!();

    // Define priority order: we want Department and Bonus to appear before Name and Salary
    let priority = vec!["Department", "ID", "Name", "Bonus", "Salary"];

    // Perform the ordered concatenation
    let result = reorder_columns_on_concat(&base_df, &new_columns_df, &priority)?;

    println!("Result (with priority order: {:?}):", priority);
    println!("{}", result);
    println!();

    // Verify column order
    let column_names: Vec<&str> = result.get_column_names();
    println!("Final column order: {:?}", column_names);
    assert_eq!(
        column_names,
        vec!["Department", "ID", "Name", "Bonus", "Salary"]
    );

    // Test with partial priority order
