    let result2 = reorder_columns_on_concat(&base_df, &new_columns_df, &partial_priority)?;
    println!("\nResult (with partial priority: {:?}):", partial_priority);
    println!("{}", result2);

    let column_names2: Vec<&str> = result2.get_column_names();
    println!("Column order: {:?}", column_names2);
    assert_eq!(
