use polars::prelude::*;
use std::error::Error;

/// Groups a DataFrame by a column and creates a hierarchical index from the grouping results.
///
/// # Arguments
/// * `df` - The input DataFrame to group
/// * `group_col` - The column name to group by
///
/// # Returns
/// A Result containing a DataFrame with a hierarchical index where:
/// - Level 0 is the original index
/// - Level 1 is the grouping values
///
/// # Example
/// ```
/// use polars::prelude::*;
///
/// let df = df!(
///     "df0" => &[
///         ("var0", &["A", "A", "B", "B", "C"]),
///         ("value", &[1, 2, 3, 4, 5])
///     ]
/// ).unwrap();
///
/// let result = group_with_hierarchical_index(df, "var0").unwrap();
/// ```
pub fn group_with_hierarchical_index(df: DataFrame, group_col: &str) -> Result<DataFrame, Box<dyn Error>> {
    // Create a grouped DataFrame
    let grouped = df.lazy()
        .group_by([group_col])
        .collect()?;

    // Get the group key values
    let group_key = grouped.column(group_col)?.to_owned();

    // Create a new DataFrame with hierarchical index
    let mut new_df = df.clone();

    // Add the group key as a new column (temporarily)
    new_df = new_df.with_column(group_key)?;

    // Create hierarchical index
    let mut index = MultiIndex::new(vec![
        // Level 0: original index
        Index::default(new_df.height()),
        // Level 1: group values
        Index::from(group_key)
    ])?;

    // Set the hierarchical index
    new_df.set_index(Some(&index))?;

    // Remove the temporary group key column
    new_df = new_df.drop(group_col)?;

    Ok(new_df)
}

