/// println!("{:?}", result);
/// ```
fn group_to_hierarchical_index(df0: DataFrame, var0: &str) -> Result<DataFrame> {
    // Validate that the grouping column exists
    if !df0.get_column_names().contains(&var0) {
        return Err(PolarsError::ComputeError(
            format!("Column '{}' not found in DataFrame", var0).into(),
        ));
    }

    // Group by the specified column
    let grouped = df0.group_by([var0])?;

    // Get the groups and their indices
    let groups = grouped.get_groups();

    // Create a vector to store the hierarchical index data
    let mut hierarchical_data: Vec<(String, Vec<AnyValue>)> = Vec::new();

    // Process each group
    for group in groups.iter() {
        let group_key = group.0.to_string();
        let group_indices = &group.1;

        // Get the rows for this group
        let group_df = df0.take(group_indices)?;

        // Collect all values for this group
        let mut group_values: Vec<AnyValue> = Vec::new();

        // Add the group key as the first level of the hierarchical index
        group_values.push(AnyValue::String(group_key.as_str()));

        // Add all column values for each row in the group
        for col_name in df0.get_column_names() {
            if col_name != var0 {
                let column = group_df.column(col_name)?;
                for i in 0..column.len() {
                    group_values.push(column.get(i)?);
                }
            }
        }

        hierarchical_data.push((group_key, group_values));
    }

    // Build the hierarchical index DataFrame
    let mut index_columns: Vec<Series> = Vec::new();
    let mut data_columns: Vec<Series> = Vec::new();

    // Create the first level of the index (group names)
    let group_names: Vec<String> = hierarchical_data.iter()
        .map(|(key, _)| key.clone())
        .collect();

    // Create a series for the group level
    let group_series = Series::new("group_level", &group_names);
    index_columns.push(group_series);

    // Create the second level of the index (row numbers within each group)
    let mut row_numbers: Vec<i32> = Vec::new();
    for (_, values) in &hierarchical_data {
        // Count how many rows are in this group (excluding the group key)
        let num_rows = (values.len() - 1) / (df0.width() - 1);
        for i in 0..num_rows {
            row_numbers.push(i as i32);
        }
    }

    let row_series = Series::new("row_level", &row_numbers);
    index_columns.push(row_series);

    // Create the data columns
    let other_columns: Vec<&str> = df0.get_column_names().iter()
        .filter(|&&name| name != var0)
        .copied()
        .collect();

    for col_name in &other_columns {
        let mut col_data: Vec<AnyValue> = Vec::new();

        for (_, values) in &hierarchical_data {
            // Find the position of this column's data in the values
            let col_index = other_columns.iter().position(|&c| c == *col_name).unwrap();
            let num_rows = (values.len() - 1) / other_columns.len();

            for row in 0..num_rows {
                let value_index = 1 + (row * other_columns.len()) + col_index;
                col_data.push(values[value_index].clone());
            }
        }

        let series = Series::new(col_name, &col_data);
        data_columns.push(series);
    }

    // Combine index and data columns into a single DataFrame
    let mut result_df = DataFrame::new(index_columns)?;
    for col in data_columns {
        result_df.with_column(col)?;
    }

    // Set the hierarchical index
    result_df = result_df.set_index(["group_level", "row_level"])?;

    Ok(result_df)
}

