/// assert_eq!(counts.get(&1).unwrap(), &2);
/// assert_eq!(counts.get(&2).unwrap(), &2);
/// assert_eq!(counts.get(&3).unwrap(), &1);
/// ```
pub fn count_distinct_per_group(df: &DataFrame, group_col: &str, value_col: &str) -> Result<HashMap<Series, usize>, PolarsError> {
    // Group by the grouping column
    let grouped = df.lazy()
        .group_by([group_col])
        .agg([col(value_col).n_unique()]);

    // Collect the result into a DataFrame
    let result_df = grouped.collect()?;

    // Convert to HashMap
    let mut result = HashMap::new();

    // Get the group column and value counts
    let group_series = result_df.column(group_col)?;
    let count_series = result_df.column(value_col)?;

    // Verify we have the expected columns
    if group_series.name() != group_col || count_series.name() != value_col {
        return Err(PolarsError::ComputeError(
            "Unexpected column names in result".to_string()
        ));
    }

    // Convert to HashMap
    for (i, (group_val, count_val)) in group_series.iter().zip(count_series.iter()) {
        let count = count_val.i64()?;
        result.insert(group_val.clone(), count as usize);
    }

    Ok(result)
}

