/// sort_records_by_key_order(&mut records, "name", &order).unwrap();
///
/// assert_eq!(records[0].get("name").unwrap(), "Alice");
/// assert_eq!(records[1].get("name").unwrap(), "Bob");
/// assert_eq!(records[2].get("name").unwrap(), "Charlie");
/// ```
pub fn sort_records_by_key_order(
    records: &mut [HashMap<String, String>],
    sort_key: &str,
    order_sequence: &[&str],
) -> Result<(), String> {
    // Build a mapping from each value to its position in the order sequence
    let position_map: IndexMap<&str, usize> = order_sequence
        .iter()
        .enumerate()
        .map(|(idx, val)| (*val, idx))
        .collect();

    // Validate that all records have the sort key
    for record in records.iter() {
        if !record.contains_key(sort_key) {
            return Err(format!("Record missing required key: '{}'", sort_key));
        }
    }

    // Sort records using stable sort to preserve relative order of equal elements
    records.sort_by(|a, b| {
        let a_val = a.get(sort_key).unwrap();
        let b_val = b.get(sort_key).unwrap();

        // Get positions, defaulting to usize::MAX for values not in the order sequence
        let a_pos = position_map.get(a_val.as_str()).copied().unwrap_or(usize::MAX);
        let b_pos = position_map.get(b_val.as_str()).copied().unwrap_or(usize::MAX);

        a_pos.cmp(&b_pos)
    });

    Ok(())
}

