    let mut list_indices = vec![0; lists.len()];

    for list_index in sequence {
        if list_indices[list_index] < lists[list_index].len() {
            result.push(lists[list_index][list_indices[list_index]]);
            list_indices[list_index] += 1;
        }
    }

    result
}

fn main() {
