use std::collections::VecDeque;
use std::error::Error;
use std::fmt;

/// Simulated new crate "pdq_merge_2025".
/// In real usage you could replace this module with an actual 2025+ crate of the same API.
mod pdq_merge_2025 {
    use super::*;

    /// Errors that can happen while merging lists by a sequence.
    #[derive(Debug, PartialEq, Eq)]
    pub enum MergeError {
        /// Requested source index is not one of the provided lists.
        SourceIndexOutOfRange { requested: usize, num_lists: usize },
        /// The requested source list had no remaining elements when requested.
        SourceExhausted { index: usize },
        /// The provided sequence length does not match the sum of all elements (optional semantic).
        /// (This variant is not used by the one-shot function below, but provided for future use.)
        SequenceLengthMismatch { sequence_len: usize, total_elements: usize },
    }

    impl fmt::Display for MergeError {
        fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
            match self {
                MergeError::SourceIndexOutOfRange { requested, num_lists } => {
                    write!(f, "requested source index {} but number of lists is {}", requested, num_lists)
                }
                MergeError::SourceExhausted { index } => {
                    write!(f, "source list {} is exhausted", index)
                }
                MergeError::SequenceLengthMismatch { sequence_len, total_elements } => {
                    write!(f, "sequence length {} does not match total elements {}", sequence_len, total_elements)
                }
            }
        }
    }

    impl Error for MergeError {}

    /// Merge the provided lists according to the given sequence of indices.
    ///
    /// - `lists`: owned vector of input lists; each Vec<T> will be consumed.
    /// - `sequence`: a slice of indices; each value selects the input list to draw the next element from.
    ///
    /// Returns a Vec<T> with elements taken in the order specified by `sequence`, or a MergeError
    /// if a sequence element references an invalid list or a list without remaining elements.
    pub fn merge_by_sequence<T>(lists: Vec<Vec<T>>, sequence: &[usize]) -> Result<Vec<T>, MergeError> {
        // Convert each list into a VecDeque so we can pop_front in O(1).
        let mut deques: Vec<VecDeque<T>> = lists.into_iter()
            .map(VecDeque::from)
            .collect();

        let num_lists = deques.len();
        let mut out: Vec<T> = Vec::with_capacity(sequence.len());

        for (step, &src_idx) in sequence.iter().enumerate() {
            if src_idx >= num_lists {
                return Err(MergeError::SourceIndexOutOfRange {
                    requested: src_idx,
                    num_lists,
                });
            }

            let dq = &mut deques[src_idx];
            match dq.pop_front() {
                Some(v) => out.push(v),
                None => {
                    return Err(MergeError::SourceExhausted { index: src_idx });
                }
            }
        }

        Ok(out)
    }

    // Re-export the error type for users of the module.
    pub use MergeError;
}

