///     vec![10, 20],
///     vec![100, 200, 300],
/// ];
/// let sequence = vec![0, 1, 0, 2, 1, 0, 2];
/// let result = combine_lists_by_sequence(lists, sequence);
/// assert_eq!(result, vec![1, 10, 2, 100, 20, 3, 200]);
/// ```
fn combine_lists_by_sequence<T: Clone>(
    lists: Vec<Vec<T>>,
    sequence: Vec<usize>,
) -> Vec<T> {
    // Create mutable iterators for each list
    let mut iterators: Vec<_> = lists.into_iter().map(|list| list.into_iter()).collect();

    // Follow the sequence and collect elements
    sequence
        .into_iter()
        .map(|index| {
            iterators[index]
                .next()
                .unwrap_or_else(|| panic!("List {} exhausted before sequence completed", index))
        })
        .collect()
}

