    for (step, &index) in sequence.iter().enumerate() {
        if index >= iterators.len() {
            return Err(format!("Step {}: sequence index {} out of bounds", step, index));
        }

        match iterators[index].next() {
            Some(element) => result.push(element),
            None => return Err(format!("Step {}: list {} exhausted", step, index)),
