/// Solves a system of two coupled nonlinear equations using Newton-Raphson method.
///
/// # Arguments
/// * `f` - A function that takes a 2D vector and returns a 2D vector of residuals.
/// * `x0` - Initial guess for the solution (2D vector).
/// * `tol` - Tolerance for convergence (default: 1e-6).
/// * `max_iter` - Maximum iterations (default: 100).
///
/// # Returns
/// A tuple of `(solution, iterations)` where `solution` is the approximate root.
///
/// # Example
/// ```rust
/// use ndarray::array;
///
/// fn coupled_equations(x: &Array1<f64>) -> Array1<f64> {
///     let [x1, x2] = x;
///     array![x1 * x1 + x2 - 1.0, x1 + x2 * x2 - 1.0]
/// }
///
/// fn main() {
///     let x0 = array![1.0, 1.0];
///     let (solution, _) = newton_coupled(&coupled_equations, x0, 1e-6, 100);
///     println!("Solution: {:?}", solution);
/// }
/// ```
pub fn newton_coupled<F>(
    f: F,
    x0: Array1<f64>,
    tol: f64,
    max_iter: usize,
) -> (Array1<f64>, usize)
where
    F: Fn(&Array1<f64>) -> Array1<f64>,
{
    let mut x = x0.clone();
    let mut iter = 0;

    while iter < max_iter {
        let f_x = f(&x);
        let norm_f = f_x.norm();

        if norm_f < tol {
            return (x, iter);
        }

        // Compute Jacobian (finite differences for simplicity)
        let h = 1e-5;
        let mut jacobian = Array2::zeros((2, 2));
        for i in 0..2 {
            for j in 0..2 {
                let mut x_perturbed = x.clone();
                x_perturbed[j] += h;
                let f_perturbed = f(&x_perturbed);
                jacobian[[i, j]] = (f_perturbed[i] - f_x[i]) / h;
            }
        }

        // Newton update: x = x - J⁻¹ f(x)
        let jacobian_inv = jacobian.try_inverse().unwrap_or_else(|_| panic!("Jacobian singular"));
        let delta = -jacobian_inv.dot(&f_x);
        x += delta;

        iter += 1;
    }

    panic!("Newton method did not converge within {} iterations", max_iter);
}

