use nalgebra::{Vector2, Matrix2};

/// Solves a system of two coupled nonlinear equations using Newton-Raphson method.
///
/// # Arguments
/// * `f` - Function that computes the residual vector [f1(x, y), f2(x, y)]
/// * `jacobian` - Function that computes the 2x2 Jacobian matrix
/// * `initial_guess` - Initial estimate [x0, y0]
/// * `tolerance` - Convergence tolerance (default: 1e-10)
/// * `max_iterations` - Maximum number of iterations (default: 100)
///
/// # Returns
/// * `Ok(Vector2<f64>)` - The solution [x, y]
/// * `Err(String)` - Error message if convergence fails
///
/// # Example
/// Solve: x^2 + y^2 = 4, x - y = 1
pub fn solve_coupled_equations<F, J>(
    f: F,
    jacobian: J,
    initial_guess: Vector2<f64>,
    tolerance: f64,
    max_iterations: usize,
) -> Result<Vector2<f64>, String>
where
    F: Fn(Vector2<f64>) -> Vector2<f64>,
    J: Fn(Vector2<f64>) -> Matrix2<f64>,
{
    let mut x = initial_guess;

    for iteration in 0..max_iterations {
        // Compute residual
        let residual = f(x);

        // Check convergence
        let residual_norm = residual.norm();
        if residual_norm < tolerance {
            println!("Converged in {} iterations", iteration);
            return Ok(x);
        }

        // Compute Jacobian and solve for delta
        let jac = jacobian(x);

        // Try to solve J * delta = -f(x)
        let lu = jac.lu();
        let delta = match lu.solve(&(-residual)) {
            Some(d) => d,
            None => return Err("Jacobian is singular".to_string()),
        };

        // Update solution
        x += delta;

        // Print iteration info
        println!(
            "Iteration {}: x = [{:.10}, {:.10}], residual norm = {:.2e}",
            iteration, x[0], x[1], residual_norm
        );
    }

    Err(format!(
        "Failed to converge after {} iterations",
        max_iterations
