use polars::prelude::*;

/// Segment the entries in column "str0" of `df0` into intervals defined by `lst0`.
/// - `df0`: mutable reference to a polars DataFrame containing a Utf8 column named "str0".
/// - `lst0`: slice of f64 boundary values (need at least two). Will be sorted ascending internally.
/// - `output_col`: name of the column to create with interval labels (strings like "[a, b)").
/// Returns PolarsResult<()>.
pub fn segment_str0_into_intervals(
    df0: &mut DataFrame,
    lst0: &[f64],
    output_col: &str,
) -> PolarsResult<()> {
    // Basic checks
    if lst0.len() < 2 {
        return Err(PolarsError::ShapeMisMatch(
            "lst0 must contain at least two boundaries".into(),
        ));
    }

    // Make a local sorted, deduplicated list of boundaries
    let mut bounds: Vec<f64> = lst0.to_vec();
    bounds.sort_by(|a, b| a.partial_cmp(b).unwrap());
    bounds.dedup_by(|a, b| a == b);

    if bounds.len() < 2 {
        return Err(PolarsError::ShapeMisMatch(
            "after deduplication, lst0 must have at least two unique boundaries".into(),
        ));
    }

    // Build textual labels for the intervals: [a, b)
    let labels: Vec<String> = bounds
        .windows(2)
        .map(|w| format!("[{}, {})", w[0], w[1]))
        .collect();

    // Helper to find interval index for a value
    let find_interval = |v: f64| -> Option<usize> {
        // left-inclusive, right-exclusive intervals [bounds[i], bounds[i+1])
        if v < bounds[0] {
            return None;
        }
        for i in 0..(bounds.len() - 1) {
            if v >= bounds[i] && v < bounds[i + 1] {
                return Some(i);
            }
        }
        // If exactly equal to the last boundary, put it into the last interval
        if (v == bounds[bounds.len() - 1]) {
            return Some(bounds.len() - 2);
        }
        None
    };

    // Access the "str0" column as Utf8Chunked
    let col = df0.column("str0")?.utf8()?;

    // Map each entry to an Option<String> label
    let mapped = col.into_iter().map(|opt_s| {
        opt_s.and_then(|s| {
            // parse numeric value from string; if parse fails, leave None
            s.parse::<f64>().ok().and_then(|v| {
                find_interval(v).map(|idx| labels[idx].clone())
            })
        })
    });

    // Build a new Utf8Chunked (nullable) column and insert
    let out_chunked = Utf8Chunked::from_iter_opt(output_col, mapped);
    df0.with_column(out_chunked.into_series())?;
    Ok(())
}

Example usage:

