use polars::prelude::*;

/// Segments entries in a DataFrame column into intervals based on provided boundaries.
///
/// # Arguments
/// * `df0` - A Polars DataFrame containing the data
/// * `column_name` - Name of the column to segment (e.g., "str0")
/// * `lst0` - A vector of boundary values (should be sorted)
///
/// # Returns
/// * A new DataFrame with an additional column containing interval labels
///
