use polars::prelude::*;
use chrono::NaiveDate;

/// Parse the `col_name` column of `df0` from "DD-MM-YYYY" strings into a Date (Date32) column.
/// Returns a new DataFrame with the column replaced. Parsing is strict: any invalid date returns an error.
pub fn parse_date_column(df0: &DataFrame, col_name: &str) -> PolarsResult<DataFrame> {
    // Ensure column exists and is utf8
    let ca = df0.column(col_name)?
        .utf8()
        .ok_or_else(|| PolarsError::SchemaMisMatch(
            format!("Column '{}' is not UTF8/string type", col_name).into()
        ))?;

    // epoch for Date32: 1970-01-01
    let epoch = NaiveDate::from_ymd_opt(1970, 1, 1).unwrap();

    // Collect parsed days (i32) as Option so we preserve nulls
    let mut parsed: Vec<Option<i32>> = Vec::with_capacity(ca.len());
    for i in 0..ca.len() {
        match ca.get(i) {
            Some(s) => {
                match NaiveDate::parse_from_str(s, "%d-%m-%Y") {
                    Ok(d) => {
                        let days = (d - epoch).num_days() as i32;
                        parsed.push(Some(days));
                    }
                    Err(_) => {
                        return Err(PolarsError::ComputeError(
                            format!("Failed to parse '{}' in column '{}', expected format DD-MM-YYYY", s, col_name).into()
                        ));
                    }
                }
            }
            None => parsed.push(None),
        }
    }

    // Build a Series from the parsed days and cast it to Date (Date32)
    let date_series = Series::new(col_name, parsed).cast(&DataType::Date)?;

    // Rebuild DataFrame with the replaced column
    let mut cols: Vec<Series> = Vec::with_capacity(df0.width());
    for s in df0.get_columns() {
        if s.name() == col_name {
            cols.push(date_series.clone());
        } else {
            cols.push(s.clone());
        }
    }
    DataFrame::new(cols)
}

Example usage:
- Suppose df0 has a "Date" column of strings like "31-12-2024".
- Call: let new_df = parse_date_column(&df0, "Date")?;

Notes:
- The resulting column is polars Date (Date32) type — days since Unix epoch — which is the native date dtype in polars.
- If you prefer a DateTime (with time-of-day), you can adjust to produce DateTime (Date64) by computing milliseconds since epoch instead of days and casting to DataType::Datetime(TimeUnit::Milliseconds, None).
- If you want non-strict parsing (e.g., invalid items become null), modify the match on parse errors to push(None) instead of returning an Err.

