    pairs.sort_by(|(key_a, _), (key_b, _)| {
        let seq_a = extract_letters_and_digits(key_a);
        let seq_b = extract_letters_and_digits(key_b);

        compare_sequences(&seq_a, &seq_b)
    });

    pairs
