/// Extracts only letters and digits from a string, preserving their order
fn extract_letters_and_digits(s: &str) -> Vec<char> {
    s.chars()
        .filter(|c| c.is_ascii_alphabetic() || c.is_ascii_digit())
        .collect()
}

/// Compares two sequences of characters according to the specified rules
fn compare_sequences(seq_a: &[char], seq_b: &[char]) -> Ordering {
    let min_len = seq_a.len().min(seq_b.len());

    for i in 0..min_len {
        let char_a = seq_a[i];
        let char_b = seq_b[i];

        // Check if both are letters
        if char_a.is_ascii_alphabetic() && char_b.is_ascii_alphabetic() {
            let cmp = char_a.to_ascii_lowercase().cmp(&char_b.to_ascii_lowercase());
            if cmp != Ordering::Equal {
                return cmp;
            }
        }
        // Check if both are digits
        else if char_a.is_ascii_digit() && char_b.is_ascii_digit() {
            let cmp = char_a.cmp(&char_b);
            if cmp != Ordering::Equal {
                return cmp;
            }
        }
        // One is a letter and the other is a digit - letters come before digits
        else {
            if char_a.is_ascii_alphabetic() {
                return Ordering::Less;
            } else {
                return Ordering::Greater;
            }
        }
    }

    // If we've compared all common characters, shorter sequence comes first
    seq_a.len().cmp(&seq_b.len())
}

