use std::cmp::Ordering;

/// Sorts the keys of a key-value mapping based on alphanumeric sequence.
/// 
/// This function extracts and sorts keys from a HashMap, using a natural sort
/// that compares sequences of letters and digits intelligently.
/// 
/// # Arguments
/// * `data_mapping` - A HashMap with String keys and generic values
/// 
/// # Returns
/// A Vec of sorted keys
fn sort_keys_by_alphanumeric<V>(data_mapping: &std::collections::HashMap<String, V>) -> Vec<String> {
    let mut keys: Vec<String> = data_mapping.keys().cloned().collect();

    keys.sort_by(|a, b| {
        let mut a_chars = a.chars().peekable();
        let mut b_chars = b.chars().peekable();

        loop {
            match (a_chars.next(), b_chars.next()) {
                (None, None) => return Ordering::Equal,
                (None, Some(_)) => return Ordering::Less,
                (Some(_), None) => return Ordering::Greater,
                (Some(a_char), Some(b_char)) => {
                    // Check if both are digits
                    if a_char.is_ascii_digit() && b_char.is_ascii_digit() {
                        // Collect full numbers for comparison
                        let mut a_num = a_char.to_string();
                        while let Some(&next) = a_chars.peek() {
                            if next.is_ascii_digit() {
                                a_num.push(next);
                                a_chars.next();
                            } else {
                                break;
                            }
                        }

                        let mut b_num = b_char.to_string();
                        while let Some(&next) = b_chars.peek() {
                            if next.is_ascii_digit() {
                                b_num.push(next);
                                b_chars.next();
                            } else {
                                break;
                            }
                        }

                        // Compare as integers, then as strings if equal length
                        let a_int: u64 = a_num.parse().unwrap_or(0);
                        let b_int: u64 = b_num.parse().unwrap_or(0);

                        match a_int.cmp(&b_int) {
                            Ordering::Equal => continue,
                            other => return other,
                        }
                    } else {
                        // Compare characters normally
                        match a_char.cmp(&b_char) {
                            Ordering::Equal => continue,
                            other => return other,
                        }
                    }
                }
            }
        }
    });

    keys
}

