/// Reorder `lst0` so its elements follow the order defined by `lst1`.
///
/// - Both slices must have equal length.
/// - Keys in `lst1` are used to determine order; elements in `lst0` move together with their keys.
/// - The sort is stable: items with equal keys preserve their original relative order.
///
/// Returns `Err(&str)` on length mismatch, otherwise `Ok(Vec<T>)` with reordered items.
///
/// Example:
/// let a = vec!["apple", "banana", "cherry"];
/// let keys = vec![2, 0, 1];
/// let reordered = reorder_by_keys(&a, &keys).unwrap();
/// assert_eq!(reordered, vec!["banana", "cherry", "apple"]);
pub fn reorder_by_keys<T, K>(lst0: &[T], lst1: &[K]) -> Result<Vec<T>, &'static str>
where
    T: Clone,
    K: Ord + Clone,
{
    if lst0.len() != lst1.len() {
        return Err("lst0 and lst1 must have the same length");
    }

    // Pair each key with its corresponding value from lst0, then sort by key.
    // sorted_by_key is stable, so equal keys preserve original order.
    let reordered: Vec<T> = lst1
        .iter()
        .cloned()
        .zip(lst0.iter().cloned())
        .sorted_by_key(|(k, _)| k.clone())
