use ndarray::{Array2, Axis};
use num_traits::Float;

/// Replace missing entries in a 2D table with the arithmetic mean of their respective column.
///
/// # Arguments
///
/// * `table`: The input 2D table.
/// * `missing_value`: The value representing missing entries.
///
/// # Returns
///
/// The table with missing entries replaced.
pub fn replace_missing_with_column_mean<F>(table: Array2<F>, missing_value: F) -> Array2<F>
where
    F: Float + std::fmt::Debug,
{
    let mut result = table.clone();

    for col in 0..table.ncols() {
        let column = table.column(col);
        let non_missing_values: Vec<F> = column.iter().filter(|&x| *x != missing_value).cloned().collect();

        if non_missing_values.is_empty() {
            // If all values in the column are missing, we cannot calculate the mean.
            // In this case, we will leave the missing values as they are.
            continue;
        }

        let mean = non_missing_values.iter().sum::<F>() / F::from(non_missing_values.len()).unwrap();

        for (i, x) in column.iter().enumerate() {
            if *x == missing_value {
                result[[i, col]] = mean;
            }
        }
    }

    result
}

