```rust
use ndarray::{Array2, ArrayView1};
use ndarray_stats::QuantileExt;

/// Replaces missing entries (represented as NaN) in a 2D table with the arithmetic mean
/// of their respective column.
///
/// # Arguments
/// * `table` - A mutable 2D array where NaN values represent missing entries
///
/// # Example
/// ```
/// use ndarray::Array2;
///
/// let mut data = Array2::from_shape_vec((3, 3), vec![
///     1.0, 2.0, f64::NAN,
///     4.0, f64::NAN, 6.0,
///     7.0, 8.0, 9.0,
/// ]).unwrap();
///
/// fill_missing_with_column_mean(&mut data);
///
/// // Column 0: [1.0, 4.0, 7.0] -> mean = 4.0
/// // Column 1: [2.0, NaN, 8.0] -> mean = 5.0 (ignoring NaN)
/// // Column 2: [NaN, 6.0, 9.0] -> mean = 7.5 (ignoring NaN)
/// ```
pub fn fill_missing_with_column_mean(table: &mut Array2<f64>) {
    let n_cols = table.ncols();

    // Calculate mean for each column (ignoring NaN values)
    let column_means: Vec<f64> = (0..n_cols)
        .map(|col_idx| {
            let column = table.column(col_idx);
            let valid_values: Vec<f64> = column
                .iter()
                .filter(|&&val| !val.is_nan())
                .copied()
                .collect();

            if valid_values.is_empty() {
                0.0 // Default to 0 if all values are NaN
            } else {
                valid_values.iter().sum::<f64>() / valid_values.len() as f64
            }
        })
        .collect();

    // Replace NaN values with corresponding column mean
    for (col_idx, &mean) in column_means.iter().enumerate() {
        for row_idx in 0..table.nrows() {
            if table[[row_idx, col_idx]].is_nan() {
                table[[row_idx, col_idx]] = mean;
            }
        }
    }
}

