/// Remove any mapping (JSON object) from `mappings` whose "link" field
/// matches one of the values in `links_to_remove`.
///
/// - `mappings` is mutated in-place.
/// - `links_to_remove` can be any IntoIterator of items convertible to &str
///
/// Behavior:
/// - If a mapping is not an object, it is preserved.
/// - If an object has no "link" field or the "link" is not a string, it is preserved.
fn remove_mappings_with_links<I, S>(mappings: &mut Vec<Value>, links_to_remove: I)
where
    I: IntoIterator<Item = S>,
    S: AsRef<str>,
{
    let set: HashSet<String> = links_to_remove
        .into_iter()
        .map(|s| s.as_ref().to_string())
        .collect();

    mappings.retain(|m| {
        // Only remove when m is an object and has a string "link" that matches the set.
        match m.get("link").and_then(|v| v.as_str()) {
            Some(link) => !set.contains(link),
            None => true,
        }
    });
}

