use polars::prelude::*;
use chrono::{NaiveDateTime, Datelike, Timelike};

pub fn reformat_date_column(
    df: &DataFrame,
    col_name: &str,
    format_str: &str,
) -> Result<DataFrame> {
    // Check if the column exists in the DataFrame
    let series = df
        .column(col_name)
        .map_err(|_| polars::error::PolarsError::ColumnNotFound(col_name.to_string()))?;

    // Ensure the data type of the column is DateTime
    let datetime_series = series
        .date64() // Assuming DateTime is stored as milliseconds since epoch
        .map_err(|_| polars::error::PolarsError::ComputeError("Column is not a DateTime type.".into()))?;

    // Transform the DateTime to desired format
    let formatted_series = datetime_series
        .into_iter()
        .map(|opt_dt| opt_dt.map(|dt| {
            let naive = NaiveDateTime::from_timestamp(dt / 1000, 0); // Convert to naive
            naive.format(format_str).to_string()
        }))
