    let str_series = match series.dtype() {
        DataType::String => series,
        DataType::Datetime(_, _) => {
            // Convert datetime to string first
            series.str()?.clone().into_series()
        }
        _ => {
            // Try to cast to string
            series.cast(&DataType::String)?
        }
    };

    // Parse each string as datetime and reformat
    let reformatted: Series = str_series
        .str()?
        .into_iter()
        .map(|opt_val| {
            opt_val.map(|val| {
                // Try common datetime formats
                let formats = [
                    "%Y-%m-%d %H:%M:%S",
                    "%Y-%m-%dT%H:%M:%S",
                    "%Y-%m-%d %H:%M:%S%.f",
                    "%Y/%m/%d %H:%M:%S",
                    "%d-%m-%Y %H:%M:%S",
                    "%m/%d/%Y %H:%M:%S",
                ];

                let parsed = formats.iter()
                    .find_map(|fmt| NaiveDateTime::parse_from_str(val, fmt).ok())
                    .or_else(|| NaiveDateTime::parse_from_str(val, "%Y-%m-%d %H:%M:%S").ok());

                match parsed {
