/// Combine two columns (col0 = date, col1 = time) from `table` into a Vec<Option<DateTime<Utc>>>.
/// - Accepts date/time inputs as typed date/time values, strings in common formats, or integers.
/// - Returns None for rows where either value is null/missing or when parsing fails for that row.
/// - Returns Err only for fatal problems (missing columns or row-count mismatch).
pub fn combine_cols_to_datetimes(
    table: &Table,
    col0: &str,
    col1: &str,
) -> Result<Vec<Option<DateTime<Utc>>>, String> {
    // Get columns by name (fictional Table API)
    let c0 = table
        .column(col0)
        .ok_or_else(|| format!("column '{}' not found", col0))?;
    let c1 = table
        .column(col1)
        .ok_or_else(|| format!("column '{}' not found", col1))?;

    if c0.len() != c1.len() {
        return Err(format!(
            "column length mismatch: '{}' is {}, '{}' is {}",
            col0,
            c0.len(),
            col1,
            c1.len()
        ));
    }

    let mut out: Vec<Option<DateTime<Utc>>> = Vec::with_capacity(c0.len());

    for i in 0..c0.len() {
        let vdate = c0.get(i);
        let vtime = c1.get(i);

        // treat missing/null as None
        match (vdate, vtime) {
            (None, _) | (_, None) => {
                out.push(None);
                continue;
            }
            (Some(Value::Null), _) | (_, Some(Value::Null)) => {
                out.push(None);
                continue;
            }
            (Some(dv), Some(tv)) => {
                // try to extract NaiveDate and NaiveTime; if either parse fails, push None
                match (extract_date(dv), extract_time(tv)) {
                    (Ok(date), Ok(time)) => {
                        let ndt = NaiveDateTime::new(date, time);
                        // interpret the combined naive datetime as UTC
                        let dt_utc: DateTime<Utc> = Utc.from_utc_datetime(&ndt);
                        out.push(Some(dt_utc));
                    }
                    // If either parsing fails for this row, return None for this row (non-fatal)
                    _ => out.push(None),
                }
            }
        }
    }

    Ok(out)
}

/// Helper: attempt to get a NaiveDate from a Value (typed date, string, or integer).
fn extract_date(v: &Value) -> Result<NaiveDate, ()> {
    match v {
        Value::Date(d) => Ok(*d), // assume Value::Date carries NaiveDate
        Value::Str(s) => {
            // Try a few common formats
            if let Ok(d) = NaiveDate::parse_from_str(s, "%Y-%m-%d") {
                return Ok(d);
            }
            if let Ok(d) = NaiveDate::parse_from_str(s, "%Y%m%d") {
                return Ok(d);
            }
            if let Ok(d) = NaiveDate::parse_from_str(s, "%d/%m/%Y") {
                return Ok(d);
            }
            if let Ok(d) = NaiveDate::parse_from_str(s, "%m/%d/%Y") {
                return Ok(d);
            }
            Err(())
        }
        Value::Int(i) => {
            // interpret as YYYYMMDD
            // allow negative check omitted; assume positive
            let y = (i / 10000) as i32;
            let m = ((i / 100) % 100) as u32;
            let d = (i % 100) as u32;
            NaiveDate::from_ymd_opt(y, m, d).ok_or(())
        }
        _ => Err(()),
    }
}

/// Helper: attempt to get a NaiveTime from a Value (typed time, string, or integer).
fn extract_time(v: &Value) -> Result<NaiveTime, ()> {
    match v {
        Value::Time(t) => Ok(*t), // assume Value::Time carries NaiveTime
        Value::Str(s) => {
            if let Ok(t) = NaiveTime::parse_from_str(s, "%H:%M:%S") {
                return Ok(t);
            }
            if let Ok(t) = NaiveTime::parse_from_str(s, "%H:%M") {
                return Ok(t);
            }
            // accept HHMMSS or HHMM
            let digits: String = s.chars().filter(|c| c.is_ascii_digit()).collect();
            match digits.len() {
                6 => {
                    let hh: u32 = digits[0..2].parse().map_err(|_| ())?;
                    let mm: u32 = digits[2..4].parse().map_err(|_| ())?;
                    let ss: u32 = digits[4..6].parse().map_err(|_| ())?;
                    NaiveTime::from_hms_opt(hh, mm, ss).ok_or(())
                }
                4 => {
                    let hh: u32 = digits[0..2].parse().map_err(|_| ())?;
                    let mm: u32 = digits[2..4].parse().map_err(|_| ())?;
                    NaiveTime::from_hms_opt(hh, mm, 0).ok_or(())
                }
                _ => Err(()),
            }
        }
        Value::Int(i) => {
            // treat as HHMMSS (e.g., 930 -> 00:09:30? better treat as HMMSS or HHMM)
            let mut x = *i;
            if x < 0 {
                return Err(());
            }
            // If >= 10000 assume HHMMSS, if >= 100 assume HHMM or HMM
            if x >= 10000 {
                let hh = (x / 10000) as u32;
                let mm = ((x / 100) % 100) as u32;
                let ss = (x % 100) as u32;
                NaiveTime::from_hms_opt(hh, mm, ss).ok_or(())
            } else if x >= 100 {
                let hh = (x / 100) as u32;
                let mm = (x % 100) as u32;
