mod modern_split_2025 {
    /// Split a &str at commas that are not inside paired double quotes.
    ///
    /// Rules:
    /// - A double-quote (") toggles "inside-quote" status unless it is escaped by a backslash.
    /// - A quote preceded by an odd number of backslashes is considered escaped.
    /// - Commas inside quoted regions are ignored.
    /// - Empty segments (from consecutive commas or leading/trailing commas) are preserved.
    ///
    /// Returns a Vec<String> with the segments in the original order.
    pub fn split_commas_ignoring_quoted(s: &str) -> Vec<String> {
        // We'll iterate with char_indices (gives byte index boundaries) and use the raw bytes
        // to check for backslashes immediately preceding quotes.
        let bytes = s.as_bytes();
        let mut segments = Vec::new();
        let mut segment_start = 0usize;
        let mut in_quotes = false;

        for (i, ch) in s.char_indices() {
            match ch {
                '"' => {
                    // Count number of consecutive backslashes immediately before the quote.
                    // If the count is even, the quote is not escaped and toggles in_quotes.
                    let mut backslash_count = 0usize;
                    let mut j = i;
                    while j > 0 {
                        // Look at the byte immediately before j
                        j -= 1;
                        if bytes[j] == b'\\' {
                            backslash_count += 1;
                        } else {
