                        }
                    }
                    if backslash_count % 2 == 0 {
                        in_quotes = !in_quotes;
                    }
                }
                ',' => {
                    if !in_quotes {
                        // slice from segment_start .. i
                        segments.push(s[segment_start..i].to_string());
                        // new segment starts after the comma (i is the byte index of the comma)
                        segment_start = i + ch.len_utf8();
                    }
                }
                _ => {}
            }
        }

        // push final segment (including possibility of empty trailing segment)
        segments.push(s[segment_start..].to_string());
        segments
    }
