# Rust Function for CSV-like Parsing

```rust
use csv::StringRecord;

/// Separates input text into segments at each comma, except commas within double quotes.
/// 
/// # Arguments
/// * `input` - A string slice to be separated
/// 
/// # Returns
/// A vector of strings, each trimmed of whitespace
/// 
/// # Example
/// ```
/// let result = separate_by_comma(r#"apple, "banana, cherry", date"#);
/// assert_eq!(result, vec!["apple", "banana, cherry", "date"]);
/// ```
fn separate_by_comma(input: &str) -> Vec<String> {
    let mut record = StringRecord::from(vec![input]);
    record.set_terminator(csv::Terminator::CRLF);

    // Parse using csv reader to handle quoted fields
    let mut reader = csv::ReaderBuilder::new()
        .has_headers(false)
        .from_reader(input.as_bytes());

    reader.records()
        .filter_map(|record| record.ok())
        .flat_map(|record| {
            record.iter()
                .map(|field| field.trim().to_string())
                .collect::<Vec<_>>()
        })
        .collect()
}

fn main() {
    // Example 1: Simple comma separation
    let test1 = "apple, banana, cherry";
    println!("Test 1: {:?}", separate_by_comma(test1));
    // Output: ["apple", "banana", "cherry"]

    // Example 2: Comma within quotes
    let test2 = r#"apple, "banana, cherry", date"#;
    println!("Test 2: {:?}", separate_by_comma(test2));
    // Output: ["apple", "banana, cherry", "date"]

    // Example 3: Multiple quoted fields
    let test3 = r#""hello, world", "foo, bar", baz"#;
    println!("Test 3: {:?}", separate_by_comma(test3));
    // Output: ["hello, world", "foo, bar", "baz"]

    // Example 4: Mixed spacing
    let test4 = r#"  item1  ,  "item 2, with comma"  ,  item3  "#;
    println!("Test 4: {:?}", separate_by_comma(test4));
    // Output: ["item1", "item 2, with comma", "item3"]
}
