use num_traits::float::Float;
use num_traits::FromPrimitive;

/// Sorts a list in place by comparing each element according to its floating-point interpretation.
///
/// # Arguments
///
/// * `list`: The list to be sorted.
///
/// # Example
///
/// ```
/// let mut list = vec![5, 2, 8, 3, 1, 6, 4];
