use std::cmp::Ordering;

/// Sort `data` in place by comparing elements according to their floating-point interpretation.
///
/// The caller provides `to_f64` which maps each element to an `f64`.
/// Comparison uses a total ordering (`f64::total_cmp`) so NaNs and -0.0/+0.0
/// are ordered deterministically.
///
/// Example:
/// let mut items = ["3.0", "nan", "-0.0", "2.5"];
/// sort_by_float_in_place(&mut items, |s| s.parse::<f64>().unwrap_or(f64::NAN));
pub fn sort_by_float_in_place<T, F>(data: &mut [T], mut to_f64: F)
where
    F: FnMut(&T) -> f64,
{
    data.sort_by(|a, b| {
        let fa = to_f64(a);
        let fb = to_f64(b);
        fa.total_cmp(&fb)
    });
}
