/// # Example
/// ```
/// let mut numbers = vec!["3.14", "2.71", "1.41", "1.73"];
/// sort_by_float_interpretation(&mut numbers);
/// assert_eq!(numbers, vec!["1.41", "1.73", "2.71", "3.14"]);
/// ```

fn sort_by_float_interpretation<T>(data: &mut [T])
where
    T: AsRef<str> + Ord,
{
    data.sort_by(|a, b| {
        let a_float = a.as_ref().parse::<f64>().unwrap_or(f64::NAN);
