        match (a_float.is_nan(), b_float.is_nan()) {
            (true, true) => std::cmp::Ordering::Equal,
            (true, false) => std::cmp::Ordering::Greater,
            (false, true) => std::cmp::Ordering::Less,
            (false, false) => a_float.partial_cmp(&b_float).unwrap_or(std::cmp::Ordering::Equal),
        }
    });
}

