    /// Iterator type produced by `zip_pairs`.
    pub struct ZipPairs<I, J> {
        a: I,
        b: J,
    }

    /// Construct a ZipPairs iterator from two IntoIterator values.
    pub fn zip_pairs<IA, IB>(a: IA, b: IB) -> ZipPairs<IA::IntoIter, IB::IntoIter>
    where
        IA: IntoIterator,
        IB: IntoIterator,
