/// Generate the Cartesian product of two integer ranges.
/// Each range is specified by (start, stop_exclusive, step).
///
/// - start: starting integer (inclusive)
/// - stop: stop integer (exclusive)
/// - step: step; may be positive or negative but not zero
///
/// Returns Err if either step is zero. Otherwise returns a Vec of (a, b)
/// pairs where `a` iterates over the first range and `b` over the second range.
pub fn cartesian_product_ranges(
    start0: i64,
    stop0: i64,
    step0: i64,
    start1: i64,
    stop1: i64,
    step1: i64,
) -> Result<Vec<(i64, i64)>, String> {
    if step0 == 0 || step1 == 0 {
        return Err("step must be non-zero".to_string());
    }

    // Helper to produce the values for one range.
    fn make_seq(start: i64, stop: i64, step: i64) -> Vec<i64> {
        let mut v = Vec::new();
        if step > 0 {
            let mut cur = start;
            while cur < stop {
                v.push(cur);
                cur = cur.wrapping_add(step);
            }
        } else {
            let mut cur = start;
            while cur > stop {
                v.push(cur);
                cur = cur.wrapping_add(step);
            }
        }
        v
    }

    let seq0 = make_seq(start0, stop0, step0);
    let seq1 = make_seq(start1, stop1, step1);

    // If either sequence is empty, product is empty
    if seq0.is_empty() || seq1.is_empty() {
        return Ok(Vec::new());
    }

    let mut product = Vec::with_capacity(seq0.len() * seq1.len());
    for &a in &seq0 {
        for &b in &seq1 {
            product.push((a, b));
        }
    }

    Ok(product)
}

