pub fn any_in_range(df0: &DataFrame, var0: &str, var1: f64, var2: f64) -> bool {
    // Ensure var1 <= var2 to avoid logical errors
    let (lower, upper) = if var1 <= var2 { (var1, var2) } else { (var2, var1) };

