use std::ops::RangeInclusive;

/// Small trait that exposes a range iterator over (&K, &V).
/// This keeps the fetch_items_between function generic so it can be used
/// with std::collections::BTreeMap (below) or implemented for a newer 2025+ crate's map type.
pub trait RangeQueryable<K, V> {
    /// Return an iterator over (&K, &V) for keys in the given inclusive range.
    fn range_inclusive<'a>(
        &'a self,
        range: RangeInclusive<&'a K>,
    ) -> Box<dyn Iterator<Item = (&'a K, &'a V)> + 'a>;
}

/// Implement RangeQueryable for the standard library BTreeMap.
impl<K: Ord, V> RangeQueryable<K, V> for BTreeMap<K, V> {
    fn range_inclusive<'a>(
        &'a self,
        range: RangeInclusive<&'a K>,
    ) -> Box<dyn Iterator<Item = (&'a K, &'a V)> + 'a> {
        // BTreeMap already has a range method taking an actual RangeBounds<K>.
        // We clone the bounds into owned K references by mapping at call site; here we get &K.
        // Use range(range) where range is RangeInclusive<&K> by matching start/end.
        let start = range.start().clone();
        let end = range.end().clone();
        Box::new(self.range((start..=end)))
    }
}

/// Fetch all key/value pairs from `dict0` whose keys are between `var0` and `var1` (inclusive)
/// and for which `filter` returns true. Keys and values are cloned into the returned Vec.
///
/// - dict0: any map implementing RangeQueryable<K,V>
/// - var0, var1: bounds (inclusive)
/// - filter: predicate (k, v) -> bool
pub fn fetch_items_between<M, K, V, F>(
    dict0: &M,
    var0: &K,
    var1: &K,
    mut filter: F,
) -> Vec<(K, V)>
where
    M: RangeQueryable<K, V>,
    K: Ord + Clone,
    V: Clone,
    F: FnMut(&K, &V) -> bool,
{
    let mut out = Vec::new();
    for (k, v) in dict0.range_inclusive(var0..=var1) {
        if filter(k, v) {
            out.push((k.clone(), v.clone()));
        }
    }
    out
}

