fn collapse_consecutive_uppercase(text: &str) -> String {
    text.chars()
        .fold(String::new(), |mut result, ch| {
            if ch.is_uppercase() {
                let lowercase = ch.to_lowercase().to_string();
                // Only add if it's different from the last character
                if !result.ends_with(&lowercase) {
                    result.push_str(&lowercase);
                }
            } else {
                result.push(ch);
            }
            result
        })
}

#[cfg(test)]
