        assert_eq!(collapse_consecutive_uppercase("AAAaaaBBBbbbCCC"), "aabbc");
        assert_eq!(collapse_consecutive_uppercase("hello"), "hello");
        assert_eq!(collapse_consecutive_uppercase("HELLO"), "helo");
        assert_eq!(collapse_consecutive_uppercase("AAaaBBbbCC"), "aabbc");
        assert_eq!(collapse_consecutive_uppercase(""), "");
        assert_eq!(collapse_consecutive_uppercase("A"), "a");
        assert_eq!(collapse_consecutive_uppercase("AABBCC"), "abc");
        assert_eq!(collapse_consecutive_uppercase("AaBbCc"), "abc");
    }
