/// ).unwrap();
/// 
/// let result = aggregate_by_id(&df, "id", &["value1", "value2"]).unwrap();
/// println!("{:?}", result);
/// ```
pub fn aggregate_by_id(
    df: &DataFrame,
    id_column: &str,
    value_columns: &[&str],
) -> Result<DataFrame, Box<dyn Error>> {
    // Validate that the id column exists
    if !df.get_column_names().contains(&id_column) {
        return Err(format!("Column '{}' not found in DataFrame", id_column).into());
    }

    // Validate that all value columns exist
    for col in value_columns {
        if !df.get_column_names().contains(col) {
            return Err(format!("Column '{}' not found in DataFrame", col).into());
        }
    }

    // Build aggregation expressions for each value column
    let agg_exprs: Vec<Expr> = value_columns
        .iter()
        .map(|col| col(sum(col)))
        .collect();

    // Group by the identifier column and aggregate
    let result = df
        .lazy()
        .group_by([col(id_column)])
        .agg(agg_exprs)
        .collect()?;

    Ok(result)
}

// Alternative version using eager API (simpler but less flexible)
pub fn aggregate_by_id_eager(
    df: &DataFrame,
    id_column: &str,
    value_columns: &[&str],
) -> Result<DataFrame, Box<dyn Error>> {
    // Validate columns exist
    if !df.get_column_names().contains(&id_column) {
        return Err(format!("Column '{}' not found in DataFrame", id_column).into());
    }

    for col in value_columns {
        if !df.get_column_names().contains(col) {
            return Err(format!("Column '{}' not found in DataFrame", col).into());
        }
    }

    // Group by and aggregate using eager API
