```rust
use itertools::Itertools;

/// Pads each inner group in a nested collection to ensure it contains
/// exactly the specified number of elements by appending a fill element.
///
/// # Arguments
/// * `nested: Vec<Vec<T>>` - A nested collection (vector of vectors)
/// * `target_size: usize` - The desired size for each inner group
/// * `fill: T` - The element to append for padding (must be Clone)
///
/// # Returns
/// A new nested collection where each inner group is padded to `target_size`
///
/// # Example
/// ```
/// let data = vec![
///     vec![1, 2],
///     vec![3],
///     vec![4, 5, 6],
/// ];
/// let padded = pad_inner_groups(data, 3, 0);
/// assert_eq!(padded, vec![
///     vec![1, 2, 0],
///     vec![3, 0, 0],
///     vec![4, 5, 6],
/// ]);
/// ```
fn pad_inner_groups<T: Clone>(
    nested: Vec<Vec<T>>,
    target_size: usize,
    fill: T,
) -> Vec<Vec<T>> {
    nested
        .into_iter()
        .map(|mut group| {
            let current_len = group.len();
            if current_len < target_size {
                group.extend(std::iter::repeat(fill.clone()).take(target_size - current_len));
            }
            group
        })
        .collect()
}

// Alternative using itertools for more functional style
fn pad_inner_groups_functional<T: Clone>(
    nested: Vec<Vec<T>>,
    target_size: usize,
    fill: T,
) -> Vec<Vec<T>> {
    nested
        .into_iter()
        .map(|group| {
            let padding_needed = target_size.saturating_sub(group.len());
            group
                .into_iter()
                .chain(std::iter::repeat(fill.clone()).take(padding_needed))
                .collect()
        })
        .collect()
}

