use polars::prelude::*;
use serde_json::Value as JsonValue;
use std::collections::HashMap;

/// Convert a polars DataFrame `df` into a Vec<HashMap<String, serde_json::Value>>.
/// Each map corresponds to one row mapping column name -> value.
///
/// - Handles common scalar types (null, bool, ints, floats, utf8).
/// - Falls back to string representation for other/complex types.
fn df_to_vec_maps(df: &DataFrame) -> Vec<HashMap<String, JsonValue>> {
    let cols = df.get_columns();
    let nrows = df.height();
    let mut out = Vec::with_capacity(nrows);

    for row_idx in 0..nrows {
        let mut map = HashMap::with_capacity(cols.len());
        for s in cols.iter() {
            let key = s.name().to_string();
            let av = s.get(row_idx); // returns AnyValue<'_>
            let jv = match av {
                AnyValue::Null => JsonValue::Null,
                AnyValue::Boolean(b) => JsonValue::Bool(b),
                AnyValue::Utf8(s) => JsonValue::String(s.to_string()),
                // signed integers
                AnyValue::Int8(i) => JsonValue::from(i),
                AnyValue::Int16(i) => JsonValue::from(i),
                AnyValue::Int32(i) => JsonValue::from(i),
                AnyValue::Int64(i) => JsonValue::from(i),
                // unsigned integers
                AnyValue::UInt8(u) => JsonValue::from(u),
                AnyValue::UInt16(u) => JsonValue::from(u),
                AnyValue::UInt32(u) => JsonValue::from(u),
                AnyValue::UInt64(u) => JsonValue::from(u),
                // floats
                AnyValue::Float32(f) => JsonValue::from(f as f64),
                AnyValue::Float64(f) => JsonValue::from(f),
                // date/time types and other specialized types: stringify as fallback
                _ => JsonValue::String(av.to_string()),
            };
            map.insert(key, jv);
        }
        out.push(map);
    }

    out
}

fn main() -> PolarsResult<()> {
    // Example: construct a small DataFrame named `df`
    let df = df![
        "name" => &["Alice", "Bob", "Carol"],
        "age" => &[30i32, 25, 27],
        "score" => &[85.2f64, 91.5, 78.0],
        "active" => &[true, false, true]
    ]?;

    let vec_maps = df_to_vec_maps(&df);

    // Print the resulting vector of maps as JSON for demonstration
    for (i, row_map) in vec_maps.iter().enumerate() {
        println!("row {}: {}", i, serde_json::to_string(row_map).unwrap());
    }

    Ok(())
}

