use ndarray::{Array1, Zip};

fn weighted_average(col_values: Vec<f64>, col_weights: Vec<f64>) -> Option<f64> {
    // Check if the lengths of both vectors match
    if col_values.len() != col_weights.len() || col_values.is_empty() {
        return None; // Return None if lengths don't match or vectors are empty
    }

    let values = Array1::from(col_values);
    let weights = Array1::from(col_weights);

    // Calculate the sum of the weighted values and the sum of the weights
    let sum_weights: f64 = weights.sum();

    if sum_weights == 0.0 { // Prevent division by zero
        return None;
    }

    let weighted_sum: f64 = Zip::from(&values)
        .and(&weights)
        .apply(|&value, &weight| value * weight)
        .sum();

    Some(weighted_sum / sum_weights)
}

fn main() {
    let col_values = vec![4.0, 5.0, 6.0];
    let col_weights = vec![1.0, 2.0, 3.0];

    match weighted_average(col_values, col_weights) {
        Some(avg) => println!("Weighted Average: {}", avg),
        None => println!("Error: Check the input vectors."),
    }
}
```

