use polars::prelude::*;

/// Compute weighted mean of `val_col` using weights in `wt_col`.
/// Returns Ok(Some(mean)) if at least one valid pair and total weight != 0.0,
/// Ok(None) if total weight is zero or there are no valid (value,weight) pairs,
/// or Err(...) if a DataFrame/column error occurs.
pub fn weighted_mean_from_df(
    df: &DataFrame,
    val_col: &str,
    wt_col: &str,
) -> PolarsResult<Option<f64>> {
    // Get columns and cast to Float64
    let vals_s = df.column(val_col)?.cast(&DataType::Float64)?;
    let wts_s = df.column(wt_col)?.cast(&DataType::Float64)?;

    let vals = vals_s.f64()?;
    let wts = wts_s.f64()?;

    let len = vals.len().max(wts.len());
    let mut weighted_sum: f64 = 0.0;
    let mut weight_sum: f64 = 0.0;

    for i in 0..len {
        // Use get to obtain Option<f64>; out-of-range indexes are treated as None
        let v_opt = vals.get(i);
        let w_opt = wts.get(i);

        if let (Some(v), Some(w)) = (v_opt, w_opt) {
            // skip NaN/inf values
            if v.is_finite() && w.is_finite() {
                weighted_sum += v * w;
                weight_sum += w;
            }
        }
    }

    if weight_sum == 0.0 {
        Ok(None)
    } else {
        Ok(Some(weighted_sum / weight_sum))
    }
}

