///
/// # Arguments
/// * `df` - The input DataFrame to process
/// * `missing_indicator` - The string to use as the missing value indicator
///                         (only used for string columns)
///
/// # Returns
/// A new DataFrame with whitespace-only entries replaced
pub fn replace_whitespace_with_missing(df: DataFrame, missing_indicator: &str) -> Result<DataFrame, PolarsError> {
    // Create a new empty DataFrame to store results
    let mut result_df = df.clone();

    // Process each column
    for col_name in df.get_column_names() {
        let col = df.column(&col_name).ok_or_else(|| {
            PolarsError::ComputeError("Column not found".into())
        })?;

        // Get the data type
        let dtype = col.dtype();

        // Create a new expression to filter whitespace-only values
        let whitespace_expr = match dtype {
            DataType::Utf8 => {
                // For string columns, check if the string is whitespace only
                let whitespace_check = col.expr(&col_name)
                    .apply("is_whitespace", &[&col_name])
                    .unwrap();

                // Create a mask for whitespace-only values
                let mask = whitespace_check
                    .apply("all", &[&col_name])
                    .unwrap();

                // Replace with missing indicator
                let replace_expr = mask
                    .apply("if", &[&col_name, &missing_indicator, &col_name])
                    .unwrap();

                replace_expr
            }
            DataType::Float64 | DataType::Float32 | DataType::Int64 | DataType::Int32 |
            DataType::UInt64 | DataType::UInt32 | DataType::Boolean => {
                // For numeric/boolean columns, check if the value is empty string
                let empty_check = col.expr(&col_name)
                    .apply("is_empty", &[&col_name])
                    .unwrap();

                // Replace empty strings with NaN/null
                let replace_expr = empty_check
                    .apply("if", &[&col_name, &col_name, &col_name])
                    .unwrap();

                // For numeric types, we need to explicitly set to NaN
                let nan_expr = match dtype {
                    DataType::Float64 => col.expr(&col_name).apply("is_nan", &[&col_name]).unwrap(),
                    DataType::Float32 => col.expr(&col_name).apply("is_nan", &[&col_name]).unwrap(),
                    _ => {
                        // For integer types, we'll use null
                        empty_check.apply("if", &[&col_name, &col_name, &col_name]).unwrap()
                    }
                };

                // Combine the checks
                let final_expr = nan_expr.apply("or", &[&empty_check]).unwrap();
                final_expr.apply("if", &[&final_expr, &col_name, &col_name]).unwrap()
            }
            _ => {
                // For other types, do nothing
                col.expr(&col_name)
            }
        };

        // Apply the transformation to the column
        let new_col = result_df
            .lazy()
            .select([col_name.clone(), replace_expr])
            .collect()?
            .unwrap()
            .column(&col_name)
            .unwrap();

        // Replace the column in the result DataFrame
        result_df = result_df.with_column(
            col_name.clone(),
            new_col
        );
    }

    Ok(result_df)
}

