                            .zip(whitespace_mask.iter())
                            .map(|(opt_val, is_whitespace)| {
                                match (opt_val, is_whitespace) {
                                    (_, true) => Some(indicator),
                                    (Some(val), false) => Some(val),
                                    (None, _) => None,
                                }
                            })
                            .collect();
                        replaced.into_series()
                    }
                    None => {
                        // Replace with null
                        let replaced: StringChunked = str_series
                            .into_iter()
                            .zip(whitespace_mask.iter())
                            .map(|(opt_val, is_whitespace)| {
