                                    (None, _) => None,
                                }
                            })
                            .collect();
                        replaced.into_series()
                    }
                }
            } else {
                // Non-string columns pass through unchanged
                series.clone()
            }
        })
        .collect();

    // Reconstruct DataFrame from processed columns
