use polars::prelude::*;

/// Replaces all whitespace-only entries in a Polars DataFrame with a missing value indicator.
/// 
/// # Arguments
/// * `df` - A mutable reference to the DataFrame to process
/// * `missing_indicator` - The string to use as a missing value indicator (e.g., "NA", "NULL", "")
/// 
/// # Returns
/// * `Result<DataFrame>` - The processed DataFrame with whitespace entries replaced
/// 
/// # Example
/// ```
/// use polars::prelude::*;
/// 
/// let mut df = df!{
///     "col1" => ["hello", "  ", "world"],
///     "col2" => ["\t", "test", "\n"],
/// }.unwrap();
/// 
/// let result = replace_whitespace_with_missing(df, "NA").unwrap();
/// ```
pub fn replace_whitespace_with_missing(
    df: DataFrame,
    missing_indicator: &str,
) -> Result<DataFrame> {
    let mut new_df = df.clone();

    // Process each column
    let columns: Vec<String> = new_df.get_column_names()
        .iter()
        .map(|s| s.to_string())
        .collect();

    for col_name in columns {
        let col = new_df.column(&col_name)?;

        // Only process string columns
        if let Ok(str_col) = col.str() {
            // Create a new series with whitespace entries replaced
            let processed = str_col
                .into_iter()
                .map(|opt_val| {
                    opt_val.and_then(|val| {
                        // Check if the string contains only whitespace
                        if val.trim().is_empty() {
                            Some(missing_indicator)
                        } else {
                            Some(val)
                        }
                    })
                })
                .collect::<StringChunked>()
                .into_series();

            // Replace the column in the dataframe
            new_df = new_df.with_columns(vec![processed.alias(&col_name)])?;
        }
    }

    Ok(new_df)
}

