use polars::prelude::*;
use std::collections::HashMap;

/// Count occurrences of each unique value in `column_name0` from `df0`.
/// Returns a DataFrame with columns:
/// - column_name0: the unique values (as Utf8 strings)
/// - count: the occurrence count (i64)
///
/// Example usage:
/// let df = DataFrame::new(vec![
///     Series::new("column_name0", &["a", "b", "a", "c", "b", "a"]),
/// ])?;
/// let counts_df = count_unique_values(&df, "column_name0")?;
/// println!("{counts_df}");
pub fn count_unique_values(df0: &DataFrame, column_name0: &str) -> PolarsResult<DataFrame> {
    // Get the Series for the requested column (returns error if column not present)
    let s = df0.column(column_name0)?;

    // Count occurrences using a HashMap keyed by string representation.
    // We convert AnyValue -> String because AnyValue is not Hash/Eq.
    let mut counts: HashMap<String, usize> = HashMap::new();
    for av in s.iter() {
        // Represent nulls explicitly
        let key = match av {
            AnyValue::Null => "__NULL".to_string(),
            _ => av.to_string(),
        };
        *counts.entry(key).or_insert(0) += 1;
    }

    // Convert hashmap into a vector of (value, count) and sort by count desc
    let mut pairs: Vec<(String, usize)> = counts.into_iter().collect();
    pairs.sort_by(|a, b| b.1.cmp(&a.1));

    // Build columns for the result DataFrame
    let values: Vec<String> = pairs.iter().map(|(v, _)| v.clone()).collect();
    let counts_i64: Vec<i64> = pairs.iter().map(|(_, c)| *c as i64).collect();

    let s_vals = Series::new(column_name0, &values);
    let s_counts = Series::new("count", &counts_i64);

    DataFrame::new(vec![s_vals, s_counts])
}

