use std::ptr;

/// Remove elements matching `pred` from `vec`, optimizing for the case where
/// only a small number of elements are removed.
///
/// Returns the number of elements removed.
///
/// Complexity:
/// - single pass to find removal indices (O(n))
/// - then copies contiguous kept ranges in bulk (few large memmoves if removals are few)
/// - minimal heap allocations (only small vector to store removal indices)
///
/// Safe to use with non-Copy, Drop types.
pub fn remove_if_small<T, F>(vec: &mut Vec<T>, mut pred: F) -> usize
where
    F: FnMut(&T) -> bool,
{
    let len = vec.len();
    // Collect indices to remove; expected to be small.
    let mut remove_idxs: Vec<usize> = Vec::new();
    remove_idxs.reserve(8);
    for i in 0..len {
        if pred(&vec[i]) {
            remove_idxs.push(i);
        }
    }

    let rem = remove_idxs.len();
    if rem == 0 {
        return 0;
    }

    unsafe {
        let ptr_base = vec.as_mut_ptr();
        let mut prev = 0usize;
        let mut removed_so_far = 0usize;

        // For each removal index r, copy the kept chunk [prev .. r) left by removed_so_far.
        for &r in &remove_idxs {
            let chunk_len = r - prev;
            if chunk_len > 0 {
                // copy handles overlapping memory; dst < src here
                ptr::copy(ptr_base.add(prev), ptr_base.add(prev - removed_so_far), chunk_len);
            }
            removed_so_far += 1; // skipping the removed element at r
            prev = r + 1; // next chunk starts after removed element
        }

        // copy the final tail chunk after the last removed index
        if prev < len {
            let chunk_len = len - prev;
            ptr::copy(ptr_base.add(prev), ptr_base.add(prev - removed_so_far), chunk_len);
        }

        // drop the now-unused tail elements (they are duplicates/originals we must drop)
        let new_len = len - rem;
        for i in new_len..len {
            ptr::drop_in_place(ptr_base.add(i));
        }

        // update the Vec length
        vec.set_len(new_len);
    }

    rem
}

