/// Efficiently removes elements from a Vec based on a predicate function.
/// 
/// This function uses an in-place removal strategy that minimizes allocations
/// by using a two-pointer technique, making it efficient even for small removals.
///
/// # Arguments
/// * `collection` - A mutable reference to the Vec to be modified
/// * `predicate` - A closure that returns true for elements to remove
///
/// # Returns
/// The number of elements removed
///
/// # Example
/// ```
/// let mut numbers = vec![1, 2, 3, 4, 5, 6];
/// let removed = remove_elements(&mut numbers, |&x| x % 2 == 0);
/// assert_eq!(removed, 3);
/// assert_eq!(numbers, vec![1, 3, 5]);
/// ```
fn remove_elements<T, F>(collection: &mut Vec<T>, predicate: F) -> usize
where
    F: Fn(&T) -> bool,
{
    let mut write_pos = 0;
    let mut removed_count = 0;

    for read_pos in 0..collection.len() {
        if !predicate(&collection[read_pos]) {
            collection.swap(read_pos, write_pos);
            write_pos += 1;
        } else {
            removed_count += 1;
        }
    }

    collection.truncate(write_pos);
    removed_count
}

