use polars::prelude::*;
use std::error::Error;

/// Reorder the columns of `df0` using column names in `var0` and positions in `var1`.
///
/// - df0: input DataFrame (not modified)
/// - var0: slice of column names to place
/// - var1: slice of target positions (0-based) corresponding to names in `var0`
///
/// Returns: a new DataFrame with columns reordered, or an error if inputs are invalid.
pub fn reorder_columns(
    df0: &DataFrame,
    var0: &[&str],
    var1: &[usize],
) -> Result<DataFrame, Box<dyn Error>> {
    // basic checks
    let ncols = df0.width();
    if var0.len() != var1.len() {
        return Err(format!(
            "var0 and var1 must have the same length (got {} and {})",
            var0.len(),
            var1.len()
        )
        .into());
    }
    if ncols == 0 {
        return Ok(df0.clone()); // nothing to do
    }

    // validate target indices and uniqueness
    let mut seen = vec![false; ncols];
    for &pos in var1 {
        if pos >= ncols {
            return Err(format!("target position {} out of range (0..{})", pos, ncols - 1).into());
        }
        if seen[pos] {
            return Err(format!("duplicate target position: {}", pos).into());
        }
        seen[pos] = true;
    }

    // current column names
    let current_cols: Vec<String> = df0.get_column_names().iter().map(|s| s.to_string()).collect();

    // validate var0 names exist and collect them as Strings
    let mut to_move: Vec<String> = Vec::with_capacity(var0.len());
    for &name in var0 {
        if !current_cols.iter().any(|c| c == name) {
            return Err(format!("column '{}' not found in df0", name).into());
        }
        to_move.push(name.to_string());
    }

    // prepare slots and place specified names at their target positions
    let mut slots: Vec<Option<String>> = vec![None; ncols];
    for (name, &pos) in to_move.iter().zip(var1.iter()) {
        slots[pos] = Some(name.clone());
    }

    // fill remaining slots with columns that are not being moved, preserving their relative order
    for col in current_cols {
        if to_move.iter().any(|m| m == &col) {
            continue; // already placed by var0/var1
        }
        // find the first empty slot
        if let Some(idx) = slots.iter().position(|s| s.is_none()) {
            slots[idx] = Some(col);
        } else {
            // shouldn't happen, but handle defensively
            return Err("internal error filling remaining columns".into());
        }
    }

    // build final order and select on df0
    let final_order: Vec<String> = slots
        .into_iter()
        .map(|opt| opt.expect("slot should be filled"))
        .collect();

    let final_order_refs: Vec<&str> = final_order.iter().map(|s| s.as_str()).collect();
    let result = df0.select(final_order_refs.as_slice())?;

    Ok(result)
}

