```rust
use std::collections::HashMap;
use std::hash::Hash;

/// Small "comprehensions" helper module (library-style, self-contained).
/// Provides a comprehension-style conversion from an iterator of items into a HashMap<K,V>.
pub mod comprehensions {
    use std::collections::HashMap;
    use std::hash::Hash;

    /// Convert an iterator of T into a HashMap<K, V> by applying `pair_fn` to each item.
    /// `pair_fn` consumes each T and returns the (K, V) pair for insertion.
    /// The function attempts to reserve capacity using the iterator's size_hint for efficiency.
    pub fn to_map<T, K, V, I, F>(iterable: I, mut pair_fn: F) -> HashMap<K, V>
    where
        I: IntoIterator<Item = T>,
        F: FnMut(T) -> (K, V),
        K: Eq + Hash,
    {
        let mut it = iterable.into_iter();
        // Use size_hint to get a likely capacity. If upper bound is available, use it; otherwise use lower.
        let (lower, upper) = it.size_hint();
        let cap = upper.unwrap_or(lower);

        let mut map = HashMap::with_capacity(cap);
        for item in it {
            let (k, v) = pair_fn(item);
            map.insert(k, v);
        }
        map
    }
}

fn main() {
    // Example 1: lst0 is a Vec of tuples (key, value)
    let lst0 = vec![
        ("apple", 3),
        ("banana", 5),
        ("orange", 2),
    ];

    // Convert using the comprehensions helper: each item is moved and mapped to (k,v)
    let map1: HashMap<&str, i32> =
        comprehensions::to_map(lst0, |(k, v)| (k, v));

