/// ```
/// let items = vec![("a", 1), ("b", 2), ("c", 3), ("a", 4)];
/// let map = list_to_map(&items);
/// assert_eq!(map.get("a"), Some(&4)); // Last value for duplicate key
/// assert_eq!(map.get("b"), Some(&2));
/// assert_eq!(map.get("c"), Some(&3));
/// ```
pub fn list_to_map<K, V>(lst0: &[(K, V)]) -> IndexMap<K, V>
where
    K: std::hash::Hash + Eq + Clone,
    V: Clone,
{
    lst0.iter()
        .cloned()
        .collect::<IndexMap<K, V>>()
}

/// Alternative version using a more explicit comprehension-style approach
/// with error handling for duplicate keys
pub fn list_to_map_strict<K, V>(lst0: &[(K, V)]) -> Result<IndexMap<K, V>, String>
where
    K: std::hash::Hash + Eq + Clone + std::fmt::Debug,
    V: Clone,
