///
/// Parameters:
/// - `arr0`: slice of data (1-D).
/// - `k`: requested number of clusters (will be reduced to min(k, arr0.len())).
/// - `max_iters`: maximum iterations to run.
/// - `tol`: convergence tolerance (stop when max centroid shift < tol).
/// - `seed`: optional seed for deterministic initialization/restarts.
///
/// Returns:
/// - Vec<usize> of length arr0.len() with cluster indices in 0..k-1.
///
/// Notes:
/// - If `arr0` is empty, returns an empty Vec.
/// - If any cluster becomes empty during iterations, its centroid is reinitialized
///   to a random point from the data (using the same RNG).
pub fn kmeans_1d(
    arr0: &[f64],
    mut k: usize,
    max_iters: usize,
    tol: f64,
    seed: Option<u64>,
) -> Vec<usize> {
    // Simple xor-shift RNG (self-contained)
    struct XorShift64 {
        state: u64,
    }
    impl XorShift64 {
        fn new(mut seed: u64) -> Self {
            if seed == 0 {
                seed = 0x9E3779B97F4A7C15u64; // avoid zero-state
            }
            XorShift64 { state: seed }
        }
        fn next_u64(&mut self) -> u64 {
            // xorshift64* style (sufficient for simple randomized init)
            let mut x = self.state;
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            self.state = x;
            x
        }
        fn gen_usize_below(&mut self, bound: usize) -> usize {
            if bound == 0 {
                return 0;
            }
            // simple modulo - good enough here
            (self.next_u64() as usize) % bound
        }
    }

    let n = arr0.len();
    if n == 0 {
        return Vec::new();
    }
    assert!(k >= 1, "k must be at least 1");
    if k > n {
        k = n;
    }

    let mut rng = XorShift64::new(seed.unwrap_or(0xDEADBEEFCAFEBABEu64));

    // Choose k distinct initial indices via partial Fisher-Yates shuffle
    let mut indices: Vec<usize> = (0..n).collect();
    for i in 0..k {
        let j = i + rng.gen_usize_below(n - i);
        indices.swap(i, j);
    }
    let mut centroids: Vec<f64> = indices.iter().take(k).map(|&idx| arr0[idx]).collect();

    // Labels for each point
    let mut labels = vec![0usize; n];

    for _iter in 0..max_iters {
        // Assignment step: assign each point to nearest centroid
        for (i, &val) in arr0.iter().enumerate() {
            let mut best = 0usize;
            let mut best_dist = (val - centroids[0]).abs();
            for j in 1..k {
                let d = (val - centroids[j]).abs();
                if d < best_dist {
                    best_dist = d;
                    best = j;
                }
            }
            labels[i] = best;
        }

        // Update step: compute new centroids
        let mut sums = vec![0.0f64; k];
        let mut counts = vec![0usize; k];
        for (i, &val) in arr0.iter().enumerate() {
            let c = labels[i];
            sums[c] += val;
            counts[c] += 1;
        }

        let mut new_centroids = vec![0.0f64; k];
        for j in 0..k {
            if counts[j] > 0 {
                new_centroids[j] = sums[j] / (counts[j] as f64);
            } else {
                // empty cluster: reinitialize to a random data point
                let idx = rng.gen_usize_below(n);
                new_centroids[j] = arr0[idx];
            }
        }

        // Check convergence (max centroid shift)
        let mut max_shift = 0.0f64;
        for j in 0..k {
            let shift = (new_centroids[j] - centroids[j]).abs();
            if shift > max_shift {
                max_shift = shift;
            }
        }
        centroids = new_centroids;
        if max_shift < tol {
            break;
        }
    }

    labels
}

