/// K-means++ initialization for better starting centroids
fn initialize_centroids_kmeans_plus_plus(data: &Array1<f64>, k: usize) -> Vec<f64> {
    use std::collections::HashSet;

    let mut centroids = Vec::with_capacity(k);
    let mut chosen_indices = HashSet::new();

    // Choose first centroid randomly
    let first_idx = (data.len() as f64 * rand::random::<f64>()) as usize % data.len();
    centroids.push(data[first_idx]);
    chosen_indices.insert(first_idx);

    // Choose remaining k-1 centroids
    for _ in 1..k {
        let mut distances = vec![f64::MAX; data.len()];

        // Calculate distance to nearest centroid for each point
        for (i, &point) in data.iter().enumerate() {
            if !chosen_indices.contains(&i) {
                let min_dist = centroids
                    .iter()
                    .map(|&centroid| (point - centroid).abs())
                    .fold(f64::MAX, f64::min);
                distances[i] = min_dist * min_dist; // Use squared distance for probability
            }
        }

        // Choose next centroid with probability proportional to squared distance
        let sum_distances: f64 = distances.iter().sum();
        let mut cumsum = 0.0;
        let threshold = rand::random::<f64>() * sum_distances;

        for (i, &dist) in distances.iter().enumerate() {
            cumsum += dist;
            if cumsum >= threshold && !chosen_indices.contains(&i) {
                centroids.push(data[i]);
                chosen_indices.insert(i);
