/// Assign each point to the nearest centroid
fn assign_clusters(data: &Array1<f64>, centroids: &[f64]) -> Vec<usize> {
    data.iter()
        .map(|&point| {
            centroids
                .iter()
                .enumerate()
                .min_by(|(_, &c1), (_, &c2)| {
                    (point - c1)
                        .abs()
                        .partial_cmp(&(point - c2).abs())
                        .unwrap_or(std::cmp::Ordering::Equal)
                })
                .map(|(idx, _)| idx)
                .unwrap_or(0)
        })
        .collect()
}

/// Update centroids as mean of assigned points
fn update_centroids(data: &Array1<f64>, labels: &[usize], k: usize) -> Vec<f64> {
    let mut centroids = vec![0.0; k];
    let mut counts = vec![0; k];

    for (point, &label) in data.iter().zip(labels.iter()) {
        centroids[label] += point;
        counts[label] += 1;
    }

    centroids
        .iter()
        .zip(counts.iter())
        .map(|(&sum, &count)| if count > 0 { sum / count as f64 } else { sum })
        .collect()
