/// # Returns
/// A new DataFrame with columns `hours` and `minutes` representing the time difference.
pub fn calculate_time_difference(
    df0: &DataFrame,
    col0: &str,
    col1: &str,
) -> Result<DataFrame, PolarsError> {
    // Ensure columns exist and are datetime types
    let col0_series = df0.column(col0)?;
    let col1_series = df0.column(col1)?;

    if col0_series.dtype() != &DataType::Datetime(Utc) &&
       col0_series.dtype() != &DataType::Datetime(Naive) {
        return Err(PolarsError::ComputeError(
            "col0 must be a datetime column".to_string()
        ));
    }
