       col1_series.dtype() != &DataType::Datetime(Naive) {
        return Err(PolarsError::ComputeError(
            "col1 must be a datetime column".to_string()
        ));
    }

    // Convert to NaiveDateTime if needed (for UTC)
    let col0_series = if let DataType::Datetime(Utc) = col0_series.dtype() {
        col0_series.naive_datetime()?
    } else {
        col0_series
    };
    let col1_series = if let DataType::Datetime(Utc) = col1_series.dtype() {
        col1_series.naive_datetime()?
    } else {
        col1_series
    };

    // Calculate absolute difference (col0 - col1)
    let diff_series = col0_series
        .sub(&col1_series)?;

    // Convert to Duration (absolute value)
    let duration_series = diff_series
        .cast(&DataType::Duration)?;

    // Extract hours and minutes
    let hours_series = duration_series
        .get("hours")
        .ok_or_else(|| PolarsError::ComputeError("Failed to extract hours".to_string()))?
        .cast(&DataType::Int64)?;

    let minutes_series = duration_series
        .get("minutes")
