    let col0_minutes: Vec<Option<i32>> = df0
        .column("col0")?
        .str()?
        .into_iter()
        .map(|opt_s| opt_s.and_then(time_to_minutes))
        .collect();

    let col1_minutes: Vec<Option<i32>> = df0
        .column("col1")?
        .str()?
        .into_iter()
        .map(|opt_s| opt_s.and_then(time_to_minutes))
        .collect();

    // Calculate differences and format as "Xh Ym"
    let time_diff: Vec<Option<String>> = col0_minutes
        .iter()
        .zip(col1_minutes.iter())
        .map(|(t0, t1)| {
            match (t0, t1) {
                (Some(t0), Some(t1)) => {
                    // Handle overnight (if t1 < t0, add 24 hours)
                    let diff = if t1 >= t0 {
                        t1 - t0
                    } else {
                        (24 * 60) - t0 + t1
                    };
