use serde_json::{json, Map, Value};
use std::collections::HashMap;

/// Group `rows` by `group_col` and for each group keep the row with the maximum numeric value in `max_col`.
/// - rows: slice of serde_json::Map<String, Value> (each map is a row)
/// - group_col: column name to group by (stringified)
/// - max_col: column name to maximize (must be numeric; non-numeric rows are ignored)
///
/// Returns a Vec of rows (Map<String, Value>) containing one row per group (the argmax).
fn group_max_rows(rows: &[Map<String, Value>], group_col: &str, max_col: &str) -> Vec<Map<String, Value>> {
    let mut best: HashMap<String, (Map<String, Value>, f64)> = HashMap::new();

    for row in rows {
        // Get group key (stringify various JSON types)
        let group_key = match row.get(group_col) {
            Some(v) => match v {
                Value::String(s) => s.clone(),
                Value::Number(n) => n.to_string(),
                Value::Bool(b) => b.to_string(),
                other => other.to_string(),
            },
            None => continue, // skip rows without the grouping column
        };

        // Get numeric value to compare
        let value = match row.get(max_col).and_then(|v| v.as_f64()) {
            Some(n) => n,
            None => continue, // skip rows with non-numeric or missing max_col
        };

        match best.get(&group_key) {
            Some((_, existing_val)) if *existing_val >= value => {
                // current best is >= this row, keep existing
            }
            _ => {
                // either no entry yet, or this row is better
                best.insert(group_key, (row.clone(), value));
            }
        }
    }

    // Extract the chosen rows. Sort deterministically by group key for stable output.
    let mut results: Vec<Map<String, Value>> = best.into_values().map(|(row, _)| row).collect();
    results.sort_by(|a, b| {
        let ak = a.get(group_col).map(|v| v.to_string()).unwrap_or_default();
        let bk = b.get(group_col).map(|v| v.to_string()).unwrap_or_default();
        ak.cmp(&bk)
    });
    results
}

