        .unique(Some(vec![group_col.into()]), UniqueKeepStrategy::First)
        .collect()?;

    Ok(result)
}

// Alternative implementation using window functions (more elegant but requires polars 0.45+)
pub fn group_max_row_window(
    df: &DataFrame,
    group_col: &str,
    max_col: &str,
) -> Result<DataFrame, Box<dyn Error>> {
    // Validate columns exist
    if !df.get_column_names().contains(&group_col) {
        return Err(format!("Column '{}' not found in DataFrame", group_col).into());
    }
    if !df.get_column_names().contains(&max_col) {
        return Err(format!("Column '{}' not found in DataFrame", max_col).into());
    }

    // Use window function to find rows where value equals the max in its group
    let result = df
        .lazy()
        .with_column(
            (col(max_col).eq(col(max_col).max().over([col(group_col)])))
                .alias("_is_max"),
        )
        .filter(col("_is_max"))
        .select(df.get_column_names().iter().map(|c| col(*c)).collect::<Vec<_>>())
        .unique(Some(vec![group_col.into()]), UniqueKeepStrategy::First)
        .collect()?;

    Ok(result)
}

