# Rust Function for Grouping and Finding Maximum Values

```rust
use polars::prelude::*;

/// Groups a dataset by a specified column and returns the row with the maximum value
/// in another specified column for each group.
///
/// # Arguments
/// * `data` - A vector of vectors representing the tabular data (rows × columns)
/// * `column_names` - Names of the columns
/// * `group_by_column` - Name of the column to group by
/// * `max_column` - Name of the column to find maximum values in
///
/// # Returns
/// A DataFrame containing the rows with maximum values per group
///
/// # Example
/// ```
/// let data = vec![
///     vec!["A", "10"],
///     vec!["B", "20"],
///     vec!["A", "30"],
///     vec!["B", "15"],
/// ];
/// let result = group_and_max(
///     data,
///     vec!["category", "value"],
///     "category",
///     "value"
/// ).unwrap();
/// ```
fn group_and_max(
    data: Vec<Vec<&str>>,
    column_names: Vec<&str>,
    group_by_column: &str,
    max_column: &str,
) -> Result<DataFrame, PolarsError> {
    // Convert input data to appropriate Series
    let mut series_vec: Vec<Series> = Vec::new();

    for col_idx in 0..column_names.len() {
        let col_name = column_names[col_idx];
        let col_data: Vec<&str> = data.iter().map(|row| row[col_idx]).collect();

        // Try to parse as integers first, otherwise keep as strings
        if let Ok(numeric_data): Result<Vec<i64>, _> = col_data
            .iter()
            .map(|s| s.parse::<i64>())
            .collect()
        {
            series_vec.push(Series::new(col_name, numeric_data));
        } else {
            series_vec.push(Series::new(col_name, col_data));
        }
    }

    // Create DataFrame from series
    let df = DataFrame::new(series_vec)?;

    // Group by the specified column and get the row with max value in the other column
    let result = df
        .clone()
        .lazy()
        .with_columns([col(max_column).cast(DataType::Int64)])
        .groupby([col(group_by_column)])
        .agg([
            col("*")
                .filter(col(max_column).cast(DataType::Int64).eq(
                    col(max_column)
                        .cast(DataType::Int64)
                        .max()
                        .over([col(group_by_column)])
                ))
        ])
        .collect()?
        .unnest(vec![group_by_column]);

    Ok(result)
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Example usage
    let data = vec![
        vec!["Product A", "100"],
        vec!["Product B", "250"],
        vec!["Product A", "150"],
        vec!["Product B", "200"],
        vec!["Product C", "120"],
        vec!["Product A", "90"],
        vec!["Product C", "180"],
    ];

    let result = group_and_max(
        data,
        vec!["product", "sales"],
        "product",
        "sales",
    )?;

    println!("Grouped data with maximum values per group:");
    println!("{}", result);

    Ok(())
}
