/// Compute the sum of element-wise products of two slices (dot product).
/// Panics if the slices have different lengths.
///
/// Works for primitive numeric types (f32, f64, i32, etc.) and other types
/// that implement Copy, Mul<Output = T>, AddAssign, and Default.
///
/// Example:
/// let a = [1.0f64, 2.0, 3.0];
/// let b = [4.0f64, 5.0, 6.0];
/// assert_eq!(dot(&a, &b), 1.0*4.0 + 2.0*5.0 + 3.0*6.0);
pub fn dot<T>(x: &[T], y: &[T]) -> T
where
    T: Copy + std::ops::Mul<Output = T> + std::ops::AddAssign + Default,
{
    assert_eq!(
        x.len(),
        y.len(),
        "dot: input slices must have the same length"
    );

    let mut sum = T::default();
    for (a, b) in x.iter().zip(y.iter()) {
        sum += *a * *b;
    }
    sum
}

