// Uses the (stabilized) std::simd API (stabilized in 2025).
// This function performs an element-wise sum of two equal-length slices
// and returns a new Vec with the results. It uses SIMD chunks (8 lanes)
// for the main loop and falls back to scalar adds for the tail.
//
// Note: std::simd requires the std::simd types to be available on your toolchain.
// If your Rust toolchain is older than the 2025 stabilization, update to a newer toolchain.
//
// Example:
// let a = vec![1.0f32, 2.0, 3.0, 4.0];
// let b = vec![0.5f32, 0.5, 0.5, 0.5];
// let c = elementwise_sum(&a, &b).unwrap();
// assert_eq!(c, vec![1.5, 2.5, 3.5, 4.5]);

use std::simd::{Simd, SimdElement, LaneCount, SupportedLaneCount};

pub fn elementwise_sum<T>(a: &[T], b: &[T]) -> Result<Vec<T>, &'static str>
where
    T: SimdElement + Copy + std::ops::Add<Output = T>,
    // Pick a reasonable lane count for vectorization. 8 lanes is a common choice;
    // the bound below ensures the lane count is supported on the target.
    LaneCount<8>: SupportedLaneCount,
{
    if a.len() != b.len() {
        return Err("input slices must have the same length");
    }

    let n = a.len();
    let mut out = Vec::with_capacity(n);

    // Number of elements processed per SIMD vector
    const LANES: usize = 8;

    let mut i = 0;
    while i + LANES <= n {
        // SAFETY: from_slice requires exactly LANES elements in the slice window.
        let va = Simd::<T, LANES>::from_slice(&a[i..i + LANES]);
        let vb = Simd::<T, LANES>::from_slice(&b[i..i + LANES]);
        let vr = va + vb;
        let tmp = vr.to_array(); // [T; LANES]
        out.extend_from_slice(&tmp);
        i += LANES;
    }

    // tail
    while i < n {
        out.push(a[i] + b[i]);
        i += 1;
    }

    Ok(out)
}

