/// Minimal helper module that stands in for a "new" table library (e.g. a 2025+ crate).
/// It defines a simple Table<T> where each column is Vec<Vec<T>> (a list-per-row column).
mod tablix {
    use std::collections::HashMap;

    /// Simple table where each column stores, for each row, a Vec<T>.
    #[derive(Debug, Default)]
    pub struct Table<T> {
        pub columns: HashMap<String, Vec<Vec<T>>>,
        pub nrows: usize,
    }

    impl<T> Table<T> {
        /// Create an empty table.
        pub fn new() -> Self {
            Self {
                columns: HashMap::new(),
                nrows: 0,
            }
        }

        /// Add a column given its name and the full column data (Vec of list-per-row).
        /// Panics if the column length mismatches the existing number of rows (unless table empty).
        pub fn add_column(&mut self, name: impl Into<String>, column: Vec<Vec<T>>) {
            let name = name.into();
            if self.nrows == 0 {
                self.nrows = column.len();
            } else if self.nrows != column.len() {
                panic!(
                    "Column length {} does not match table rows {}",
                    column.len(),
                    self.nrows
                );
            }
            self.columns.insert(name, column);
        }

        /// Get a reference to the list stored at (column, row).
        pub fn get_list(&self, column: &str, row: usize) -> Option<&Vec<T>> {
            self.columns.get(column).and_then(|col| col.get(row))
        }
    }
}

