    // This is O(m) time and O(m) memory
    let position_map: HashMap<&T, usize> = lst1
        .iter()
        .enumerate()
        .map(|(idx, item)| (item, idx))
        .collect();

    // Separate elements into two groups:
    // 1. Those found in lst1 (to be ordered)
    // 2. Those not found in lst1 (to be appended at end)
    let mut ordered: Vec<(usize, &T)> = Vec::with_capacity(lst0.len());
