            RenameCreatesDuplicate(name) => write!(f, "renaming would create duplicate column name: {}", name),
            ReorderLengthMismatch { expected, provided } => write!(f, "reorder list length mismatch: expected {}, provided {}", expected, provided),
            ReorderNameNotFound(name) => write!(f, "reorder name not found in existing headers: {}", name),
        }
    }
}

impl std::error::Error for RenameError {}

/// Rename or reorder the column headers of `df0`.
///
/// - `dict0`: optional mapping from existing header -> new header name. If Some and non-empty,
///    renaming is applied and takes precedence over `lst0`.
/// - `lst0`: optional sequence of header names specifying the desired order. Applied only if
///    `dict0` is None or empty. The list must contain exactly the existing column names (in
///    some order).
///
/// On success the function mutates `df0` in-place and returns Ok(()). On error no mutation is
