        // Compute new indices for the desired order and validate all names exist.
        let mut order_indices: Vec<usize> = Vec::with_capacity(lst.len());
        for name in lst {
            match index_of.get(name.as_str()) {
                Some(&idx) => order_indices.push(idx),
                None => return Err(RenameError::ReorderNameNotFound(name.clone())),
            }
        }

        // Reorder headers and rows.
        let new_headers: Vec<String> = lst.iter().cloned().collect();

        let mut new_rows: Vec<Vec<String>> = Vec::with_capacity(df0.rows.len());
        for row in &df0.rows {
