    let new_names = vec![
        "column_a".to_string(),
        "column_b".to_string(),
        "column_c".to_string(),
    ];

    let renamed_df2 = rename_columns(df, None, Some(new_names))?;
    println!("\nRenamed using sequence:");
    println!("{}", renamed_df2);

    Ok(())
}
