use polars::prelude::*;
use std::collections::HashMap;

/// Rename the row identifiers in `df0` using mappings in `dict0`.
///
/// - `df0` is modified in place.
/// - `index_col` is the name of the column that contains the row identifiers.
/// - Values present as keys in `dict0` are replaced by the corresponding value.
/// - Other values (and nulls) are left unchanged.
pub fn rename_row_ids(
    df0: &mut DataFrame,
    dict0: &HashMap<String, String>,
    index_col: &str,
) -> PolarsResult<()> {
    // Get the index column as an Utf8Chunked (string column).
    let col = df0.column(index_col)?.utf8()?;

    // Build a vector of Option<String> with the renamed identifiers.
    let mut renamed: Vec<Option<String>> = Vec::with_capacity(col.len());
    for opt in col.into_iter() {
        match opt {
            Some(v) => {
                if let Some(mapped) = dict0.get(v) {
                    renamed.push(Some(mapped.clone()));
                } else {
                    renamed.push(Some(v.to_string()));
                }
            }
            None => renamed.push(None),
        }
    }

    // Convert Vec<Option<String>> -> Vec<Option<&str>> so Series::new can accept it.
    let renamed_refs: Vec<Option<&str>> = renamed.iter().map(|o| o.as_deref()).collect();

    // Create a new Series and replace the original index column.
    let new_series = Series::new(index_col, &renamed_refs);
