///
/// - If `total_len <=` number of grapheme clusters in `input`, returns `input` unchanged.
/// - `pad_char` is a `char` and will be repeated as needed.
/// - Uses grapheme-cluster counting (so emoji and composed characters count as 1).
pub fn center_text(input: &str, total_len: usize, pad_char: char) -> String {
    let input_len = input.graphemes(true).count();

    if total_len <= input_len {
        return input.to_string();
    }

    let pad_needed = total_len - input_len;
    let left_pad = pad_needed / 2;
    let right_pad = pad_needed - left_pad;

    let pad_str = pad_char.to_string();
    let left = pad_str.repeat(left_pad);
    let right = pad_str.repeat(right_pad);

    format!("{}{}{}", left, input, right)
}

