```rust
use polars::prelude::*;
use std::collections::HashMap;

/// Transforms a 2D dataset into a dictionary according to the specified orientation.
///
/// # Arguments
/// * `df` - A Polars DataFrame representing the 2D dataset
/// * `orientation` - The orientation mode:
///   - "columns": Dictionary where keys are column names, values are column data
///   - "rows": Dictionary where keys are row indices, values are row data
///   - "tight": Compact format with minimal nesting
///
/// # Returns
/// A HashMap<String, Vec<String>> representing the transformed data
///
/// # Example
/// ```
/// use polars::prelude::*;
/// use std::collections::HashMap;
///
/// let df = df! {
///     "A" => &[1, 2, 3],
///     "B" => &[4, 5, 6],
/// }.unwrap();
///
/// let result = transform_dataset(&df, "columns").unwrap();
/// assert!(result.contains_key("A"));
/// ```
fn transform_dataset(
    df: &DataFrame,
    orientation: &str,
) -> Result<HashMap<String, Vec<String>>, PolarsError> {
    let mut result: HashMap<String, Vec<String>> = HashMap::new();

    match orientation {
        "columns" => {
            // Transform to dictionary with column names as keys
            for column in df.get_columns() {
                let col_name = column.name().to_string();
                let values: Vec<String> = column
                    .iter()
                    .map(|val| format!("{}", val))
                    .collect();
                result.insert(col_name, values);
            }
        }
        "rows" => {
            // Transform to dictionary with row indices as keys
            for (row_idx, _) in df.iter_rows().enumerate() {
                let row_key = format!("row_{}", row_idx);
                let row_values: Vec<String> = df
                    .get_columns()
                    .iter()
                    .map(|col| format!("{}", col.get(row_idx)))
                    .collect();
                result.insert(row_key, row_values);
            }
        }
        "tight" => {
            // Compact format: single key "data" with all values flattened
            let mut all_values = Vec::new();
            for column in df.get_columns() {
                for val in column.iter() {
                    all_values.push(format!("{}", val));
                }
            }
            result.insert("data".to_string(), all_values);
        }
        _ => {
            return Err(PolarsError::ComputeError(
                format!("Unknown orientation: {}. Use 'columns', 'rows', or 'tight'", orientation)
                    .into(),
            ))
        }
    }

    Ok(result)
}

// Example usage and tests
