fn extract_context_words(var0: &str, var1: &str, var2: usize) -> (Vec<Option<String>>, Vec<Option<String>>) {
    // Split text into words
    let words: Vec<&str> = var0.split_whitespace().collect();

    // Find the index of the search term
    let search_index = words.iter().position(|word| {
        // Case-insensitive match, handling punctuation
        word.to_lowercase().contains(&var1.to_lowercase())
    });

    let mut words_before = Vec::new();
    let mut words_after = Vec::new();

    if let Some(idx) = search_index {
        // Extract words before
        for i in 0..var2 {
            if idx > i {
                words_before.push(Some(words[idx - var2 + i].to_string()));
            } else {
                words_before.push(None);
