```rust
use ndarray::Array1;

/// Computes the mean of the indices at which an array contains non-zero values.
///
/// # Arguments
/// * `df0` - A 1-D array of numeric values
///
/// # Returns
/// * `Option<f64>` - The mean of indices with non-zero values, or None if no non-zero values exist
///
/// # Example
/// ```
/// use ndarray::array;
/// 
/// let arr = array![0.0, 1.0, 0.0, 2.0, 0.0];
/// let result = mean_of_nonzero_indices(&arr);
/// assert_eq!(result, Some(2.5)); // indices 1 and 3 have non-zero values: (1+3)/2 = 2.0
/// ```
fn mean_of_nonzero_indices(df0: &Array1<f64>) -> Option<f64> {
    let indices: Vec<usize> = df0
        .iter()
        .enumerate()
        .filter_map(|(idx, &value)| {
            if value != 0.0 {
                Some(idx)
            } else {
                None
            }
        })
        .collect();

    if indices.is_empty() {
        return None;
    }

    let sum: usize = indices.iter().sum();
    let mean = sum as f64 / indices.len() as f64;
    Some(mean)
}

