use serde_json::{Value, Map};
use std::cmp::Ordering;

/// Sorts a list of key-value maps based on the value associated with `var0`.
///
/// # Arguments
/// * `lst0` - A vector of maps (each map represents a dictionary/record)
/// * `var0` - The key whose value will be used for sorting
///
/// # Returns
/// A new vector containing the sorted maps
///
/// # Example
/// ```
/// use serde_json::{json, Value};
/// let lst0 = vec![
///     json!({"a": 1, "b": 3}),
///     json!({"a": 2, "b": 1}),
///     json!({"a": 0, "b": 5}),
/// ];
/// let sorted = sort_by_key(&lst0, "a");
/// assert_eq!(sorted[0]["a"], 0);
/// assert_eq!(sorted[1]["a"], 1);
/// assert_eq!(sorted[2]["a"], 2);
/// ```
pub fn sort_by_key(lst0: &[Value], var0: &str) -> Vec<Value> {
    let mut sorted: Vec<_> = lst0.to_vec();

    sorted.sort_by(|a, b| {
        // Get the values for comparison
        let a_val = match a.get(var0) {
            Some(v) => v,
            None => return Ordering::Greater, // Treat missing keys as "greater"
        };

        let b_val = match b.get(var0) {
            Some(v) => v,
            None => return Ordering::Less,  // Treat missing keys as "less"
        };

        // Compare the values
        match (a_val, b_val) {
            (Value::Number(a_num), Value::Number(b_num)) => {
                a_num.as_f64().partial_cmp(&b_num.as_f64()).unwrap_or(Ordering::Equal)
            }
            (Value::String(a_str), Value::String(b_str)) => a_str.cmp(b_str),
            (Value::Bool(a_bool), Value::Bool(b_bool)) => a_bool.cmp(b_bool),
            // Handle other cases or panic if types don't match
            _ => panic!("Cannot compare different types for sorting"),
        }
    });

    sorted
}
```

