/// let result = filter_by_list(df, "col", vec!["a", "c"], "in")?;
/// // Result: rows with "a" and "c"
/// ```
pub fn filter_by_list(
    df0: DataFrame,
    var0: &str,
    lst0: Vec<&str>,
    op0: &str,
) -> PolarsResult<DataFrame> {
    // Convert list to HashSet for O(1) lookups
    let set: HashSet<&str> = lst0.into_iter().collect();

    // Create a boolean mask based on the operation
    let mask = match op0 {
        "in" => df0
