            .column(var0)?
            .str()?
            .apply_to_buffer(|val, buf| {
                let is_not_in = val.map_or(true, |v| !set.contains(v));
                buf.push(is_not_in);
            }),
        _ => polars_bail!(ComputeError: "Invalid operation '{}'. Use 'in' or 'not in'", op0),
