use std::collections::HashMap;
use std::hash::Hash;

/// Zip two same-length slices into a HashMap mapping each key to the value at the same index.
/// 
/// Returns Err if lengths differ. If a key appears multiple times, the last value for that key
/// (i.e., the value at the highest index) will be stored in the map.
/// 
/// Example:
/// let keys = ["a", "b", "c"];
/// let vals = [1, 2, 3];
/// let map = zip_to_map(&keys, &vals).unwrap();
/// assert_eq!(map.get("b"), Some(&2));
pub fn zip_to_map<K, V>(
    keys: &[K],
    values: &[V],
) -> Result<HashMap<K, V>, &'static str>
where
    K: Eq + Hash + Clone,
    V: Clone,
{
    if keys.len() != values.len() {
        return Err("keys and values must have the same length");
    }

    let mut map = HashMap::with_capacity(keys.len());
    for (k, v) in keys.iter().cloned().zip(values.iter().cloned()) {
        map.insert(k, v);
    }
    Ok(map)
}

