/// # Panics
/// Panics if any divisor (value in dict1) is zero.
///
/// # Example
/// ```
/// use std::collections::HashMap;
///
/// let mut dict0 = HashMap::new();
/// dict0.insert("a", 10.0);
/// dict0.insert("b", 20.0);
