```rust
use std::collections::HashMap;
use anyhow::Result;
use polars::prelude::*;

/// Label-encode categorical values in `col_name` of `df`:
/// - Each unique non-null string value is assigned a distinct integer (0..).
/// - The original column is replaced with an Int64 column of codes.
/// - Nulls in the original column remain null in the encoded column.
/// Returns the mapping from category string to code.
///
/// Example:
/// let mut df = df!("col0" => &["a", "b", "a", None::<&str>])?;
/// let map = label_encode_column(&mut df, "col0")?;
pub fn label_encode_column(df: &mut DataFrame, col_name: &str) -> Result<HashMap<String, i64>> {
    // Get a reference to the column as Utf8Chunked (string column)
    let series = df
        .column(col_name)
        .map_err(|e| anyhow::anyhow!("column access error: {}", e))?;
    let utf8 = series.utf8().map_err(|e| anyhow::anyhow!("column not utf8: {}", e))?;

    // Build mapping preserving first-seen order
    let mut map: HashMap<String, i64> = HashMap::new();
    let mut next_id: i64 = 0;

    // Collect code values, preserving nulls
    let mut codes: Vec<Option<i64>> = Vec::with_capacity(utf8.len());
    for opt in utf8.into_iter() {
        match opt {
            Some(s) => {
                // Insert if not present, using current next_id
                let id = map.entry(s.to_string()).or_insert_with(|| {
                    let id = next_id;
                    next_id += 1;
                    id
                });
                codes.push(Some(*id));
            }
            None => {
                // Preserve null
                codes.push(None);
            }
        }
    }

    // Create Int64Chunked from codes and replace the column
    let encoded = Int64Chunked::new_from_opt_iter(col_name, codes.into_iter());
    let encoded_series = Series::new(col_name, encoded);

    df.replace(col_name, encoded_series)
        .map_err(|e| anyhow::anyhow!("replace column error: {}", e))?;

    Ok(map)
}

fn main() -> Result<()> {
    // Example usage
    let mut df = df![
        "col0" => &["apple", "banana", "apple", "cherry", None::<&str>, "banana"],
        "value" => &[1, 2, 3, 4, 5, 6]
    ]?;

    println!("Before:\n{:?}", df);

    let mapping = label_encode_column(&mut df, "col0")?;

    println!("\nAfter:\n{:?}", df);
    println!("\nMapping (category -> code):");
    for (k, v) in mapping.iter() {
        println!("{} -> {}", k, v);
    }

    Ok(())
}
```

