///         ("name".to_string(), false),  // ascending
///         ("age".to_string(), true),    // descending
///     ]
/// );
///
/// // sorted will contain rows ordered by name ascending, then age descending
/// ```
pub fn sort_dataframe_by_columns(
    df0: &HashMap<String, Vec<&str>>,
    sort_columns: Vec<(String, bool)>,
) -> Vec<HashMap<String, String>> {
    // Convert HashMap to Polars DataFrame
    let mut columns: Vec<Series> = Vec::new();
    let column_names: Vec<&String> = df0.keys().collect();

    for col_name in &column_names {
        if let Some(values) = df0.get(*col_name) {
            let series = Series::new(col_name, values.clone());
            columns.push(series);
        }
    }

    let df = DataFrame::new(columns).expect("Failed to create DataFrame");

    // Build sort options for Polars
    let mut sort_options: Vec<(&str, SortOptions)> = Vec::new();
    for (col_name, descending) in &sort_columns {
        sort_options.push((
            col_name.as_str(),
            SortOptions {
                descending: *descending,
                nulls_last: true,
                ..Default::default()
            },
        ));
    }

    // Perform the sort
    let sorted_df = df
        .sort_by_exprs(
            sort_options.iter().map(|(name, _)| col(name)).collect::<Vec<_>>(),
            sort_options.iter().map(|(_, opts)| opts.descending).collect(),
            true, // maintain order of equal elements
        )
        .expect("Failed to sort DataFrame");

    // Convert back to vector of HashMaps
    let mut result: Vec<HashMap<String, String>> = Vec::new();

    for idx in 0..sorted_df.height() {
        let mut row = HashMap::new();
        for col_name in &column_names {
            if let Ok(series) = sorted_df.column(col_name) {
                if let Ok(value) = series.get(idx) {
                    row.insert(col_name.to_string(), value.to_string());
                }
            }
        }
        result.push(row);
    }

    result
}

