///     )?;
///
///     let normalized = z_score_normalize(&df)?;
///     println!("{:?}", normalized);
///     Ok(())
/// }
/// ```
pub fn z_score_normalize(df: &DataFrame) -> Result<DataFrame, Box<dyn Error>> {
    // Get all numeric columns
    let numeric_cols: Vec<String> = df
        .columns()
        .iter()
        .filter(|col| col.dtype().is_numeric())
        .map(|col| col.name().to_string())
        .collect();

    if numeric_cols.is_empty() {
        return Ok(df.clone());
    }

    // Create a new DataFrame for the normalized columns
    let mut normalized_df = df.clone();

    for col_name in numeric_cols {
        // Get the column as a Series
        let col_series = df.column(&col_name)?;

        // Calculate mean and std
        let mean = col_series.mean()?;
        let std_dev = col_series.std()?;

        // Handle case where std_dev is 0 (all values are identical)
        if std_dev.is_nan() || std_dev == 0.0 {
            // Replace with column of zeros (or could use ones if preferred)
            let zero_series = Series::new(&col_name, &vec![0.0; col_series.len()]);
            normalized_df = normalized_df.with_column(zero_series)?;
            continue;
        }

        // Apply z-score formula: (x - mean) / std_dev
        let normalized_series = col_series
            .f64()?
            .into_iter()
            .map(|x| (x - mean) / std_dev)
            .collect::<Vec<_>>()
            .into();

        // Replace the column in the DataFrame
        normalized_df = normalized_df.with_column(normalized_series)?;
    }

    Ok(normalized_df)
}

