use polars::prelude::*;

fn zscore_normalize(df: DataFrame) -> PolarsResult<DataFrame> {
    // Get all column names
    let columns = df.get_column_names();

    // Apply z-score normalization to each column
    let result = columns
        .iter()
        .try_fold(df.clone(), |acc, col_name| {
            let col = acc.column(col_name)?;
            let numeric_col = col.cast(&DataType::Float64)?;

            // Calculate mean
            let mean = numeric_col.mean();

            // Calculate standard deviation
            let std_dev = numeric_col.std(1); // 1 for sample std (ddof=1)

            // Avoid division by zero
            let std_dev = std_dev.unwrap_or(1.0);

            if std_dev == 0.0 {
                // If std is 0, set column to zeros (mean already 0)
                let normalized = (&numeric_col - mean.unwrap_or(0.0))?;
                return acc.with_column(normalized.alias(col_name));
            }

            // Apply z-score formula: (x - mean) / std
            let normalized = ((&numeric_col - mean.unwrap_or(0.0))? / std_dev)?;
            acc.with_column(normalized.alias(col_name))
        })?;

    Ok(result)
}

fn main() -> PolarsResult<()> {
