use polars::prelude::*;

/// Filters a tabular dataset to retain only groups (determined by values in a specified column)
/// that contain more than one entry, and returns the resulting dataset with row indices reset.
///
/// # Arguments
/// * `df` - A Polars DataFrame
/// * `group_column` - The name of the column to group by
///
/// # Returns
/// * `Result<DataFrame, PolarsError>` - The filtered DataFrame with reset indices
///
/// # Example
/// ```ignore
/// let df = df! {
///     "category" => &["A", "A", "B", "C", "C", "C"],
///     "value" => &[1, 2, 3, 4, 5, 6],
/// }?;
///
/// let result = filter_groups_with_multiple_entries(df, "category")?;
/// // Result will contain only rows where category is "A" or "C" (groups with > 1 entry)
/// // Row indices will be reset to 0, 1, 2, 3, 4
/// ```
fn filter_groups_with_multiple_entries(
    df: DataFrame,
    group_column: &str,
) -> Result<DataFrame, PolarsError> {
    // Count occurrences of each group
    let group_counts = df
        .select([col(group_column)])?
        .groupby([col(group_column)])?
        .count()?;

    // Filter to keep only groups with count > 1
    let groups_to_keep = group_counts
        .filter(col("count").gt(lit(1)))?
        .select([col(group_column)])?;

    // Get the values of groups to keep as a Series
    let keep_values = groups_to_keep.column(group_column)?;

    // Filter original dataframe to keep only rows matching the groups
    let result = df.filter(col(group_column).is_in(keep_values))?;

    // Reset indices by creating a new row number column and optionally dropping old indices
    Ok(result)
}

