pub fn apply_along_axis<F>(
    df0: &DataFrame,
    var0: &str,
    func: F,
) -> Result<DataFrame>
where
    F: Fn(f64) -> f64,
{
    // Validate input
    if df0.width() == 0 || df0.height() == 0 {
        return Err(PolarsError::ComputeError(
            "Input DataFrame is empty".into(),
        ));
    }

    match var0.to_lowercase().as_str() {
        "row" => {
            // Iterate along rows (axis=0)
            let mut result_series: Vec<Series> = Vec::new();

            for col_name in df0.get_column_names() {
                let series = df0.column(col_name)?;
                let transformed: Vec<f64> = series
                    .f64()?
                    .into_iter()
                    .map(|opt_val| match opt_val {
                        Some(val) => func(val),
                        None => f64::NAN,
                    })
                    .collect();

                result_series.push(Series::new(col_name, &transformed));
            }

            DataFrame::new(result_series)
        }
        "column" => {
            // Iterate along columns (axis=1)
            let n_rows = df0.height();
            let n_cols = df0.width();

            // Collect all values into a 2D vector
            let mut values: Vec<Vec<f64>> = vec![Vec::with_capacity(n_cols); n_rows];

            for col_name in df0.get_column_names() {
                let series = df0.column(col_name)?;
                for (i, opt_val) in series.f64()?.into_iter().enumerate() {
                    let val = match opt_val {
                        Some(v) => v,
                        None => f64::NAN,
                    };
                    values[i].push(val);
                }
            }

            // Apply function to each element
            let transformed: Vec<Vec<f64>> = values
                .into_iter()
                .map(|row| row.into_iter().map(|val| func(val)).collect())
                .collect();

            // Reconstruct DataFrame
            let mut result_series: Vec<Series> = Vec::new();
            for (j, col_name) in df0.get_column_names().iter().enumerate() {
                let col_values: Vec<f64> = transformed.iter().map(|row| row[j]).collect();
                result_series.push(Series::new(col_name, &col_values));
            }

            DataFrame::new(result_series)
        }
        _ => Err(PolarsError::ComputeError(
            format!("Invalid axis '{}'. Use 'row' or 'column'.", var0).into(),
        )),
