use polars::prelude::*;

/// Sum "other_column" for rows where "var0" == `var1` (string case).
/// Returns the total as f64 (0.0 if no matching rows or null sum).
pub fn total_other_column_where_var0_equals(
    df: &DataFrame,
    var1: &str,
) -> PolarsResult<f64> {
    // Build lazy query: filter by var0 == var1, then sum other_column.
    let result_df = df
        .lazy()
        .filter(col("var0").eq(lit(var1)))
        .select([col("other_column").sum().alias("total")])
        .collect()?; // execute

    // Cast the aggregated "total" to Float64 and extract the first value (or 0.0).
    let total_series = result_df.column("total")?.cast(&DataType::Float64)?;
    Ok(total_series.f64()?.get(0).unwrap_or(0.0))
}

