use sliding_stats::window::SlidingWindow;

/// Compute the moving average of a sequence using a sliding window.
///
/// # Arguments
/// * `lst0` - A slice of f64 values to compute moving averages for
/// * `window_size` - The size of the sliding window (must be positive)
///
/// # Returns
/// A Vec<f64> containing the moving averages. The result will have
/// length lst0.len() - window_size + 1, or an empty vec if window_size > lst0.len()
///
/// # Panics
/// Panics if window_size is 0 or negative
pub fn moving_average(lst0: &[f64], window_size: usize) -> Vec<f64> {
    assert!(window_size > 0, "window_size must be positive");

    if window_size > lst0.len() {
        return Vec::new();
    }

    // Using sliding_stats library's SlidingWindow with mean aggregation
    SlidingWindow::new(lst0, window_size)
        .map(|window| window.mean())
        .collect()
}

// Alternative implementation without external library (for completeness)
pub fn moving_average_manual(lst0: &[f64], window_size: usize) -> Vec<f64> {
    assert!(window_size > 0, "window_size must be positive");

    if window_size > lst0.len() {
        return Vec::new();
    }

    let result_len = lst0.len() - window_size + 1;
    let mut result = Vec::with_capacity(result_len);

    // Calculate first window sum
    let mut window_sum: f64 = lst0[..window_size].iter().sum();
    result.push(window_sum / window_size as f64);

    // Slide the window
    for i in window_size..lst0.len() {
        window_sum += lst0[i] - lst0[i - window_size];
        result.push(window_sum / window_size as f64);
    }

    result
}

