use std::collections::HashMap;

type Row = HashMap<String, Option<f64>>;

/// Adds a new column "A_perc" to each row in `table`, computed as A / sum.
/// - If either A or sum is missing => A_perc = None.
/// - If sum == 0.0 or sum is NaN => A_perc = None (avoids divide-by-zero).
pub fn add_a_perc(table: &mut [Row]) {
    for row in table.iter_mut() {
        // Retrieve Option<f64> for columns "A" and "sum".
        // `.get()` returns Option<&Option<f64>>; `.cloned().flatten()` yields Option<f64>.
        let a_opt = row.get("A").cloned().flatten();
        let sum_opt = row.get("sum").cloned().flatten();

        let a_perc = match (a_opt, sum_opt) {
            (Some(a), Some(s)) if s != 0.0 && !s.is_nan() => Some(a / s),
            _ => None,
        };

        row.insert("A_perc".to_string(), a_perc);
    }
}

