use tabularx::prelude::*; // hypothetical crate API
use tabularx::{DataFrame, Result as TxResult};

/// Keep only groups (by `group_col`) that have more than one row,
/// and return the resulting DataFrame with row indices reset to 0..n-1.
///
/// Returns an error if the input column does not exist or on other dataframe errors.
///
/// This function assumes `tabularx` provides:
/// - DataFrame::group_count(column) -> DataFrame with columns [column, "count"]
/// - DataFrame::inner_join(&other, &[lhs_cols], &[rhs_cols])
/// - DataFrame::with_row_numbers(name) -> DataFrame (adds a sequential index column)
pub fn filter_groups_with_multiple_entries(
    df: &DataFrame,
    group_col: &str,
) -> TxResult<DataFrame> {
    // Ensure the grouping column exists
    if !df.has_column(group_col) {
        return Err(TabularError::ColumnNotFound(group_col.to_string()));
    }

    // 1) Compute counts per group: returns DataFrame with columns [group_col, "count"]
    //    (API name is hypothetical: group_count)
    let counts = df.group_count(group_col)?;

    // 2) Keep only groups whose count > 1
    //    (Assume `counts.filter_gt(column, value)` returns a dataframe filtered by predicate)
    let multi_groups = counts.filter_gt("count", 1)?;

    // 3) Join original df with the multi_groups on the group_col to keep only rows
    //    that belong to groups with more than one row.
    let filtered = df.inner_join(&multi_groups.select_columns(&[group_col])?, &[group_col], &[group_col])?;

    // 4) Reset row index to continuous sequence 0..n-1 by adding a row-number column "index".
    //    We add it as the first column for convenience.
    let with_index = filtered.with_row_numbers("index")?;

    Ok(with_index)
}

fn main() -> TxResult<()> {
    // Example usage with a small in-memory DataFrame (hypothetical API)
    let df = DataFrame::from_columns(vec![
        Series::new("user", vec!["alice", "bob", "alice", "carol", "dave", "bob"]),
        Series::new("value", vec![10, 20, 30, 40, 50, 60]),
    ])?;

    let result = filter_groups_with_multiple_entries(&df, "user")?;

    println!("Filtered DataFrame with reset index:\n{}", result);
    Ok(())
}

