///
/// let a = [1.0_f32, 2.0, 3.0];
/// let b = [1.1_f32, 1.9, 3.2];
/// let mse = avg_squared_diff(&a, &b).unwrap();
/// // mse is ((0.1)^2 + (-0.1)^2 + ( -0.2)^2) / 3 = (0.01 + 0.01 + 0.04)/3 = 0.02
/// assert!((mse - 0.02).abs() < 1e-12);
/// ```
pub fn avg_squared_diff<T: ToF64, U: ToF64>(lst0: &[T], lst1: &[U]) -> Option<f64> {
    if lst0.len() != lst1.len() || lst0.is_empty() {
        return None;
    }
    let n = lst0.len() as f64;
    let sum_sq = lst0
        .iter()
        .zip(lst1.iter())
