/// Transform every entry in the specified column to uppercase and return the modified table.
///
/// - Accepts ownership of `table` and returns the transformed `Table`.
/// - `col` can be a zero-based index or a header name.
/// - Returns Err(String) if the specified column does not exist.
///
/// Unicode-aware uppercase is used via String::to_uppercase().
pub fn uppercase_column(mut table: Table, col: ColumnId<'_>) -> Result<Table, String> {
    let idx = table
        .column_index(&col)
        .ok_or_else(|| "column not found".to_string())?;

    for row in &mut table.rows {
        if idx < row.len() {
            // Replace the cell with its uppercase equivalent.
            row[idx] = row[idx].to_uppercase();
        } else {
            // If a row is shorter than headers, optionally extend with empty strings then uppercase.
            // Here we extend to header length with empty strings and then set the target cell to "" (still uppercase == "").
            row.resize(table.headers.len(), String::new());
            // row[idx] is already "", to_uppercase is still fine.
            row[idx] = row[idx].to_uppercase();
        }
    }

    Ok(table)
}

