use semver::{Version, VersionReq};
use std::cmp::Ordering;
use std::str::FromStr;

fn sort_versions(versions: Vec<&str>) -> Vec<String> {
    // Attempt to parse each version string into a Version object
    let mut parsed_versions: Vec<(usize, Version)> = versions
        .into_iter()
        .enumerate()
        .filter_map(|(index, version_str)| {
            Version::from_str(version_str)
                .ok()
                .map(|version| (index, version))
        })
        .collect();

    // Sort the parsed versions
    parsed_versions.sort_by(|a, b| a.1.cmp(&b.1));

    // Collect the sorted version strings, maintaining the original order for non-parsable versions
    let mut sorted_versions: Vec<String> = Vec::new();
    let mut parsed_indices = parsed_versions.iter().map(|&(index, _)| index).peekable();

    for (index, version_str) in versions.into_iter().enumerate() {
        if parsed_indices.peek() == Some(&index) {
            sorted_versions.push(parsed_versions.remove(0).1.to_string());
            parsed_indices.next();
        } else {
            sorted_versions.push(version_str.to_string());
        }
    }

    sorted_versions
}

fn main() {
    let versions = vec!["1.10.0", "1.2.3", "2.0.0", "1.9.9", "1.10.1", "1.10", "1.2"];
    let sorted_versions = sort_versions(versions);
    println!("{:?}", sorted_versions);
}
