    fn dfvalue_to_json(v: &DFValue) -> JsonValue {
        match v {
            DFValue::Null => JsonValue::Null,
            DFValue::Bool(b) => JsonValue::Bool(*b),
            DFValue::Int(i) => {
                // try to fit into serde_json::Number
                serde_json::Number::from(*i).into()
            }
            DFValue::UInt(u) => {
