            }
            DFValue::Float(f) => {
                // Use Number::from_f64 and fallback to string if NaN/infinite
                serde_json::Number::from_f64(*f).map(JsonValue::Number).unwrap_or_else(|| JsonValue::String(f.to_string()))
            }
            DFValue::String(s) => JsonValue::String(s.clone()),
            DFValue::Date(d) => JsonValue::String(d.to_string()), // assume Display impl
            DFValue::Datetime(dt) => JsonValue::String(dt.to_string()),
            DFValue::List(list) => {
                let arr = list.iter().map(|item| dfvalue_to_json(item)).collect();
