    let ncols = df0.ncols();

    // If df0 has no rows and/or no columns, handle gracefully.
    if nrows == 0 && ncols == 0 {
        // empty DataFrame, preserve empty metadata
        return DataFrame::empty();
    }

    // Build transposed data: new_nrows = ncols, new_ncols = nrows
    let mut new_data: Vec<Vec<Value>> = Vec::with_capacity(ncols);
