    /// Replace elements along the main diagonal of a 2D matrix `arr0` with `var0`.
    ///
    /// - arr0: mutable slice of rows (Vec<T>), allowing non-rectangular matrices.
    /// - var0: value to write to each diagonal position (cloned as needed).
    /// Returns the number of elements replaced (i.e., length of the diagonal written).
    ///
    /// The function writes to positions (i, i) for i = 0..rows, but only if that row
    /// has at least i+1 columns. This works for rectangular and ragged (non-rectangular)
    /// matrices.
    pub fn replace_main_diagonal<T: Clone>(arr0: &mut [Vec<T>], var0: T) -> usize {
        let mut replaced = 0usize;
        // Iterate over row indices, attempt to write arr0[i][i] if that index exists.
        for i in 0..arr0.len() {
            if let Some(row) = arr0.get_mut(i) {
                if i < row.len() {
                    row[i] = var0.clone();
                    replaced += 1;
                }
            }
        }
        replaced
    }
}

