/// println!("Found matching entries: {}", result);
/// ```
pub fn column_matches_regex(
    df0: &DataFrame,
    var0: &str,
    var1: &str,
) -> Result<bool, TabulaError> {
    // Compile the regex pattern
    let pattern = Regex::new(var1)?;

    // Get the column as a string series
    let column = df0.column(var0)?.as_string()?;

    // Check if any entry matches the pattern
    Ok(column.iter().any(|entry| {
        match entry {
            Some(value) => pattern.is_match(value),
            None => false, // Null entries don't match
        }
    }))
}

