        let len_b = b.1.as_ref().len();
        len_a.cmp(&len_b)
    });

    // Build ordered map from sorted entries
    let mut ordered = OrderedMap::new();
    for (key, value) in entries {
        ordered.insert(key.clone(), value.clone());
    }

    ordered
