use itertools::izip;

/// Given three slices of equal length — `flags`, `a`, and `b` — produce a Vec
/// where each entry is taken from `a` if the corresponding flag is true,
/// otherwise from `b`.
///
/// Panics if the slices have unequal lengths.
///
/// Generic over `T: Clone`.
pub fn conditional_select<T: Clone>(flags: &[bool], a: &[T], b: &[T]) -> Vec<T> {
    assert_eq!(flags.len(), a.len(), "flags and a must have the same length");
    assert_eq!(a.len(), b.len(), "a and b must have the same length");

    izip!(flags, a, b)
        .map(|(&flag, aval, bval)| if flag { aval.clone() } else { bval.clone() })
        .collect()
}

fn main() {
    // Example usage
    let flags = vec![true, false, true, false];
    let a = vec![1, 2, 3, 4];
    let b = vec![10, 20, 30, 40];

    let out = conditional_select(&flags, &a, &b);
    println!("{:?}", out); // prints [1, 20, 3, 40]
}

