/// Count elements in `arr0` whose values fall within the inclusive range defined by `var0` and `var1`.
/// The range is inclusive and the order of `var0` and `var1` does not matter.
/// If `var0` and `var1` are incomparable (e.g. one is NaN for floats), returns 0.
pub fn count_in_range<T: PartialOrd>(arr0: &[T], var0: &T, var1: &T) -> usize {
    // determine low and high as references; if incomparable, treat as empty range
    let (low, high) = match var0.partial_cmp(var1) {
        Some(Ordering::Less) | Some(Ordering::Equal) => (var0, var1),
        Some(Ordering::Greater) => (var1, var0),
        None => return 0,
    };

