                let a = self.slice[self.pos];
                let b = self.slice[self.pos + 1];
                self.pos += 1;
                Some((a, b))
            } else {
                None
            }
        }

        fn size_hint(&self) -> (usize, Option<usize>) {
            let remaining = self.slice.len().saturating_sub(self.pos).saturating_sub(1);
            (remaining, Some(remaining))
        }
    }
