/// Convert multiple lists (each inner list represents a column) into a 2D table.
/// - `headers` provides the column headers (the number of columns is taken from this slice).
/// - `columns` is a slice of vectors, each vector is the column's values.
/// Returns a Vec<Vec<String>> where the first row is the headers and subsequent rows are the table rows.
/// Missing cells (when columns have different lengths) are filled with empty strings.
fn lists_to_table<H: ToString, T: ToString>(headers: &[H], columns: &[Vec<T>]) -> Vec<Vec<String>> {
    let num_cols = headers.len();
    // Determine how many data rows we need (max column length among the considered columns)
    let max_rows = (0..num_cols)
        .map(|i| columns.get(i).map(|col| col.len()).unwrap_or(0))
        .max()
        .unwrap_or(0);

    let mut table = Vec::with_capacity(max_rows + 1);
    // Header row
    table.push(headers.iter().map(|h| h.to_string()).collect());

    // Data rows
    for r in 0..max_rows {
        let mut row = Vec::with_capacity(num_cols);
        for c in 0..num_cols {
            let cell = columns
                .get(c)
                .and_then(|col| col.get(r))
                .map(|v| v.to_string())
                .unwrap_or_else(|| "".to_string());
            row.push(cell);
        }
        table.push(row);
    }

    table
}

