use std::collections::HashMap;

/// A simple record type: column name -> optional value.
/// This uses String values; change to a generic type if needed.
pub type Record = HashMap<String, Option<String>>;
pub type Table = Vec<Record>;

/// Filter out any rows where `col_name` is missing (either key missing or value is None).
///
/// Returns a new Table with only rows that have Some(value) for `col_name`.
pub fn drop_missing_in_column(table: Table, col_name: &str) -> Table {
    table
        .into_iter()
        .filter(|row| row.get(col_name).and_then(|v| v.as_ref()).is_some())
        .collect()
}

