/// Compute Pearson correlation coefficient between df0["var0"] and df0["var1"].
/// Returns None if columns missing, no overlapping numeric pairs, or zero variance.
pub fn corr_var0_var1(df0: &DataFrame) -> Option<f64> {
    // Attempt to fetch the two columns. The example assumes the crate returns
    // columns as Vec<Option<f64>> (i.e. numeric values with possible missing entries).
    // Adjust the calls below to match the real crate API.
    let col0 = df0.column("var0")?; // -> &Vec<Option<f64>>
    let col1 = df0.column("var1")?; // -> &Vec<Option<f64>>

    // Collect only rows where both var0 and var1 are present (non-missing).
    let mut xs = Vec::new();
    let mut ys = Vec::new();
    for (a_opt, b_opt) in col0.iter().zip(col1.iter()) {
        if let (Some(a), Some(b)) = (a_opt, b_opt) {
            xs.push(*a);
            ys.push(*b);
        }
    }

    let n = xs.len();
    if n < 2 {
        return None; // not enough data to compute correlation
    }

    // Compute means
    let mean_x = xs.iter().sum::<f64>() / n as f64;
    let mean_y = ys.iter().sum::<f64>() / n as f64;

    // Compute sums needed for Pearson correlation (no Bessel correction needed:
    // dividing numerator and denominator by (n-1) would cancel).
    let mut cov_sum = 0.0;
    let mut sx = 0.0;
    let mut sy = 0.0;
    for i in 0..n {
        let dx = xs[i] - mean_x;
        let dy = ys[i] - mean_y;
        cov_sum += dx * dy;
        sx += dx * dx;
        sy += dy * dy;
    }

    let denom = (sx * sy).sqrt();
    if denom == 0.0 {
        return None; // zero variance in one column -> correlation undefined
    }

    Some(cov_sum / denom)
}

