///
/// # Arguments
/// * `data` - Input DataFrame containing at least column `str0`
/// * `str0` - Name of the column to split (e.g., "items")
/// * `var1` - Delimiter string to split on (e.g., ",")
/// * `str1` - Comma-separated string specifying desired column order (e.g., "name,price,items")
///
/// # Returns
/// * `Result<DataFrame, String>` - New DataFrame with expanded rows and reordered columns
///
/// # Example
/// ```rust
/// let data = DataFrame::from_csv("data.csv").unwrap();
/// let result = split_and_reorder(data, "items", ",", "name,price,items")?;
/// ```
pub fn split_and_reorder(
    data: DataFrame,
    str0: &str,
    var1: &str,
    str1: &str,
) -> Result<DataFrame, String> {
    // Step 1: Split and expand the specified column
    let split_config = SplitConfig::new()
        .column(str0)
        .delimiter(var1)
        .expand(true)  // Creates new rows for each split value
        .trim_whitespace(true);

    let expanded = data.split_column(split_config)
        .map_err(|e| format!("Failed to split column '{}': {}", str0, e))?;

    // Step 2: Parse the desired column order from str1
    let desired_order: Vec<&str> = str1
        .split(',')
        .map(|s| s.trim())
        .filter(|s| !s.is_empty())
        .collect();

    if desired_order.is_empty() {
        return Err("Column order specification is empty".to_string());
    }

    // Step 3: Validate that all specified columns exist
    let available_columns: Vec<&str> = expanded.columns()
        .iter()
        .map(|c| c.name())
        .collect();

    for col in &desired_order {
        if !available_columns.contains(col) {
            return Err(format!(
                "Column '{}' not found in dataset. Available columns: {:?}",
                col, available_columns
            ));
        }
    }

    // Step 4: Create order specification and reorder columns
    let order_spec = OrderSpec::from_iter(desired_order.iter().map(|&s| s.to_string()));

    let reordered = expanded.reorder_columns(&order_spec)
