        let mut deques: Vec<VecDeque<T>> = lists.into_iter()
            .map(VecDeque::from)
            .collect();

        let num_lists = deques.len();
        let mut out: Vec<T> = Vec::with_capacity(sequence.len());

        for (step, &src_idx) in sequence.iter().enumerate() {
            if src_idx >= num_lists {
                return Err(MergeError::SourceIndexOutOfRange {
                    requested: src_idx,
                    num_lists,
                });
