    //! This module is intentionally small and self-contained so it can be used
    //! as a drop-in example of a dedicated zip utility crate.

    /// Iterator type produced by `zip_pairs`.
    pub struct ZipPairs<I, J> {
        a: I,
        b: J,
    }

    /// Construct a ZipPairs iterator from two IntoIterator values.
    pub fn zip_pairs<IA, IB>(a: IA, b: IB) -> ZipPairs<IA::IntoIter, IB::IntoIter>
    where
        IA: IntoIterator,
        IB: IntoIterator,
    {
        ZipPairs {
            a: a.into_iter(),
            b: b.into_iter(),
        }
    }

    impl<I, J> Iterator for ZipPairs<I, J>
    where
        I: Iterator,
        J: Iterator,
    {
        type Item = (I::Item, J::Item);

        fn next(&mut self) -> Option<Self::Item> {
            match (self.a.next(), self.b.next()) {
                (Some(x), Some(y)) => Some((x, y)),
                _ => None, // stop when either iterator is exhausted
            }
        }

        fn size_hint(&self) -> (usize, Option<usize>) {
            let (la, ua) = self.a.size_hint();
            let (lb, ub) = self.b.size_hint();
            let lower = std::cmp::min(la, lb);
            let upper = match (ua, ub) {
                (Some(x), Some(y)) => Some(std::cmp::min(x, y)),
                (Some(x), None) => Some(x),
                (None, Some(y)) => Some(y),
                (None, None) => None,
            };
            (lower, upper)
        }
    }

    // Optionally, make ZipPairs implement ExactSizeIterator if both are ExactSizeIterator.
    impl<I, J> ExactSizeIterator for ZipPairs<I, J>
    where
        I: ExactSizeIterator,
        J: ExactSizeIterator,
    {
        fn len(&self) -> usize {
            std::cmp::min(self.a.len(), self.b.len())
        }
    }

