/// Collapse each consecutive run of the same uppercase character into
/// a single lowercase version of that character.
///
/// Rules:
/// - Any run of one or more identical uppercase characters (according to
///   `char::is_uppercase`) is replaced by the lowercase form of that character
///   (using `char::to_lowercase()`).
/// - Non-uppercase characters (lowercase letters, digits, punctuation, spaces, etc.)
///   are left unchanged.
/// - Runs are contiguous in the input string; intervening non-uppercase characters
///   break runs.
///
/// Examples:
/// - "AAABBBcCC" -> "abcC"  (first "AAA" -> "a", "BBB" -> "b", 'c' unchanged, "CC" -> "c")
/// - "Hello WORLD" -> "hello world"
pub fn collapse_uppercase_runs(input: &str) -> String {
    let mut out = String::with_capacity(input.len());
    // Track the uppercase character of the current run, if any.
    let mut prev_upper: Option<char> = None;

    for ch in input.chars() {
        if ch.is_uppercase() {
            // If this is continuation of the same uppercase char run, skip.
            if Some(ch) == prev_upper {
                continue;
            }
            // Start a new uppercase run: append the lowercase version of `ch`.
            prev_upper = Some(ch);
            // to_lowercase may yield multiple chars for some Unicode letters,
            // so append the whole iterator.
            for lower in ch.to_lowercase() {
                out.push(lower);
            }
        } else {
            // Non-uppercase character breaks any uppercase run and is copied as-is.
            prev_upper = None;
            out.push(ch);
        }
    }

    out
}

