    ///
    /// - dict0: collection of records to sort. Each record is a HashMap<String,String>.
    /// - lst0: reference sequence that defines the desired order of values.
    /// - var0: the key inside each record whose value is used to look up position in lst0.
    ///
    /// Returns a new Vec with records sorted. Sorting is stable: records with the same
    /// index (including those whose key/value is missing) preserve their original relative order.
    pub fn sort_records_by_reference_order(
        dict0: Vec<HashMap<String, String>>,
        lst0: &[String],
        var0: &str,
    ) -> Vec<HashMap<String, String>> {
        // Build a lookup map from value -> position index for O(1) lookups.
        let mut order_map: HashMap<&str, usize> = HashMap::with_capacity(lst0.len());
        for (i, v) in lst0.iter().enumerate() {
            order_map.insert(v.as_str(), i);
        }

        // Pair each record with its original index to preserve stable ordering for ties.
        let mut indexed: Vec<(usize, HashMap<String, String>)> =
            dict0.into_iter().enumerate().collect();

